window.__D("text/zohar-hebrew-translation/c018",{"p":[[9522011714,"<p>פָּתַח וְאָמַר, וְיִקְחוּ לִי תְּרוּמָה, כְּמוֹ שֶׁנֶּאֱמַר. בַּמָּה הִיא תְּרוּמָה? בְּסוֹד הַזָּהָב, שֶׁהֲרֵי מִשָּׁם נִזּוֹנָה בַּתְּחִלָּה, מִשּׁוּם שֶׁהִיא גְּבוּרָה תַּחְתּוֹנָה שֶׁבָּאָה מִצַּד הַזָּהָב. וְאַף עַל גַּב שֶׁבָּאָה מִצַּד הַזָּהָב, כָּל עִקָּר לֹא נִשְׁאֶרֶת, אֶלָּא בְּצַד הַכֶּסֶף, שֶׁהוּא יָמִין.</p>\n<p>וְסוֹד זֶה כּוֹס שֶׁל בְּרָכָה שֶׁצָּרִיךְ לְקַבְּלָהּ בְּיָמִין וּבִשְׂמֹאל, וְכָל הָעִקָּר לֹא נִשְׁאָר אֶלָּא בַּיָּמִין, (והשמאל נעזב ממגה ולא וכו') וְהַשְּׂמֹאל מְעוֹרֵר אֶת הַיָּמִין וְלֹא נִדְבָּק בּוֹ, מִשּׁוּם שֶׁהוּא נִתָּן בֵּין יָמִין וּשְׂמֹאל, וְהַשְּׂמֹאל נֶאֱחָז תַּחְתָּיו, וְיָמִין נֶאֱחָז בּוֹ לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. זָהָב וָכָסֶף - כְּמוֹ שֶׁנֶּאֱמַר (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>וּנְחֹשֶׁת - זֶהוּ צֶבַע כְּגוֹן הַזָּהָב, מִשּׁוּם שֶׁנִּצְבָּע מִגָּוֶן זָהָב וּמִגָּוֶן כֶּסֶף. וְלָכֵן מִזְבַּח הַנְּחֹשֶׁת קָטָן. לָמָּה הוּא קָטָן? כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ח) כִּי מִזְבַּח הַנְּחֹשֶׁת אֲשֶׁר לִפְנֵי ה' קָטֹן מֵהָכִיל אֶת הָעֹלָה וְגוֹ'. כְּמוֹ שֶׁנֶּאֱמַר וְדָוִד הוּא הַקָּטָן. וְאַף עַל גַּב שֶׁהוּא קָטָן, הַכֹּל נֶאֱחָז בְּתוֹכוֹ. וְאִם תֹּאמַר, מִזְבֵּחַ אַחֵר נִקְרָא קָטָן - לֹא כָּךְ! שֶׁאֵין קָטָן פְּרָט לָזֶה, שֶׁכָּתוּב (בראשית א) אֶת הַמָּאוֹר הַגָּדֹל לְמֶמְשֶׁלֶת הַיּוֹם וְאֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה. וְזֶהוּ הַמָּאוֹר הַקָּטֹן. הַמָּאוֹר הַגָּדֹל - זֶה הַמִּזְבֵּחַ הַפְּנִימִי, שֶׁהוּא מִזְבַּח הַזָּהָב.</p>\n<p>וּתְכֵלֶת - זוֹהִי תְּכֵלֶת שֶׁל צִיצִית. תְּכֵלֶת זֶהוּ הַכִּסֵּא, סוֹד שֶׁל תְּפִלִּין שֶׁל יָד. תְּכֵלֶת זֶהוּ הַכִּסֵּא שֶׁבּוֹ דָּנִים דִּינֵי נְפָשׁוֹת. מִשּׁוּם שֶׁיֵּשׁ כִּסֵּא שֶׁדָּנִים בּוֹ דִּינֵי מָמוֹנוֹת, וְיֵשׁ כִּסֵּא שֶׁדָּנִים בּוֹ דִּינֵי נְפָשׁוֹת. וְלָכֵן כָּל הַגְּוָנִים טוֹבִים לַחֲלוֹם, פְּרָט לְגָוֶן תְּכֵלֶת, כְּדֵי שֶׁיֵּדַע שֶׁהֲרֵי נִשְׁמָתוֹ הֲרֵי עוֹלָה בְדִין. וּכְשֶׁנְּשָׁמָה עוֹלָה בְדִין, הַגּוּף נִדּוֹן לְהִתְכַּלּוֹת, וְצָרִיךְ אוֹתוֹ הַחֲלוֹם לְרַחֲמִים רַבִּים.</p>\n<p>תְּכֵלֶת זֶהוּ כִּסֵּא, שֶׁכָּתוּב בּוֹ כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא, וְכָתוּב (יחזקאל א) וְנֹגַהּ לוֹ סָבִיב. מִשּׁוּם שֶׁעוֹשִׂים בּוֹ כְּרִיכוֹת לַצִּיצִית, וּכְשֶׁנֹּגַהּ לוֹ הוֹפֵךְ לְגָוֶן יָרֹק, כְּגָוֶן כַּרְתִּי, מֵאוֹתָהּ שָׁעָה וְאֵילָךְ מַתְחִיל זְמַן קְרִיאַת שְׁמַע, שֶׁהֲרֵי הִשְׁתַּנָּה גָּוֶן תְּכֵלֶת מִכְּמוֹ שֶׁהָיָה, וְלָכֵן אָסוּר לָדוּן דִּינֵי נְפָשׁוֹת בַּלַּיְלָה, מִשּׁוּם שֶׁשּׁוֹלֵט אוֹתוֹ גָוֶן תְּכֵלֶת בְּאוֹתוֹ זְמַן, וְנִתְּנָה רְשׁוּת לַחֲטֹף נֶפֶשׁ בְּלִי מִשְׁפָּט. שֶׁהֲרֵי מִשְׁפָּט לֹא שׁוֹלֵט בְּאוֹתוֹ זְמַן.</p>\n<p>כְּשֶׁבָּא הַבֹּקֶר וּמִתְעוֹרֵר הַיָּמִין שֶׁלְּמַעְלָה, יוֹצֵא אוֹתוֹ הָאוֹר וּמַגִּיעַ עַד הַתְּכֵלֶת הַ את וּמִשְׁתַּנֶּה מִכְּמוֹ שֶׁהָיָה, וְאָז שׁוֹלֵט עָלָיו וְנִדְבָּק בּוֹ כִּסֵּא קָדוֹשׁ אַחֵר. מֵאוֹתָהּ שָׁעָה וְאֵילָךְ זְמַן קְרִיאַת שְׁמַע.</p>\n<p>וְאַרְגָּמָן - זֶה כִּנּוּס שֶׁכּוֹלֵל כָּל הַגְּוָנִים כְּאֶחָד. וְתוֹלַעַת שָׁנִי - כָּתוּב שָׁנִי, וְכָתוּב שָׁנִים, שֶׁכָּתוּב (משלי לא) כִּי כָל בֵּיתָהּ לָבֻשׁ שָׁנִים. אֶלָּא זֶהוּ גָּוֶן שֶׁנִּקְרָא שָׁנִי, שֶׁנּוֹטֵל בּוֹ אֶת כָּל הַגְּוָנִים וְהַכֹּל אֶחָד, שָׁנִי וְשָׁנִים. שָׁנִים - כְּשֶׁכֻּלָּם כְּלוּלִים בּוֹ כְּאֶחָד. שָׁנִי - שֶׁיּוֹצֵא מֵהַכִּסֵּא הָעֶלְיוֹן שֶׁשּׁוֹלֵט עַל תְּכֵלֶת מִצַּד הַיָּמִין, וְזֶהוּ הָאַפּוֹטְרוֹפּוֹס שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב בּוֹ (דניאל י) מִיכָאֵל שַׂרְכֶם. תּוֹלַעַת - שֶׁכֹּחָהּ בְּפִיהָ. כְּתוֹלַעַת שֶׁמְּשַׁבֶּרֶת הַכֹּל וּמְעַקֶּרֶת הַכֹּל.</p>\n<p>תּוֹלַעַת שָׁנִי וְשֵׁשׁ - שְׁנֵי גְוָנִים כְּאֶחָד, שֶׁל יָמִין וּשְׂמֹאל, לָבָן וְאָדם. וְשֵׁשׁ - הוּא בּוּץ. שֶׁשִּׁשָּׁה חוּטִים מִתְחַבְּרִים, וְזֶהוּ שֶׁכָּתוּב וּגְוִיָּתוֹ כְתַרְשִׁישׁ. וּבִשְׁנֵי אֵלֶּה כְּלוּלִים שְׁנֵי אֲחֵרִים.</p>\n<p>וְעִזִּים - גְּבוּרוֹת תַּחְתּוֹנוֹת שֶׁלַּחוּץ, לְכַסּוֹת עַל הַפְּנִימִיִּים. וְהַכֹּל צָרִיךְ. וְצָרִיךְ לָתֵת מָקוֹם לַכֹּל, שֶׁהֲרֵי מִצַּד הַזָּהָב הֵם בָּאִים. וְעֹרֹת אֵילִם מְאָדָּמִים - מְשִׁיכָה שֶׁל שְׁנֵי צְדָדִים, שֶׁל יָמִין וּשְׂמֹאל, לְכַסּוֹת בְּמָקוֹם אַחֵר.</p>\n<p>וְעֹרֹת תְּחָשִׁים - צַד אֶחָד יֵשׁ שֶׁגָּדֵל בְּתוֹךְ הַצַּד הָאַחֵר בְּחֻרְבָּה, וְלֹא נִמְצָא בְיִשּׁוּב, וְזֶהוּ צַד טֹהַר, וְנִקְרָא תַּחַשׁ.</p>\n<p>בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ יֵשׁ בְּתוֹךְ מִזְבַּח הַנְּחֹשֶׁת שֶׁאָמַרְנוּ סוֹדוֹת עֶלְיוֹנִים. שֶׁהֲרֵי כָּתוּב, (שמות כ) מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִּי וְגוֹ', וְזֶהוּ סוֹד כָּרָאוּי. נְחֹשֶׁת - כְּשֶׁשּׁוֹלְטִים הָרִים אֲחֵרִים, וְהִיא צְרִיכָה לִזּוֹן אוֹתָם, נִצְבַּעַת בַּגָּוֶן הַזֶּה לָזוּן אוֹתָם, וְהֵם נִקְרָאִים הָרֵי נְחֹשֶׁת.</p>\n<p>וְאוֹתָם הָרֵי נְחֹשֶׁת נִמְשָׁךְ עֲלֵיהֶם רוּחַ אַחַת מִתּוֹךְ הַמִּזְבֵּחַ הַזֶּה, וּכְשֶׁמִּזְבֵּחַ זֶה מִתְעַלֶּה בַּעֲלִיָּה אַחֶרֶת, אָז מִסְתַּלֶּקֶת אוֹת נ', שֶׁהוּא מִזְבֵּחַ קָדוֹשׁ, וְנִשְׁאֶרֶת הָרוּחַ שֶׁל הָרֵי הַנְּחֹשֶׁת הַלָּלוּ. וּכְשֶׁאוֹתָהּ רוּחַ מִתְעַלֵּית בְּקִיּוּמָהּ, הִיא נִקְרֵאת תַּחַשׁ, שֶׁהֲרֵי הִסְתַּלְּקָה מִמֶּנָּה אוֹת נ'.</p>\n<p>וְזְהִ נִפְרָד לְכַמָּה רוּחוֹת אֲחֵרוֹת, וְנִקְרָאִים אַף כָּךְ, וְלָכֵן נִקְרָא אוֹתוֹ הָעָם (אחד) תַּחַשׁ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כב) וְאֶת תַּחַשׁ וְאֶת מַעֲכָה. הֵם הָיוּ מַכִּירִים אֶת הַחַיָּה הַזּוֹ שֶׁל הַמִּשְׁכָּן שֶׁנִּקְרֵאת עַל שְׁמָם.</p>\n<p>וַעָצֵי שִׁטִּים - אֵלוּ אוֹתָם סוֹדוֹת קְדוֹשִׁים, שֶׁהֵם לוּחוֹת הַמִּשְׁכָּן, וְהֵם נִקְרָאִים בַּסּוֹד שֶׁלָּהֶם. כָּתוּב עֲצֵי שִׁטִּים עֹמְדִים, וְכָתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים.</p>\n<p>מִכָּאן וָהָלְאָה - שֶׁמֶן לַמָּאֹר, מְשִׁיכָה שֶׁל שֶׁמֶן מִשְׁחָה קָדוֹשׁ לִמְשֹׁךְ עֲלֵיהֶם. אַבְנֵי שֹׁהַם וְאַבְנֵי מִלּוּאִים - אֵלּוּ אַבְנֵי קֹדֶשׁ, יְסוֹדוֹת הַמִּקְדָּשׁ, בַּמֶּרְכָּבוֹת הַקְּדוֹשׁוֹת הַלָּלוּ מִזְדַּמְּנִים לְבַדָּם לְכַבֵּד וּלְשַׁבֵּחַ בִּלְבוּשׁ כָּבוֹד לְעַיֵּן הַכֹּהֵן בָּהֶם שָׁם וּלְהַזְכִּיר (ולברך) שְׁנֵים עָשָׂר שְׁבָטִים, וְלָכֵן שְׁתֵּים עֶשְׂרֵה אֲבָנִים כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>שְׁלשָה עָשָׂר מִינִים הֵם, פְּרָט לִשְׁתֵּים עֶשְׂרֵה הָאֲבָנִים הַיְקָרוֹת הַלָּלוּ, וְכֻלָּם עוֹלִים לְעֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת בַּסּוֹד הָעֶלְיוֹן שֶׁל הַיִּחוּד. וּכְנֶגֶד אֵלֶּה חָקַק וְתִקֵּן מֹשֶׁה עֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת בְּסוֹד הַפָּסוּק שֶׁל הַיִּחוּד, שֶׁכָּתוּב (דברים ו) שְׁמַע יִשְׂרָאֵל יְהֹוָה אֱלֹהֵינוּ יְהֹוָה אֶחָד. וְהֵם עֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת, גִּלּוּפִים חֲקוּקִים בַּסּוֹד שֶׁלְּמַעְלָה.</p>\n<p>יַעָקֹב רָצָה לְתַקֵּן לְמַטָּה בְּסוֹד הַיִּחוּד, וְתִקֵּן בְּעֶשְׂרִים וְאַרְבַּע אוֹתִיּוֹת, וְהֵן: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְלֹא הִשְׁלִים לְעֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת, מִשּׁוּם שֶׁעֲדַיִן לֹא הִתְתַּקֵּן הַמִּשְׁכָּן. כֵּיוָן שֶׁהִתְתַּקֵּן הַמִּשְׁכָּן וְנִשְׁלַם, הַדָּבָר הָרִאשׁוֹן שֶׁהָיָה יוֹצֵא מִמֶּנּוּ כְּשֶׁהִשְׁתַּלֵּם - לֹא דִבֵּר אֶלָּא בְּעֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת, לְהַרְאוֹת שֶׁהֲרֵי נִשְׁלָם זֶה כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (ויקרא א) וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. הֲרֵי עֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת.</p>\n<p>וְלָכֵן עֶשְׂרִים וַחֲמִשָּׁה מִינִים לְהַשְׁלִים תִּקּוּן הַמִּקְדָּשׁ (המשכן) וְכָל אֵלּוּ הָאוֹתִיּוֹת בֵּאַרְנוּ בְּאוֹתָן אוֹתִיּוֹת חֲקוּקוֹת שֶׁלָּמַדְנוּ מִמּוֹרֵנוּ. וּמִשּׁוּם שֶׁהַמִּשְׁכָּן נִשְׁלָם בַּסּוֹדוֹת הַלָּלוּ, נִקְרָא כ\"ה, בַּיִּחוּד שֶׁל שְׁלֵמוּת הַמִּשְׁכָּן, וְלָכֵן (תהלים קמד) וַחֲסִידֶיךְ יְבָרְכוּכָה כָּתוּב, סוֹד שֶׁל שְׁלֵמוּת שֶׁל כָּל הַמִּשְׁכָּן וְתִקּוּנוֹ. כ\"ה כְּנֶגֶד עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, וְתוֹרָה וּנְבִיאִים וּכְתוּבִים, שֶׁהֵם כְּלָל אֶחָד וְסוֹד אֶחָד.</p>\n<p>בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְיַחֲדִים יִחוּד בַּפָּסוּק הַזֶּה בְּסוֹד שֶׁל עֶשְׂרִים וְחָמֵשׁ אוֹתִיּוֹת, שֶׁהֵן: שְׁמַע יִשְׂרָאֵל יְיָ אֱלֹהֵינוּ יְיָ אֶחָד, וּבָרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, שֶׁהֵם עֶשְׂרִים וְאַרְבַּע אוֹתִיּוֹת, וִיכַוֵּן כָּל אֶחָד בָּהֶן - כָּל הָאוֹתִיּוֹת מִתְחַבְּרוֹת כְּאַחַת, וְעוֹלוֹת בְּחִבּוּר אֶחָד (אז נפתחו) אַרְבָּעִים וְתִשְׁעָה שְׁעָרִים בְּסוֹד הַיּוֹבֵל, וְאָז צָרִיךְ לַעֲלוֹת עַד וְלֹא יוֹתֵר. וְאָז נִפְתָּחִים הַשְּׁעָרִים, וּמַחֲשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ הָאָדָם כְּאִלּוּ קִיֵּם אֶת כָּל הַתּוֹרָה שֶׁבָּא בְּאַרְבָּעִים וְתֵשַׁע פָּנִים.</p>\n<p>וְלָכֵן צָרִיךְ לְכַוֵּן לֵב וְרָצוֹן בְּעֶשְׂרִים וְחָמֵשׁ וּבְעֶשְׂרִים וְאַרְבַּע וּלְהַעֲלוֹתָם בִּרְצוֹן הַלֵּב לְאַרְבָּעִים וְתִשְׁעָה שְׁעָרִים שֶׁאָמַרְנוּ. כֵּיוָן שֶׁהִתְכַּוֵּן בָּזֶה, יִתְכַּוֵּן בְּאוֹתוֹ יִחוּד שֶׁאָמַר מוֹרֵנוּ - שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, כְּלָל שֶׁל כָּל הַתּוֹרָה כֻּלָּהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיִּתְכַּוֵּן בָּהֶם, שֶׁוַּדַּאי כְּלָל הוּא שֶׁל כָּל הַתּוֹרָה, שֶׁלְּמַעְלָה וּמַטָּה. וְזֶהוּ סוֹד שֶׁל אָדָם שָׁלֵם, שֶׁל זָכָר וּנְקֵבָה, וְסוֹד שֶׁל כָּל הָאֱמוּנָה.</p>\n<p>מַחֲלֹקֶת שֶׁל שַׁמַּאי וְהִלֵּל בְּקִימָה וּבִשְׁכִיבָה, שֶׁכָּתוּב (דבריםי) בְּשָׁכְבְּךְ וּבְקוּמֶךְ. שֶׁשַּׁמַּאי סוֹבֵר, בָּעֶרֶב, שֶׁכְּלוּלָה הַנְּקֵבָה בְּשִׁלְטוֹנָהּ, צָרִיךְ לַנְּקֵבָה שֶׁיַּטּוּ וְיִקְרְאוּ. וּבַבֹּקֶר כְּשֶׁשּׁוֹלֵט הַזָּכָר בְּשִׁלְטוֹן הָעוֹלָם הָעֶלְיוֹן, צָרִיךְ לַעֲמֹד לִפְנֵי הַזָּכָר כְּמוֹ שֶׁצָּרִיךְ בִּתְפִלַּת מְעֻמָּד, וּבְכָל מָקוֹם שֶׁהַזָּכָר בָּא.</p>\n<p>וּבֵית הִלֵּל סוֹבֵר, שֶׁאִלְמָלֵא שֶׁנִּמְצָא זֶה לְחוּד וְזֶה לְחוּד - כָּךְ צָרִיךְ. אֲבָל כֵּיוָן שֶׁאָנוּ מְחַבְּרִים אוֹתָם כְּאֶחָד בְּחִבּוּר בְּאַרְבָּעִים וְתֵשַׁע פָּנִים וְאַרְבָּעִים וְתִשְׁעָה שְׁעָרִים, לֹא צְרִיכִים אָנוּ לְהַפְרִיד זֶה לְחוּד וְזֶה לְחוּד, אֶלָּא לְהַשְׁגִּיחַ שֶׁהַכֹּל אֶחָד בְּלִי פֵרוּד, וּכְמוֹ שֶׁמִּזְדַּמֵּן לָאָדָם - כָּךְ יֹאמַר, שֶׁהֲרֵי שְׁנֵיהֶם בְּחִבּוּר אֶחָד כְּמוֹ שֶׁנּוֹחַ לָהֶם, וְכָךְ צָרִיךְ לְהֵרָאוֹת.</p>\n<p>וְלָכֵן הַזָּכָר בְּשִׁשָּׁה צְדָדִים, בַּפָּסוּק שֶׁל שְׁמַע יִשְׂרָאֵל, שֶׁהֵם שֵׁשׁ תֵּבוֹת, וְהַנְּקֵבָה בְּשִׁשָּׁה צְדָדִים - בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, שֶׁהֵם שֵׁשׁ תֵּבוֹת אֲחֵרוֹת, וְעוֹלִים בְּחִבּוּר אֶחָד, בְּסוֹד שֶׁל אַרְבָּעִים וְתִשְׁעָה שְׁעָרִים, וַהֲלָכָה כְּמוֹ בֵּית הִלֵּל בְּכָל מָקוֹם.</p>"],[9522011715,"<p>רַבִּי שִׁמְעוֹן הֵרִים יָדוֹ וּבֵרַךְ אֶת רַבִּי אֶלְעָזָר בְּנוֹ. פָּתַח וְאָמַר, (ישעיה מא) מִי הֵעִיר מִמִּזְרָח וְגוֹ'. פָּסוּק זֶה בֵּאַרְנוּ וְנִתְבָּאֵר, אֲבָל סוֹד הַחָכְמָה הוּא. מִ\"י הוּא סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, שֶׁהֲרֵי מִשָּׁם יוֹצֵאת הָרֵאשִׁית לְגַלּוֹת סוֹד הָאֱמוּנָה, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>עוד מִ\"י - הַטָּמִיר שֶׁל כָּל הַטְּמִירִים, שֶׁלֹּא נוֹדַע וְלֹא הִתְגַּלָּה כְּלָל. גִּלָּה כְבוֹדוֹ לְהִוָּדַע מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא מִזְרָח, שֶׁהֲרֵי מִשָּׁם רֵאשִׁית שֶׁל כָּל סוֹד הָאֱמוּנָה וְהָאוֹר לְהִגָּלוֹת. וְאַחַר כָּךְ, צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, שֶׁהֲרֵי צֶדֶק גִּלָּה הַגְּבוּרָה הָעֶלְיוֹנָה וְשִׁלְטוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֶת הַצֶּדֶק הַזֶּה הִשְׁלִיט עַל כָּל הָעוֹלָמוֹת לְהַנְהִיגָם וּלְתַקְּנָם כָּרָאוּי. וְלָכֵן, יִתֵּן לְפָנָיו גּוֹיִם וּמְלָכִים יַרְדְּ, שֶׁהֲרֵי כָּל מַלְכֵי הָעוֹלָם בִּרְשׁוּת הַצֶּדֶק הַזֶּה הֵם עוֹמְדִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק.</p>\n<p>עוֹד צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ - מִי קוֹרֵא לְמִי? אֶלָּא הַצֶּדֶק קוֹרֵא תָמִיד לְאַסְפַּקְלַרְיָה הַמְּאִירָה, וְלֹא שׁוֹכֵךְ לְעוֹלָמִים, וְצֶדֶק עוֹמֵד תָּמִיד לְרַגְלוֹ, שֶׁלֹּא זָז מִשָּׁם, וְקוֹרֵא וְלֹא שׁוֹכֵךְ. זֶהוּ שֶׁכָּתוּב (שם פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל יֶחֱרַשׁ וְאַל תִּשְׁקֹט אֵל. וְעַכְשָׁו הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִיר לָנוּ הַדֶּרֶךְ הַזּוֹ בִּשְׁבִילֵנוּ (ורבי) אֶלְעָזָר בְּנִי שֶׁקּוֹרֵא לָאוֹר הָעֶלְיוֹן וְלֹא שׁוֹכֵךְ. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (ועתה, אלעזר בני, קורא לאורהעליוןולאשוכך, והקדושברוך הוא מאיר לנו הדרך בגללו. אשרי חלקו ואשרי חלקם של הצדיקים).</p>"],[9522011716,"<p>רַבִּי אַבָּא פָּתַח פָּסוּק וְאָמַר, (שם סג) מִזְמוֹר לְדָוִד בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה. מַה זֶּה שׁוֹנֶה מִכָּל שְׁאָר הַתִּשְׁבָּחוֹת שֶׁלֹּא אָמַר בְּאֵיזֶה מָקוֹם שִׁבַּח אוֹתָם דָּוִד הַמֶּלֶךְ? וּמַה שּׁוֹנֶה כָּאן שֶׁאָמַר בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה? אֶלָּא לֹא זֶה לְבַדּוֹ, שֶׁהֲרֵי אַף כָּךְ גַּם - (שם לד) בְּשַׁנּוֹתוֹ אֶת טַעְמוֹ לִפְנֵי אֲבִימֶלֶךְ. בְּבֹא הַזִּיפִים. וְכֵן כֻּלָּם. לְהַרְאוֹת לְכָל בְּנֵי הָעוֹלָם שִׁבְחוֹ שֶׁל דָּוִד, שֶׁאַף עַל גַּב שֶׁהָיָה בְּצַעַר וְהָיוּ רוֹדְפִים אַחֲרָיו, הָיָה מִשְׁתַּדֵּל לוֹמַר שִׁירוֹת וְתִשְׁבָּחוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>וְאַף עַל גַּב שֶׁבְּרוּחַ הַקֹּדֶשׁ הָיָה אוֹמֵר - רוּחַ הַקֹּדֶשׁ לֹא הָיְתָה שׁוֹרָה עָלָיו עַד שֶׁהוּא הִשְׁתַּדֵּל שֶׁתִּשְׁרֶה עָלָיו. וְכָךְ בְּכָל מָקוֹם - לֹא שׁוֹרָה רוּחַ הַקֹּדֶשׁ שֶׁלְּמַעְלָה עַד שֶׁיִּתְעוֹרֵר עָלָיו הָאָדָם מִלְּמַטָּה. וְדָוִד, אַף עַל גַּב שֶׁרָדְפוּ אַחֲרָיו וְהָיָה בְּצַעֲרוֹ, לֹא הָיָה עוֹזֵב שִׁירוֹת וְתִשְׁבָּחוֹת מִפִּיו וּלְשַׁבֵּחַ אֶת רִבּוֹנוֹ עַל הַכֹּל.</p>\n<p>וְאִם תֹּאמַר, זֶה שֶׁשָּׁנִינוּ מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר, וְכָאן שָׁרְתָה עָלָיו רוּחַ הַקֹּדֶשׁ בַּתְּחִלָּה, מִשּׁוּם שֶׁאָמַר מִזְמוֹר לְדָוִד. אֶלָּא, אִם הוּא הָיָה מְכַוֵּן עַצְמוֹ בַּתְּחִלָּה, לֹא הָיְתָה שׁוֹרָה עָלָיו רוּחַ הַקֹּדֶשׁ.</p>\n<p>מִזְמוֹר זֶה רוּחַ הַקֹּדֶשׁ. לָמָּה נִקְרָא כָּךְ? מִשּׁוּם שֶׁהִיא מְשַׁבַּחַת אֶת הַמֶּלֶךְ הָעֶלְיוֹן תָּמִיד, (שכל הזמן הוא היה משבח ומזמר ולא שוכך) שֶׁכָּל הַזְּמַן הָיְתָה מְשַׁבַּחַת וּמְזַמֶּרֶת וְלֹא שׁוֹכֶכֶת. כֵּיוָן שֶׁבָּא דָוִד, מָצָא גוּף מְתֻקָּן כָּרָאוּי וְשָׁרְתָה עָלָיו, וְהָיוּ מְגַלִּים בָּעוֹלָם הַזֶּה לְשַׁבֵּחַ וּלְזַמֵּר לַמֶּלֶךְ, וְהַכֹּל כְּדֵי שֶׁיִּתְתַּקֵּן הָעוֹלָם הַזֶּה כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>לְדָוִד - אִישׁ שָׁלֵם בְּתִקּוּנוֹ, אִישׁ מְתֻקָּן, אִישׁ צַדִּיק. דָּוִד וַדַּאי שֶׁלֹּא הִשְׁתַּנָּה לְעוֹלָמִים. בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה - זֶה שֶׁבַח שֶׁל דָּוִד, אַף עַל גַּב שֶׁהָיָה בְּצַעֲרוֹ, אַף עַל גַּב שֶׁהָיוּ רוֹדְפִים אַחֲרָיו, וְאֵיזוֹ תִשְׁבַּחַת אָמַר? תִּשְׁבַּחַת גְּדוֹלָה וְנִכְבָּדָה.</p>\n<p>וְהַשֶּׁבַח שֶׁלּוֹ מַה הוּא? (תהלים סג) אֱלֹהִים אֵלִי אַתָּה אֲשַׁחֲרֶךָּ. אֱלֹהִים סְתָם. כֵּיוָן שֶׁאָמַר אֱלֹהִים, לָמָּה אֵלִי? אֶלָּא אוֹתָהּ דַּרְגָּה שֶׁלּוֹ. שָׁלֹשׁ דְּרָגוֹת כָּאן: אֱלֹהִים, אֵלִי, אַתָּה. וְאַף עַל גַּב שֶׁהֵם שְׁלֹשָׁה שֵׁמוֹת, דַּרְגָּה אַחַת הִיא, בְּסוֹד שֶׁל אֱלֹהִים חַיִּים. אֱלֹהִים - לְמַעְלָה, אֱלֹהִים חַיִּים. אֵלִי - קְצֵה הַשָּׁמַיִם עַד קְצֵה הַשָּׁמַים. אַתָּה - הַדַּרְגָּה שֶׁלּוֹ. וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד וּבְשֵׁם אֶחָד עוֹלֶה.</p>\n<p>אֲשַׁחֲרֶךָּ - אִם כְּמַשְׁמָעוֹ שֶׁלּוֹ, יָפֶה. אֲבָל אֲשַׁחֲרֶךָּ - הִתְקִין הָאוֹר שֶׁמֵּאִיר בַּשַּׁחַר. שֶׁהֲרֵי הָאוֹר שֶׁעוֹמֵד בַּשַּׁחַר לֹא מֵאִיר עַד שֶׁיְּתַקְּנוּ אוֹתוֹ לְמַטָּה. וּמִי שֶׁמְּתַקֵּן אֶת אוֹר הַשַּׁחַר הַזֶּה, אַף עַל גַּב שֶׁהוּא שָׁחֹר, זוֹכֶה לְאוֹר לָבָן שֶׁמֵּאִיר, וְזֶהוּ אוֹר אַסְפַּקְלַרְיָה הַמְּאִירָה, וְזֶהוּ הָאָדָם שֶׁזּוֹכֶה לָעוֹלָם הַבָּא.</p>\n<p>וְזְה סוֹד (משלי א) וּמְשַׁחֲרַי יִמְצָאֻנְנִי. וּמְשַׁחֲרַי - שֶׁמְּתַקְּנִים הָאוֹר שֶׁל מְשַׁחֲרַי הַשָּׁחֹר. יִמְצָאֻנְנִי, לֹא כָתוּב יִמְצָאוּנִי, אֶלָּא יִמְצָאֻנְנִי, שֶׁזּוֹכִים לִשְׁנֵי אוֹרוֹת - לְאוֹר הַשַּׁחַר הַשָּׁחֹר, וְלָאוֹר הַלָּבָן שֶׁמֵּאִיר. וְזוֹכֶה לְאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, וּלְאַסְפַּקְלַרְיָה שֶׁמְּאִירָה. וְזֶהוּ יִמְצָאֻנְנִי. וְעַל כֵּן אָמַר דָּוִד אֲשַׁחֲרֶךָּ. הִתְקִין אוֹר שֶׁל הַשַּׁחַר הַשָּׁחֹר לְהָאִיר עָלָיו אוֹר לָבָן שֶׁמֵּאִיר.</p>\n<p>צָמְאָה לְךְ נַפְשִׁי כָּמַהּ לְךְ בְּשָׂרִי (תהלים סג), כְּמִי שֶׁרָעֵב לֶאֱכֹל וְצָמֵא לִשְׁתּוֹת. בְּאֶרֶץ צִיָּה וְעָיֵף בְּלִי מָיִם, מִשּׁוּם שֶׁהוּא מִדְבָּר וְאֵינוֹ מָקוֹם שֶׁל יִשּׁוּב, וְלֹא מָקוֹם שֶׁל קֹדֶשׁ. וְלָכֵן הוּא מָקוֹם בְּלִי מַיִם. וּכְמוֹ שֶׁאָנוּ רְעֵבִים וּצְמֵאִים אֵלֶיךְ בַּמָּקוֹם הַזֶּה, כֵּן בַּקֹּדֶשׁ חֲזִיתִיךְ וְגוֹ'. וְאָנוּ, כְּמוֹ שֶׁאָנוּ צְמֵאִים אֶל מוֹרֵנוּ לִשְׁתּוֹת בְּצִמָּאוֹן אֶת דְּבָרָיו בַּמָּקוֹם הַזֶּה, אַף כָּךְ צְמֵאִים לִשְׁתּוֹת בַּצָּמָא דְּבָרָיו בְּבֵית הַמִּקְדָּשׁ, הַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אַבָּא, מִי שֶׁהִתְחִיל הַדָּבָר - יֹאמַר עַכְשָׁו.</p>"],[9522011717,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ וְגוֹ'. בְּשָׁעָה שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה אֶת מַעֲשֵׂה הַמִּשְׁכָּן, הָיָה קָשֶׁה לְפָנָיו, וְלֹא יָכֹל לַעֲמֹד בּוֹ, וַהֲרֵי פֵּרְשׁוּהָ. וְעַכְשָׁו יֵשׁ לָנוּ לְהַקְשׁוֹת כָּאן, אִם הַתְּרוּמָה הַזּוֹ נְתָנָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה לְבַדּוֹ, אֵיךְ נְתָנָהּ לְאַחֵר, וְאָמַר שֶׁלִּבְנֵי יִשְׂרָאֵל יִקְחוּ אֶת הַתְּרוּמָה הַזּוֹ?</p>\n<p>אֶלָּא וַדַּאי שֶׁלְּמֹשֶׁה נְתָנָהּ, וְלֹא נְתָנָהּ לְאַחֵר. לְמֶלֶךְ שֶׁהָיָה בְּתוֹךְ עַמּוֹ, וְלֹא הָיְתָה הַגְּבִירָה עִם הַמֶּלֶךְ. כָּל זְמַן שֶׁהַגְּבִירָה לֹא הָיְתָה עִם הַמֶּלֶךְ, הָעָם לֹא קוֹבְעִים בּוֹ וְאֵינָם יוֹשְׁבִים לָבֶטַח. כֵּיוָן שֶׁבָּאָה הַגְּבִירָה, כָּל הָעָם שְׂמֵחִים וְיוֹשְׁבִים בְּבִטָּחוֹן. כָּךְ בַּתְּחִלָּה, אַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה לָהֶם נִסִּים וְאוֹתוֹת עַל יְדֵי מֹשֶׁה, לֹא קוֹבְעִים הָעָם. כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא וְיִקְחוּ לִי תְּרוּמָה - וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכֲכֶם. מִיָּד כֻּלָּם קָבְעוּ וְשָׂמְחוּ בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (במדבר ז) וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה, שֶׁיָּרְדָה כַּלַּת מֹשֶׁה לָאָרֶץ.</p>\n<p>וְאִם תֹּאמַר, \"וַיְהִי\" בְּכָל מָקוֹם אֵינוֹ אֶלָּא לְשׁוֹן צַעַר, וְכָאן כָּתוּב וַיְהִי בְּיוֹם? אֶלָּא, בְּאוֹתוֹ יוֹם שֶׁשְּׁכִינָה יָרְדָה לָאָרֶץ, נִמְצָא לָהּ מְקַטְרֵג, וְכִסָּה אוֹתוֹ הַחֹשֶׁךְ כְּנֶגְדָּהּ כְּדֵי שֶׁלֹּא תֵרֵד. וְשָׁנִינוּ, אֶלֶף וַחֲמֵשׁ מֵאוֹת רִבּוֹא מַלְאָכִים נִמְצְאוּ לְפָנֶיהָ כְּדֵי שֶׁלֹּא תֵרֵד.</p>\n<p>וּבְאוֹתוֹ זְמַן נִמְצְאוּ כָּל הַכֶּנֶס שֶׁל הַמַּלְאָכִים הָעֶלְיוֹנִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמְרוּ לְפָנָיו: רִבּוֹן הָעוֹלָם, כָּל הַזִּיו וְכָל הָאוֹר שֶׁלָּנוּ - בִּשְׁכִינַת כְּבוֹדְךְ הוּא, וְעַכְשָׁו תֵּרֵד לַתַּחְתּוֹנִים? בְּאוֹתָהּ שָׁעָה הִתְחַזְּקָה הַשְּׁכִינָה וְשִׁבְּרָה אוֹתוֹ חֹשֶׁךְ אֲפֵלָה כְּמִי שֶׁמְּשַׁבֵּר חֲתִיכוֹת חֲזָקוֹת, וְיָרְדָה לָאָרֶץ. כֵּיוָן שֶׁכֻּלָּם רָאוּ כָּךְ, פָּתְחוּ וְאָמְרוּ, (תהלים ח) ה' אֲדוֹנֵנוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ. אַדִּיר וַדַּאי, שֶׁשִּׁבְּרָה כַּמָּה חֲתִיכוֹת וְכֹחוֹת חֲזָקִים, וְיָרְדָה לָאָרֶץ וְשָׁלְטָה בַכֹּל. וְלָכֵן כָּתוּב וַיְהִי. הַצַּעַר שֶׁקִּבְּלוּ כַּמָּה חֲיָלוֹת וּמַחֲנוֹת בַּיּוֹם שֶׁיָּרְדָה לָאָרֶץ כַּלַּת מֹשֶׁה.</p>\n<p>וְלָכֵן וְיִקְחוּ לִי תְּרוּמָה וְגוֹ'. לֹא כָתוּב וְיִקְחוּ לִי וּתְרוּמָה, אֶלָּא וְיִקְחוּ לִי תְּרוּמָה, לְהַרְאוֹת שֶׁהַכֹּל אֶחָד בְּלִי פֵרוּד. וּמַעֲשֵׂה הַמִּשְׁכָּן כְּמוֹ שֶׁלְּמַעְלָה, זֶה כְּנֶגֶד זֶה, לְהַכְלִיל הַשְּׁכִינָה מִכָּל הַצְּדָדִים, מַעְלָה וּמַטָּה. כָּאן בָּעוֹלָם הַזֶּה הַמַּעֲשֶׂה שֶׁלּוֹ כְּמַעֲשֵׂה הַגּוּף, לְהַכְלִיל אֶת הָרוּחַ בְּתוֹכוֹ, וְזוֹהִי שְׁכִינָה, שֶׁנִּכְלְלָה מַעְלָה וּמַטָּה, וְהִיא רוּחַ הַקֹּדֶשׁ.</p>\n<p>וּלְעוֹלָם נִמְשֶׁכֶת וְנִכְנֶסֶת לְתוֹךְ סוֹד הַגּוּף, לְהַשְׁרוֹת מֹחַ בְּתוֹךְ קְלִפָּה הַכֹּל כָּרָאוּי. רוּחַ הַקֹּדֶשׁ הַזּוֹ נַעֲשֵׂית בְּגוּף, לְהַכְלִיל בְּתוֹכוֹ רוּחַ אַחֶרֶת עֶלְיוֹנָה, דַּק וּמֵאִיר, וְהַכֹּל כָּךְ נֶאֱחָז וְנִכְלָל זֶה בָּזֶה וְנִכְנָס זֶה בָּזֶה, עַד שֶׁנֶּאֱחָז בָּעוֹלָם הַזֶּה, שֶׁהוּא קְלִפָּה אַחֲרוֹנָה חִיצוֹנָה.</p>\n<p>קְלִפָּה חֲזָקָה הִיא לִפְנִים מִקְּלִפָּה שֶׁל הָעוֹלָם הַזֶּה. כְּמוֹ שֶׁהָאֱגוֹז, שֶׁהַקְּלִפָּה הַחִיצוֹנָה אֵינָהּ קָשָׁה, קְלִפָּה שֶׁהִיא לִפְנִים מִמֶּנָּה הִיא קְלִפָּה קָשָׁה - אַף כָּךְ לְמַעְלָה. קְלִפָּה קָשָׁה הִיא רוּחַ אַחֶרֶת שֶׁשּׁוֹלֶטֶת בַּגּוּף. לִפְנִים מִמֶּנּוּ הִיא קְלִפָּה קְלוּשָׁה. לִפְנִים מִמֶּנּוּ - הַמֹּחַ.</p>"],[9522011718,"<p>בָּאָרֶץ הַקְּדוֹשָׁה מְתֻקָּן הַכֹּל בְּגָוֶן אַחֵר, שֶׁהֲרֵי הַקְּלִפָּה הַקָּשָׁה נִשְׁבְּרָה מֵאוֹתוֹ מָקוֹם וְלֹא שׁוֹלֶטֶת בּוֹ כְּלָל. הַקְּלִפָּה הַקָּשָׁה נִשְׁבֶּרֶת שֶׁבֶר, (מההוא יותר תמיד) וְנִפְתַּחַת מִצַּד זֶה (עדשגאחזבסוד שלהמשכן. בעולם הזה הקלפה האחרונה היא לחוץ, הקלפה החזקה היא לפנים. כמו זה אף כך למעלה, הקלפה החזקה היא לחוץ. לפנים ממגה היא קלפהקלושה, ולאשולטתבו כלל, ונפתחת מצד זה) וּמִצַּד זֶה.</p>\n<p>וְאוֹתָהּ פְּתִיחָה הָיְתָה בָּאָרֶץ הַקְּדוֹשָׁה בְּכָל זְמַן שֶׁעוֹבְדִים עֲבוֹדָה כָּרָאוּי. כֵּיוָן שֶׁגָּרְמוּ הַחֲטָאִים, נִמְשְׁכָה אוֹתָהּ פְּתִיחָה לְצַד זֶה וּלְצַד זֶה, עַד שֶׁהִתְקָרְבָה הַקְּלִפָּה הַכֹּל כְּאֶחָד. כֵּיוָן שֶׁסָּתְמָה הַקְּלִפָּה אֶת הַמֹּחַ, אָז שׁוֹלֶטֶת אוֹתָהּ קְלִפָּה עֲלֵיהֶם, וְדוֹחָה אוֹתָם מִחוּץ לְאוֹתוֹ מָקוֹם.</p>\n<p>וְעִם כָּל זֶה, אַף עַל גַּב שֶׁדָּחֲתָה אוֹתָם הַחוּצָה, לֹא יְכוֹלָה אוֹתָהּ קְלִפָּה קָשָׁה לִשְׁלֹט בְּאוֹתוֹ מָקוֹם קָדוֹשׁ שֶׁאֵינוֹ מְקוֹמוֹ. וְאִם תֹּאמַר, אִם כָּךְ, הוֹאִיל וְלֹא יְכוֹלָה אוֹתָהּ קְלִפָּה קָשָׁה לִשְׁלֹט בְּאוֹתוֹ מָקוֹם קָדוֹשׁ, לָמָּה עוֹמֵד חָרוּב, שֶׁהֲרֵי אֵין חֻרְבָּן בָּעוֹלָם אֶלָּא רַק מִצַּד אוֹתָהּ קְלִפָּה קָשָׁה?</p>\n<p>אֶלָּא וַדַּאי כְּשֶׁנֶּחֱרַב, לֹא נֶחֱרַב אֶלָּא מֵאוֹתוֹ צַד, בְּשָׁעָה שֶׁסָּתַם אֶת הַמֹּחַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה שֶׁלֹּא תִשְׁלֹט אוֹתָהּ קְלִפָּה קָשָׁה עַל אוֹתוֹ מָקוֹם, וּכְשֶׁדָּחֲתָה אֶת יִשְׂרָאֵל מִמֶּנּוּ, אָז הַקְּלִפָּה חָזְרָה וְנִפְתְּחָה כְּמִקֹּדֶם. וּמִשּׁוּם שֶׁהָעָם הַקָּדוֹשׁ לֹא הָיוּ שָׁם, נִכְנְסָה עַל אוֹתָהּ פְּתִיחָה כִּסּוּי קָדוֹשׁ שֶׁל פָּרֹכֶת קְלוּשָׁה, לִשְׁמֹר אֶת אוֹתוֹ מָקוֹם שֶׁלֹּא יִסְתֹּם אֶת אוֹתָהּ קְלִפָּה קָשָׁה, וְאוֹחֵז בְּכָל צְדָדָיו.</p>\n<p>לִהְיוֹת מִשְׁחַת קֹדֶשׁ עַל הָאָרֶץ כְּמִקֹּדֶם לֹא יָכוֹל, שֶׁהֲרֵי אוֹתוֹ כִסּוּי קָלוּשׁ אָחוּז, שֶׁלֹּא יֵרֵד לְמַטָּה, שֶׁהֲרֵי הָעָם הַקָּדוֹשׁ אֵינוֹ שָׁם, וְלָכֵן לֹא נִבְנֶה הַחֻרְבָּן מִיּוֹם שֶׁנֶּחֶרְבוּ. שֶׁתִּשְׁלֹט אוֹתָהּ קְלִפָּה קָשָׁה, לֹא יְכוֹלָה, שֶׁהֲרֵי אוֹתוֹ כִסּוּי קָלוּשׁ אוֹחֵז בּוֹ בְּכָל צְדָדָיו בְּאוֹתָהּ פְּתִיחָה שֶׁלֹּא תִשְׁלֹט שָׁם וְלֹא תִסְתֹּם אֶת הַמֹּחַ בְּאוֹתוֹ כִסּוּי שֶׁל פָּרֹכֶת קְלוּשָׁה, שֶׁהִיא מִתּוֹךְ מְשִׁיכַת הַפָּרֹכֶת הַקְּדוֹשָׁה שֶׁלְּמַעְלָה, שֶׁשּׁוֹמֶרֶת אוֹתוֹ הַמָּקוֹם.</p>\n<p>וְלָכֵן כָּל אוֹתָן הַנְּשָׁמוֹת שֶׁל שְׁאָר הָעַמִּים שֶׁדָּרִים בָּאָרֶץ, כְּשֶׁיּוֹצְאוֹת מֵהָעוֹלָם הַזֶּה לֹא מְקַבְּלִים אוֹתָן, וְדוֹחִין אוֹתָן הַחוּצָה, וְהוֹלְכוֹת וּמְשׁוֹטְטוֹת וּמִתְגַּלְגְּלוֹת בְּכַמָּה גִלְגּוּלִים, עַד שֶׁיּוֹצְאוֹת מִכָּל הָאָרֶץ הַקְּדוֹשָׁה וְסוֹבְבוֹת (לסביבתם) לְצִדָּם בְּטֻמְאָתָן. וְכָל אוֹתָן נִשְׁמוֹת יִשְׂרָאֵל שֶׁיּוֹצְאוֹת שָׁם, עוֹלוֹת, וְאוֹתוֹ כִסּוּי קָלוּשׁ מְקַבֵּל אוֹתָן, וְנִכְנָסִים לִקְדֻשָּׁה עֶלְיוֹנָה, מִשּׁוּם שֶׁכָּל מִין הוֹלֵךְ לְמִינוֹ.</p>\n<p>וְנִשְׁמוֹת יִשְׂרָאֵל שֶׁיּוֹצְאוֹת לְחוּץ לָאָרֶץ בִּרְשׁוּתָהּ שֶׁל אוֹתָהּ קְלִפָּה קָשָׁה, הוֹלְכוֹת וְסוֹבְבוֹת וּמִתְגַּלְגְּלוֹת, עַד שֶׁשָּׁבוֹת לִמְקוֹמָן וְנִכְנָסוֹת לְמָקוֹם שֶׁרָאוּי לָהֶן. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּשְׁמָתוֹ יָצְאָה בָּרָשׁוּת הַקְּדוֹשָׁה בְּאוֹתָהּ פְּתִיחָה שֶׁל הָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>מִי שֶׁנִּשְׁמָתוֹ יוֹצֵאת בָּאָרֶץ הַקְּדוֹשָׁה - אִם נִקְבַּר בְּאוֹתוֹ יוֹם, לֹא שׁוֹלֵט עָלָיו רוּחַ טֻמְאָה כְּלָל, וְלָכֵן כָּתוּב בַּתָּלוּי, (דברים כא) כִּי קָבוֹר תִּקְבְּרֶנּוּ בַּיּוֹם הַהוּא (וגו') וְלֹא תְטַמֵּא אֶת אַדְמָתְךְ. מִשּׁוּם שֶׁבַּלַּיְלָה נִתְּנָה רְשׁוּת לְרוּחַ טֻמְאָה לְשׁוֹטֵט. וְאַף עַל גַּב שֶׁנִּתְּנָה לָהֶם רְשׁוּת, לֹא נִכְנָסִים לָאָרֶץ הַקְּדוֹשָׁה, פְּרָט אִם מוֹצְאִים שָׁם כְּלִי לְהִכָּנֵס בּוֹ.</p>\n<p>אֵיבָרִים וּפְדָרִים שֶׁנִּשְׂרָפִים בַּלַּיְלָה לְהָזִין מִינִים אֲחֵרִים, לֹא שֶׁנִּכְנָסִים לָאָרֶץ, וְלֹא לְהַמְשִׁיכָם לָאָרֶץ, אֶלָּא כְּדֵי שֶׁלֹּא יִשְׁלֹט הַצַּד הָאַחֵר בְּתוֹךְ הָאָרֶץ וְלֹא יִמָּשֵׁךְ לְהִכָּנֵס לְשָׁם. וְלָכֵן הֶעָשָׁן הָיָה עוֹלֶה מֵהֶם עָקֹם, וּמִתְגַּלְגֵּל הַחוּצָה וְהוֹלֵךְ (חזק) בְּחָפְזָה, עַד שֶׁנִּכְנָס לַנֶּקֶב שֶׁל הַצָּפוֹן שֶׁשָּׁם מְדוֹרֵי כָּל הַצְּדָדִים הָאֲחֵרִים, וְשָׁם נִכִנָס הֶעָשָׁן, וְכֻלָּם נִזּוֹנִים שָׁם.</p>\n<p>הֶעָֹשָׁן שֶׁל הַיּוֹם הָיָה עוֹלֶה לִמְקוֹמוֹ בְּדֶרֶךְ יָשָׁר, וּמֵזִין מַה שֶּׁמֵּזִין, וּמֵאוֹתָהּ פְּתִיחָה נִזּוֹנִים כָּל צִדְדֵי הַקְּלִפָּה הַקָּשָׁה שֶׁהִיא מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, וּמֵאוֹתוֹ עָשָׁן גַּס, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>גּוּפוֹת הַצַּדִּיקִים שֶׁלֹּא נִמְשְׁכוּ בָּעוֹלָם הַזֶּה אַחַר הַהֲנָאוֹת שֶׁל אוֹתָהּ קְלִפָּה קָשָׁה, לֹא שׁוֹלֶטֶת עֲלֵיהֶם רוּחַ טֻמְאָה כְּלָל, שֶׁהֲרֵי לֹא הִשְׁתַּתְּפוּ אַחֲרָיו כְּלוּם בָּעוֹלָם הַזֶּה. כְּמוֹ שֶׁגּוּף הָרְשָׁעִים (גופות הצדיקים שלא נמשכו אחר הנאות וכסופים של העולם הזה, אותה קלפה קשה לא שולטת עליהם, שהרי לא נמשכו אחריה בעולם הזה, שהרי כמו שגוף הרשעים) נִמְשָׁךְ בָּעוֹלָם הַזֶּה אַחַר אוֹתָהּ קְלִפָּה קָשָׁה וַהֲנָאוֹת וְהָעִנּוּגִים שֶׁלָּהּ וְהַתִּקּוּנִים שֶׁלָּהּ, כָּךְ נִטְמָא אַחַר שֶׁיּוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ.</p>\n<p>גּוּפוֹת הַצַּדִּיקִים שֶׁלֹּא מִתְעַנְּגִים בָּעוֹלָם הַזֶּה, אֶלָּא מִתַּעֲנוּגֵי מִצְוָה וּסְעוּדוֹת שַׁבָּתוֹת וְחַגִּים וּזְמַנִּים - אוֹתָהּ רוּחַ טֻמְאָה לֹא יְכוֹלָה לִשְׁלֹט עֲלֵיהֶם, שֶׁהֲרֵי לֹא הִתְעַנְּגוּ מִשֶּׁלָּהּ כְּלוּם. וְהוֹאִיל וְלֹא נָטְלוּ מִשֶּׁלָּהּ, אֵין לָהּ רְשׁוּת עֲלֵיהֶם כְּלָל. אַשְׁרֵי מִי שֶׁלֹּא נֶהֱנֶה מִשֶּׁלָּהּ כְּלוּם.</p>\n<p>מִי שֶׁנִּשְׁמָתוֹ יָצְאָה מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, וְאוֹתוֹ גוּף נִטְמָא בְּאוֹתָהּ רוּחַ טֻמְאָה - אוֹתָהּ רוּחַ טֻמְאָה נִשְׁאֶבֶת לְתוֹכוֹ, עַד שֶׁחוֹזֵר לֶעָפָר (שמתבלה הגוףבעפר). וְאִם אוֹתוֹ גוּף שֶׁנִּשְׁאֲבָה בּוֹ אוֹתָהּ רוּחַ טֻמְאָה מַעֲלִים אוֹתוֹ לְהִקָּבֵר בְּתוֹךְ הָאָרֶץ הַקְּדוֹשָׁה, עָלָיו כָּתוּב (ירמיה ב) וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. אַרְצִי, שֶׁלֹּא שָׁלְטָה עָלֶיהָ רוּחַ טֻמְאָה בְּאוֹתוֹ גוּף שֶׁלָּכֶם שֶׁנִּשְׁאֲבָה בּוֹ רוּחַ טֻמְאָה, שֶׁמְּבִיאִים לִקְבֹּר אוֹתוֹ בְּאַרְצִי - אַתֶּם מְטַמְּאִים אוֹתָהּ לְהִטָּמֵא בּוֹ. אִם לֹא שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא רְפוּאָה לָאָרֶץ, שֶׁהֲרֵי שֶׁכֵּיוָן שֶׁנִּבְלֶה אוֹתוֹ גוּף, מֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ מִלְמַעְלָה וְדוֹחֶה אֶת אוֹתָהּ רוּחַ טֻמְאָה הַחוּצָה, שֶׁהֲרֵי הוּא חָס עַל אַרְצוֹ.</p>\n<p>עֵל יוֹסֵף לֹא שָׁלַט גּוּפוֹ רוּחַ טֻמְאָה לְעוֹלָמִים, אַף עַל גַּב שֶׁנִּשְׁמָתוֹ יָצְאָה בְּרָשׁוּת אַחֶרֶת. מָה הַטַּעַם? כִּי לֹא נִמְשָׁךְ בְּחַיָּיו אַחַר רוּחַ טֻמְאָה, וְעִם כָּל זֶה לֹא רָצָה שֶׁיַּעֲלוּ אֶת גּוּפוֹ לְהִקָּבֵר בָּאָרֶץ הַקְּדוֹשָׁה, אֶלָּא אָמַר (בראשית נ) וְהַעֲלִתֶם אֶת עַצְמֹתַי, וְלֹא גוּפִי.</p>\n<p>יַעָקֹב לֹא מֵת, וְגוּפוֹ הִתְקַיֵּם בְּקִיּוּם תְּמִידִי וְלֹא פָחַד מֵהַצַּד הָאַחֵר, שֶׁהֲרֵי מִטָּתוֹ הָיְתָה שְׁלֵמָה בִּשְׁלֵמוּת הָאוֹר הָעֶלְיוֹן בְּאוֹר שֶׁל שְׁנֵים עָשָׂר שְׁבָטִים וּבְשִׁבְעִים נֶפֶשׁ, מִשּׁוּם כָּךְ לֹא פָחַד מֵהַצַּד הָאַחֵר וְלֹא יָכֹל לִשְׁלֹט עָלָיו. וְעוֹד, שֶׁהוּא גּוּף שֶׁל דְּיוֹקָן עֶלְיוֹן שֶׁיָּפְיוֹ אָחוּז לְכָל הַצְּדָדִים, וְכָל אוֹתָם אֵיבְרֵי אָדָם הָרִאשׁוֹן הָיוּ אֲחוּזִים בּוֹ, וְלָכֵן כָּתוּב בּוֹ (שם מז) וְשָׁכַבְתִּי עִם אֲבֹתַי וּנְשָׂאתַנִי מִמִּצְרַיִם. גּוּף שָׁלֵם. וְלָכֵן וַיַּחַנְטוּ הָרוֹפְאִים אֶת יִשְׂרָאֵל, שֶׁגּוּפוֹ יִהְיֶה עוֹמֵד בְּקִיּוּם. וְכָךְ צָרִיךְ שְׁאָר בְּנֵי הָעוֹלָם שֶׁנִּשְׁמָתָם יָצְאָה בָּאָרֶץ הַקְּדוֹשָׁה, הַנֶּפֶשׁ וְהַגּוּף נִצּוֹלִים מֵהַכֹּל.</p>"],[9522011719,"<p>בִּשְׁלשָה שֵׁמוֹת נִקְרֵאת נִשְׁמַת הָאָדָם: נֶפֶשׁ, רוּחַ, וּנְשָׁמָה. וְכֻלָּם כְּלוּלִים זֶה בָּזֶה, וּבִשְׁלֹשָׁה מְקוֹמוֹת נִמְצָא כֹחָם. הַנֶּפֶשׁ הַזּוֹ נִמְצֵאת בְּתוֹךְ הַקֶּבֶר עַד שֶׁהַגּוּף נִרְקָב בֶּעָפָר, וּבָזֶה הִיא מִתְגַּלְגֶּלֶת בָּעוֹלָם הַזֶּה לְהִמָּצֵא בְּתוֹךְ הַחַיִּים וְלָדַעַת בַּצַּעַר שֶׁלָּהֶם, וּבְשָׁעָה שֶׁהֵם צְרִיכִים, הִיא מְבַקֶּשֶׁת עֲלֵיהֶם רַחֲמִים.</p>\n<p>הָרוּחַ הַזּוֹ הִיא נִכְנֶסֶת לַגָּן שֶׁבָּאָרֶץ וּמִצְטַיֶּרֶת שָׁם בִּדְיוֹקַן הַגּוּף שֶׁל הָעוֹלָם הַזֶּה בְּמַלְבּוּשׁ אֶחָד שֶׁמִּתְלַבֶּשֶׁת שָׁם, וְזוֹ נֶהֱנֵית שָׁם בַּהֲנָאוֹת וְכִסּוּפִים בַּזִּיו שֶׁבַּגָּן, וּבְשַׁבָּתוֹת וָחֳדָשִׁים וּזְמַנִּים הִיא עוֹלָה לְמַעְלָה, וְנֶהֱנֵית שָׁם וְשָׁבָה לִמְקוֹמָהּ. וְלָכֵן כָּתוּב (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. תָּשׁוּב וַדַּאי, בַּזְּמַנִּים הַלָּלוּ שֶׁאָמַ רְנוּ.</p>\n<p>הַנְּשָׁמָה עוֹלָה מִיָּד לִמְקוֹמָהּ לְאוֹתוֹ מָקוֹם שֶׁיָּצְאָה מִמֶּנּוּ, וְזוֹהִי שֶׁבִּשְׁבִילָהּ מֵאִיר הַנֵּר לְהָאִיר לְמַעְלָה, זוֹ לֹא יוֹרֶדֶת לְמַטָּה לְעוֹלָמִים. בָּזֶה נִכְלֶלֶת מִי שֶׁנִּכְלֶלֶת מִכָּל הַצְּדָדִים, מִמַּעְלָה וּמִמַּטָּה. וְעַד שֶׁזּוֹ לֹא עוֹלָה לְהִתְקַשֵּׁר (במקומה) בַּכִּסֵּא, לֹא מִתְעַטֶּרֶת הָרוּחַ בַּגָּן שֶׁבָּאָרֶץ, וְהַנֶּפֶשׁ לֹא מִתְיַשֶּׁבֶת בִּמְקוֹמָהּ. כֵּיוָן שֶׁהִיא עוֹלָה, לְכֻלָּן יֵשׁ מְנוּחָה.</p>\n<p>וּכְשֶׁצָרִיךָ לִבְנֵי הָעוֹלָם, כְּשֶׁהֵם בְּצַעַר וְהוֹלְכִים לְבֵית הַקְּבָרוֹת, הַנֶּפֶשׁ הַזּוֹ מִתְעוֹרֶרֶת וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת וּמְעוֹרֶרֶת אֶת הָרוּחַ, וְאוֹתָהּ רוּחַ מְעוֹרֶרֶת אֵצֶל הָאָבוֹת, וְעוֹלָה וּמְעוֹרֶרֶת אֶת הַנְּשָׁמָה, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם, וַהֲרֵי בֵּאַרְנוּ. וְאַף עַל גַּב שֶׁהֲרֵי הִתְעוֹרְרוּ דִּבְרֵי הַנְּשָׁמָה הַלָּלוּ בִּגְוָנִים אֲחֵרִים, כֻּלָּם עוֹלִים בְּמִשְׁקָל זֶה, וְזֶהוּ בֵּרוּר הַדָּבָר, וְהַכֹּל אֶחָד.</p>\n<p>וּכְשֶׁהַנְּשָׁמָה מִתְעַכֶּבֶת מִלַּעֲלוֹת לִמְקוֹמָהּ, הָרוּחַ הוֹלֶכֶת וְעוֹמֶדֶת בְּפֶתַח הַגַּן עֵדֶן, וְלֹא פוֹתְחִים לָהּ פֶּתַח, וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת, וְאֵין מִי שֶׁיַּשְׁגִּיחַ בָּהּ. הַנֶּפֶשׁ הוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם, רוֹאָה אֶת הַגּוּף שֶׁמַּעֲלֶה תוֹלָעִים וּבְאוֹתוֹ דִין שֶׁל הַקֶּבֶר, וּמִתְאַבֶּלֶת עָלָיו, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁכָּתוּב, (איוב יד) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. וְהַכֹּל הוּא בְּעֹנֶשׁ. עַד שֶׁהַנְּשָׁמָה נִקְשֶׁרֶת בִּמְקוֹמָהּ לְמַעְלָה, וְאָז כֻּלָּם נִקְשָׁרִים בִּמְקוֹמָם.</p>\n<p>מִשּׁוּם שֶׁכָּל שְׁלֹשֶׁת אֵלּוּ הֵם בְּקֶשֶׁר אֶחָד, כְּמוֹ שֶׁלְּמַעְלָה, בְּסוֹד שֶׁל נֶפֶשׁ רוּחַ וּנְשָׁמָה, שֶׁהַכֹּל אֶחָד וְקֶשֶׁר אֶחָד. לַנֶּפֶשׁ אֵין לָהּ אוֹר מֵעַצְמָהּ כְּלוּם, וְזוֹהִי שֶׁמִּשְׁתַּתֶּפֶת בְּסוֹד שֶׁל גּוּף אֶחָד לְעַנְּגוֹ וְלָזוּן אוֹתוֹ בְּכָל מַה שֶּׁצָּרִיךְ, כְּמוֹ שֶׁנֶּאֱמַר (משלילא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. בֵּיתָהּ - זֶהוּ גוּפָהּ, שֶׁהִיא זָנָה אוֹתוֹ. וְנַעֲרֹתֶיהָ - אֵלּוּ הֵם הָאֵיבָרִים שֶׁל הַגּוּף הַזֶּה.</p>\n<p>הָרוּחַ, זֶהוּ שֶׁרוֹכֵב עַל הַנֶּפֶשׁ הַזּוֹ וְשׁוֹלֵט עָלֶיהָ וּמֵאִיר לָהּ בְּכָל מַה שֶּׁצָּרִיךְ, וְהַנֶּפֶשׁ הִיא כִּסֵּא לָרוּחַ הַזּוֹ. הַנְּשָׁמָה, הִיא מוֹצִיאָה אֶת הָרוּחַ הַזּוֹ, וְשׁוֹלֶטֶת עָלָיו וּמְאִירָה לוֹ בְּאוֹתוֹ אוֹר הַחַיִּים, וְאוֹתָהּ רוּחַ תְּלוּיָה בַּנְּשָׁמָה הַזּוֹ, וְנָאוֹר מִמֶּנָּה בְּאוֹתוֹ הָאוֹר שֶׁמֵּאִיר. אוֹתָהּ נֶפֶשׁ תְּלוּיָה בְּאוֹתָהּ רוּחַ, וּנְאוֹרָה מִמֶּנָּה וְנִזּוֹנֵית מִמֶּנָּה, וְהַכֹּל קֶשֶׁר אֶחָד.</p>\n<p>וְעַד שֶׁנְּשָׁמָה עֶלְיוֹנָה זוֹ לֹא עוֹלָה לְתוֹךְ נְבִיעַת עַתִּיק הָעַתִּיקִים, נִסְתַּר כָּל הַנִּסְתָּרִים, וּמִתְמַלֵּאת מִמֶּנּוּ, מִשּׁוּם שֶׁלֹּא פוֹסֵק - הָרוּחַ הַזּוֹ לֹא נִכְנֶסֶת לְגַן עֵדֶן, שֶׁהִיא נֶפֶשׁ, וּלְעוֹלָם הָרוּחַ לֹא שׁוֹרָה אֶלָּא בְּגַן עֵדֶן, וּנְשָׁמָה לְמַעְלָה. נֶפֶשׁ זוֹ מִתְיַשֶּׁבֶת (לא מתישבת) בִּמְקוֹמָהּ בְּתוֹךְ הַגּוּף לְמַטָּה.</p>\n<p>כְּמוֹ זֶה הַכֹּל לְמַטָּה כָּךְ נִפְרָדִים בָּאָדָם. וְאַף עַל גַּב שֶׁכֻּלָּם קֶשֶׁר אֶחָד, הַנְּשָׁמָה עוֹלָה לְמַעְלָה לְתוֹךְ נְבִיעַת הַבְּאֵר. הָרוּחַ נִכְנֶסֶת לְגַן עֵדֶן כְּמוֹ שֶׁלְּמַעְלָה. הַנֶּפֶשׁ מִתְיַשֶּׁבֶת בְּתוֹךְ הַקֶּבֶר. וְאִם תֹּאמַר, הַנֶּפֶשׁ לְמַעְלָה שֶׁמִּתְיַשֶּׁבֶת בְּתוֹךְ הַגּוּף בַּקֶּבֶר, אֵיפֹה הוּא הַקֶּבֶר? אֶלָּא בְּתוֹךְ אוֹתָהּ קְלִפָּה קָשָׁה, וְלָכֵן נֶפֶשׁ כְּמוֹ זוֹ שֶׁלְּמַטָּה, וְהַכֹּל זֶה כְּמוֹ זֶה, וְלָכֵן שָׁלֹשׁ דְּרָגוֹת נִפְרָדוֹת, וְהֵן קֶשֶׁר אֶחָד וְסוֹד אֶחָד.</p>\n<p>וּבְכָל זְמַן שֶׁהָעֲצָמוֹת נִמְצָאוֹת בְּתוֹךְ הַקֶּבֶר, הַנֶּפֶשׁ הַזּוֹ נִמְצֵאת שָׁם. כָּאן יֵשׁ סוֹד לְיוֹדְעֵי דֶרֶךְ הָאֱמֶת יִרְאֵי חֵטְא. בְּשָׁעָה שֶׁהַנְּשָׁמָה מִתְעַטֶּרֶת לְמַעְלָה בְּתוֹךְ הָעֲטָרָה הַקְּדוֹשָׁה, וְהָרוּחַ עוֹמֶדֶת בְּאוֹר עֶלְיוֹן בְּשַׁבָּתוֹת וָחֳדָשִׁים וּזְמַנִּים - הַנֶּפֶשׁ הַזּוֹ, בְּשָׁעָה שֶׁהָרוּחַ יוֹרֶדֶת מִתּוֹךְ הָאוֹר הָעֶלְיוֹן לָדוּר בְּגַן עֵדֶן מֵאִיר וְנוֹצֵץ, הִיא עוֹמֶדֶת בְּתוֹךְ הַקֶּבֶר וּמִתְגַּלֶּמֶת בַּדְּיוֹקָן שֶׁהָיָה בְּתוֹךְ הַגּוּף בַּתְּחִלָּה, וְכָל אוֹתָן עֲצָמוֹת עוֹלוֹת בְּאוֹתוֹ דְיוֹקָן, וּמְשַׁבְּחוֹת וּמוֹדוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (תהלים לה) כָּל עַצְמֹתַי תֹּאמַרְנָה ה' מִי כָמוֹךְ. לֹא כָתוּב אוֹמְרוֹת, אֶלָּא תֹּאמַרְנָה.</p>\n<p>וְאִלְמָלֵא נִתְּנָה רְשׁוּת לָעַיִן לִרְאוֹת, הָיְתָה רוֹאָה בַּלַּיְלָה כְּשֶׁנִּכְנֶסֶת (כשיוצאת) שַׁבָּת וְלֵילוֹת חֳדָשִׁים וּזְמַנִּים כְּמוֹ דְּמֻיּוֹת עַל גַּבֵּי הַקְּבָרִים מוֹדוֹת וּמְשַׁבְּחוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. אֲבָל טִפְּשׁוּת בְּנֵי הָאָדָם מְעַכֶּבֶת אוֹתָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים עַל מָה עוֹמְדִים בָּעוֹלָם הַזֶּה, וְלֹא חוֹשְׁשִׁים לְהַשְׁגִּיחַ בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן בָּעוֹלָם הַזֶּה, כָּל שֶׁכֵּן לְהַשְׁגִּיחַ בִּכְבוֹד אוֹתוֹ הָעוֹלָם, וְעַל מָה עוֹמֵד, וְאֵיךְ הַדְּבָרִים מִתְפָּרְשִׁים.</p>\n<p>בְּיוֹם רֹאשׁ הַשָּׁנָה, כְּשֶׁהָעוֹלָם נִדּוֹן וְכִסֵּא הַדִּין עוֹמֵד לַמֶּלֶךְ הָעֶלְיוֹן לָדוּן אֶת הָעוֹלָם, כָּל נֶפֶשׁ וָנֶפֶשׁ מְשׁוֹטְטוֹת וּמְבַקְשׁוֹת רַחֲמִים עַל הַחַיִּים. בַּלַּיְלָה שֶׁיּוֹצֵא יוֹם הַדִּין, הוֹלְכוֹת וּמְשׁוֹטְטוֹת לִשְׁמֹעַ וְלָדַעַת מַהוּ הַדִּין שֶׁנִּדּוֹן עַל הָעוֹלָם, וְלִפְעָמִים שֶׁמּוֹדִיעוֹת בְּמַרְאֶה לַחַיִּים, כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפֹל תַּרְדֵּמָה עַל אֲנָשִׁים וְגוֹ', אָז יִגְלֶה אֹזֶן אֲנָשִׁים וּבְמֹסָרָם יַחְתֹּם. מַה זֶּה מֹסָרָם? זוֹ הַנֶּפֶשׁ, שֶׁעוֹמֶדֶת וְחוֹתֶמֶת לַאֲנָשִׁים דְּבָרִים לְקַבֵּל מוּסָר.</p>\n<p>בַּלַּיְלָה הָאַחֲרוֹן שֶׁל הֶחָג, שֶׁיּוֹצְאִים הַפְּתָקִים מִבֵּית הַמֶּלֶךְ, וְאוֹתוֹ צֵל מוּסָר מִבְּנֵי הַנִּגְרָעִים שֶׁל הָעוֹלָם הַזֶּה אוֹתָהּ נֶפֶשׁ שֶׁאָמַרְנוּ הוֹלֶכֶת וּמְשׁוֹטֶטֶת, וּמְמֻנֶּה אֶחָד שׁוֹטֵר, בְּסוֹד חָקוּק בְּטַבַּעַת בִּכְתָב מְפֹרָשׁ, יְדוּמִיעָ\"ם, שֶׁפּוֹקֵד בִּכְתָב שֶׁל זִיו הֶחָקוּק וּבְתוֹךְ מַרְאוֹת עֶלְיוֹנִים יוֹרֵד בְּאוֹתוֹ לַיְלָה, וְכַמָּה אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת עִמּוֹ, וְנוֹטְלִים אוֹתוֹ צֵל מִכָּל אֶחָד וְאֶחָד וּמַעֲלִים אוֹתוֹ לְמַעְלָה.</p>\n<p>וְאוֹתָהּ נֶפֶשׁ שֶׁאָמַרְנוּ הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְרוֹאָה אֶת אוֹתוֹ צֵל, וְשָׁבָה לִמְקוֹמָהּ לְתוֹךְ הַקֶּבֶר, וּמַכְרִיזָה לִשְׁאָר הַמֵּתִים: פְּלוֹנִי יָבא אֵלֵינוּ, פְּלוֹנִי יָבא אֵלֵינוּ. אִם צַדִּיק טוֹב הוּא - כֻּלָּם שְׂמֵחִים. וְאִם לֹא - כֻּלָּם אוֹמְרִים אוֹי. כְּשֶׁמַּעֲלִים אוֹתוֹ צֵל, מַעֲלִים אוֹתוֹ לְאוֹתוֹ עֶבֶד נֶאֱמָן שֶׁשְּׁמוֹ מטטרו\"ן, וְנוֹטֵל אֵלָיו אוֹתוֹ הַצֵּל וּמַעֲלֶה אוֹתוֹ לִמְקוֹמוֹ, כְּמוֹ שֶׁנֶּאֱמַר (איוב ז) כְּעֶבֶד יִשְׁאַף צֵל. יִשְׁאַף צֵל וַדַּאי.</p>\n<p>מֵאוֹתָהּ שָׁעָה וְאֵילָךְ מְתֻקָּן מָקוֹם לְאוֹתָהּ נְשָׁמָה שֶׁל אוֹתוֹ אִישׁ, וּמָקוֹם לָרוּחַ בְּגַן עֵדֶן, וּמָקוֹם לַנֶּפֶשׁ לִמְנוּחָה וְלַהֲנָאָה בְּשָׁעָה שֶׁמְּשׁוֹטֶטֶת וְהוֹלֶכֶת, מִשּׁוּם שֶׁיֵּשׁ נֶפֶשׁ שֶׁאֵין לָהּ מְנוּחָה, וְיֵשׁ נֶפֶשׁ שֶׁמִּתְכַּלָּה עִם הַגּוּף.</p>\n<p>וְזוהִי שֶׁאֵין לָהּ מְנוּחָה, וְזוֹהִי שֶׁכָּתוּב בָּהּ וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. שֶׁזּוֹהִי שֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת וּמִתְגַּלְגֶּלֶת בְּכָל הָעוֹלָם, וְאֵין לָהּ מְנוּחָה כְּלָל יוֹמָם וָלַיְלָה, וְזֶהו עֹנֶשׁ יוֹתֵר מֵהַכֹּל וְאוֹתָהּ שֶׁתִּכְלֶה עִם הַגּוּף, (ההיא שכתובבה (ויקרא יז) והכרתי אתה מקרב עמה. ולזה אין לה זכרון כלל. ויש נפש שלא תכלה עם הגוף) וְתִכְלֶה מִמָּקוֹם אַחֵר (עליון) אוֹתָהּ שֶׁכָּתוּב בָּהּ (ויקרא כב) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מִלְּפָנַי אֲנִי ה'. מַה זֶּה מִלְּפָנַי? שֶׁלֹּא שׁוֹרָה עָלֶיהָ רוּחַ. וּכְשֶׁלֹּא שׁוֹרָה עָלֶיהָ רוּחַ, אֵין לָהּ שֻׁתָּפוּת כְּלָל בְּמַה שֶּׁלְּמַעְלָה, וְלֹא יוֹדַעַת מֵאוֹתָם דְּבָרִים שֶׁל אוֹתוֹ עוֹלָם כְּלָל, וְזוֹהִי נֶפֶשׁ כְּמוֹ שֶׁל הַבְּהֵמוֹת.</p>\n<p>נפש שֶׁאֵין (נפש שיש) לָהּ מְנוּחָה, זוֹהִי כְּשֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת, פּוֹגֶשֶׁת בַּמְמֻנֶּה הַזֶּה יְדוּמִיעָ\"ם, וּבְאוֹתָם הַשּׁוֹטְרִים שֶׁלּוֹ, וְנוֹטְלִים אוֹתָהּ וּמַכְנִיסִים אוֹתָהּ בְּכָל פִּתְחֵי גַּן הָעֵדֶן, וּמַרְאִים לָהּ אֶת כְּבוֹד הַצַּדִּיקִים וּכְבוֹד אוֹתָהּ הָרוּחַ שֶׁלָּהּ, וְהִיא נִדְבֶּקֶת בּוֹ בִּמְנוּחָה תּוֹךְ אוֹתוֹ הַלְּבוּשׁ, וְאָז יוֹדַעַת בְּאוֹתָם דְּבָרִים שֶׁל הָעוֹלָם.</p>\n<p>וּכְשֶׁאוֹתָהּ רוּחַ עוֹלָה לְהִתְעַטֵּר לְתוֹךְ הַנְּשָׁמָה הָעֶלְיוֹנָה לְמַעְלָה, אוֹתָהּ נֶפֶשׁ נִקְשֶׁרֶת בְּאוֹתָהּ רוּחַ וּנְאוֹרָה מִמֶּנָּה, כַּלְּבָנָה כְּשֶׁנְּאוֹרָה מֵהַשֶּׁמֶשׁ, וְהָרוּחַ נִקְשֶׁרֶת לְתוֹךְ אוֹתָהּ נְשָׁמָה, וְאוֹתָהּ נְשָׁמָה נִקְשֶׁרֶת לְתוֹךְ סוֹף הַמַּחֲשָׁבָה, שֶׁהִיא סוֹד הַנֶּפֶשׁ שֶׁלְּמַעְלָה.</p>\n<p>וְאוֹתָהּ נֶפֶשׁ נִקְשֶׁרֶת תּוֹךְ אוֹתָהּ רוּחַ עֶלְיוֹנָה, וְאוֹתָהּ רוּחַ נִקְשֶׁרֶת לְתוֹךְ אוֹתָהּ נְשָׁמָה עֶלְיוֹנָה, וְאוֹתָהּ נְשָׁמָה נִקְשֶׁרֶת בָּאֵין סוֹף. וְאָז הוּא מְנוּחַת הַכֹּל וְקֶשֶׁר שֶׁל הַכֹּל לְמַעְלָה וּלְמַטָּה, הַכֹּל בְּסוֹד אֶחָד וְגָוֶן אֶחָד.</p>\n<p>וְאָז זוֹהִי מְנוּחָה לַנֶּפֶשׁ שֶׁלְּמַטָּה, וְעַל זֶה כָּתוּב (שמואל א כה) וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים אֵת ה' אֱלֹהֶיךְ. בְּגָוֶן אֶחָד וּבְסוֹד אֶחָד. שֶׁאוֹתוֹ אֵת, זֶה כְּמוֹ זֶה.</p>\n<p>כְּשֶׁיּוֹרֶדֶת הַלְּבָנָה בְּסוֹד הַנֶּפֶשׁ הָעֶלְיוֹנָה, מְאִירָה מִכָּל הַצְּדָדִים. הִיא מְאִירָה לְכָל הַמֶּרְכָּבוֹת וְהַמַּחֲנוֹת וְעוֹשָׂה לָהֶם גּוּף אֶחָד שָׁלֵם שֶׁמֵּאִיר בְּאוֹר בַּזִּיו הָעֶלְיוֹן. אַף כָּךְ כְּמוֹ זֶה יוֹרֶדֶת הַנֶּפֶשׁ הַתַּחְתּוֹנָה הַזּוֹ מְאִירָה לְכָל הַצְּדָדִים מִתּוֹךְ אוֹר הַנְּשָׁמָה, וּמִתּוֹךְ אוֹר הָרוּחַ, וְיוֹרֶדֶת וּמְאִירָה לְכָל אוֹתָם מֶרְכָּבוֹת וּמַחֲנוֹת, שֶׁהֵם אֵיבָרִים וַעֲצָמוֹת, וְעוֹשָׂה אוֹתָם גּוּף שָׁלֵם שֶׁמֵּאִיר בְּאוֹר.</p>\n<p>זְהִוּ שֶׁכָּתוּב (ישעיה נח) וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. נַפְשֶׁךְ מַמָּשׁ. וְאַחַר כָּךְ - וְעַצְמֹתֶיךְ יַחֲלִיץ, שֶׁעוֹשֶׂה מֵהֶם גּוּף שָׁלֵם, וּמֵאִיר בְּאוֹר, וְקָם וּמוֹדֶה וּמְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁכָּתוּב (תהלים לה) כָּל עַצְמֹתַי תֹּאמַרְנָה ה' מִי כָמוֹךְ. וְזוֹהִי מְנוּחַת הַנֶּפֶשׁ וַדַּאי מִכָּל הַצְּדָדִים.</p>\n<p>אַשְׁרֵי הַצַּדִּיקִים שֶׁפּוֹחֲדִים מֵרִבּוֹנָם בָּעוֹלָם הַזֶּה לִזְכּוֹת בְּשָׁלֹשׁ מְנוּחוֹת לָעוֹלָם הַבָּא. בָּא רַבִּי שִׁמְעוֹן וּבֵרְכוֹ אֶת רַבִּי אַבָּא. אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵיכֶם בָּנַי, וְאַשְׁרַי שֶׁעֵינַי רָאוּ בְּכָךְ. כַּמָּה מְקוֹמוֹת עֶלְיוֹנִים מְתֻקָּנִים לָנוּ וּמְאִירִים לָנוּ לָעוֹלָם הַבָּא.</p>"],[9522011720,"<p>פָּתַח וְאָמַר, (תהלים קכה) שִׁיר הַמַּעֲלוֹת הַבּטְחִים בַּה' כְּהַר צִיּוֹן לֹא יִמּוֹט לְעוֹלָם יֵשֵׁב. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל שִׁיר הַמַּעֲלוֹת - תִּשְׁבַּחַת שֶׁאוֹמְרוֹת אוֹתָן דְּרָגוֹת קְדוֹשׁוֹת עֶלְיוֹנוֹת מִצַּד שֶׁל הַגְּבוּרוֹת הָעֶלְיוֹנוֹת, וְהֵם כְּמוֹ הַלְוִיִּם שֶׁלְּמַטָּה, וְהֵם מַעֲלוֹת, דְּרָגוֹת עַל דְּרָגוֹת, וְעוֹבְדִים בְּסוֹד שֶׁל חֲמִשִּׁים שָׁנִים. וְזֶהוּ שִׁיר</p>\n<p>הַמַּעֲלוֹת הַבּטְחִים בַּה' כְּהַר צִיּוֹן, אֵלּוּ הֵם הַצַּדִּיקִים שֶׁבּוֹטְחִים בּוֹ בַּמַּעֲשִׂים שֶׁלָּהֶם, כְּמוֹ שֶׁנֶּאֱמַר (משלי כח) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וְאִם תֹּאמַר, הֲרֵי הַצַּדִּיקִים לֹא בוֹטְחִים בְּמַעֲשֵׂיהֶם כְּלָל וְתָמִיד פּוֹחֲדִים, כְּמוֹ אַבְרָהָם שֶׁכָּתוּב בּוֹ (בראשיתיב) וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבוֹא מִצְרָיְמָה וְגוֹ', כְּמוֹ יִצְחָק שֶׁכָּתוּב בּוֹ (שם כו) כִּי יָרֵא לֵאמֹר אִשְׁתִּי. כְּיַעֲקֹב שֶׁכָּתוּב בּוֹ (שם לב) וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ. וְאִם אֵלֶּה לֹא בָטְחוּ בְּמַעֲשֵׂיהֶם, כָּל שֶׁכֵּן שְׁאָר צַדִּיקֵי הָעוֹלָם, וְאַתָּה אוֹמֵר וְצַדִּיקִים כִּכְפִיר יִבְטָח?!</p>\n<p>אֶלָּא וַדַּאי כָּתוּב כִּכְפִיר, שֶׁהֲרֵי מִכָּל אוֹתָם שֵׁמוֹת לֹא כָתוּב אֶלָּא כְּפִיר, וְלֹא כָתוּב לֹא אַרְיֵה וְלֹא שַׁחַל וְלֹא שַׁחַץ - אֶלָּא כְּפִיר, שֶׁהוּא הַחַלָּשׁ וְהַקָּטָן מִכֻּלָּם וְלֹא בוֹטֵחַ בְּכֹחוֹ אַף עַל גַּב שֶׁהוּא חָזָק. כָּךְ הַצַּדִּיקִים לֹא בוֹטְחִים בְּמַעֲשֵׂיהֶם עַכְשָׁו אֶלָּא כִּכְפִיר. אַף עַל גַּב שֶׁיּוֹדְעִים שֶׁחָזָק כֹּחַ מַעֲשֵׂיהֶם, לֹא בוֹטְחִים אֶלָּא כִּכְפִיר, וְלֹא יוֹתֵר.</p>\n<p>וְלָכֵן הַבּטְחִים בַּה' כְּהַר צִיּוֹן וְגוֹ', לֹא כִּכְפִיר וְלֹא כְּאַרְיֵה וְלֹא כְּמוֹ כָּל הַשֵּׁמוֹת, אֶלָּא כְּהַר צִיּוֹן. וּפֵרְשׁוּהָ, מַה הַר צִיּוֹן הוּא חָזָק וְלֹא יִמּוֹט תָּמִיד, אַף כָּךְ בְּאוֹתוֹ זְמַן יִהְיוּ כְּמוֹ הַר צִיּוֹן, וְלֹא כְּמוֹ עַכְשָׁו שֶׁלֹּא בוֹטְחִים, אֶלָּא כִּכְפִיר שֶׁפּוֹחֵד וְלֹא בוֹטֵחַ בְּכֹחוֹ. וְאַתֶּם בְּנֵי קְדוֹשִׁים עֶלְיוֹנִים, בִּטְחוֹנְכֶם כְּהַר צִיּוֹן, וַדַּאי אַשְׁרֵיכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>הָלְכוּ, כְּשֶׁהִגִּיעוּ לָעִיר נֶחְשַׁךְ הַלַּיְלָה. אָמַר רַבִּי שִׁמְעוֹן, כְּמוֹ שֶׁיּוֹם זֶה מֵאִיר לָנוּ בַּדֶּרֶךְ הַזּוֹ לִזְכּוֹת בּוֹ בָּעוֹלָם הַבָּא, אַף כָּךְ הַלַּיְלָה הַזֶּה יָאִיר לָנוּ לְזַכּוֹתֵנוּ לָעוֹלָם הַבָּא, וּלְעַטֵּר דְּבָרִים שֶׁל הַיּוֹם בַּלַּיְלָה הַזֶּה לִפְנֵי עַתִּיק הַיָּמִים. שֶׁהֲרֵי כְּמוֹ הַיּוֹם הַשָּׁלֵם הַזֶּה לֹא יִמָּצֵא בְּכָל הַדּוֹרוֹת הָאֲחֵרִים. אַשְׁרֵי חֶלְקֵנוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>נִכְנְסוּ לְבֵיתוֹ שֶׁל רַבִּי שִׁמְעוֹן, וְרַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְרַבִּי יוֹסֵי עִמָּם. לָנוּ עַד שֶׁנֶּחֱלַק הַלַּיְלָה. כֵּיוָן שֶׁנֶּחֱלַק הַלַּיְלָה, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, זְמַן הוּא לְעַטֵּר אֶת הַמֶּרְכָּבָה הַקְּדוֹשָׁה לְמַעְלָה בְּהִשְׁתַּדְּלוּתֵנוּ. אָמַר לְרַבִּי יוֹסֵי, אַתָּה שֶׁלֹּא נִשְׁמְעוּ דְבָרֶיךְ בַּיּוֹם הַזֶּה בֵּינֵינוּ, אַתָּה תִּהְיֶה רֵאשִׁית לְהָאִיר הַלַּיְלָה, שֶׁהֲרֵי עַכְשָׁו עֵת רָצוֹן הִיא לְהָאִיר מַעְלָה וּמַטָּה.</p>"],[9522011721,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה. שִׁיר זֶה עוֹרֵר אוֹתָהּ שְׁלֹמֹה הַמֶּלֶךְ כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ, וְכָל הָעוֹלָמוֹת נִשְׁלְמוּ, מַעְלָה וּמַטָּה, בִּשְׁלֵמוּת אַחַת. וְאַף עַל גַּב שֶׁהַחֲבֵרִים חָלְקוּ בָזֶה (מתי נאמר), אֲבָל שִׁירָה זוֹ לֹא נֶאֶמְרָה אֶלָּא בִּשְׁלֵמוּת. כְּשֶׁהַלְּבָנָה הִתְמַלְּאָה בִּשְׁלֵמוּת, וּבֵית הַמִּקְדָּשׁ נִבְנָה כְּמוֹ שֶׁלְּמַעְלָה בְּשָׁעָה שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ לְמַטָּה, לֹא הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם כְּמוֹ אוֹתוֹ הַיּוֹם.</p>\n<p>הַמִּשְׁכָּן שֶׁעָשָׂה מֹשֶׁה בַּמִּדְבָּר לְהוֹרִיד שְׁכִינָה לָאָרֶץ, בְּאוֹתוֹ יוֹם הוּקַם מִשְׁכָּן אַחֵר עִמּוֹ לְמַעְלָה, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁכָּתוּב (שמות מ) הוּקַם הַמִּשְׁכָּן. הַמִּשְׁכָּן - מִשְׁכָּן אַחֵר שֶׁהוּקַם עִמּוֹ, וְזֶה מִשְׁכַּן הַנַּעַר מטטרו\"ן, וְלֹא יוֹתֵר. כְּשֶׁנִּבְנָה בַּיִת רִאשׁוֹן, בַּיִת רִאשׁוֹן אַחֵר נִבְנָה עִמּוֹ, וְהִתְקַיֵּם בְּכָל הָעוֹלָמוֹת וְהֵאִיר (בעולם והאיר) לְכָל הָעוֹלָמוֹת, וְהִתְבַּשֵּׂם הָעוֹלָם, וְנִפְתְּחוּ כָּל הַמַּשְׁקוֹפִים הָעֶלְיוֹנִים לְהָאִיר, וְלֹא הָיְתָה שִׂמְחָה בְּכָל הָעוֹלָמוֹת כְּמוֹ אוֹתוֹ הַיּוֹם. אָז פָּתְחוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְאָמְרוּ שִׁירָה, וְזֶהוּ שִׁיר הַשִּׁירִים. שִׁיר שֶׁאוֹתָם הַמְנַגְּנִים שֶׁמְּנַגְּנִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>דָּוִד הַמֶּלֶךְ אָמַר שִׁיר הַמַּעֲלוֹת. שְׁלֹמֹה הַמֶּלֶךְ אָמַר שִׁיר הַשִּׁירִים, שִׁיר מֵאוֹתָם מְנַגְּנִים. מַה בֵּין זֶה לָזֶה, שֶׁהֲרֵי נִשְׁמָע שֶׁהַכֹּל אֶחָד? אֶלָּא וַדַּאי שֶׁהַכֹּל אֶחָד, אֲבָל בִּימֵי דָוִד הַמֶּלֶךְ לֹא הָיוּ כָּל אוֹתָם מְנַגְּנִים מְתֻקָּנִים בִּמְקוֹמָם לְנַגֵּן כָּרָאוּי, וּבֵית הַמִּקְדָּשׁ לֹא נִבְנָה, וְלָכֵן לֹא הִתְתַּקְּנוּ לְמַעְלָה בִּמְקוֹמָם. שֶׁהֶרֵי כְּמוֹ שֶׁיֵּשׁ תִּקּוּנֵי מִשְׁמָרוֹת בָּאָרֶץ, אַף כָּךְ בָּרָקִיעַ, וְעוֹמְדִים אֵלֶּה כְּנֶגֶד אֵלֶּה.</p>\n<p>וּבַיּוֹם שֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ נִתְקְנוּ כֻלָּם בִּמְקוֹמָם, וְהַנֵּר שֶׁלֹּא מֵאִיר הִתְחִיל לְהָאִיר. וְשִׁירָה זוֹ נִתְקְנָה לַמֶּלֶךְ הָעֶלְיוֹן, הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. וְהַתִּשְׁבַּחַת הַזּוֹ הִיא מְעֻלָּה מִכָּל הַתִּשְׁבָּחוֹת הָרִאשׁוֹנוֹת. הַיּוֹם שֶׁהִתְגַּלְּתָה תִשְׁבַּחַת זוֹ (בעולם) בָּאָרֶץ, בְּאוֹתוֹ יוֹם נִמְצְאָה שְׁלֵמוּת בַּכֹּל, וְלָכֵן הוּא קֹדֶשׁ קָדָשִׁים.</p>\n<p>בַּסֵּפֶר שֶׁל אָדָם הָרִאשׁוֹן הָיָה כָּתוּב בּוֹ, בַּיּוֹם שֶׁיּוּקַם הַמִּשְׁכָּן (שיבנה בית המקדש) יְעוֹרְרוּ הָאָבוֹת שִׁירָה מַעְלָה וּמַטָּה. וּמִשּׁוּם כָּךְ מָצָאנוּ שִׁין מֵאוֹתִיּוֹת גְּדוֹלוֹת. וְאֵלֶּה הֵם שֶׁעוֹרְרוּ, לֹא שֶׁהֵם מְנַגְּנִים, אֶלָּא שֶׁהֵם מְעוֹרְרִים אֶל מַעְלָה. (כביכול) שִׁיר שֶׁל אוֹתָם גְּדוֹלִים שֶׁמְּמֻנִּים עַל כָּל הָעוֹלָמוֹת.</p>\n<p>וְשָׁנִינוּ, בְּאוֹתוֹ יוֹם עָמַד יַעֲקֹב הַשָּׁלֵם וְנִכְנַס לְגַן עֵדֶן בְּשִׂמְחָה עַל מְקוֹמוֹ, וְאָז גַּן הָעֵדֶן הִתְחִיל לְנַגֵּן, וְכָל אוֹתָם בְּשָׂמִים שֶׁל הַגָּן. מִי גָרַם שִׁירָה זוֹ וּמִי אָמַר אוֹתָהּ? הֱוֵה אוֹמֵר, זֶה יַעֲקֹב. שֶׁאִלְמָלֵא הוּא לֹא נִכְנַס לְגַן הָעֵדֶן, לֹא אָמַר הַגָּן שִׁירָה.</p>\n<p>שִירָה זוֹ שִׁירָה, שֶׁהִיא כְּלָל שֶׁל כָּל הַתּוֹרָה. שִׁירָה שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים מִתְעוֹרְרִים אֵלֶיהָ. שִׁירָה שֶׁהִיא כְּמוֹ הָעוֹלָם שֶׁלְּמַעְלָה, שֶׁהוּא שַׁבָּת הָעֶלְיוֹנָה. שִׁירָה שֶׁהַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן מִתְעַטֵּר בִּשְׁבִילָהּ, וְלָכֵן הוּא קֹדֶשׁ קָדָשִׁים. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל דְּבָרָיו בְּאַהֲבָה וְשִׂמְחָה הַכֹּל. (וזה) מִשּׁוּם שֶׁכּוֹס שֶׁל בְּרָכָה נִתֶּנֶת בְּיָמִין. כֵּיוָן שֶׁנִּתֶּנֶת בְּיָמִין, אָז כָּל הַשִּׂמְחָה וְכָל הָאַהֲבָה נִמְצָאִים. וְלָכֵן כָּל דְּבָרָיו בְּאַהֲבָה וְשִׂמְחָה.</p>\n<p>בִּזְמַן שֶׁהַיָּמִין הַזּוֹ חוֹזֶרֶת לְאָחוֹר, כְּמוֹ שֶׁנֶּאֱמַר הֵשִׁיב אָחוֹר יְמִינוֹ, אָז כּוֹס שֶׁל בְּרָכָה נִתֶּנֶת בִּשְׂמֹאל. כֵּיוָן שֶׁנִּתְּנָה בִּשְׂמֹאל, מַתְחִילִים עֶלְיוֹנִים וְתַחְתּוֹנִים לִפְתֹּחַ עָלָיו קִינָה. וּמָה אוֹמְרִים? אֵיכָה. אֵי כָּה. אֵי כּוֹס שֶׁל בְּרָכָה, שֶׁמָּקוֹם עֶלְיוֹן שֶׁהָיְתָה יוֹשֶׁבֶת בְּתוֹכוֹ נִמְנָע וְנִגְרָע מִמֶּנָּה. מִשּׁוּם כָּךְ שִׁיר הַשִּׁירִים, שֶׁהָיָה מִצַּד הַיָּמִין, כָּל דְּבָרָיו בְּאַהֲבָה וְשִׂמְחָה. אֵיכָה, שֶׁחָסֵר הַיָּמִין וְנִמְצָא הַשְּׂמֹאל, כָּל דְּבָרָיו קִנְטוּרִים וְקִינוֹת.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּל שִׂמְחָה וְכָל חֶדְוָה וְכָל שִׁיר הוּא מִצַּד הַשְּׂמֹאל, וְלָכֵן הַלְוִיִּם מִצַּד הַשְּׂמֹאל מְנַגְּנִים שִׁירָה. אֶלָּא כָּל שִׂמְחָה שֶׁנִּמְצֵאת מִצַּד הַשְּׂמֹאל, לֹא נִמְצָא אֶלָּא בִּזְמַן שֶׁהַיָּמִין נִדְבָּק עִמּוֹ. וּבִזְמַן שֶׁהַיָּמִין מִתְעוֹרֵר וְנִדְבָּק עִמּוֹ, אָז אוֹתָהּ חֶדְוָה מִיָּמִין מֵיטִיבָה אֶת הַכַּעַס. וּכְשֶׁהַכַּעַס שׁוֹכֵךְ וְהַשִּׂמְחָה הִיא מִצַּד הַיָּמִין, אָז חֶדְוָה שְׁלֵמָה בָּאָה מֵהַצַּד הַזֶּה.</p>\n<p>וּכְשֶׁיָּמִין לֹא נִמְצָא, הַכַּעַס שֶׁל הַשְּׂמֹאל רַב, וְלֹא שׁוֹכֵךְ וְלֹא מֵיטִיב וְלֹא מְשַׂמֵּחַ, וְאָז אֵיכָה. אֵי כָּה. כּוֹס שֶׁל בְּרָכָה מַה תְּהֵא עָלֶיהָ? שֶׁהֲרֵי יוֹשֶׁבֶת בִּשְׂמֹאל, וְהַכַּעַס רַב וְלֹא שׁוֹכֵךְ. וַדַּאי מִתְעוֹרְרִים קִנְטוּרִים וְקִינוֹת.</p>\n<p>אֲבָל שִׁיר הַשִּׁירִים, וַדַּאי כּוֹס שֶׁל בְּרָכָה שֶׁנִּתֶּנֶת בְּיָמִין וְנִמְסָר בְּתוֹכוֹ, וְלָכֵן נִמְצָאִים כָּל הָאַהֲבָה וְכָל הַשִּׂמְחָה, וְלָכֵן כָּל דְּבָרָיו בְּאַהֲבָה וְחֶדְוָה, וְלֹא נִמְצָא בִּשְׁאָר כָּל הַשִּׁירִים שֶׁל הָעוֹלָם כָּךְ, וְלָכֵן מִצַּד הָאָבוֹת הִתְעוֹרְרָה שִׁירָה זוֹ.</p>\n<p>הַיּוֹם שֶׁהִתְגַּלְּתָה הַשִּׁירָה הַזּוֹ, בְּאוֹתוֹ יוֹם יָרְדָה שְׁכִינָה לָאָרֶץ, שֶׁכָּתוּב (מלכים א ח) וְלֹא יָכְלוּ הַכֹּהֲנִים לַעֲמֹד לְשָׁרֵת וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם כִּי מָלֵא כְבוֹד ה' אֶת בֵּית ה'. בְּאוֹתוֹ יוֹם מַמָּשׁ הִתְגַּלְּתָה הַתִּשְׁבַּחַת הַזֹּאת, וְאָמַר אוֹתָהּ שְׁלֹמֹה בְּרוּחַ הַקֹּדֶשׁ.</p>\n<p>תִּשְׁבַּחַת הַשִּׁירָה הַזּוֹ הִיא כְּלָל שֶׁל כָּל הַתּוֹרָה. הַכְּלָל שֶׁל כָּל מַעֲשֵׂה בְרֵאשִׁית. הַכְּלָל שֶׁל סוֹד הָאָבוֹת. הַכְּלָל שֶׁל גָּלוּת מִצְרַיִם, וּכְשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְתִשְׁבַּחַת הַיָּם. הַכְּלָל שֶׁל יוֹ\"ד אֲמִירוֹת וְקִיּוּם שֶׁל הַר סִינַי. וּכְשֶׁהָלְכוּ יִשְׂרָאֵל בַּמִּדְבָּר, עַד שֶׁנִּכְנְסוּ לָאָרֶץ וְנִבְנָה בֵּית הַמִּקְדָּשׁ. הַכְּלָל שֶׁל עִטּוּר הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן בְּאַהֲבָה וְשִׂמְחָה. הַכְּלָל שֶׁל גָּלוּת יִשְׂרָאֵל בֵּין הָעַמִּים וְהַגְּאֻלָּה שֶׁלָּהֶם. הַכְּלָל שֶׁל תְּחִיַּת הַמֵּתִים, עַד לַיּוֹם שֶׁהוּא שַׁבָּת לַה'. מַה שֶּׁהָיָה, וּמַה שֶּׁיִּהְיֶה, וּמַה שֶּׁעָתִיד לִהְיוֹת אַחַר הַיּוֹם הַשְּׁבִיעִי, כְּשֶׁתִּהְיֶה שַׁבָּת לַה', הַכֹּל נִמְצָא בְּשִׁיר הַשִּׁירִים.</p>\n<p>וְעַל זֶה שָׁנִינוּ, כָּל מִי שֶׁמּוֹצִיא פָסוּק שֶׁל שִׁיר הַשִּׁירִים וְאוֹמֵר אוֹתוֹ בְּבֵית הַמִּשְׁתֶּה, הַתּוֹרָה חוֹגֶרֶת שַׂק, וְעוֹלָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא וְאוֹמֶרֶת לְפָנָיו: עָשׂוּ אוֹתִי בָּנֶיךְ צְחוֹק בְּבֵית הַמִּשְׁתֶּה. וַדַּאי שֶׁתּוֹרָה עוֹלָה וְאוֹמֶרֶת כָּךְ. וְלָכֵן צָרִיךְ לִשְׁמֹר וּלְהַעֲלוֹת עֲטָרָה עַל רֹאשׁ הָאָדָם כָּל דָּבָר וְדָבָר שֶׁל שִׁיר הַשִּׁירִים.</p>\n<p>וְאִם תֹּאמַר, לָמָּה הוּא בֵּין הַכְּתוּבִים? - כָּךְ זֶה וַדַּאי, מִשּׁוּם שֶׁהוּא שִׁיר תִּשְׁבַּחְתָּהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל שֶׁמִּתְעַטֶּרֶת לְמַעְלָה. וְלָכֵן כָּל הַתִּשְׁבָּחוֹת שֶׁבָּעוֹלָם לֹא מַעֲלוֹת רָצוֹן לַקָּדוֹשׁ-בָּרוּךְ-הוּא כְּמוֹ הַתִּשְׁבַּחַת הַ את.</p>\n<p>כָּךָ לָמַדְנוּ: שִׁיר - אֶחָד. הַשִּׁירִים - שְׁנַיִם. אֲשֶׁר - הֲרֵי שְׁלֹשָׁה. וְסוֹד זֶה - שֶׁנִּתְּנָה כּוֹס שֶׁל בְּרָכָה וְנִטֶּלֶת בֵּין יָמִין וּשְׂמֹאל. וְהַכֹּל מִתְעוֹרֵר לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. וּבָזֶה עוֹלֶה רָצוֹן לְמַעְלָה לְמַעְלָה בְּסוֹד הָאֵין סוֹף. כָּאן נִמְצֵאת מֶרְכָּבָה קְדוֹשָׁה, שֶׁהֲרֵי הָאָבוֹת הֵם הַמֶּרְכָּבָה, וְדָוִד הַמֶּלֶךְ מִתְחַבֵּר עִמָּם, וְהֵם אַרְבָּעָה, סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה (חכמה בינה תפארת ומלכות, או חסד גבורה תפארת ומלכות). וְלָכֵן אַרְבַּע תֵּבוֹת בַּפָּסוּק הָרִאשׁוֹן הַזֶּה, סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה הַשְּׁלֵמָה.</p>\n<p>עוֹד סוֹד זֶה, שִׁיר - זֶה סוֹד שֶׁל דָּוִד הַמֶּלֶךְ, שֶׁהוּא סוֹד לַעֲלוֹת בְּשִׁיר. הַשִּׁירִים - אֵלּוּ הָאָבוֹת, סוֹד הַמְמֻנִּים הַגְּדוֹלִים, מֶרְכָּבָה שְׁלֵמָה כָּרָאוּי. אֲשֶׁר לִשְׁלֹמֹה - סוֹד מִי שֶׁרוֹכֵב עַל הַמֶּרְכָּבָה הַשְּׁלֵמָה הַזּוֹ.</p>\n<p>וּבַפָּסוּק הַזֶּה נִמְצֵאת שְׁלֵמוּת שֶׁל הַסּוֹד מִן הָעוֹלָם וְעַד הָעוֹלָם, הַסּוֹד שֶׁל כָּל הָאֱמוּנָה. וְהַכֹּל הוּא מֶרְכָּבָה שְׁלֵמָה לְמִי שֶׁיּוֹדֵעַ וּלְמִי שֶׁלֹּא נוֹדַע, וְאֵין מִי שֶׁעוֹמֵד לָדַעַת בּוֹ. וְלָכֵן נֶאֱמַר הַפָּסוּק הַזֶּה בְּאַרְבַּע תֵּבוֹת, סוֹד הַמֶּרְכָּבָה הַשְּׁלֵמָה מִכָּל הַצְּדָדִים. מִכָּאן וָהָלְאָה נִמְסָר הַסּוֹד לַחֲכָמִים.</p>\n<p>וְעוֹד יֵשׁ בּוֹ סוֹד פְּנִימִי, שֶׁשָּׁנִינוּ, מִי שֶׁרוֹאֶה עֲנָבִים בַּחֲלוֹם, אִם לְבָנִים - הֵם טוֹבִים. אִם שְׁחֹרִים - בִּזְמַנָּם טוֹבִים, שֶׁלֹּא בִּזְמַנָּם צְרִיכִים רַחֲמִים. מַה שּׁוֹנֶה בִּלְבָנִים, וּמַה שּׁוֹנֶה שְׁחֹרִים, וּמַה שּׁוֹנֶה בִּזְמַנָּם, וּמַה שּׁוֹנֶה שֶׁלֹּא בִזְמַנָּם? וְעוֹד שָׁנִינוּ, אָכַל אֶת אוֹתָם שְׁחֹרִים - מֻבְטָח לוֹ שֶׁהוּא בֶּן הָעוֹלָם הַבָּא. לָמָּה?</p>\n<p>אֶלָּא שָׁנִינוּ, הָעֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן, עֲנָבִים הָיָה, שֶׁכָּתוּב (דברים לב) עֲנָבֵמוֹ עִנְּבֵי רוֹשׁ, וְאֵלֶּה הֵם עֲנָבִים שְׁחֹרִים, מִשּׁוּם שֶׁיֵּשׁ עֲנָבִים שְׁחֹרִים וְיֵשׁ עֲנָבִים לְבָנִים. הַלְּבָנִים טוֹבִים, שֶׁהֲרֵי הֵם מִצַּד הַחַיִּים. שְׁחֹרִים צְרִיכִים רַחֲמִים, שֶׁהֲרֵי הֵם מִצַּד הַמָּוֶת. בִּזְמַנָּם טוֹבִים, מָה הַטַּעַם? מִשּׁוּם שֶׁבִּזְמַן שֶׁהַלְּבָנִים שׁוֹלְטִים, הַכֹּל מִתְבַּשֵּׂם, שֶׁהֲרֵי בְּאוֹתוֹ זְמַן הַכֹּל צָרִיךְ תִּקּוּן, וְהַכֹּל הוּא יָפֶה, וְהַכֹּל תִּקּוּן אֶחָד, שָׁחֹר וְלָבָן. וּבִזְמַן שֶׁהַלְּבָנִים לֹא שׁוֹלְטִים וְנִרְאִים שְׁחֹרִים, יֵשׁ לָדַעַת שֶׁהֲרֵי בְּדִין הַמָּוֶת עוֹלֶה, וְצָרִיךְ רַחֲמִים, שֶׁהֲרֵי הָעֵץ שֶׁבּוֹ חָטָא אָדָם הָרִאשׁוֹן וְגָרַם מָוֶת לוֹ וּלְכָל הָעוֹלָם הוּא רָאָה.</p>\n<p>כָּאן יֵשׁ לְהִתְבּוֹנֵן, וְאִם מוֹרִי לֹא כָאן - לֹא אֹמַר. שָׁנִינוּ שֶׁהָעוֹלָם הַזֶּה הוּא כְּמוֹ הָעוֹלָם שֶׁלְּמַעְלָה, וְהָעוֹלָם שֶׁלְּמַעְלָה - כָּל מַה שֶּׁיֶּשְׁנוֹ בָּעוֹלָם הַזֶּה, כָּךְ זֶה לְמַעְלָה. אִם הַנָּחָשׁ גָּרַם מָוֶת לָאָדָם לְמַטָּה, אָז לָמָּה לְמַעְלָה? אִם תֹּאמַר (עוד) לָאִשָּׁה (למטה), שֶׁבִּגְלַל הַנָּחָשׁ נִגְרַע הָאוֹר, שֶׁהֲרֵי לִפְעָמִים הַלְּבָנָה גּוֹרַעַת אוֹרָהּ וּבְאוֹתוֹ זְמַן הִיא מֵתָה, הַזָּכָר לָמָּה? שֶׁאִם נֹאמַר שֶׁהַלְּבָנָה מֵתָה בְּעֶטְיוֹ שֶׁל נָחָשׁ בִּגְרִיעַת הָאוֹר, הֲרֵי שָׁנִינוּ שֶׁזֶּה לֹא הָיָה מִשּׁוּם הַנָּחָשׁ, אֶלָּא שֶׁאָמְרָה הַלְּבָנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְכוּ'. הֲרֵי לֹא מִשּׁוּם הַנָּחָשׁ זֶה הָיָה. וְאִם תֹּאמַר שֶׁבַּעְלָהּ כָּךְ הוּא - חַס וְחָלִילָה שֶׁגְּרִיעוּת הָיְתָה לְמַעְלָה.</p>\n<p>אֶלָּא כָּל זֶה סִתְרֵי תוֹרָה, וְהַנָּחָשׁ תִּקֵּן בַּכֹּל גְּרִיעוּת. בּא וּרְאֵה, וְכָךְ לָמַדְנוּ, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה, הַכֹּל הוּא בְּסוֹד שֶׁל זָכָר וּנְקֵבָה, וְכַמָּה דְרָגוֹת הֵן לְמַעְלָה מְשֻׁנּוֹת אֵלּוּ מֵאֵלּוּ. וּמִדַּרְגָּה עַד דַּרְגָּה סוֹד שֶׁל אָדָם, וְאוֹתָן דְּרָגוֹת שֶׁהֵן מִין אֶחָד, עָשָׂה אוֹתָן הַקָּדוֹשׁ בָּרוּךְ הוּא דְּיוֹקָן שֶׁל גּוּף אֶחָד, עַד שֶׁעוֹלִים בְּסוֹד שֶׁל אָדָם.</p>\n<p>וְשָׁנִינוּ, בַּיּוֹם הַשֵּׁנִי שֶׁל מַעֲשֵׂה בְרֵאשִׁית, שֶׁבּוֹ נִבְרָא גֵיהִנָּם, נַעֲשָׂה גוּף אֶחָד בְּסוֹד שֶׁל אָדָם, וְהֵם אֵיבָרִים מְמֻנִּים שֶׁמִּתְקָרְבִים לָאֵשׁ וּמֵתִים, וְחוֹזְרִים כְּמִקֹּדֶם. וְזֶה מִשּׁוּם שֶׁהֵם הִתְקָרְבוּ לַנָּחָשׁ הַזֶּה, וְהוּא אָדָם הָרִאשׁוֹן שֶׁהִתְפַּתָּה לְתוֹךְ הַמִּשְׁכָּן בַּנָּחָשׁ הַזֶּה וְלָכֵן מֵת, וְהַנָּחָשׁ גָּרַם לוֹ מָוֶת שֶׁהוּא הִתְקָרֵב אֵלָיו.</p>\n<p>וּבְכָל מָקוֹם אָדָם הוּא זָכָר וּנְקֵבָה, אֲבָל אָדָם שֶׁהוּא קָדוֹשׁ עֶלְיוֹן, הוּא שׁוֹלֵט עַל הַכֹּל, זֶה הַנּוֹתֵן מָזוֹן וְחַיִּים לַכֹּל. וְלָכֵן בַּכֹּל מָנַע אוֹר הַנָּחָשׁ הַקָּשֶׁה. כְּשֶׁטִּמֵּא אֶת הַמִּשְׁכָּן, נְקֵבָתוֹ שֶׁל אוֹתוֹ אָדָם מֵתָה כְּמוֹ שֶׁאָמַר, וְהַזָּכָר מֵת, וְעָלוּ כְּמִקֹּדֶם. וְלָכֵן הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>אָכַל אוֹתָם עֲנָבִים שְׁחֹרִים - מֻבְטָח לוֹ שֶׁהוּא בֶּן הָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהִשְׁמִיד וְשָׁלַט עַל אוֹתוֹ מָקוֹם, (והעבר) וְהִתְגַּבֵּר עָלָיו וְשָׁחַק אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ז) אָכְלָה וְשָׁחֲקָה. כֵּיוָן שֶׁהָעָבְרָה אוֹתָהּ קְלִפָּה קָשָׁה, הֲרֵי קָרֵב לָעוֹלָם הַבָּא וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. וְלָכֵן מִי שֶׁרוֹאֶה בַּחֲלוֹמוֹ אוֹתָם עֲנָבִים שְׁחֹרִים אוֹכֵל וּמְהַדֵּק, מֻבְטָח לוֹ וְכוּ'.</p>\n<p>כְּמוֹ כֵן לֹא הָיָה שִׁיר בְּבֵית דָּוִד עַד שֶׁהָעָבְרוּ אוֹתָם עֲנָבִים שְׁחֹרִים וְשָׁלַט עֲלֵיהֶם, וְאָז נֶאֱמַר שִׁיר הַשִּׁירִים כְּמוֹ שֶׁנִּתְבָּאֵר. וַאֲפִלּוּ !!!!!!! !!!!!!! בְּמָקוֹם זֶה נִקְרָא עֲנָבִים, כְּמוֹ שֶׁנֶּאֱמַר (הושע ט) כַּעֲנָבִים בַּמִּדְבָּר וְגוֹ', וְאֵלֶּה הֵם עֲנָבִים לְבָנִים.</p>\n<p>שִׁירָה זוֹ הִיא מְעֻלָּה עַל כָּל שְׁאָר הַשִּׁירִים שֶׁל הָרִאשׁוֹנִים. כָּל הַשִּׁירִים שֶׁהָרִאשׁוֹנִים אָמְרוּ, לֹא עָלוּ אֶלָּא תּוֹךְ הַשִּׁירִים שֶׁהַמַּלְאָכִים הָעֶלְיוֹנִים אָמְרוּ. וְאַף עַל גַּב שֶׁהֲרֵי פֵּרְשׁוּהָ, אֲבָל כָּתוּב שִׁיר הַמַּעֲלוֹת לְדָוִד. שִׁיר הַמַּעֲלוֹת - שִׁיר שֶׁהַמַּלְאָכִים הָעֶלְיוֹנִים אוֹמְרִים, שֶׁהֵם מַעֲלוֹת וּדְרָגוֹת. לְמִי אוֹמְרִים? לְדָוִד. לְבַקֵּשׁ טֶרֶף וּמָזוֹן מִמֶּנּוּ.</p>\n<p>עוֹד שִׁיר הַמַּעֲלוֹת - כְּמוֹ שֶׁנֶּאֱמַר (תהלים מו) עַל עֲלָמוֹת שִׁיר. (שיר א) עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ. לְדָוִד - בִּשְׁבִיל דָּוִד הַמֶּלֶךְ הָעֶלְיוֹן שֶׁמְּשַׁבֵּחַ תָּמִיד אֶת הַמֶּלֶךְ הָעֶלְיוֹן.</p>\n<p>כֵּיוָן שֶׁבָּא שְׁלֹמֹה הַמֶּלֶךְ, אָמַר שִׁיר שֶׁהוּא עֶלְיוֹן לְמַעְלָה, שֶׁגְּדוֹלֵי עוֹלָם עֶלְיוֹנִים אוֹמְרִים לַמֶּלֶךְ הָעֶלְיוֹן שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ. כָּל הָאוֹמְרִים שִׁירָה לֹא עוֹלִים בְּשִׁירָה זוֹ לוֹמַר, אֶלָּא אוֹתָהּ שִׁירָה שֶׁאוֹמְרִים מַלְאֲכֵי הַשָּׁרֵת. פְּרָט לַמֶּלֶךְ שְׁלֹמֹה שֶׁעלֶה בַּשִּׁירָה הַהִיא לְמַה שֶּׁגְּדוֹלִים עֶלְיוֹנִים עַמּוּדֵי עוֹלָם אוֹמְרִים. כָּל בְּנֵי הָעוֹלָם בְּמֶרְכָּבוֹת תַּחְתּוֹנוֹת, וּשְׁלֹמֹה הַמֶּלֶךְ בְּמֶרְכָּבוֹת עֶלְיוֹנוֹת.</p>\n<p>וְאִם תֹּאמַר, מֹשֶׁה, שֶׁעָלָה בְּדַרְגַּת נְבוּאָה וּבַחֲבִיבוּת לַקָּדוֹשׁ-בָּרוּךְ- הוּא עַל כָּל בְּנֵי הָעוֹלָם, אוֹתָהּ שִׁירָה שֶׁאָמַר בְּמֶרְכָּבוֹת תַּחְתּוֹנוֹת הָיְתָה וְלֹא עָלָה יוֹתֵר - בֹּא וּרְאֵה, הַשִּׁירָה שֶׁאָמַר מֹשֶׁה עָלְתָה לְמַעְלָה וְלֹא לְמַטָּה. אֲבָל לֹא אָמַר שִׁירָה כִּשְׁלֹמֹה הַמֶּלֶךְ, וְלֹא הָיָה אָדָם שֶׁעָלָה בְשִׁירָה כְּמוֹ שְׁלֹמֹה.</p>\n<p>מֹשֶׁה עָלָה בְּתִשְׁבַּחְתּוֹ לְמַעְלָה, וְתִשְׁבַּחְתּוֹ הָיְתָה לָתֵת תִּשְׁבָּחוֹת וְהוֹדָאוֹת לַמֶּלֶךְ הָעֶלְיוֹן שֶׁהִצִּיל אֶת יִשְׂרָאֵל וְעָשָׂה לָהֶם נִסִּים וּגְבוּרוֹת בְּמִצְרַיִם וְעַל הַיָּם. אֲבָל דָּוִד הַמֶּלֶךְ וּשְׁלֹמֹה בְּנוֹ אָמְרוּ שִׁירָה בְּגָוֶן אַחֵר. דָּוִד הִשְׁתַּדֵּל לְתַקֵּן אֶת הָעֲלָמוֹת וּלְקַשֵּׁט אוֹתָם לַגְּבִירָה, שֶׁתֵּרָאֶה הַגְּבִירָה וְעַלְמוֹתֶיהָ בְּיֹפִי, וְלָכֵן הִשְׁתַּדֵּל בְּאוֹתָם שּיּריּם ותשּבָּחות שִּאִצּלָם, עַד שִּתקּן וְקִשֵּׁט אֶת כָּל הָעֲלָמוֹת וְאֶת הַגְּבִירָה.</p>\n<p>כֵּיוָן שֶׁבָּא שְׁלֹמֹה, מָצָא גְבִירָה מְקֻשֶּׁטֶת וְעַלְמוֹתֶיהָ בְּיֹפִי, הִשְׁתַּדֵּל לְהַכְנִיסָהּ לֶחָתָן, וְהִכְנִיס הֶחָתָן לַחֻפָּה עִם הַגְּבִירָה, וְהִכְנִיס דִּבְרֵי אַהֲבָה בֵּינֵיהֶם כְּדֵי לְחַבְּרָם כְּאֶחָד וְלִהְיוֹת שְׁנֵיהֶם בִּשְׁלֵמוּת אַחַת בַּחֲבִיבוּת שְׁלֵמָה. וְלָכֵן שְׁלֹמֹה עָלָה בְּתִשְׁבַּחַת עֶלְיוֹנָה עַל כָּל בְּנֵי הָעוֹלָם.</p>\n<p>מֹשֶׁה זִוֵּג אֶת הַגְּבִירָה בָּעוֹלָם הַזֶּה לְמַטָּה לִהְיוֹת בָּעוֹלָם הַזֶּה בְּזִוּוּג שָׁלֵם בַּתַּחְתּוֹנִים. שְׁלֹמֹה זִוֵּג אֶת הַגְּבִירָה בְּזִוּוּג שָׁלֵם לְמַעְלָה, וְהִכְנִיס אֶת הֶחָתָן לַחֻפָּה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ הִכְנִיס אֶת שְׁנֵיהֶם לָעוֹלָם הַזֶּה, וְזִמְּנָם בְּשִׂמְחָה בְּבֵית הַמִּקְדָּשׁ שֶׁהוּא בָּנָה.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ הִכְנִיס מֹשֶׁה אֶת הַגְּבִירָה לְבַדָּהּ לָעוֹלָם הַזֶּה, שֶׁהֲרֵי נִרְאֶה בְּפֵרוּד? בּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא זִוֵּג אוֹתָהּ עִם מֹשֶׁה בַּתְּחִלָּה, וְהִיא הָיְתָה כַּלַּת מֹשֶׁה, כְּמוֹ שֶׁנִּתְבָּאֵר. כֵּיוָן שֶׁהִזְדַּוְּגָה עִם מֹשֶׁה, יָרְדָה לָעוֹלָם הַזֶּה בְּזִוּוּג שֶׁל הָעוֹלָם הַזֶּה, וְהִתְתַּקְּנָה בָּעוֹלָם הַזֶּה מַה שֶּׁלֹּא הָיְתָה מִקֹּדֶם לָזֶה, וּלְעוֹלָם לֹא הָיְתָה בְּפֵרוּד.</p>\n<p>אֲבָל לֹא הָיָה אָדָם בָּעוֹלָם מִיּוֹם שֶׁנִּבְרָא אָדָם שֶׁיַּכְנִיס אַהֲבָה וַחֲבִיבוּת וְדִבְרֵי זִוּוּג לְמַעְלָה פְּרָט לִשְׁלֹמֹה הַמֶּלֶךְ שֶׁתִּקֵּן הַזִּוּוּג שֶׁלְּמַעְלָה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ הִזְמִין אוֹתָם כְּאֶחָד בַּבַּיִת שֶׁתִּקֵּן לָהֶם. אַשְׁרֵיהֶם דָּוִד וּשְׁלֹמֹה בְּנוֹ שֶׁתִּקְּנוּ אֶת הַזִּוּוּג שֶׁלְּמַעְלָה. מִיּוֹם שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַלְּבָנָה לְכִי וְהַקְטִינִי אֶת עַצְמֵךְ, לֹא הִזְדַּוְּגָה בְּזִוּוּג שָׁלֵם עִם הַשֶּׁמֶשׁ, פְּרָט לִכְשֶׁבָּא הַמֶּלֶךְ שְׁלֹמֹה.</p>\n<p>שִׁיר הַשִּׁירִים - הֲרֵי כָּאן חָמֵשׁ דְּרָגוֹת לִדְבֹּק בָּעוֹלָם הַבָּא. שִׁיר - אַחַת. הַשִּׁירִים - שְׁתַּיִם. הֲרֵי שָׁלֹשׁ. אֲשֶׁר - הֲרֵי אַרְבַּע. לִשְׁלֹמֹה - הֲרֵי חָמֵשׁ. בַּחֲמִישִׁי הוּא. שֶׁהֲרֵי יוֹם הַחֲמִשִּׁים הוּא סוֹד הַיּוֹבֵל.</p>\n<p>בֹּא וּרְאֵה, אֶת הַזִּוּוּג הָעֶלְיוֹן לֹא יָכֹל שְׁלֹמֹה לְתַקֵּן, אֶלָּא מִשּׁוּם שֶׁנִּמְצָא זִוּוּג לְמַטָּה מִקֹּדֶם לָכֵן, וּמִיהוּ? הַזִּוּוּג שֶׁל מֹשֶׁה. שֶׁאִם לֹא הָיָה אָז הַזִּוּוּג הַזֶּה, לֹא הִתְתַּקֵּן הַזִּוּוּג שֶׁל מַעְלָה. וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן לְחַכְמֵי הַלֵּב.</p>\n<p>כָּתוּב (מלכים א ה) וַיְדַבֵּר שְׁלֹשֶׁת אֲלָפִים מָשָׁל וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף. פָּסוּק זֶה פֵּרְשׁוּהוּ הַחֲבֵרִים. אֲבָל וַיְדַבֵּר שְׁלֹשֶׁת אֲלָפִים מָשָׁל, וַדַּאי שֶׁעַל כָּל דָּבָר וְדָבָר שֶׁהוּא הָיָה אוֹמֵר, הָיוּ בוֹ שְׁלֹשֶׁת אַלְפֵי מְשָׁלִים, כְּמוֹ סֵפֶר שֶׁל קֹהֶלֶת שֶׁהוּא בְּסוֹד עֶלְיוֹן וְהוּא בְּדֶרֶךְ מָשָׁל, שֶׁאֵין בּוֹ פָּסוּק שֶׁאֵינוֹ בְּחָכְמָה עֶלְיוֹנָה וּבְדֶרֶךְ מָשָׁל אֲפִלּוּ הַפָּסוּק הַקָּטָן שֶׁבּוֹ.</p>\n<p>שֶׁכְּשֶׁהָיָה מַגִּיעַ רַב הַמְנוּנָא סָבָא הָרִאשׁוֹן לַפָּסוּק הַזֶּה, (קהלת יא) שְׂמַח בָּחוּר בְּיַלְדוּתֶךְ וִיטִיבְךְ לִבְּךְ בִּימֵי בְחוּרוֹתֶיךְ - הָיָה בּוֹכֶה. וְאָמַר, וַדַּאי פָּסוּק זֶה נָאֶה הוּא, וְהוּא בְּדֶרֶךְ מָשָׁל, וּמִי יָכוֹל לַעֲשׂוֹת דְּרָשׁ בְּמָשָׁל זֶה?! וְאִם הוּא דְּרָשׁ, אֵין בּוֹ דְּרָשׁ אֶלָּא כְּמוֹ שֶׁרָאִינוּ בָּעֵינַיִם. וְאִם זוֹ חָכְמָה, מִי יָכוֹל לָדַעַת אוֹתָהּ?!</p>\n<p>מִיָּד הָיָה שָׁב וְאוֹמֵר, כָּתוּב (בראשית לז) אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה וְגוֹ'. פָּסוּק זֶה שֶׁל קֹהֶלֶת הוּא מָשָׁל לַחָכְמָה שֶׁל פָּסוּק זֶה שֶׁל הַתּוֹרָה, וְזֶה מָשָׁל לָזֶה. שְׂמַח בָּחוּר בְּיַלְדוּתֶךְ - וְהוּא נַעַר. וִיטִיבְךְ לִבְּךְ - הָיָה רֹעֶה אֶת אֶחָיו בַּצֹּאן. בִּימֵי בְחוּרוֹתֶיךְ - אֶת בְּנֵי בִלְהָה וְאֶת בְּנֵי זִלְפָּה נְשֵׁי אָבִיו. וְדַע כִּי עַל כָּל אֵלֶּה - וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה. יְבִיאֲךְ אֱלֹהִים בַּמִּשְׁפָּט - אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף. יוֹסֵף נִכְלָל בְּיַעֲקֹב, וְהַסּוֹדוֹת שֶׁל סִתְרֵי הַתּוֹרָה מִי יָכוֹל לָדַעַת אוֹתָם?!</p>\n<p>וְהַמָּשָׁל הַזֶּה הִתְפַּשֵּׁט לִשְׁלֹשֶׁת אַלְפֵי מְשָׁלִים, וְכֻלָּם בַּמָּשָׁל הַזֶּה, בְּשָׁעָה שֶׁיּוֹסֵף נִכְלָל בְּיַעֲקֹב, שְׁלֹשֶׁת אֲלָפִים הֵם, בְּאַבְרָהָם יִצְחָק וְיַעֲקֹב, שֶׁכֻּלָּם בַּמָּשָׁל הַזֶּה בְּסוֹד הַחָכְמָה. וְכָאן כַּמָּה סוֹחֲרִים הֵם בַּמַּשָּׂאוֹת שֶׁל הַנִּסְתָּר, וּבָהֶם דַּיָּרֵי הַמָּגִנִּים שֶׁאֵין לָהֶם חֶשְׁבּוֹן לְסִתְרֵי הַחָכְמָה.</p>\n<p>וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף. כָּךְ בֵּאַרְנוּ, וַיְהִי שִׁירוֹ שֶׁל מָשָׁל, וְהַכֹּל אֶחָד, בֵּין מִי שֶׁאָמַר וַיְהִי שִׁירוֹ שֶׁל שְׁלֹמֹה, בֵּין מִי שֶׁאוֹמֵר וַיְהִי שִׁירוֹ שֶׁל מָשָׁל. הַכֹּל אֶחָד הוּא, וְאֶת הַכֹּל הוּא אָמַר. וַיְהִי שִׁירוֹ - זֶה שִׁיר הַשִּׁירִים. וְכִי חֲמִשָּׁה וָאָלֶף הוּא שִׁיר הַשִּׁירִים? וַדַּאי כָּךְ זֶה, חֲמִשָּׁה הֵם שְׁעָרִים נִפְתָּחִים שֶׁנִּפְתָּחִים בַּמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, וְהֵם חֲמֵשׁ מֵאוֹת שָׁנִים שֶׁל עֵץ הַחַיִּים. חֲמִשִּׁים שְׁנוֹת הַיּוֹבֵל.</p>\n<p>וָאָלֶף - זֶהוּ עֵץ הַחַיִּים, חָתָן שֶׁיּוֹצֵא מִצִּדּוֹ, וְהוּא יוֹרֵד כָּל אוֹתָם הַחֲמִשָּׁה לַהֲבִיאָם לַכַּלָּה. יוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא אֶלֶף שָׁנִים, וְזֶהוּ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן. יוֹסֵף הַצַּדִּיק. שֶׁנִּקְרָא צַדִּיק עַל שֵׁם הַלְּבָנָה, כְּמוֹ שֶׁהִתְנָה בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ שִׁיר הַשִּׁירִים קֹדֶשׁ קָדָשִׁים.</p>\n<p>וְאֵין לְךְ פָּסוּק בְּשִׁיר הַשִּׁירִים שֶׁאֵין בּוֹ סוֹד שֶׁל חֲמִשָּׁה וָאָלֶף וַדַּאי. שִׁיר הַשִּׁירִים וַדַּאי שֶׁכָּךְ הוּא. חָמֵשׁ דְּרָגוֹת הָיוּ בַּפָּסוּק הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר. וְאִם תֹּאמַר, הָאֶלֶף לָמָּה לֹא נִזְכָּר כָּאן? וַדַּאי שֶׁאוֹתוֹ אֶלֶף הָיָה טָמִיר, וְהוּא טָמִיר עַד שֶׁהִתְחַבְּרָה אִשָּׁה בְּבַעְלָהּ. וְלָכֵן הִשְׁתַּדֵּל שְׁלֹמֹה לְהָבִיא אוֹתוֹ אֶלֶף לַכַּלָּה, בַּסֵּתֶר שֶׁל הַחָכְמָה הָעֶלְיוֹנָה.</p>\n<p>כֵּיוָן שֶׁעָשָׂה קֹדֶשׁ הַקְּדָשִׁים לְמַטָּה גָּנוּז וְטָמִיר, וְהִכְנִיס לְשָׁם אֶת סוֹד קֹדֶשׁ הַקְּדָשִׁים לַעֲשׂוֹת גְּנִיזַת הַשִּׁמּוּשׁ הַשָּׁלֵם לְמַעְלָה וּלְמַטָּה כָּרָאוּי. קֹדֶשׁ הַקְּדָשִׁים הוּא לְמַעְלָה, סוֹד הַחָכְמָה הָעֶלְיוֹנָה וְהַיּוֹבֵל. כְּמוֹ זֶה יוֹרְשִׁים הֶחָתָן וְהַכַּלָּה יְרֻשַּׁת הָאָב וְהָאֵם.</p>\n<p>וְחָזְרוּ נַחֲלַת הַיְרֻשָּׁה בְּגָוֶן אַחֵר. יְרֻשַּׁת הָאָב יָרְשָׁה הַבַּת בַּעֲלִיָּתוֹ שֶׁל הַשֵּׁם הַקָּדוֹשׁ הַזֶּה, וְנִקְרָא אַף כָּךְ קֹדֶשׁ, חָכְמָה. יְרֻשַּׁת הָאֵם יָרַשׁ הַבֵּן, וְנִקְרָא קָדָשִׁים, מִשּׁוּם שֶׁנָּטַל אֶת כָּל אוֹתָם הַקְּדָשִׁים הָעֶלְיוֹנִים וְכִנְּסָם אֵלָיו, וְאַחַר כָּךְ נוֹתֵן אוֹתָם וּמַכְנִיסָם לַכַּלָּה.</p>\n<p>וְעַל זֶה אָמַר שִׁיר הַשִּׁירִים. שִׁיר - לְקֹדֶשׁ. הַשִּׁירִים - לָקֳדָשִׁים, לִהְיוֹת הַכֹּל קֹדֶשׁ קָדָשִׁים בְּסוֹד אֶחָד כְּמוֹ שֶׁרָאוּי. אֲשֶׁר לִשְׁלֹמֹה - הֲרֵי נִתְבָּאֵר, לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ.</p>\n<p>וְאִם תֹּאמַר שֶׁשֶּׁבַח זֶה הוּא שֶׁלּוֹ - אַל תֹּאמַר כָּךְ, אֶלָּא הַשֶּׁבַח עוֹלֶה לְמָקוֹם עֶלְיוֹן. אֲבָל כָּאן הוּא סוֹד. כְּשֶׁמִּתְתַּקְנִים זָכָר וּנְקֵבָה כְּאֶחָד תַּחַת הַמֶּלֶךְ הָעֶלְיוֹן, אָז אוֹתוֹ מֶלֶךְ מִתְעַלֶּה לְמַעְלָה וּמִתְמַלֵּא מִכָּל הַקְּדֻשּׁוֹת וּמִכָּל הַבְּרָכוֹת שֶׁשּׁוֹפְעוֹת לְמַטָּה, וּמִתְמַלֵּא וּמֵרִיק לְמַטָּה, וְזוֹהִי תְּשׁוּקַת הַמֶּלֶךְ הָעֶלְיוֹן, כְּשֶׁמִּתְמַלֵּא קְדֻשּׁוֹת וּבְרָכוֹת וּמֵרִיק לְמַטָּה.</p>\n<p>וְשֶׁלָיִּכֵתְןתַּקֵּןהַ וְתְּיִפִתְלּוֹמַלֵּתא וְאהַוֹבַּתוֹקָּשׁהַוֹמַּתבּוּ -עַ הָעֶלְיוֹן. שֶׁכֵּיוָן שֶׁהוּא מִתְתַּקֵּן כָּרָאוּי מִמַּרְאֵהוּ וּמִמַּרְאֶה שֶׁל אוֹתוֹ הַתִּקּוּן, מִתְתַּקֵּן הָעוֹלָם הַתַּחְתּוֹן וְעַלְמוֹתֶיהָ, וְלֹא צָרִיךְ לְהִתְתַּקֵּן הָעוֹלָם הַתַּחְתּוֹן אֶלָּא מֵהַמַּרְאֶה שֶׁל הָעוֹלָם הָעֶלְיוֹן, לַלְּבָנָה אֵין מַרְאֶה מֵעַצְמָהּ כְּלָל, פְּרָט לְכַאֲשֶׁר מִתְתַּקֶּנֶת בַּשֶּׁמֶשׁ וּמְאִירָה, וּמִמַּרְאֵה הַשֶּׁמֶשׁ וְתִקּוּנוֹ נִתְקֶנֶת הַלְּבָנָה וּמְאִירָה.</p>\n<p>מַה שֶּׁצְּרִיכִים הַתְּפִלּוֹת וְהַבַּקָּשׁוֹת - שֶׁיּוֹאַר וִיתֻקַּן אוֹתוֹ מָקוֹם שֶׁיּוֹצֵא מִמֶּנּוּ אוֹר. שֶׁכֵּיוָן שֶׁאוֹתוֹ מָקוֹם מְתֻקָּן מִן הַמַּרְאֶה שֶׁלּוֹ, מִתְתַּקֵּן כָּל מַה שֶּׁלְּמַטָּה. וְלָכֵן הַתִּשְׁבַּחַת שֶׁאָמַר שְׁלֹמֹה, לֹא הִשְׁתַּדֵּל אֶלָּא בִּשְׁבִיל הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ שֶׁיִּתְתַּקֵּן. כֵּיוָן שֶׁהִתְתַּקֵּן מִמַּרְאֵהוּ, הַכֹּל הִתְתַּקֵּן. וְאִם הוּא לֹא הִתְתַּקֵּן, אֵין תִּקּוּן לַלְּבָנָה לְעוֹלָמִים, וּמִשּׁוּם כָּךְ אֲשֶׁר לִשְׁלֹמֹה. שֶׁיִּתְתַּקֵּן וְיִתְמַלֵּא כָּרָאוּי בָּרִאשׁוֹנָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522011722,"<p>(שמות כה) וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ וְגוֹ', סוֹד הַסּוֹדוֹת לְיוֹדְעֵי הַחָכְמָה. כְּשֶׁעָלָה בְרָצוֹן סֵתֶר כָּל הַסְּתָרִים לַעֲשׂוֹת כָּבוֹד לִכְבוֹדוֹ, הֵשִׁיב רוּחַ מִנְּקֻדָּה עֶלְיוֹנָה שֶׁשּׁוֹפַעַת מִלְמַעְלָה לְמַטָּה, וְשָׁם תִּקּוּנוֹ לְהִתְיַשֵּׁב בָּעוֹלָם הַזֶּה. לָמָּה? בִּשְׁבִיל שֶׁאִם לֹא יִהְיֶה עִקָּר וְשֹׁרֶשׁ בָּעוֹלָם הַזֶּה, לֹא יִהְיֶה כְּלִי לְהוֹרִיק בָּעוֹלָם הַזֶּה כְּלָל. וְאִם לֹא יָרִיק לָעוֹלָם הַזֶּה, מִיָּד נֶאֱבָד וְלֹא יָכוֹל לַעֲמֹד אֲפִלּוּ רֶגַע אֶחָד. אֲבָל מִשּׁוּם שֶׁתִּקּוּנוֹ הוּא מִן הָעוֹלָם הַזֶּה, מִתְמַלֵּא מִצַּד אֶחָד לְהוֹרִיק לָעוֹלָם הַזֶּה, וּמִצַּד אַחֵר לְהוֹרִיק לַמַּלְאָכִים הָעֶלְיוֹנִים. וְהַכֹּל נִזּוֹנוּ מִמֶּנּוּ כְּאֶחָד.</p>\n<p>שְלֵמוּת הַתִּקּוּן שֶׁל הָרוּחַ הַזּוֹ - רוּחוֹת הַצַּדִּיקִים בָּעוֹלָם הַזֶּה. רוּחַ זוֹ נִשְׁלְמָה בִּזְמַן שֶׁחֲנוֹךְ וְיֶרֶד וּמַהֲלְאֵל הָיוּ בָעוֹלָם, וּכְשֶׁהִתְרַבּוּ הָרְשָׁעִים בָּעוֹלָם זָזָה הַשְּׁלֵמוּת הַהִיא מִמֶּנּוּ. אַחַר שֶׁאָבְדוּ - בָּא נֹחַ וְהִשְׁלִים אוֹתוֹ. בָּא דּוֹר הַפְּלַגָּה וְהֵזִיז אוֹתָהּ שְׁלֵמוּת מִמֶּנּוּ - בָּא אַבְרָהָם וְהִשְׁלִים אוֹתוֹ. בָּאוּ אַנְשֵׁי סְדוֹם וְהֵזִיזוּ אוֹתוֹ - בָּא יִצְחָק וְהִשְׁלִים אוֹתוֹ. בָּאוּ פְלִשְׁתִּים וְרִשְׁעֵי הַדּוֹר וְהֵזִיזוּ אוֹתוֹ מִמֶּנּוּ - בָּא יַעֲקֹב וּבָנָיו, הַמִּטָּה הַשְּׁלֵמָה, וְהִשְׁלִימוּ אוֹתוֹ.</p>\n<p>יָצְאוּ מֵהָאָרֶץ הַקְּדוֹשָׁה וְיָרְדוּ לְמִצְרַיִם, וּבִשְׁבִילָם הִתְעַכְּבָה שָׁם. וּמִשּׁוּם שֶׁחָזְרוּ שָׁם יִשְׂרָאֵל לְמַעֲשֵׂי הַמִּצְרִים, נִכְנְעָה וְזָזָה אוֹתָהּ שְׁלֵמוּת מִמֶּנּוּ, עַד שֶׁיָּצְאוּ מִמִּצְרַיִם וּבָאוּ לַעֲשׂוֹת מִשְׁכָּן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: רְצוֹנִי לָדוּר בֵּינֵיכֶם, אֲבָל לֹא יָכוֹל עַד שֶׁתְּתַּקְנוּ אוֹתָהּ רוּחַ שֶׁלִּי שֶׁתִּשְׁרֶה בֵינֵיכֶם. זֶהוּ שֶׁכָּתוּב וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם.</p>\n<p>וְזֶהוּ סוֹד הַכָּתוּב וְיִקְחוּ לִי תְּרוּמָה. אָמַר מֹשֶׁה לַקָּדוֹשׁ-בָּרוּךְ-הוּא: מִי יָכוֹל לָקַחַת אוֹתָהּ וְלַעֲשׂוֹת אוֹתָהּ? אָמַר לוֹ: מֹשֶׁה, לֹא כְמוֹ שֶׁאַתָּה חוֹשֵׁב, אֶלָּא - מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ וְגוֹ', מֵאוֹתוֹ רָצוֹן וְרוּחַ שֶׁלָּהֶם תִּקְחוּ אוֹתָהּ וְתַשְׁלִימוּ אוֹתָהּ.</p>\n<p>כְּשֶׁבָּא שְׁלֹמֹה, תִּקֵּן אוֹתָהּ רוּחַ בַּשְּׁלֵמוּת שֶׁלְּמַעְלָה, שֶׁהֲרֵי מִיּוֹם שֶׁנִּשְׁלְמָה לְמַטָּה בִּימֵי מֹשֶׁה לֹא הוּסְרָה אוֹתָהּ שְׁלֵמוּת מִמֶּנּוּ. (עד שבא שלמה) כֵּיוָן שֶׁבָּא שְׁלֹמֹה, הִשְׁתַּדֵּל לְהַשְׁלִימוֹ לְמַעְלָה, וְהִתְחִיל לְתַקֵּן אֶת מַרְאֵה הָעוֹלָם הָעֶלְיוֹן לְהִתְתַּקֵּן מֵאוֹתוֹ מַרְאֶה שֶׁל הָעוֹלָם הַתַּחְתּוֹן, וְזֶהוּ אֲשֶׁר לִשְׁלֹמֹה.</p>"],[9522011723,"<p>וְזֹאת הַתְּרוּמָה - הֲרֵי נֶאֱמַר, שֶׁכְּשֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַר סִינַי, כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל בְּעֶשֶׂר אֲמִירוֹת, כָּל אֲמִירָה וַאֲמִירָה עָשְׂתָה קוֹל, וְאוֹתוֹ קוֹל נֶחֱלַק לְשִׁבְעִים קוֹלוֹת, וְכֻלָּם הָיוּ מְאִירִים וְנוֹצְצִים לְעֵינֵי כָּל יִשְׂרָאֵל, וְהָיוּ רוֹאִים עַיִן בְּעַיִן אֶת זִיו כְּבוֹדוֹ. זֶהוּ שֶׁכָּתוּב (שמות כ) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. רוֹאִים וַדַּאי.</p>\n<p>וְאוֹתוֹ קוֹל הָיָה מַתְרֶה בְּכָל אֶחָד וְאֶחָד מִיִּשְׂרָאֵל וְאוֹמֵר לָהֶם: תְּקַבֵּל אוֹתִי עָלֶיךְ בְּכָךְ וְכָךְ מִצְווֹת שֶׁבַּתּוֹרָה? וְאָמְרוּ כֵּן. חָזַר לוֹ עַל רֹאשׁוֹ וְהִתְגַּלְגֵּל עָלָיו, וְהָיָה מַתְרֶה בּוֹ וְאוֹמֵר לוֹ: תְּקַבֵּל אוֹתִי עָלֶיךְ בְּכָךְ עֳנָשִׁים שֶׁבַּתּוֹרָה? וְהָיָה אוֹמֵר כֵּן. אַחַר כָּךְ חָזַר אוֹתוֹ הַקּוֹל וְנָשַׁק אוֹתוֹ בְּפִיו. זֶהוּ שֶׁכָּתוּב (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ.</p>\n<p>וְאָז כָּל מַה שֶּׁהָיוּ רוֹאִים יִשְׂרָאֵל בְּאוֹתוֹ זְמַן, הָיוּ רוֹאִים בְּתוֹךְ אוֹר אֶחָד שֶׁקִּבֵּל כָּל אוֹתָם הָאוֹרוֹת הָאֲחֵרִים, וְהָיוּ מִשְׁתּוֹקְקִים לִרְאוֹת. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: אוֹתוֹ הָאוֹר שֶׁרְאִיתֶם בְּהַר סִינַי שֶׁקִּבֵּל כָּל אוֹתָם גּוֹנֵי הָאוֹרוֹת וּתְשׁוּקַתְכֶם עָלָיו, תְּקַבְּלוּ אוֹתָהּ וְתִקְחוּ אוֹתָהּ אֲלֵיכֶם, וְאוֹתָם גְּוָנִים שֶׁהִיא מְקַבֶּלֶת, אֵלֶּה הֵם זָהָב וָכֶסֶף וּנְחֹשֶׁת וְגוֹ'.</p>\n<p>דָּבָר אַחֵר יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ - מָה רָאָה שְׁלֹמֹה הַמֶּלֶךְ שֶׁהִכְנִיס דִּבְרֵי אַהֲבָה בֵּין הָעוֹלָם הָעֶלְיוֹן לָעוֹלָם הַתַּחְתּוֹן, וְרֵאשִׁית הַתִּשְׁבַּחַת שֶׁל הָאַהֲבָה שֶׁהִכְנִיס בֵּינֵיהֶם הוּא יִשָּׁקֵנִי? אֶלָּא הֲרֵי פֵּרְשׁוּהָ וְכָךְ הוּא, שֶׁאֵין אַהֲבָה שֶׁל דְּבֵקוּת רוּחַ בְּרוּחַ פְּרָט לִנְשִׁיקָה, וּנְשִׁיקָה הִיא בַּפֶּה, שֶׁהִיא מַבּוּעַ שֶׁל הָרוּחַ וְהַמּוֹצָא שֶׁלּוֹ. וּכְשֶׁנּוֹשְׁקִים זֶה לָזֶה, נִדְבָּקוֹת הָרוּחוֹת אֵלֶּה בְאֵלֶּה וְנִהְיִים אֶחָד, וְאָז זוֹהִי אַהֲבָה אַחַת.</p>\n<p>בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא הָרִאשׁוֹן הָיָה אוֹמֵר עַל הַפָּסוּק הַזֶּה, נְשִׁיקָה שֶׁל אַהֲבָה מִתְפַּשֶּׁטֶת לְאַרְבַּע רוּחוֹת, וְאַרְבַּע רוּחוֹת נִדְבָּקוֹת כְּאֶחָד, וְהֵן בְּתוֹךְ סוֹד הָאֱמוּנָה, וְעוֹלוֹת בְּאַרְבַּע אוֹתִיּוֹת. וְאוֹתָן הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ תְּלוּיִים בָּהֶם, וְעֶלְיוֹנִים וְתַחְתּוֹנִים תְּלוּיִים בָּהֶם, וְתִשְׁבַּחַת שִׁיר הַשִּׁירִים תְּלוּיָה בָהֶם. וּמַה הוּא? אַהֲבָ\"ה. וְהֵן מֶרְכָּבָה עֶלְיוֹנָה. וְהֵם חֲבֵרוּת וּדְבֵקוּת וּשְׁלֵמוּת הַכֹּל.</p>\n<p>אֵלּוּ הָאוֹתִיּוֹת הֵן אַרְבַּע רוּחוֹת, וְהֵן רוּחוֹת שֶׁל אַהֲבָה וְשִׂמְחָה שֶׁל כָּל אֵיבְרֵי הַגּוּף בְּלִי עֶצֶב כְּלָל. אַרְבַּע רוּחוֹת הֵן בִּנְשִׁיקָה, כָּל אַחַת וְאַחַת כְּלוּלָה בַּחֲבֶרְתָּהּ. וּכְשֶׁהָרוּחַ הַזּוֹ כְּלוּלָה בְּאַחֶרֶת, וְאוֹתָהּ אַחֶרֶת כְּלוּלָה בָּזֶה, נַעֲשׂוֹת שְׁתֵּי רוּחוֹת כְּאַחַת, וְאָז מִתְחַבְּרוֹת בִּדְבֵקוּת אַחַת, וְהֵן אַרְבַּע בִּשְׁלֵמוּת, וְנוֹבְעוֹת זוֹ מִזּוֹ וְנִכְלָלוֹת זוֹ בָּזוֹ.</p>\n<p>וּכְשֶׁמִּתְפַּשְּׁטוֹת (וכשנפרדות), נַעֲשֶׂה מֵאוֹתָן אַרְבַּע רוּחוֹת פְּרִי אֶחָד, וְהוּא רוּחַ אַחַת הַכְּלוּלָה מֵאַרְבַּע רוּחוֹת, וְזֶה עוֹלֶה וּבוֹקֵעַ רְקִיעִים, עַד שֶׁעוֹלֶה וְיוֹשֵׁב אֵצֶל הֵיכָל אֶחָד שֶׁנִּקְרָא הֵיכַל הָאַהֲבָה, וְהוּא הַהֵיכָל שֶׁכָּל אַהֲבָה תְּלוּיָה בּוֹ. וְאוֹתָהּ רוּחַ כָּךְ נִקְרֵאת - אַהֲבָה, וּכְשֶׁרוּחַ זוֹ עוֹלָה, מִתְעוֹרֶרֶת לְאוֹתוֹ הֵיכָל לְהִתְחַבֵּר לְמַעְלָה.</p>\n<p>אַרְבַּע אוֹתִיּוֹת הֵן אֵצֶל אַרְבַּע רוּחוֹת, וְהֵן אַהֲבָה, וְהַפְּרִי שֶׁלָּהֶן אַהֲבָה. כְּשֶׁמִּתְחַבְּרוֹת זוֹ בָּזוֹ, מִיָּד מִתְעוֹרֵר זֶה בְּצַד זֶה וְזֶה בְּצַד זֶה. א'. מִיָּד יוֹצֵא ה' וּמִתְחַבֵּר בְּא', נִדְבָּק בִּדְבֵקוּת בְּאַהֲבָה. וְנַעֲשׂוֹת (ומתעוררות) שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת, ב' ה', וְנִכְלָלוֹת רוּחוֹת בְּרוּחוֹת בִּדְבֵקוּת שֶׁל אַהֲבָה, וּפוֹרְחוֹת מֵהֶן הָאוֹתִיּוֹת הַלָּלוּ בְּאוֹתָהּ רוּחַ שֶׁעוֹלָה, וּמִתְעַטְּרוֹת בּוֹ כָּרָאוּי.</p>\n<p>כֵּיוָן שֶׁהוֹלֶכֶת וְעוֹלָה אוֹתָהּ אַהֲבָה שְׁלֵמָה, כְּלוּלָה בְּכָל אוֹתָן אַרְבַּע רוּחוֹת, פּוֹגֶשֶׁת בִּמְמֻנֶּה אֶחָד עֶלְיוֹן גָּדוֹל שֶׁמְּמֻנֶּה עַל אֶלֶף וּתְשַׁע מֵאוֹת וְתִשְׁעִים רְקִיעִים, וְהוּא מְמֻנֶּה עַל הַשֶּׁפַע שֶׁל שְׁלֹשָׁה עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן זַךְ שֶׁשּׁוֹפֵעַ מִסּוֹד שֶׁל הַטַּל הָעֶלְיוֹן, וְאוֹתוֹ הַשֶּׁפַע נִקְרָא מַיִם רַבִּים. כֵּיוָן שֶׁפּוֹגֵשׁ לְאוֹתוֹ גְדוֹל הַמַּחֲנוֹת עוֹמֵד אֶצְלוֹ, וְלֹא יָכוֹל לְעַכֵּב אוֹתוֹ, וְעוֹבֵר בָּהֶם עַד שֶׁנִּכְנָס לְהֵיכַל הָאַהֲבָה.</p>\n<p>וְעַל זֶה אָמַר שְׁלֹמֹה בְּסִיּוּם שִׁבְחוֹ, מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. מַיִם רַבִּים - אֵלּוּ מַיִם עֶלְיוֹן שֶׁשּׁוֹפְעִים תּוֹךְ (מתוך) הַטַּל הָעֶלְיוֹן. וּנְהָרוֹת לֹא יִשְׁטְפוּהָ - אֵלֶּה הֵם נַהֲרוֹת אֲפַרְסְמוֹן זַךְ, שֶׁהֵם שְׁלֹשָׁה עָשָׂר. אוֹתוֹ מְמֻנֶּה הוּא מַלְאָךְ שָׁלִיחַ מִלִּפְנֵי ה', וְזֶהוּ גְּדוֹל הַמַּחֲנוֹת שֶׁקּוֹשֵׁר כְּתָרִים לְרִבּוֹנוֹ, סוֹד שֶׁל אַכְתָרִיאֵ\"ל, מְעַטֵּר הָעֲטָרוֹת לְרִבּוֹנוֹ בְּשֵׁם מְגֻלָּף מְחֻקָּק, יְהֹוָה יָהּ צְבָאוֹת.</p>\n<p>כֵּיוָן שֶׁנִּכְנָס לְהֵיכַל (שהולך ועולה אותה) הָאַהֲבָה, מִתְעוֹרֶרֶת אַהֲבָה שֶׁל נְשִׁיקוֹת עֶלְיוֹנוֹת, שֶׁכָּתוּב (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל, לִהְיוֹת נְשִׁיקוֹת שֶׁל אַהֲבָה עֶלְיוֹנָה כָּרָאוּי. וְאוֹתָן נְשִׁיקוֹת רֵאשִׁית הַהִתְעוֹרְרוּת שֶׁל כָּל אַהֲבָה, וְהִתְדַּבְּקוּת וְקֶשֶׁר שֶׁלְּמַעְלָה. וּמִשּׁוּם כָּךְ רֵאשִׁית הַתִּשְׁבַּחַת שֶׁל שִׁירָה זוֹ הוּא יִשָּׁקֵנִי.</p>\n<p>מִי יִשָּׁקֵנִי? אוֹתוֹ הַנִּסְתָּר תּוֹךְ הַסֵּתֶר הָעֶלְיוֹן. וְאִם תֹּאמַר שֶׁנִּסְתַּר כָּל הַנִּסְתָּרִים בּוֹ תְּלוּיוֹת הַנְּשִׁיקוֹת וְנוֹשֵׁק לְמַטָּה - בּא וּרְאֵה, נִסְתַּר כָּל הַנִּסְתָּרִים אֵין מִי שֶׁמַּכִּיר אוֹתוֹ, וְהוּא גִּלָּה מִמֶּנּוּ אוֹר אֶחָד דַּקִּיק וְנִסְתָּר שֶׁלֹּא הִתְגַּלָּה, רַק בִּשְׁבִיל אֶחָד דַּקִּיק שֶׁהִתְפַּשֵּׁט מִתּוֹכוֹ, וְהוּא אוֹר שֶׁמֵּאִיר לַכֹּל, וְזוֹ הִתְעוֹרְרוּת שֶׁל כָּל הַסּוֹדוֹת הָעֶלְיוֹנִים. וְהוּא נִסְתָּר. לִפְעָמִים נִסְתָּר, לִפְעָמִים גָּלוּי, וְאַף עַל גַּב שֶׁלֹּא הִתְגַּלָּה כְּלָל. וְהִתְעוֹרְרוּת הָעֲלִיָּה שֶׁל הַנְּשִׁיקוֹת תְּלוּיִים בּוֹ. וּמִתּוֹךְ שֶׁהוּא נִסְתָּר, רֵאשִׁית הַתִּשְׁבַּחַת הִיא בְּדֶרֶךְ נִסְתָּר.</p>\n<p>וְאִם בּוֹ תְּלוּיִים, מָה רוֹצֶה יַעֲקֹב כָּאן, שֶׁהֲרֵי בּוֹ תְּלוּיוֹת הַנְּשִׁיקוֹת? אֶלָּא וַדַּאי כָּךְ הוּא. יִשָּׁקֵנִי, אוֹתוֹ הַנִּסְתָּר לְמַעְלָה. וּבַמֶּה? בְּאוֹתָהּ הַמֶּרְכָּבָה (מנורה) הָעֶלְיוֹנָה שֶׁכָּל הַגְּוָנִים תְּלוּיִים וּמִתְחַבְּרִים בָּהּ. וְזֶהוּ יַעֲקֹב, כְּמוֹ שֶׁאָמַרְנוּ, דְּבֵקוּת לְהִדָּבֵק בַּמֶּלֶךְ בַּבֵּן שֶׁלּוֹ הוּא. וְעַל זֶה כָּתוּב מִנְּשִׁיקוֹת פִּיהוּ.</p>\n<p>כִּי טוֹבִים דּוֹדֶיךְ, חָזַר לַשֶּׁמֶשׁ שֶׁמֵּאִיר לַלְּבָנָה מִתּוֹךְ הָאוֹר שֶׁל אוֹתָן מְנוֹרוֹת עֶלְיוֹנוֹת, וְהוּא נוֹטֵל אֶת הָאוֹר שֶׁל כֻּלָּם וּמֵאִיר לַלְּבָנָה. וְאוֹתָם נֵרוֹת (נשיקות) עֶלְיוֹנִים, וְהוּא נוֹטֵל הָאוֹר שֶׁל כֻּלָּם וּמֵאִיר לַלְּבָנָה. וְאוֹתָם הַנֵּרוֹת שֶׁמִּזְדַּוְּגִים בּוֹ, מֵאֵיזֶה מָקוֹם מְאִירִים? חָזַר וְאָמַר מִיָּיִן, מֵאוֹתוֹ יַיִן הַמְשֻׁמָּר, מֵאוֹתוֹ יַיִן שֶׁהוּא שִׂמְחַת כָּל הַשְּׂמָחוֹת. וּמִיהוּ אוֹתוֹ הַיִּין שֶׁנּוֹתֵן חַיִּים וְשִׂמְחָה לַכֹּל? זֶה אֱלֹהִים חַיִּים, יַיִן שֶׁנּוֹתֵן חַיִּים וְחֶדְוָה לַכֹּל.</p>\n<p>עוֹד מִיָּיִן - מֵאוֹתוֹ שֵׁם שֶׁנִּקְרָא יהו\"ה. זֶהוּ יַיִן שֶׁל שִׂמְחָה, שֶׁל אַהֲבָה, שֶׁל רַחֲמִים, וּמִזֶּה כֻלָּם מְאִירִים וּשְׂמֵחִים. בָּאוּ הַחֲבֵרִים וּנְשָׁקוּהוּ בְרֹאשׁוֹ. (כשהגיעו אל רבי שמעון, סדרו הדברים לפניו).</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, יָדַעְתִּי וַדַּאי שֶׁרוּחַ קְדוֹשָׁה עֶלְיוֹנָה מְכַשְׁכֶּשֶׁת (מנצנצת) בָּכֶם. אַשְׁרֵי הַדּוֹר הַזֶּה, שֶׁהֲרֵי לֹא יִהְיֶה כַּדּוֹר הַזֶּה עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, שֶׁהֲרֵי הַתּוֹרָה חוֹזֶרֶת לְיָשְׁנָהּ. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011724,"<p>וְזֹאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם. רַבִּי אֶלְעָזָר אָמַר, פָּסוּק זֶה פֵּרְשׁוּהוּ, וְסוֹדוֹת שֶׁלּוֹ הֲרֵי נֶאֶמְרוּ. אֲבָל (פשט) סוֹד הַכָּתוּב כָּךְ לָמַדְנוּ, וְהַפְּסוּקִים קָשִׁים, שֶׁאִם הֵם בַּסּוֹד שֶׁלְּמַטָּה - קָשִׁים זֶה עַל זֶה, וְאִם הֵם בַּסּוֹד שֶׁלְּמַעְלָה - אֵינָם בָּאוֹר. (אלא כך הוא) דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ לִי תְּרוּמָה - יָפֶה. תִּקְחוּ אֶת תְּרוּמָתִי - קָשֶׁה. וְזֹאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם - קָשֶׁה, וְזֶה (ודאי) הַכֹּל, מַעְלָה וּמַטָּה כְּאֶחָד.</p>\n<p>וְיִקְחוּ לִי תְּרוּמָה - מִי? בְּנֵי יִשְׂרָאֵל. מֵאֵת כָּל אִישׁ - אֵלֶּה מַלְאָכִים עֶלְיוֹנִים לְמַעְלָה, מִשּׁוּם שֶׁעֲלֵיהֶם הִיא תְּרוּמָה, הֲרָמָה שֶׁהֵם מְרִימִים אוֹתָהּ תָּמִיד לַמֶּלֶךְ הָעֶלְיוֹן, שֶׁהֲרֵי הֵם מַעֲלִים אוֹתָהּ תָּמִיד לַמֶּלֶךְ הָעֶלְיוֹן. וּכְשֶׁיִּשְׂרָאֵל צַדִּיקִים, הֵם לוֹקְחִים אוֹתָהּ מֵהֶם וּמוֹרִידִים אוֹתָהּ לְמַטָּה. זֶהוּ שֶׁכָּתוּב מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. וּמִי הֵם? אוֹתָם הָאַרְבָּעָה שֶׁהֵרִימוּ אוֹתָהּ לְמַעְלָה, שֶׁאוֹתוֹ לֵב הִתְרַצָּה בָהֶם. וְאוֹתָהּ תִּרוּמָה הִיא זְקוּפָה עֲלֵיהֶם.</p>\n<p>וְאַףֹ עַל גַּב שֶׁהִיא עוֹמֶדֶת עֲלֵיהֶם וּמֻנַּחַת עַל גַּבֵּיהֶם - תִּקְחוּ, תִּקְחוּ אוֹתָהּ מֵהֶם לְהוֹרִידָהּ לְמַטָּה. וּבַמֶּה? בַּזְּמַן הַזֶּה - בְּאוֹתָם מַעֲשִׂים כְּשֵׁרִים, בִּתְפִלּוֹת וּבְבַקָּשׁוֹת, לַעֲשׂוֹת מִצְווֹת הַתּוֹרָה. בְּאוֹתוֹ זְמַן - בְּאוֹתָם גְּוָנִים הַנִּרְאִים לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, בְּאוֹתָן עֲבוֹדוֹת (אחרות). וְאוֹתָם גְּוָנִים מוֹשְׁכִים לְמַטָּה אוֹתָהּ הַתְּרוּמָה, וּמְנַצְּחִים הַגְּוָנִים שֶׁלְּמַטָּה אֶת אוֹתָם הַגְּוָנִים שֶׁלְּמַעְלָה, וּמוֹשְׁכִים אוֹתָם הַגְּוָנִים הַלָּלוּ לִגְוָנִים עֶלְיוֹנִים, וְנִכְנָסִים אֵלּוּ בְאֵלּוּ, וְנַעֲשִׂים אֵלּוּ גּוּף לְאֵלּוּ, וְעַל זֶה כָּתוּב תִּקְחוּ מֵאִתָּם.</p>\n<p>זָהָב שֶׁנִּכְלָל בְּגַבְרִיאֵל, זָהָב לְמַעְלָה, גַּבְרִיאֵל נוֹטֵל אוֹתוֹ לְמַטָּה. וְשִׁבְעָה מִינֵי זָהָב נִפְרָדִים לְמַטָּה מִזֶּה. וְכֶסֶף לְמַעְלָה, וְנִכְלָל בְּמִיכָאֵל לְמַטָּה, וְשׁוֹרֶה זֶה עַל זֶה. וּנְחֹשֶׁת לְמַעְלָה, וְיוֹצְאָה מִזָּהָב, מִשּׁוּם שֶׁזָּהָב וְאֵשׁ עוֹמְדִים בְּסוֹד אֶחָד וְהוֹלְכִים, אֵשׁ מוֹצִיאָה נְחֹשֶׁת. וּמִכֹּחַ וְהַתֹּקֶף הַזֶּה מִתְפַּזְּרִים נְחָשִׁים שְׂרָפִים שֶׁיּוֹצְאִים מֵאֵשׁ, וְלָכֵן נְחֹשֶׁת אֲדֻמָּה כָּאֵשׁ וְנִכְלֶלֶת בְּאוּרִיאֵ\"ל, וְנַעֲשֶׂה זֶה גּוּף לָזֶה.</p>\n<p>וּתְכֵלֶת שׁוֹרָה בָּזֶה וּבָזֶה, בַּנְּחֹשֶׁת וּבַזָּהָב, וּמִשּׁוּם שֶׁמַּחֲזִיק בִּשְׁנֵי צְדָדִים. הַתְּכֵלֶת הוּא תַּקִיף, וְאֵין מִי שֶׁשּׁוֹלֵט עָלֶיהָ לַחַיִּים, שֶׁהִיא כִּסֵּא הַדִּין לִשְׁרוֹת בּוֹ הַדִּין הַקָּשֶׁה, וְזֶהוּ ב\"ו א\"ל, ב\"ו א\"ל, שֶׁכָּתוּב (תהלים ז) וְאֵל זעֵם בְּכָל יוֹם. וּכְשֶׁחוֹזְרִים בְּנֵי אָדָם בִּתְשׁוּבָה שְׁלֵמָה, הוֹפֵךְ שְׁמוֹ לִרְפָאֵ\"ל, שֶׁזּוֹ רְפוּאָה שֶׁמִּזְדַּמֶּנֶת לָהֶם מֵאוֹתוֹ הַדִּין הַקָּשֶׁה.</p>\n<p>וְאַרְגָּמָן - זֶה זָהָב וָכֶסֶף שֶׁחוֹזְרִים לְהִכָּלֵל כְּאֶחָד, מִיכָאֵל וְגַבְרִיֵל נִכְלְלוּ זֶה עִם זֶה, מְשֻׁלָּבִים זֶה בָּזֶה, וְעַל זֶה כָּתוּב (איוב כה) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. וּמִשּׁוּם שֶׁהֵם מְשֻׁלָּבִים זֶה בָּזֶה, נַעֲשִׂים גּוּף אֶחָד.</p>\n<p>וְתוֹלַעַת שָׁנִי לְמַעְלָה, וְנִכְלָל בְּאוּרִיאֵ\"ל כְּמִקֹּדֶם לִהְיוֹת אָחוּז בְּתוֹךְ הַתְּכֵלֶת וּבְתוֹךְ הָאַרְגָּמָן, וְשֵׁשׁ הוּא לְמַעְלָה, וְנִכְלָל כְּמִקֹּדֶם בַּסּוֹד שֶׁל רְפָאֵל לְהֵאָחֵז בַּכֶּסֶף וּבַזָּהָב.</p>\n<p>עֵד כָּאן הַסּוֹד שֶׁל שִׁבְעַת הָעַמּוּדִים שֶׁלְּמַעְלָה תּוֹךְ שִׁבְעַת הָעַמּוּדִים שֶׁלְּמַטָּה, קְלִפָּה בְּתוֹךְ קְלִפָּה לִשְׁמִירָה. וְעִזִּים - הֲרֵי בֵּאַרְנוּ שֶׁהֲרֵי אֵלֶּה שִׁבְעָה, מֹחַ לְמֹחַ, וְזֶהוּ קְלִפָּה לַמֹּחַ.</p>\n<p>וְעֹרֹת אֵילִם מְאָדָּמִים - אֵלֶּה הֵם בַּעֲלֵי מָגִנִּים, עֵינַיִם לוֹהֲטוֹת בְּלַהֲבוֹת אֵשׁ, כְּמוֹ שֶׁנֶּאֱמַר (דניאל י) וְעֵינָיו כְּלַפִּידֵי אֵשׁ. וְנִקְרָאִים רְקִיעִים בַּחוּץ בְּתוֹךְ קְלִפָּה. וְעֹרֹת תְּחָשִׁים - אֵלֶּה הֵם לִפְנִים בְּצַד הַקְּדֻשָּׁה, וְנֶאֱחָזִים בַּקְּדֻשָּׁה וְלֹא נֶאֱחָזִים, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>כְּמוֹ שֶׁאָמַרְנוּ שֶׁאַבְרָהָם הֲרֵי הוֹלִיד בְּאִשָּׁה אַחֶרֶת אֶת תַּחַשׁ, כְּמוֹ שֶׁנֶּאֱמַר וְאֶת תַּחַשׁ, וְאֵלּוּ הֵם בָּאִמָּא שֶׁל יִשְׁמָעֵאל, אֲחִיהֶם שֶׁל יִשְׁמָעֵאל. שֶׁכְּמוֹ שֶׁיֵּשׁ מַדְרֵגוֹת בְּעֵשָׂו, כָּךְ גַּם יֵשׁ מַדְרֵגוֹת בְּיִשְׁמָעֵאל. אִמּוֹ שֶׁל יִשְׁמָעֵאל הוֹלִידָה לְתַחַשׁ, וּמִצִּדּוֹ שֶׁל אַבְרָהָם בָּאָה, שֶׁהֲרֵי אוֹר הָרִאשׁוֹן מצפ\"ץ בְּשָׁעָה שֶׁהוֹצִיא אוֹרוֹת לְכָל הַצְּדָדִים. כֵּיוָן שֶׁנִּמְתַּק הָאוֹר הַהוּא הָרִאשׁוֹן, גָּנַז אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. וּלְמִי גָּנַז אוֹתוֹ? לַצַּדִּיקִים. וּמִי אֵלּוּ? צַדִּיק וְצֶדֶק, כְּדֵי לַעֲשׂוֹת בָּאוֹר הָרִאשׁוֹן הַהוּא פֵּרוֹת לָעוֹלָם, וְאֵלּוּ הַפֵּרוֹת שֶׁמְּזֻמָּנִים לָבֹא לָעוֹלָם. שֶׁהֲרֵי אַבְרָהָם וְשָׂרָה עָשׂוּ (ואברהם ושרה מאותו האור עשו) פֵרוֹת וּנְפָשׁוֹת, שֶׁכָּתוּב (בראשיתי ב) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. וּכְמוֹ שֶׁעָשׂוּ נְפָשׁוֹת בְּצַד הַקְּדֻשָּׁה, כָּךְ גַּם עָשׂוּ נְפָשׁוֹת בַּצַּד הָאַחֵר, שֶׁאִם לֹא מֵאוֹתָהּ הִתְעוֹרְרוּת שֶׁהִתְעוֹרֵר אַבְרָהָם בַּצַּד הָאַחֵר, לֹא נִמְצְאוּ גֵרִים בָּעוֹלָם כְּלָל. וַעָצֵי שִׁטִּים - הֲרֵי בֵּאַרְנוּ שֶׁהֵם שְׂרָפִים עוֹמְדִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ. מַה זֶּה מִמַּעַל לוֹ? מִמַּעַל לְאוֹתָהּ הַקְּלִפָּה. וְאִם תֹּאמַר שֶׁפָּסוּק זֶה נֶאֱמַר עַל הַקָּדוֹשׁ בָּרוּךְ הוּא - וַהֲרֵי נֶאֱמַר וָאֶרְאֶה אֶת ה', אֶת דַּוְקָא, כְּמוֹ זֶה שֶׁכָּתוּב בַּפָּסוּק הַזֶּה, שֶׁכָּתוּב וְשׁוּלָיו מְלֵאִים אֶת הַהֵיכָל. אֶת דַּוְקָא, לְרַבּוֹת אוֹתָהּ הַקְּלִפָּה. כֵּיוָן שֶׁאָמַר אֶת סוֹד אוֹתָהּ הַקְּלִפָּה, כָּתוּב שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ, מִמַּעַל לְאוֹתָהּ קְלִפָּה. שֶׁמֶן לַמָּאוֹר - זֶה שֶׁמֶן מִשְׁחָה עֶלְיוֹן שֶׁבָּא מִלְמַעְלָה. שְׁנַיִם שֶׁמֶן הֵם, וְהֵם שְׁנַיִם. (אחד) לְמַעְלָה שֶׁנִּקְרָא שֶׁמֶן הַמָּאוֹר, וְאֶחָד לְמַטָּה שֶׁנִּקְרָא שֶׁמֶן לַמָּאוֹר.</p>\n<p>שֶׁמֶן הַמָּאוֹר הוּא עֶלְיוֹן, שֶׁעוֹמֵד בְּוַדַּאי וְלֹא פוֹסֵק לְעוֹלָמִים, וְתָמִיד מָלֵא מִשְׁחַת קֹדֶשׁ, וְכָל הַבְּרָכוֹת וְכָל הָאוֹרוֹת וְכָל הַמְּנוֹרוֹת כֻּלָּם מִתְבָּרְכִים וּנְאוֹרִים מִשָּׁם. שֶׁמֶן לַמָּאוֹר, לִפְעָמִים מִתְמַלֵּא וְלִפְעָמִים לֹא.</p>\n<p>עוֹד, הֲרֵי שָׁנִינוּ, כָּתוּב (בראשית א) וַיַּעַשׂ אֱלֹהִים אֶת שְׁנֵי הַמְּאֹרֹת הַגְּדלִים וְגוֹ', וְאַף עַל גַּב שֶׁהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים וְכָךְ הוּא, אֲבָל שְׁנֵי הַמְּאוֹרוֹת הַגְּדוֹלִים הָאֵלֶּה - שֶׁמֶן הַמָּאוֹר וְשֶׁמֶן לַמָּאוֹר. עוֹלָם עֶלְיוֹן וְעוֹלָם תַּחְתּוֹן. אֶחָד זָכָר וְאֶחָד נְקֵבָה. וְכָל זְמַן שֶׁהַזָּכָר וְהַנְּקֵבָה בָּאִים כְּאֶחָד, שְׁנֵיהֶם קְרוּיִים בִּלְשׁוֹן זָכָר. וּמִשּׁוּם שֶׁהָעוֹלָם הָעֶלְיוֹן נִקְרָא גָדוֹל, בִּשְׁבִילוֹ הָעוֹלָם הַתַּחְתּוֹן שֶׁמִּתְחַבֵּר עִמּוֹ בִּכְלָל נִקְרָא גָדוֹל.</p>\n<p>כֵּיוָן שֶׁנִּפְרָדִים זֶה מִזֶּה, הֵם נִזְכָּרִים בִּפְרָט, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. זֶה נִקְרָא גָדוֹל, וְזֶה נִקְרָא קָטָן. וּמִשּׁוּם כָּךְ אָמְרוּ הָרִאשׁוֹנִים, שֶׁיִּהְיֶה אָדָם זָנָב לָאֲרָיוֹת, וְלֹא רֹאשׁ לַשּׁוּעָלִים. שֶׁכְּשֶׁהוּא עוֹמֵד בְּתוֹךְ הָאֲרָיוֹת, נִקְרָא הַכֹּל בִּכְלָל שֶׁל אֲרָיוֹת. זְנַב הָאַרְיֵה הוּא אַרְיֵה בְּלִי הַפְרָדָה. וְאִם בְּתוֹךְ שׁוּעָלִים, אֲפִלּוּ שֶׁהוּא רֹאשׁ - רֹאשׁ הַשּׁוּעָל הוּא שׁוּעָל בְּלִי הַפְרָדָה, וְנִקְרָא שׁוּעָל.</p>\n<p>וְזְהִ סוֹד הַפָּסוּק הַזֶּה, שֶׁהֲרֵי בָּרִאשׁוֹנָה כְּשֶׁיּוֹשְׁבִים כְּאֶחָד, שְׁנֵי הַמְּאֹרֹת הַגְּדֹלִים נִקְרְאוּ, אַף עַל גַּב שֶׁזֶּה זָנָב אֶל הָעֶלְיוֹן. כֵּיוָן שֶׁזֶּה נִפְרָד מֵהָעֶלְיוֹן כִּבְיָכוֹל לִהְיוֹת רֹאשׁ לַשּׁוּעָלִים, אָז נִקְרָא קָטָן. וְעַל סוֹד זֶה שֶׁמֶן הַמָּאוֹר, שֶׁלֹּא פוֹסֵק לְעוֹלָמִים וְעוֹמֵד בַּעֲלִיָּה עֶלְיוֹנָה לִשְׁלֹט בַּיּוֹם. שֶׁמֶן לַמָּאוֹר פּוֹסֵק, וְנִקְרָא קָטָן, וְשׁוֹלֵט בַּלַּיְלָה.</p>\n<p>וַחֲמִשָּׁה בְשָׂמִים הֵם לְתוֹךְ שֶׁמֶן וּקְטֹרֶת, וְאַף עַל גַּב שֶׁהִיא אֶחָד - הֵם שְׁנַיִם, וְהַכֹּל אֶחָד. אַבְנֵי שֹׁהַם וְגוֹ'. כָּל אֵלֶּה שְׁלֹשָׁה עָשָׂר הֵם, וְהֵם תִּקּוּן הַמִּשְׁכָּן.</p>\n<p>וְחָזַרְנוּ לַדְּבָרִים הָרִאשׁוֹנִים. זָהָב - הֲרֵי נֶאֱמַר שֶׁשִּׁבְעָה מִינֵי זָהָב הֵם. וְאִם תֹּאמַר שֶׁזָּהָב הוּא דִּין וְכֶסֶף הוּא רַחֲמִים, וְעוֹלֶה הַזָּהָב לְמַעְלָה מִמֶּנּוּ - לֹא כָּךְ! שֶׁוַּדַּאי זָהָב עוֹלֶה יוֹתֵר הוּא עַל הַכֹּל, אֲבָל זָהָב הוּא בְּדֶרֶךְ סְתָם, וְזֶה הַזָּהָב הָעֶלְיוֹן, שֶׁהוּא שְׁבִיעִי מִכָּל מִינֵי הַזָּהָב, וְזֶהוּ הַזָּהָב שֶׁמֵּאִיר וְנוֹצֵץ לָעֵינַיִם, וְזֶהוּ שֶׁכְּשֶׁיּוֹצֵא לָעוֹלָם, מִי שֶׁמַּשִּׂיג אוֹתוֹ טוֹמֵן אוֹתוֹ בְּתוֹכוֹ, וּמִשָּׁם יוֹצְאִים וְנִמְשָׁכִים כָּל מִינֵי זָהָב.</p>\n<p>מָתַי נִקְרָא זָהָב? מִי שֶׁנִּקְרָא זָהָב? כְּשֶׁהוּא בְּאוֹר, וּמִתְעַלֶּה בִּכְבוֹד הַפַּחַד, וְהוּא בְּשִׂמְחָה עֶלְיוֹנָה לְשַׂמֵּחַ אֶת הַתַּחְתּוֹנִים. וּכְשֶׁהוּא בְּדִין, כְּשֶׁמִּשְׁתַּנֶּה מֵאוֹתוֹ גָוֶן לְגָוֶן תְּכֵלֶת שָׁחֹר וְאָדם, אָז הוּא בַּדִּין הַקָּשֶׁה. אֲבָל זָהָב הוּא בְּשִׂמְחָה, וּבַעֲלִיַּת הַפַּחַד שֶׁל שִׂמְחָה עוֹמֵד וּבְהִתְעוֹרְרוּת הַשִּׂמְחָה.</p>\n<p>וָכֶסֶף - לְמַטָּה, הַסּוֹד שֶׁל זְרוֹעַ יָמִין, שֶׁהֲרֵי הָרֹאשׁ הָעֶלְיוֹן הוּא זָהָב (דין), שֶׁכָּתוּב (דניאלב) אַתָּה הוּא רֹאשׁ הַזָּהָב. חָזֵהוּ וּזְרוֹעוֹתָיו שֶׁל כֶּסֶף לְמַטָּה. (ואימתי נשלם הכסף, ' כאשר הוא נכלל וכו') וּכְשֶׁנִּשְׁתַּלֵּם הַכֶּסֶף, אָז נִכְלָל בַּזָּהָב, וְסוֹד זֶה - (משלי כד) תַּפּוּחֵי זָהָב בְּמַשְׂכִּיּוֹת כָּסֶף. נִמְצָא שֶׁכֶּסֶף הוֹפֵךְ לְזָהָב וְאָז נִשְׁתַּלֵּם מְקוֹמוֹ. וְלָכֵן שִׁבְעָה מִינֵי זָהָב הֵם.</p>\n<p>וּנְחֹשֶׁת יוֹצֵאת מִזָּהָב וּמִשְׁתַּנָּה לְגֵרָעוֹן, זְרוֹעַ שְׂמֹאל. וּתְכֵלֶת - יָרֵךְ שְׂמֹאל. וְתוֹלַעַת שָׁנִי - יָרֵךְ יָמִין, וְנִכְלֶלֶת בַּשְּׂמֹאל. וְשֵׁשׁ - זֶה נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, שֶׁנּוֹטֵל כָּל שֵׁשֶׁת הַצְּדָדִים. וּכְמוֹ זֶה לְמַטָּה, וַהֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר.</p>\n<p>הֲרֵי כָּאן שֶׁבַע שֶׁל יוֹבֵל, וְהֵם שֶׁבַע שֶׁל שְׁמִטָּה. וְאַף עַל גַּב שֶׁהֵם שֵׁשׁ, הֵם שְׁלֹשׁ עֶשְׂרֵה, בַּשְּׁבִיעִי, שֶׁהוּא רֹאשׁ עֲלֵיהֶם, הֲרֵי שְׁלֹשׁ עֶשְׂרֵה. הָרֹאשׁ שֶׁעוֹמֵד עַל כָּל הַגּוּף לְמַטָּה, הָרֹאשׁ שֶׁעוֹמֵד עַל כָּל אֵיבְרֵי הַגּוּף הוּא זָהָב. מַה בֵּין זֶה לָזֶה? הַזָּהָב הָעֶלְיוֹן הוּא בְּסוֹד נִסְתָּר, וּשְׁמוֹ הוּא זָהָב סָגוּר, סָגוּר וְסָתוּם מִן הַכֹּל, וְלָכֵן נִקְרָא סָגוּר, שֶׁהוּא סָגוּר מֵהָעַיִן שֶׁאֵינָהּ שׁוֹלֶטֶת בּוֹ. הַזָּהָב הַתַּחְתּוֹן הוּא יוֹתֵר גָּלוּי. (ושמו נקרא זהב ירקרק וכו').</p>"],[9522011725,"<p>לְשַׁעִִתּוֹ הוּא הָיָה, שֶׁכָּתוּב וְרוּחַ אֱלֹהִים לָבְשָׁה אֶת זְכַרְיָה. וְאִם תֹּאמַר, הֲרֵי יִרְמְיָהוּ שֶׁבּוֹ כָּתוּב (ירמיה א) בְּטֶרֶם אֱצָרְךְ בַבֶּטֶן יְדַעְתִּיךְ, וַהֲרֵי אֲחֵרִים - אֶלָּא כֻלָּם לֹא זָכוּ לִנְבוּאָה וְלִכְהֻנָּה עֶלְיוֹנָה כְּמוֹ אַהֲרֹן, שֶׁהֲרֵי אַהֲרֹן זָכָה בִּנְבוּאָה עֶלְיוֹנָה עַל כָּל שְׁאָר הַכֹּהֲנִים. זָכָה בִּכְהֻנָּה עַל כֻּלָּם.</p>\n<p>מֹשֶׁה זָכָה בִּנְבוּאָה, וְשִׁמֵּשׁ בִּכְהֻנָּה עֶלְיוֹנָה. שְׁמוּאֵל זָכָה בִּשְׁתֵּיהֶן. מַה מֹּשֶׁה הָיָה קוֹרֵא וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵשִׁיב לוֹ מִיָּד - אַף בִּשְׁמוּאֵל כָּתוּב (שמואל איב) הֲלֹא קְצִיר חִטִּים הַיּוֹם אֶקְרָא אֶל ה' וְיִתֵּן קֹלוֹת וְגוֹ'. אֲבָל לֹא עָלָה לְדַרְגָּה עֶלְיוֹנָה כְּמֹשֶׁה. מָה אַהֲרֹן הָיָה מְשַׁמֵּשׁ בִּכְהֻנָּה אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא - אַף שְׁמוּאֵל הָיָה מְשַׁמֵּשׁ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל לֹא עָלָה בְּשִׁמּוּשׁ עֶלְיוֹן כְּמוֹ אַהֲרֹן.</p>\n<p>וְהַדָּבָר כָּךְ הוּא: שְׁלֹשָׁה הֵם שֶׁהָיוּ נְבִיאִים נֶאֱמָנִים וְשִׁמְּשׁוּ בִּכְהֻנָּה. אֶחָד מֹשֶׁה, וְאֶחָד אַהֲרֹן, וְאֶחָד שְׁמוּאֵל. וְאִם תֹּאמַר שֶׁשְּׁמוּאֵל לֹא הִמְשִׁיךְ (שמש) בַּכְּהֻנָּה, אֶלָּא אַחֵר הָיָה שֶׁשִּׁמֵּשׁ בִּכְהֻנָּה, וּמִיהוּ? יִרְמְיָהוּ - לֹא כָּךְ! שֶׁהֲרֵי כָּתוּב (ירמיהא) מִן הַכֹּהֲנִים אֲשֶׁר בַּעֲנָתוֹת. מִן הַכֹּהֲנִים הָיָה, אֲבָל לֹא שִׁמֵּשׁ. וּשְׁמוּאֵל שִׁמֵּשׁ בִּימֵי עֵלִי, וּמֹשֶׁה פַּעַם אַחַת כָּל אוֹתָם שִׁבְעַת יְמֵי הַמִּלּוּאִים.</p>\n<p>שְׁמוּאֵל זָכָה לְנַעַר, שֶׁכָּתוּב (שמואל א א) וְהַנַּעַר נָעַר. (שם ב) וּשְׁמוּאֵל מְשָׁרֵת. וּמִשּׁוּם שֶׁעוֹמֵד בַּדַּרְגָּה הַזּוֹ, וַדַּאי שֶׁהוּא כְּמוֹ מֹשֶׁה וְאַהֲרֹן. מִי שֶׁנּוֹטֵל אֶת הַנַּעַר הַזֶּה וְזוֹכֶה בּוֹ, זוֹכֶה בְּאוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת שֶׁעָמְדוּ בָהֶם מֹשֶׁה וְאַהֲרֹן.</p>"],[9522011726,"<p>הַכְּרוּבִים הֵם זָהָב, כְּמוֹ שֶׁבֵּאֲרוּהָ, מִשּׁוּם שֶׁיּוֹצְאִים מִצַּד הַזָּהָב, וְלֹא מְעֹרָב בָּהֶם כֶּסֶף וְלֹא גָוֶן אַחֵר, וְזֶהו גָּוֶן זָהָב יְרַקְרַק. בַּמִּשְׁכָּן מִתְעָרְבִים הַגְּוָנִים זָהָב וָכֶסֶף לָלֶכֶת כְּאֶחָד, לִהְיוֹת סוֹד שֶׁלְּמַעְלָה בְּאֶחָד. עוֹד נְחֹשֶׁת לִהְיוֹת עִמָּם, וְלָלֶכֶת בֵּין כָּל הַצְּדָדִים, שֶׁתִּמָּצֵא שְׁלֵמוּת בַּכֹּל כְּאֶחָד, שֶׁכָּתוּב זָהָב וָכֶסֶף וּנְחֹשֶׁת.</p>\n<p>דָּבָר אַחֵר זָהָב וָכֶסֶף - זֶה שֶׁחוֹזֵר לְכֶסֶף, וְכֶסֶף לְזָהָב, וְהַכֹּל כָּלוּל יַחַד וּבְמָקוֹם אֶחָד. בְּשָׁלֹשׁ צוּרוֹת חוֹזֵר: כַּאֲשֶׁר צָרִיךְ לְשִׂמְחָה וְלֹא לְדִין - זָהָב. כַּאֲשֶׁר צָרִיךְ לְרַחֲמִים - כֶּסֶף. כַּאֲשֶׁר צָרִיךְ תֹּקֶף הַדִּין - נְחֹשֶׁת.</p>\n<p>וְעַל זֶה הִסְתַּכֵּל מֹשֶׁה בַּמַּעֲשֶׂה שֶׁל נְחַשׁ הַנְּחֹשֶׁת, שֶׁכָּתוּב וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת, וְהָיָה יוֹדֵעַ הַמָּקוֹם שֶׁל הִתּוּךְ הַזָּהָב בְּאוֹתָהּ נְחֹשֶׁת, מִשּׁוּם שֶׁנָּחָשׁ הוּא כִּלְשׁוֹנוֹ, וּמְקוֹמוֹ הָיָה יוֹדֵעַ. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא אָמַר לוֹ אֶלָּא עֲשֵׂה לְךְ שָׂרָף, וְהוּא בָּא וְעָשָׂה נְחַשׁ נְחֹשֶׁת, שֶׁכָּתוּב וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת. מָה הַטַּעַם?</p>\n<p>אֶלָּא מָקוֹם הָיָה יוֹדֵעַ, וְעִקַּר הַדָּבָר הָיָה, שֶׁהֲרֵי בָּרִאשׁוֹנָה כָּתוּב וַיְשַׁלַּח ה' בָּעָם אֶת הַנְּחָשִׁים הַשְּׂרָפִים, וְכָתוּב נָחָשׁ שָׂרָף. עִקָּרָם הוּא נָחָשׁ. וּמִשּׁוּם שֶׁמֹּשֶׁה הָיָה יוֹדֵעַ אֶת הָעִקָּר וְהַשֹּׁרֶשׁ וְהַיְסוֹד מֵאוֹתוֹ מָקוֹם, עָשָׂה נָחָשׁ וְהִסְתַּמֵּךְ עָלָיו. מָה הַטַּעַם? כִּי יִשְׂרָאֵל חָטְאוּ בִלְשׁוֹנָם, שֶׁכָּתוּב וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה, וְעַל זֶה וַיְשַׁלַּח ה' בָּעָם אֶת הַנְּחָשִׁים הַשְּׂרָפִים.</p>\n<p>וּמֹשֶׁה לֹא הָלַךְ אֶלָּא אַחַר הָעִקָּר וְעָשָׂה נְחַשׁ נְחֹשֶׁת בְּאוֹתוֹ גָוֶן שֶׁצָּרִיךְ לוֹ, שֶׁהֲרֵי מְקוֹמוֹ הוּא נְחֹשֶׁת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא אָמַר לוֹ מִמַּה יַּעֲשֶׂה, וּמֹשֶׁה הִתְבּוֹנֵן וְעָשָׂה אוֹתוֹ מִנְּחֹשֶׁת כְּפִי שֶׁצָּרִיךְ לִמְקוֹמוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת וַיְשִׂמֵהוּ עַל הַנֵּס. מַה זֶּה עַל הַנֵּס? עַל אוֹתוֹ רֹשֶׁם שֶׁהוּא לְמַעְלָה.</p>\n<p>וַהֲרֵי שָׁנִינוּ, בְּכָל מָקוֹם הַנָּחָשׁ הַזֶּה הוֹלֵךְ אַחַר סוֹד שֶׁל אֵשֶׁת חַיִל, וּצְרִיכָה אֵשֶׁת זְנוּנִים לְתַקֵּן עַצְמָהּ כְּמוֹ שֶׁלָּהּ, וְלֹא יְכוֹלָה. הָרֹשֶׁם וְהָאוֹת שֶׁל אֵשֶׁת חַיִל הוּא הָאוֹת ה', וְכָךְ רָאוּי לָהּ. הָרֹשֶׁם הַהוּא שֶׁל אֵשֶׁת זְנוּנִים וְהָאוֹת שֶׁלָּהּ הוּא כְּמוֹ אוֹתוֹ גָוֶן (שצריך), וְלֹא הִתְתַּקֵּן לִהְיוֹת כָּךְ, וְהָאוֹת שֶׁלָּהּ ק'. הָאוֹת שֶׁלָּהּ הִתְתַּקְּנָה בַּתִּקּוּן שֶׁל הָאוֹת ה', (אותק'באותוגוןשלה', ולאנתקנהלהיות כך, האותשלהנתקנהבתקוןשלהאותה') כְּמוֹ קוֹף אֵצֶל בְּנֵי הָאָדָם שֶׁהוֹלֵךְ אַחַר בְּנֵי אָדָם וְלֹא נִתְקָן לַעֲשׂוֹת כָּךְ. כְּמוֹ כֵן עָשָׂה מֹשֶׁה אֶת אוֹתוֹ הַנָּחָשׁ עַל אוֹתוֹ רֹשֶׁם שֶׁרָאוּי לוֹ, וְתָמִיד מְתֻקָּן לְהָרַע, וְעָלָיו חָטָא אָדָם וְגֹרַשׁ מִגַּן עֵדֶן, שֶׁיִּהְיֶה מְקוֹם דִּיּוּרוֹ כְּמוֹ הַדִּיּוּר שֶׁלְּמַעְלָה.</p>"],[9522011727,"<p>כָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. אָמַר רַבִּי יוֹסֵי, אוֹתוֹ אוֹר נִגְנַז וְהִזְדַּמֵּן לַצַּדִּיקִים לָעוֹלָם הַבָּא, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (תהלים צו) אוֹר זָרֻעַ לַצַּדִּיק, לַצַּדִּיק וַדַּאי סְתָם. וְאוֹתוֹ הָאוֹר לֹא שִׁמֵּשׁ בָּעוֹלָם פְּרָט לַיּוֹם הָרִאשׁוֹן, וְאַחַר כָּךְ נִגְנַז וְלֹא שִׁמֵּשׁ יוֹתֵר.</p>\n<p>רַבִּי יְהוּדָה אוֹמֵר, אִלְמָלֵא נִגְנַז מִכֹּל וָכֹל, לֹא עוֹמֵד הָעוֹלָם אֲפִלּוּ רֶגַע אֶחָד, אֶלָּא נִגְנַז וְנִזְרַע כַּזֶּרַע הַזֶּה שֶׁעוֹשֶׂה תוֹלָדוֹת וּזְרָעִים וּפֵרוֹת, וּמִמֶּנּוּ הִתְקַיֵּם הָעוֹלָם. וְאֵין לְךְ יוֹם שֶׁלֹּא יוֹצֵא מִמֶּנּוּ בָּעוֹלָם וּמְקַיֵּם הַכֹּל שֶׁבּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא זָן אֶת הָעוֹלָם. וּבְכָל מָקוֹם שֶׁעוֹסְקִים בַּתּוֹרָה בַּלַּיְלָה, חוּט אֶחָד יוֹצֵא מֵאוֹתוֹ אוֹר גָּנוּז וְנִמְשָׁךְ עַל אוֹתָם שֶׁעוֹסְקִים בָּהּ. זֶהוּ שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>בַּיּוֹם שֶׁהוּקַם הַמִּשְׁכָּן לְמַטָּה, מַה כָּתוּב? (שמות מ) וְלֹא יָכֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד כִּי שָׁכַן עָלָיו הֶעָנָן. מַה זֶּה הֶעָנָן? חוּט אֶחָד הָיָה (עמוד הענן) מֵאוֹתוֹ צַד שֶׁל הָאוֹר הָרִאשׁוֹן שֶׁיָּצָא בְּשִׂמְחָה בַּכֹּל (של הכל) כְּשֶׁנִּכְנַס לַמִּשְׁכָּן שֶׁלְּמַטָּה, וּמֵאוֹתוֹ יוֹם (ראשון) לֹא נִגְלָה, אֲבָל שִׁמּוּשׁ מְשַׁמֵּשׁ בָּעוֹלָם, וְהוּא מְחַדֵּשׁ בְּכָל יוֹם מַעֲשֵׂה בְרֵאשִׁית.</p>\n<p>רַבִּי יוֹסֵי הָיָה עוֹסֵק בַּתּוֹרָה, וְהָיוּ עִמּוֹ רַבִּי יִצְחָק וְרַבִּי חִזְקִיָּה. אָמַר רַבִּי יִצְחָק, הֲרֵי רָאִינוּ שֶׁמַּעֲשֵׂה הַמִּשְׁכָּן הוּא כְּמוֹ מַעֲשֵׂה שָׁמַיִם וָאָרֶץ, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים בַּסּוֹדוֹת שֶׁלָּהֶם מְעַט, שֶׁלֹּא יָכוֹל אִישׁ לֶאֱכֹל בְּפִיו וּלְהוֹשִׁיט יָדוֹ לְתוֹךְ פִּיו וְלִבְלֹעַ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, דְּבָרִים אֵלּוּ נַעֲלֶה אוֹתָם לְתוֹךְ (אצלו) הַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁהוּא מְתַקֵּן תַּבְשִׁילִים מְתוּקִים, כְּמוֹ שֶׁהִתְקִינָם הָעַתִּיק הַקָּדוֹשׁ, נִסְתַּר כָּל הַנִּסְתָּרִים, וְהוּא מַתְקִין תַּבְשִׁילִים, שֶׁאֵין בָּהּ מָקוֹם שֶׁיָּבֹא אַחֵר וְיִשְׁפֹּךְ בָּהֶם מֶלַח. וְעוֹד, שֶׁיָּכוֹל אָדָם לֶאֱכֹל וְלִשְׁתּוֹת וּלְהַשְׁלִים כְּרֵסוֹ מִכָּל עִדּוּנֵי הָעוֹלָם וּלְהִשָּׁאֵר, וּבוֹ יִתְקַיֵּם (מלכים ב ד) וַיִּתֵּן לִפְנֵיהֶם וַיֹּאכְלוּ וַיּוֹתִרוּ כִּדְבַר ה'.</p>"],[9522011728,"<p>פָּתַח וְאָמַר, (שם א ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ וַיְהִי שָׁלֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה וַיִּכְרְתוּ בְרִית שְׁנֵיהֶם. פָּסוּק זֶה הֲרֵי נֶאֱמַר בְּכַמָּה מְקוֹמוֹת. אֲבָל וַה' - הַסְכָּמָה שֶׁלְּמַעְלָה וּמַטָּה כְּאֶחָד. וַה' - הוּא וּבֵית דִּינוֹ. נָתַן חָכְמָה - נָתַן, כְּמוֹ שֶׁנּוֹתֵן דּוֹרוֹן וּמַתָּנוֹת לַאֲהוּבוֹ. כַּאֲשֶׁר דִּבֶּר לוֹ - שְׁלֵמוּת הַחָכְמָה, בְּעֹשֶׁר, וּבְשָׁלוֹם וּבְשִׁלְטוֹן. זֶהוּ שֶׁכָּתוּב כַּאֲשֶׁר דִּבֶּר לוֹ.</p>\n<p>וַיְהִי שָׁלֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה, מָה הַטַּעַם? כִּי הָיוּ מַכִּירִים זֶה עִם זֶה אֶת סֵתֶר הַדְּבָרִים שֶׁהָיוּ אוֹמְרִים, וּבְנֵי אָדָם אֲחֵרִים לֹא הָיוּ יוֹדְעִים לְהִתְבּוֹנֵן וְלָדַעַת בָּהֶם כְּלָל, וּבִשְׁבִילָם חָזַר חִירָם לְהוֹדוֹת לִשְׁלֹמֹה בְּכָל דְּבָרָיו.</p>\n<p>שְׁלֹמֹה הַמֶּלֶךְ הִתְבּוֹנֵן וְהָיָה רוֹאֶה, שֶׁהֲרֵי אֲפִלּוּ בְּאוֹתוֹ דוֹר, שֶׁהָיָה שָׁלֵם מִכָּל הַדּוֹרוֹת הָאֲחֵרִים, לֹא הָיָה רְצוֹן הַמֶּלֶךְ הָעֶלְיוֹן שֶׁתִּתְגַּלֶּה חָכְמָה כָּל כָּךְ עַל יָדוֹ, (ולא התגלתה) שֶׁתִּתְגַּלֶּה תוֹרָה שֶׁהָיְתָה נִסְתֶּרֶת בָּרִאשׁוֹנָה, וּפָתַח לָהּ פְּתָחִים. וְאַף עַל גַּב שֶׁפָּתַח, הֵם נִסְתָּרִים, פְּרָט לְאוֹתָם חֲכָמִים שֶׁזָּכוּ וּמְגַמְגְּמִים בָּהֶם, וְלֹא יוֹדְעִים לִפְתֹּחַ בָּהֶם פֶּה. וְהַדּוֹר הַזֶּה שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בְּתוֹכוֹ, רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בִּשְׁבִיל רַבִּי שִׁמְעוֹן, שֶׁיִּתְגַּלּוּ דְבָרִים נִסְתָּרִים עַל יָדוֹ.</p>\n<p>אֲבָל תְּמֵהַנִי עַל חַכְמֵי הַדּוֹר אֵיךְ עוֹזְבִים אֲפִלּוּ רֶגַע אֶחָד מִלַּעֲמֹד לִפְנֵי רַבִּי שִׁמְעוֹן לַעֲסֹק בַּתּוֹרָה, בְּעוֹד שֶׁרַבִּי שִׁמְעוֹן עוֹמֵד בָּעוֹלָם, אֲבָל בַּדּוֹר הַזֶּה לֹא תִשָּׁכַח הַחָכְמָה מִן הָעוֹלָם. אוֹי לַדּוֹר כְּשֶׁהוּא יִסְתַּלֵּק, וְהַחֲכָמִים יִתְמַעֲטוּ, וְהַחָכְמָה תִּשְׁתַּכַּח מֵהָעוֹלָם.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַדַּאי כָּךְ הוּא, שֶׁהֲרֵי יוֹם אֶחָד הָיִיתִי הוֹלֵךְ עִמּוֹ בַּדֶּרֶךְ, וּפָתַח פִּיו בַּתּוֹרָה, וְרָאִיתִי עַמּוּד עָנָן נָעוּץ מִמַּעְלָה לְמַטָּה, וְזֹּהַר אֶחָד זוֹהֵר תּוֹךְ הָעַמּוּד. פָּחַדְתִּי פַּחַד רַב וְאָמַרְתִּי: אַשְׁרֵי הָאִישׁ שֶׁכָּךְ הִזְדַּמֵּן לוֹ בָּעוֹלָם הַזֶּה.</p>\n<p>מַה כָּתוּב בְּמֹשֶׁה? (שמות לג) וְרָאָה כָל הָעָם אֶת עַמּוּד הֶעָנָן עֹמֵד פֶּתַח הָאֹהֶל וְקָם כָּל הָעָם וְהִשְׁתַּחֲווּ אִישׁ פֶּתַח אָהֳלוֹ. נָאֶה הוּא לְמֹשֶׁה, שֶׁהוּא נָבִיא נֶאֱמָן עֶלְיוֹן עַל כָּל נְבִיאֵי הָעוֹלָם, וְאוֹתוֹ דוֹר שֶׁקִּבְּלוּ תוֹרָה עַל הַר סִינַי וְרָאוּ כַּמָּה נִסִּים וְכַמָּה גְבוּרוֹת בְּמִצְרַיִם וְעַל הַיָּם. אֲבָל כָּאן בַּדּוֹר הַזֶּה, הַזְּכוּת הָעֶלְיוֹנָה שֶׁרַבִּי שִׁמְעוֹן עָשָׂה - לְהֵרָאוֹת נִסִּים עַל יָדוֹ.</p>"],[9522011729,"<p>וּתְכֵלֶת, אָמַר רַבִּי יִצְחָק, תְּכֵלֶת מֵאוֹתוֹ דָג שֶׁל יָם גִּינוֹסָר, שֶׁהוּא בְּגוֹרָלוֹ שֶׁל זְבוּלוּן, וְהִצְטָרֵךְ הַגָּוֶן הַזֶּה לְמַעֲשֵׂה הַמִּשְׁכָּן שֶׁיֵּרָאֶה הַגָּוֶן הַזֶּה.</p>\n<p>פָּתַח וְאָמַר, (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. הָרָקִיעַ הַזֶּה נִבְרָא בַּשֵּׁנִי, שֶׁהַמַּעֲשֶׂה הַזֶּה הוּא מִצַּד הַשְּׂמֹאל. וּבַיּוֹם הַשֵּׁנִי שֶׁהוּא צַד הַשְּׂמֹאל, בּוֹ נִבְרָא גֵיהִנֹּם שֶׁיּוֹצֵא מִתּוֹךְ הִתּוּךְ הָאֵשׁ שֶׁל הַשְּׂמֹאל, וּבַיָּם נִצְבָּע בּוֹ גָּוֶן תְּכֵלֶת, שֶׁהוּא כִּסֵּא הַדִּין.</p>\n<p>וְנוֹטֵל הַיּוֹם הַמַּיִם שֶׁהָיוּ מִצַּד הַיָּמִין, וְאוֹתָם הַמַּיִם שֶׁהָיוּ מִצַּד הַיָּמִין לֹא הִתְגַּלּוּ אֶלָּא בְּיוֹם שֵׁנִי. בַּיּוֹם שֶׁלּוֹ לֹא הִתְגַּלָּה מַיִם, אֶלָּא הִתְחַלֵּף, מִשּׁוּם שֶׁנִּכְלָל זֶה בָּזֶה וְהִתְבַּסֵּם זֶה בָּזֶה. הָאוֹר שֶׁל הַיּוֹם הָרִאשׁוֹן, הָאוֹר הָרִאשׁוֹן מִכָּל שֵׁשֶׁת הָאוֹרוֹת הוּא. וְהָאוֹר הַזֶּה הָיָה בְּצַד הָאֵשׁ, שֶׁכָּתוּב (ישעיה י) וְהָיָה אוֹר יִשְׂרָאֵל לְאֵשׁ. וְאוֹתוֹ אוֹר שֶׁל יִשְׂרָאֵל הָיָה מִצַּד הַיָּמִין, נִכְלָל בְּאֵשׁ.</p>\n<p>וְהַיּוֹם הָרִאשׁוֹן מֵאוֹתָם שֵׁשֶׁת הַיָּמִים הוּא מַיִם, וְלֹא שִׁמֵּשׁ מַעֲשֵׂה הַמַּיִם, אֶלָּא מַעֲשֵׂה הָאוֹר, שֶׁהוּא מִצַּד הָאֵשׁ, שֶׁהוּא יוֹם שֵׁנִי, לְהַרְאוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא בָרָא אֶת הָעוֹלָם אֶלָּא עַל שָׁלוֹם, וּבְדֶרֶךְ שָׁלוֹם הַכֹּל הָיָה. הַיּוֹם הָרִאשׁוֹן, כָּל מַה שֶּׁעָשָׂה, מִצַּד חֲבֵרוֹ עָשָׂה. הַיּוֹם הַשֵּׁנִי בְּצַד יוֹם הָרִאשׁוֹן עָשָׂה אוֹתוֹ אֻמָּן וְשִׁמֵּשׁ בָּהּ, שֶׁכָּל אֶחָד שִׁמֵּשׁ בְּמַעֲשֵׂה חֲבֵרוֹ, לְהַרְאוֹת שֶׁהַכֹּל נִכְלְלוּ זֶה בָּזֶה. הַיּוֹם הַשְּׁלִישִׁי הָיָה בַּצַּד שֶׁל שְׁנֵיהֶם, וּבוֹ הָיָה אַרְגָּמָן, וְעַל זֶה כָּתוּב כִּי טוֹב כִּי טוֹב פַּעֲמַיִם בַּיּוֹם הַשְּׁלִישִׁי.</p>\n<p>תְּכֵלֶת, זֶה הַיּוֹם הַשֵּׁנִי, נִצְבַּע בִּשְׁנֵי גְוָנִים - אָדם וְשָׁחֹר. וּתְכֵלֶת - הָאָדם הוּא שֶׁלּוֹ, מֵהַיּוֹם הַשֵּׁנִי מַמָּשׁ, כְּעֵין גּוֹן הָאֵשׁ, וְזֶהוּ אֱלֹהִים, וְיָרַשׁ גּוֹן הַזָּהָב, שֶׁהַכֹּל גָּוֶן אֶחָד. תְּכֵלֶת יוֹצֵאת מִתּוֹךְ אוֹתוֹ גָּוֶן אָדם, וּכְשֶׁיּוֹרֵד לְמַטָּה, הִתְרַחֵק גָּוֶן אָדם, וְנִכְנָס לְתוֹךְ אוֹתוֹ מָקוֹם, שֶׁהוּא הַיָּם, וְנִצְבָּע בְּגָוֶן תְּכֵלֶת. אוֹתוֹ אָדם נִכְנָס לְתוֹךְ הַיָּם וְנֶחֱלָשׁ גּוֹנוֹ וְהוֹפֵךְ לִתְכֵלֶת, וְזֶהוּ אֱלֹהִים, אֲבָל אֵינוֹ חָזָק כְּמוֹ הָרִאשׁוֹן.</p>\n<p>שָׁחֹר, גָּוֶן זֶה יוֹצֵא מֵהִתּוּךְ הָאָדֹם כְּשֶׁמִּתְהַתֵּךְ וְנֶחֱלָשׁ לְמַטָּה בְּהִתּוּךְ הַזֻּהֲמָה, וְיוֹרֵד לְמַטָּה, וְיוֹצֵא מֵאוֹתָהּ זֻהֲמָה גָּוֶן אָדם, מֵהַזֻּהֲמָה הַקָּשָׁה, וּמִתּוֹךְ הַזֻּהֲמָה הַקָּשָׁה הוֹפֵךְ לְשָׁחֹר. וְהַכֹּל מֵאוֹתוֹ הָאָדֹם הָרִאשׁוֹן (העליון) הִתְהַתֵּךְ, וְכָל זֶה נִבְרָא בַּשֵּׁנִי, וְזֶה נִקְרָא אֱלֹהִים אֲחֵרִים.</p>\n<p>הַשָּׁחֹר הוּא יוֹתֵר חָשׁוּךְ, שֶׁלֹּא נִרְאֶה הַגָּוֶן שֶׁלּוֹ מִתּוֹךְ הַחֹשֶׁךְ. הַמְּנוֹרָה הַקְּדוֹשָׁה כָּךְ אָמַר, שֶׁהַגָּוֶן הַשָּׁחֹר הַזֶּה הֶחָשׁוּךְ, בְּאֵיזֶה מָקוֹם נִצְבָּע? אֶלָּא כְּשֶׁאוֹתוֹ אָדֹם מִתְהַתֵּךְ בְּתוֹךְ הַתְּכֵלֶת וּמִתְעָרְבִים הַגְּוָנִים, מִתְהַתֵּךְ הִתּוּךְ הַזֻּהֲמָה לְתוֹךְ הַתְּהוֹמוֹת וְנַעֲשֶׂה מִשָּׁם רֶפֶשׁ וָטִיט, כְּמוֹ שֶׁנֶּאֱמַר (שם נז) וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט. וּמִתּוֹךְ אוֹתוֹ טִיט שֶׁל הַתְּהוֹמוֹת יוֹצֵא אוֹתוֹ חֹשֶׁךְ, שֶׁהוּא שָׁחֹר, וְלֹא שָׁחֹר אֶלָּא יוֹתֵר חָשׁוּךְ. זֶהוּ שֶׁכָּתוּב וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם. לָמָּה נִקְרָא חֹשֶׁךְ? מִשּׁוּם שֶׁהַגָּוֶן שֶׁלּוֹ חָשׁוּךְ וּמַחֲשִׁיךְ אֶת פְּנֵי הַבְּרִיּוֹת, וְזֶהוּ אָדם וְשָׁחֹר, וּמִשּׁוּם זֶה לֹא כָתוּב בַּשֵּׁנִי כִּי טוֹב.</p>"],[9522011730,"<p>וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב וְהִנֵּה טוֹב מְאֹד, זֶה מַלְאַךְ הַמָּוֶת, וְכָאן אָמַרְתָּ שֶׁלֹּא נֶאֱמַר בִּגְלָלוֹ כִּי טוֹב - אֶלָּא סוֹד הַסּוֹדוֹת כָּאן, שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת וַדַּאי הוּא טוֹב מְאֹד. מָה הַטַּעַם? מִשּׁוּם שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם יוֹדְעִים שֶׁיָּמוּתוּ וְיַחְזְרוּ לֶעָפָר, וְרַבִּים הֵם שֶׁחוֹזְרִים בִּתְשׁוּבָה לְרִבּוֹנָם מִשּׁוּם פַּחַד זֶה, וּפוֹחֲדִים לַחֲטֹא לְפָנָיו. רַבִּים פּוֹחֲדִים מֵהַמֶּלֶךְ מִתּוֹךְ שֶׁתְּלוּיָה רְצוּעָה לִפְנֵיהֶם. כַּמָּה טוֹבָה אוֹתָהּ רְצוּעָה אֶל הָאָדָם, שֶׁעוֹשָׂה לָהֶם טוֹבוֹת וַאֲמִתּוֹת וּמְתַקְּנִים בְּדַרְכֵיהֶם כָּרָאוּי. וְעַל זֶה וְהִנֵּה טוֹב מְאֹד. מְאֹד וַדַּאי.</p>\n<p>סוֹד הַסּוֹדוֹת שֶׁלָּמַדְנוּ מִתּוֹךְ הַמְּנוֹרָה הַקְּדוֹשָׁה, וְהִנֵּה טוֹב - זֶה מַלְאַךְ הַחַיִּים. מְאֹד - זֶה מַלְאַךְ הַמָּוֶת, שֶׁהוּא יוֹתֵר. לָמָּה מַלְאַךְ הַמָּוֶת הוּא טוֹב מְאֹד? אֶלָּא כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הַכֹּל הָיָה מְתֻקָּן טֶרֶם שֶׁבָּא אָדָם, שֶׁהוּא הַמֶּלֶךְ שֶׁל הָעוֹלָם הַזֶּה. כֵּיוָן שֶׁנִּבְרָא אָדָם, עָשָׂה אוֹתוֹ מְתֻקָּן בְּדֶרֶךְ אֱמֶת. זֶהוּ שֶׁכָּתוּב (קהלת ז) אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְהֵמָּה בִקְשׁוּ חִשְּׁבנוֹת רַבִּים. עָשָׂה אוֹתוֹ יָשָׁר, וְאַחַר כָּךְ סָרַח וְנִטְרַד מִגַּן עֵדֶן.</p>\n<p>גַּן הָעֵדֶן הוּא נָטוּעַ בָּאָרֶץ בְּאוֹתָן נְטִיעוֹת שֶׁנָּטַע אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וַיִּטַּע ה' אֱלֹהִים גַּן בְּעֵדֶן מִקֶּדֶם. הוּא נָטַע אוֹתוֹ בְּשֵׁם שָׁלֵם, כְּדֻגְמַת עֶלְיוֹן שֶׁלְּמַעְלָה. וְכָל הַדְּיוֹקְנָאוֹת הָעֶלְיוֹנִים כֻּלָּם, מְרֻקָּמִים וּמְצֻיָּרִים בְּגַן הָעֵדֶן הַזֶּה שֶׁלְּמַטָּה, וְשָׁם הֵם הַכְּרוּבִים. אֵינָם חֲקוּקִים בַּחֲקִיקוֹת שֶׁל בְּנֵי אָדָם מִזָּהָב אוֹ מִדָּבָר אַחֵר, אֶלָּא כֻּלָּם אוֹרוֹת שֶׁלְּמַעְלָה חֲקוּקִים וּמְצֻיָּרִים בְּצִיּוּר מְרֻקָּם, מַעֲשֵׂה יְדֵי אָמָּן שֶׁל הַשֵּׁם הַשָּׁלֵם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם חֲקוּקִים שָׁם. וְכָל הַדְּיוֹקְנָאוֹת וְהַצִּיּוּרִים שֶׁל הָעוֹלָם הַזֶּה, כֻּלָּם מְצֻיָּרִים שָׁם, וַחֲקוּקִים וּמִתְחַקְקִים שָׁם כֻּלָּם כְּמוֹ הָעוֹלָם הַזֶּה.</p>\n<p>וּמָקוֹם זֶה הוּא מָדוֹר לְרוּחוֹת קְדוֹשׁוֹת, בֵּין אוֹתָן שֶׁבָּאוּ לָעוֹלָם הַזֶּה, בֵּין אוֹתָן שֶׁלֹּא בָאוּ לָעוֹלָם הַזֶּה וְהֵם עֲתִידִים לָבֹא לָעוֹלָם הַזֶּה. כֻּלָּן רוּחוֹת מְלֻבָּשׁוֹת בִּלְבוּשִׁים וְגוּפִים וּפַרְצוּפִים כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, וּמִסְתַּכְּלוֹת שָׁם בְּזִיו כְּבוֹד רִבּוֹנָם, עַד שֶׁבָּאוֹת לָעוֹלָם הַזֶּה.</p>\n<p>בְּשָׁעָה שֶׁיּוֹצְאוֹת מִשָּׁם לָבֹא לָעוֹלָם הַזֶּה, מִתְפַּשְּׁטוֹת אוֹתָן רוּחוֹת מֵאוֹתוֹ גוּף וּלְבוּשׁ שֶׁל שָׁם, וּמִתְלַבְּשׁוֹת בְּגוּף וּלְבוּשׁ שֶׁל הָעוֹלָם הַזֶּה, וְעוֹשׂוֹת מְדוֹרָם בָּעוֹלָם הַזֶּה בִּלְבוּשׁ וְגוּף הַזֶּה, שֶׁהוּא מִטִּפָּה סְרוּחָה.</p>\n<p>וּכְשֶׁמַּגִּיעַ זְמַנּוֹ לָלֶכֶת וְלָצֵאת מֵהָעוֹלָם הַזֶּה, לֹא יוֹצֵא עַד שֶׁמַּלְאַךְ הַמָּוֶת הַזֶּה מַפְשִׁיטוֹ הַלְּבוּשׁ שֶׁל הַגּוּף הַזֶּה. כֵּיוָן שֶׁנִּפְשָׁט הַגּוּף מֵאוֹתָהּ רוּחַ עַל יְדֵי אוֹתוֹ מַלְאַךְ הַמָּוֶת, הוֹלֵךְ וּמִתְלַבֵּשׁ בְּאוֹתוֹ גוּף הָאַחֵר שֶׁבְּגַן עֵדֶן שֶׁמִּמֶּנּוּ הִתְפַּשֵּׁט כְּשֶׁבָּא לָעוֹלָם הַזֶּה, וְאֵין שִׂמְחָה לָרוּחַ פְּרָט לְאוֹתוֹ הַגּוּף שֶׁל שָׁם, וְשָׂמֵחַ עַל שֶׁהִתְפַּשֵּׁט מֵהַגּוּף הַזֶּה שֶׁל הָעוֹלָם הַזֶּה וְהִתְלַבֵּשׁ בְּגוּף אַחֵר שָׁלֵם כְּמוֹ שֶׁל (אותו) הָעוֹלָם הַזֶּה, וּבוֹ יוֹשֵׁב וְהוֹלֵךְ וּמִתְבּוֹנֵן בַּסּוֹדוֹת הָעֶלְיוֹנִים, מַה שֶּׁלֹּא יָכֹל לָדַעַת וּלְהִתְבּוֹנֵן בָּעוֹלָם הַזֶּה בַּגּוּף הַזֶּה.</p>\n<p>וּכְשֶׁמִּתְלַבֶּשֶׁת הַנְּשָׁמָה בְּאוֹתוֹ לְבוּשׁ שֶׁל אוֹתוֹ עוֹלָם, כַּמָּה עִדּוּנִים וְכַמָּה כִסּוּפִים שֶׁלָּהּ שָׁם. מַה גָּרַם לַגּוּף הַזֶּה לְהִתְלַבֵּשׁ בּוֹ הָרוּחַ? הֱוֵה אוֹמֵר, אוֹתוֹ מַעֲשֶׂה שֶׁהִפְשִׁיטוּ מֵהַלְּבוּשִׁים הַלָּלוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה טוֹב עִם הַבְּרִיּוֹת שֶׁלֹּא מַפְשִׁיט מֵהָאָדָם הַלְּבוּשִׁים הַלָּלוּ עַד שֶׁמַּתְקִין לוֹ לְבוּשִׁים אֲחֵרִים נִכְבָּדִים וְטוֹבִים מֵאֵלֶּה.</p>\n<p>פְּרָט לְאוֹתָם רִשְׁעֵי הָעוֹלָם שֶׁלֹּא חָזְרוּ בִתְשׁוּבָה שְׁלֵמָה לְרִבּוֹנָם, שֶׁמְּעֻרְטָלִים בָּאוּ לָעוֹלָם הַזֶּה וּמְעֻרְטָלִים יָשׁוּבוּ לְשָׁם. וְהַנְּשָׁמָה הוֹלֶכֶת בְּבוּשָׁה כְּלַפֵּי אֲחֵרוֹת, כִּי אֵין לָהּ כְּלָל לְבוּשִׁים, וְנִדּוֹנֵית בְּאוֹתוֹ גֵיהִנֹּם שֶׁבָּאָרֶץ מִתּוֹךְ אוֹתָהּ הָאֵשׁ שֶׁלְּמַעְלָה. וְיֵשׁ מֵהֶן שֶׁמְּצַפְצְפוֹת וְעוֹלוֹת, וְאֵלּוּ הֵם רִשְׁעֵי הָעוֹלָם שֶׁחָשְׁבוּ בְלִבָּם תְּשׁוּבָה וּמֵתוּ, וְלֹא יָכְלוּ לַעֲשׂוֹת אוֹתָהּ. אֵלֶּה נִדּוֹנִים שָׁם בַּגֵּיהִנֹּם, וְאַחַר כָּךְ מְצַפְצְפִים וְעוֹלִים.</p>\n<p>רְאֵה כַּמָּה רַחֲמָנוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו, שֶׁאֲפִלּוּ שֶׁהוּא רָשָׁע גָּדוֹל וְהִרְהֵר תְּשׁוּבָה וְלֹא יָכֹל לַעֲשׂוֹת תְּשׁוּבָה וּמֵת, הֲרֵי וַדַּאי מְקַבֵּל עֹנֶשׁ עַד שֶׁהוֹלֵךְ בְּלִי תְשׁוּבָה. אַחַר כָּךְ אוֹתוֹ הָרָצוֹן שֶׁשָּׂם לַעֲשׂוֹת תְּשׁוּבָה, לֹא זָז מִלִּפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְתַקֵּן לְאוֹתוֹ רָשָׁע מָקוֹם בִּמְדוֹר הַשְּׁאוֹל, וְשָׁם מְצַפְצֵף תְּשׁוּבָה. שֶׁהֲרֵי אוֹתוֹ רָצוֹן יוֹרֵד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹבֵר כָּל הַשּׁוֹמְרִים (לאחר שקבל ענשו, אותו רצון טוב שהגיח אותו רשע לעשות תשובה, עולה לפני המלך העליון, ולא זז משם עד שהקדוש ברוך הוא מתקן לאותו רשע מקום במדור השאול, ואז אותו רצון יורד מלפני הקדוש ברוך הואו שובר את כל השומרים) שֶׁל שַׁעֲרֵי מְדוֹרֵי הַגֵּיהִנֹּם, וּמַגִּיעַ לְאוֹתוֹ מָקוֹם שֶׁאוֹתוֹ הָרָשָׁע שָׁם, וּמַכֶּה בּוֹ וּמְעוֹרֵר אֶת אוֹתוֹ רָצוֹן כְּמִקֹּדֶם. וְאָז מְצַפְצֶפֶת אוֹתָהּ נְשָׁמָה לַעֲלוֹת מִתּוֹךְ מְדוֹר הַשְּׁאוֹל.</p>\n<p>וְאֵין רָצוֹן טוֹב שֶׁנֶּאֱבָד מִלִּפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וּמִשּׁוּם כָּךְ אַשְׁרֵי אוֹתוֹ מִי שֶׁמְּהַרְהֵר הִרְהוּרִים טוֹבִים לְרִבּוֹנוֹ. שֶׁאַף עַל גַּב שֶׁלֹּא יָכֹל לַעֲשׂוֹת אוֹתָם, הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלֶה אֶת רְצוֹנוֹ כְּאִלּוּ עָשָׂה, וְזֶה לְטוֹב. אֲבָל רָצוֹן לְרַע - לֹא, פְּרָט לְהִרְהוּר שֶׁל עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>אוֹתָם שֶׁלֹּא הִרְהֲרוּ תְשׁוּבָה, יוֹרְדִים לַשְּׁאוֹל, וְלֹא עוֹלִים מִשָּׁם לְדוֹרֵי דוֹרוֹת. עֲלֵיהֶם כָּתוּב (איוב ו) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה. עַל הָרִאשׁוֹנִים כָּתוּב (שמואל א ב) ה' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל.</p>"],[9522011731,"<p>אָמַר רַבִּי יְהוּדָה, דִּין שֶׁל עָנְשֵׁי הַגֵּיהִנֹּם, הֲרֵי לָמַדְנוּ שֶׁהוּא לָדוּן שָׁם אֶת הָרְשָׁעִים. עַל מַה נִּדּוֹנִים בְּאֵשׁ הַגֵּיהִנֹּם? אֶלָּא גֵּיהִנֹּם הִיא אֵשׁ דּוֹלֶקֶת יָמִים וְלֵילוֹת, כְּמוֹ שֶׁהָרְשָׁעִים מִתְחַמְּמִים בָּאֵשׁ שֶׁל יֵצֶר הָרָע לַעֲבֹר עַל דִּבְרֵי הַתּוֹרָה. בְּכָל חִמּוּם וְחִמּוּם שֶׁהֵם מִתְחַמְּמִים בַּיֵּצֶר הָרָע, כָּךְ בּוֹעֶרֶת אֵשׁ הַגֵּיהִנֹּם.</p>\n<p>פַּעַם אַחַת לֹא נִמְצָא יֵצֶר הָרָע בָּעוֹלָם, שֶׁהִכְנִיסוּ אוֹתוֹ לְתוֹךְ חוֹתַם בַּרְזֶל בְּנֶקֶב תְּהוֹם רַבָּה, וְכָל אוֹתוֹ זְמַן כָּבְתָה אֵשׁ הַגֵּיהִנֹּם וְלֹא בָעֲרָה כְּלָל. חָזַר יֵצֶר הָרָע לִמְקוֹמוֹ - הִתְחִילוּ רִשְׁעֵי הָעוֹלָם לְהִתְחַמֵּם בּוֹ, וְהִתְחִילָה אֵשׁ הַגֵּיהִנֹּם לִבְעֹר, שֶׁהֲרֵי הַגֵּיהִנֹּם לֹא בוֹעֵר אֶלָּא בַּחֹם שֶׁל תֹּקֶף הַיֵּצֶר הָרָע שֶׁל הָרְשָׁעִים. וּבְאוֹתוֹ הַחֹם אֵשׁ הַגֵּיהִנֹּם בּוֹעֶרֶת יָמִים וְלֵילוֹת וְלֹא שׁוֹכֶכֶת.</p>\n<p>שִׁבְעָה פְתָחִים הֵם לַגֵּיהִנֹּם, וְיֵשׁ שָׁם שִׁבְעָה מְדוֹרִים. שִׁבְעָה מִינֵי רְשָׁעִים הֵם: רַע. בְּלִיַּעַל. חוֹטֵא. רָשָׁע. מַשְׁחִית. לֵץ. יָהִיר. וּכְנֶגֶד כֻּלָּם יֵשׁ מְדוֹרִים לַגֵּיהִנֹּם, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. וּכְפִי אוֹתָהּ מַעֲלָה שֶׁחָטָא בָּהּ אוֹתוֹ הָרָשָׁע, כָּךְ נוֹתְנִים לוֹ מָדוֹר בַּגֵּיהִנֹּם.</p>\n<p>וּבְכָל מָדוֹר וּמָדוֹר יֵשׁ מַלְאָךְ מְמֻנֶּה עַל אוֹתוֹ מָקוֹם תַּחַת יָדוֹ שֶׁל דּוּמָה, וְכַמָּה אֶלֶף וְרִבּוֹא עִמּוֹ שֶׁדָּנִים אֶת הָרְשָׁעִים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ בְּאוֹתוֹ מָדוֹר שֶׁהוּא שָׁם.</p>\n<p>(אש הגיהגם שלמעלה מגיעה לגיהגם שלמטה) אֵשׁ הַגֵּיהִנֹּם לְמַטָּה מַגִּיעָה מִתּוֹךְ אֵשׁ הַגֵּיהִנֹּם שֶׁלְּמַעְלָה, וּמַגִּיעָה לַגֵּיהִנֹּם הַזֶּה שֶׁלְּמַטָּה, וּבוֹעֶרֶת בְּאוֹתָהּ הִתְעוֹרְרוּת הַחֹם שֶׁל הָרְשָׁעִים, שֶׁמְּחַמְּמִים אֶת עַצְמָם תּוֹךְ יֵצֶר הָרָע, וְכָל אוֹתָם מְדוֹרִים דּוֹלְקִים שָׁם.</p>\n<p>מָקוֹם יֵשׁ בַּגֵּיהִנֹּם, וְיֵשׁ שָׁם דְּרָגוֹת שֶׁנִּקְרְאוּ צוֹאָה רוֹתַחַת, וְשָׁם הִיא זֻהֲמַת הַנְּשָׁמוֹת, אוֹתָן שֶׁמִּתְלַכְלְכוֹת מִכָּל הַזֻּהֲמָה שֶׁל הָעוֹלָם הַזֶּה. וּמִתְלַבְּנוֹת וְעוֹלוֹת, וְנִשְׁאֶרֶת שָׁם אוֹתָהּ זֻהֲמָה, וְאוֹתָן דְּרָגוֹת רָעוֹת שֶׁנִּקְרָאוֹת צוֹאָה רוֹתַחַת הִתְמַנּוּ עַל אוֹתָהּ זֻהֲמָה, וְאֵשׁ הַגֵּיהִנֹּם שׁוֹלֶטֶת בְּאוֹתָהּ זֻהֲמָה שֶׁנִּשְׁאֲרָה.</p>\n<p>וְיִשִׁ רְשָׁעִים, אוֹתָם שֶׁמִּתְלַכְלְכִים בַּחֲטָאֵיהֶם תָּמִיד וְלֹא מִתְלַבְּנִים מֵהֶם, וּמֵתוּ בְּלִי תְשׁוּבָה, וְחָטְאוּ וְהֶחֱטִיאוּ אֲחֵרִים וְהָיוּ תָמִיד קְשֵׁי עֹרֶף, וְלֹא נִשְׁבְּרוּ לִפְנֵי רִבּוֹנָם בָּעוֹלָם הַזֶּה. אֵלּוּ נִדּוֹנִים שָׁם בְּאוֹתָהּ זֻהֲמָה וּבְאוֹתָהּ צוֹאָה רוֹתַחַת שֶׁלֹּא יוֹצְאִים מִשָּׁם לְעוֹלָמִים. אוֹתָם שֶׁמַּשְׁחִיתִים דַּרְכָּם עַל הָאָרֶץ וְלֹא חָשְׁשׁוּ לִכְבוֹד רִבּוֹנָם בָּעוֹלָם הַזֶּה, כָּל אֵלֶּה נִדּוֹנִים שָׁם לְדוֹרֵי דוֹרוֹת וְלֹא יוֹצְאִים מִשָּׁם.</p>\n<p>בְּשַׁבָּתוֹת וּבֶחֳדָשִׁים וּבִזְמַנִּים וּבְחַגִּים, בְּאוֹתוֹ מָקוֹם הָאֵשׁ שׁוֹכֶכֶת וְלֹא נִדּוֹנִים, אֲבָל לֹא יוֹצְאִים מִשָּׁם כִּשְׁאָר הָרְשָׁעִים שֶׁיֵּשׁ לָהֶם מְנוּחָה. כָּל אוֹתָם שֶׁמְּחַלְּלִים שַׁבָּתוֹת וּזְמַנִּים וְלֹא חוֹשְׁשִׁים לִכְבוֹד רִבּוֹנָם כְּלָל כְּדֵי לִשְׁמֹר אוֹתָם, אֶלָּא מְחַלְּלִים בְּפַרְהֶסְיָה - כְּמוֹ שֶׁהֵם לֹא שָׁמְרוּ שַׁבָּתוֹת וּזְמַנִּים בָּעוֹלָם הַזֶּה, כָּךְ גַּם לֹא שׁוֹמְרִים אוֹתוֹ בָּעוֹלָם הַבָּא, וְאֵין לָהֶם מְנוּחָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אַל תֹּאמַר כָּךְ, אֶלָּא הֵם שׁוֹמְרִים שַׁבָּתוֹת וּזְמַנִּים שָׁם בַּגֵּיהִנֹּם בְּעַל כָּרְחָם. אָמַר רַבִּי יְהוּדָה, אֵלֶּה אוֹתָם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁלֹּא הִצְטַוּוּ, שֶׁלֹּא שָׁמְרוּ שַׁבָּת בָּעוֹלָם הַזֶּה, שׁוֹמְרִים אוֹתָהּ שָׁם בְּעַל כָּרְחָם.</p>\n<p>בְּכָל עֶרֶב שַׁבָּת כְּשֶׁמִּתְקַדֵּשׁ הַיּוֹם, הַכָּרוֹזִים הוֹלְכִים בְּכָל אוֹתָם מְדוֹרֵי הַגֵּיהִנֹּם: הִסְתַּלְּקוּ דִינֵי הָרְשָׁעִים, שֶׁהֲרֵי הַמֶּלֶךְ הַקָּדוֹשׁ בָּא, וְהַיּוֹם מִתְקַדֵּשׁ, וְהוּא מֵגֵן עַל הַכֹּל. וּמִיָּד מִסְתַּלְּקִים הַדִּינִים וְיֵשׁ לָרְשָׁעִים מְנוּחָה. (וכל אותם מחללי שבתות ומועדים בפרהסיא, דינים מסתלקים מעליהם) (ואפלו עובדי כוכבים ומזלות שלא נצטוו לשמר שבתות ומועדים, שם שומרים בעל כרחם) אֲבָל אֵשׁ הַגֵּיהִנֹּם לֹא שׁוֹכֶכֶת מֵעַל אֵלֶּה שֶׁלֹּא שָׁמְרוּ שַׁבָּת לְעוֹלָמִים, וְכָל רִשְׁעֵי הַגֵּיהִנֹּם שׁוֹאֲלִים עֲלֵיהֶם: מַה שּׁוֹנִים אֵלֶּה שֶׁאֵין לָהֶם מְנוּחָה מִכָּל הָרְשָׁעִים שֶׁל כָּאן?! וְאוֹתָם בַּעֲלֵי הַדִּין מְשִׁיבִים לָהֶם: אֵלֶּה הֵם הָרְשָׁעִים שֶׁכָּפְרוּ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְעָבְרוּ עַל כָּל הַתּוֹרָה. מִשּׁוּם שֶׁלֹּא שָׁמְרוּ שַׁבָּת שָׁם, לָכֵן אֵין לָהֶם מְנוּחָה לְעוֹלָמִים.</p>\n<p>וְכָל אוֹתָם הָרְשָׁעִים יוֹצְאִים מִמְּקוֹמָם, וְנִתֶּנֶת לָהֶם רְשׁוּת לָלֶכֶת וְלִרְאוֹת אוֹתָם. וּמַלְאָךְ אֶחָד שֶׁשְּׁמוֹ סַנְטִרִיאֵ\"ל הוֹלֵךְ וּמוֹצִיא אֶת אוֹתוֹ הַגּוּף שֶׁלָּהֶם וּמַכְנִיסוֹ לַגֵּיהִנֹּם לְעֵינֵי הָרְשָׁעִים, וְרוֹאִים אוֹתוֹ שֶׁמַּעֲלֶה תוֹלָעִים, וְלַנְּשָׁמָה אֵין מְנוּחָה בְּאֵשׁ הַגֵּיהִנֹּם.</p>\n<p>וְכָל אוֹתָם הָרְשָׁעִים שֶׁשָּׁם סוֹבְבִים אֶת אוֹתוֹ הַגּוּף וּמַכְרִיזִים עָלָיו: זֶהוּ פְּלוֹנִי הָרָשָׁע שֶׁלֹּא חָשַׁשׁ לִכְבוֹד רִבּוֹנוֹ, וְכָפַר בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכָפַר בְּכָל הַתּוֹרָה כֻּלָּהּ. אוֹי לוֹ! טוֹב שֶׁלֹּא נִבְרָא וְלֹא יָבֹא לַדִּין הַזֶּה וְלַבּוּשָׁה הַזּוֹ! זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי כִּי תוֹלַעְתָּם לֹא תָמוּת וְאִשָּׁם לֹא תִכְבֶּה וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. כִּי תוֹלַעְתָּם לֹא תָמוּת - מִן הַגּוּף. וְאִשָּׁם לֹא תִכְבֶּה - מִן הַנְּשָׁמָה. וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר - וְהָיוּ דַי רָאוֹן, עַד שֶׁכָּל רִשְׁעֵי הָעוֹלָם שֶׁל שָׁם יֹאמְרוּ דַּי לָרְאִיָּה הַזּוֹ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, וַדַּאי כָּךְ זֶה, מִשּׁוּם שֶׁשַּׁבָּת הִיא כְּנֶגֶד כָּל הַתּוֹרָה, וְהַתּוֹרָה הִיא אֵשׁ - מִשּׁוּם שֶׁעָבְרוּ עַל אֵשׁ הַתּוֹרָה, הֲרֵי אֵשׁ הַגֵּיהִנֹּם דּוֹלֵק, שֶׁלֹּא שׁוֹכֵךְ מֵעֲלֵיהֶם לְעוֹלָמִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לְאַחַר כְּשֶׁיּוֹצֵאת שַׁבָּת, בָּא אוֹתוֹ מַלְאָךְ וּמַחֲזִיר אוֹתוֹ גוּף לְקִבְרוֹ, וְנִדּוֹנִים שְׁנֵיהֶם, זֶה לְצִדּוֹ וְזֶה לְצִדּוֹ. וְכָל זֶה בְּעוֹד שֶׁהַגּוּף קַיָּם עַל בֻּרְיוֹ, שֶׁהֲרֵי כֵּיוָן שֶׁהַגּוּף נִתְעַכֵּל, אֵין לַגּוּף אֶת כָּל הַדִּינִים הַלָּלוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא כָּתוּב בּוֹ, וְלֹא יָעִיר כָּל חֲמָתוֹ.</p>\n<p>כָּל רִשְׁעֵי הָעוֹלָם, בְּעוֹד שֶׁהַגּוּף שָׁלֵם בְּכָל אֵיבָרָיו בְּתוֹךְ הַקֶּבֶר, נִדּוֹנִים גּוּף וְרוּחַ, לְכָל אֶחָד דִּין כָּרָאוּי לוֹ. כֵּיוָן שֶׁהַגּוּף נִתְעַכֵּל, דִּין הָרוּחַ שׁוֹכֵךְ. מִי שֶׁצָּרִיךְ לָצֵאת, יוֹצֵא. וּמִי שֶׁצָּרִיךְ לִהְיוֹת עֲלֵיהֶם מְנוּחָה, יֵשׁ לָהֶם מְנוּחָה. וּמִי שֶׁצָּרִיךְ לִהְיוֹת עָפָר וָאֵפֶר תַּחַת רַגְלֵי הַצַּדִּיקִים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ נַעֲשֶׂה לוֹ.</p>\n<p>וְלָכֵן כַּמָּה טוֹב לָהֶם, בֵּין לַצַּדִּיקִים בֵּין לָרְשָׁעִים, לִהְיוֹת גּוּפָם דָּבוּק בָּאָרֶץ וּלְהֵרָקֵב בְּתוֹךְ הֶעָפָר לִזְמַן קָרוֹב וְלֹא לִהְיוֹת בְּקִיּוּם כָּל אוֹתוֹ זְמַן רַב, כְּדֵי לָדוּן גּוּף וָנֶפֶשׁ וְרוּחַ תָּמִיד (בכל יום). שֶׁהֲרֵי אֵין לְךְ כָּל צַדִּיק וְצַדִּיק בָּעוֹלָם שֶׁאֵין לוֹ דִּין הַקֶּבֶר, מִשּׁוּם שֶׁאוֹתוֹ מַלְאָךְ הַמְמֻנֶּה עַל הַקְּבָרִים עוֹמֵד עַל הַגּוּף וְדָן אוֹתוֹ בְּכָל יוֹם וָיוֹם. אִם לַצַּדִּיקִים כָּךְ - עַל אַחַת כַּמָּה וְכַמָּה לָרְשָׁעִים.</p>\n<p>וּבִזְמַן שֶׁהַגּוּף נִרְקָב וְנִבְלֶה בֶּעָפָר, הֲרֵי הַדִּין שׁוֹכֵךְ מֵהַכֹּל, פְּרָט לְאוֹתָם חֲסִידִים הָעַמּוּדִים שֶׁל הָעוֹלָם שֶׁהֵם רְאוּיִים לְהַעֲלוֹת נִשְׁמָתָם לְאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁרָאוּי לָהֶם, וּמְעַטִּים הֵם בָּעוֹלָם.</p>\n<p>כָּל אוֹתָם הַמֵּתִים שֶׁל הָעוֹלָם, כֻּלָּם מֵתִים עַל יְדֵי הַמַּלְאָךְ הַמַּשְׁחִית, פְּרָט לְאוֹתָם שֶׁמֵּתִים בָּאָרֶץ הַקְּדוֹשָׁה (וכלם מתים על ידי המלאך המשחית, שהוא מלאך המות, וכל אותם המתים שבארץ הקדושה) שֶׁלֹּא מֵתִים עַל יָדוֹ, אֶלָּא עַל יְדֵי מַלְאַךְ הָרַחֲמִים שֶׁשּׁוֹלֵט בָּאָרֶץ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אִם כָּךְ, מָה הַשֶּׁבַח שֶׁל מֹשֶׁה וְאַהֲרֹן וּמִרְיָם שֶׁכָּתוּב בָּהֶם עַל פִּי ה', שֶׁאֵלֶּה לֹא מֵתוּ עַל יְדֵי אוֹתוֹ הַמַּלְאָךְ הַמַּשְׁחִית, וְאַתָּה אוֹמֵר שֶׁכָּל הָעוֹלָם, אוֹתָם שֶׁמֵּתוּ בְּאֶרֶץ יִשְׂרָאֵל, לֹא מֵתִים עַל יְדֵי זֶה?</p>\n<p>אָמַר לוֹ, כָּךְ הוּא וַדַּאי, וְהַשֶּׁבַח שֶׁל מֹשֶׁה אַהֲרֹן וּמִרְיָם הָיָה יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם שֶׁהֵם מֵתוּ מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה. שֶׁמֹּשֶׁה אַהֲרֹן וּמִרְיָם מֵתוּ מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, וְכֻלָּם מֵתוּ עַל יְדֵי אוֹתוֹ הַמַּשְׁחִית, פְּרָט לְמֹשֶׁה אַהֲרֹן וּמִרְיָם שֶׁלֹּא מֵתוּ אֶלָּא עַל יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אֲבָל אוֹתָם שֶׁמֵּתִים בָּאָרֶץ הַקְּדוֹשָׁה, לֹא מֵתִים עַל יְדֵי אוֹתוֹ הַמַּשְׁחִית, שֶׁהֲרֵי הָאָרֶץ הַקְּדוֹשָׁה אֵינָהּ עוֹמֶדֶת בְּרָשׁוּת אַחֶרֶת, אֶלָּא בִּרְשׁוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ.</p>\n<p>וְלָכֵן כָּתוּב, (ישעיה כו) יִחְיוּ מֵתֶיךְ נְבֵלָתִי יְקוּמוּן הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר וְגוֹ'. יִחְיוּ מֵתֶיךְ - אֵלּוּ שֶׁמֵּתִים בָּאָרֶץ הַקְּדוֹשָׁה, שֶׁהֵם מֵתִים שֶׁלּוֹ, וְלֹא מֵאַחֵר, שֶׁלֹּא שׁוֹלֵט שָׁם הַצַּד הָאַחֵר כְּלָל, וְלָכֵן כָּתוּב מֵתֶיךְ. נְבֵלָתִי יְקוּמוּן - אוֹתָם שֶׁמֵּתוּ בְּאֶרֶץ נָכְרִיָּה אַחֶרֶת עַל יְדֵי אוֹתוֹ הַמַּשְׁחִית.</p>\n<p>וְלָכֵן נִקְרְאוּ נְבֵלָה. מַה נְּבֵלָה מְטַמְּאָה בְמַשָּׂא - אַף אוֹתָם שֶׁמֵּתִים מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה מְטַמְּאִים בְּמַשָּׂא (במגע). וְלָכֵן הֵם נְבֵלָה. כָּל שְׁחִיטָה שֶׁנִּפְסְלָה נִקְרֵאת נְבֵלָה, מִשּׁוּם שֶׁשְּׁחִיטָה זוֹ הִיא מִצַּד הָאַחֵר, וּמִיָּד כְּשֶׁנִּפְסָל שׁוֹרֶה עָלָיו הַצַּד הָאַחֵר. וּמִשּׁוּם שֶׁהִיא שֶׁלּוֹ וְשׁוֹרֶה עָלֶיהָ נִקְרָא נְבֵלָה. וְסוֹד זֶה - (כשמו כן הוא) נָבָל הוּא, וְנָבָל שְׁמוֹ וּנְבָלָה עִמּוֹ.</p>\n<p>וְלָכֵן בְּכָל מָקוֹם שֶׁהוּא שׁוֹרֶה נִקְרָא נְבֵלָה. הַמְנֻוָּל הַזֶּה לֹא שׁוֹרֶה אֶלָּא בְּמָקוֹם פָּסוּל, וְלָכֵן שְׁחִיטָה שֶׁנִּפְסְלָה הִיא שֶׁלּוֹ, וְנִקְרֵאת עַל שְׁמוֹ. וְלָכֵן הַמֵּתִים מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה תַּחַת רָשׁוּת אַחֶרֶת וְשׁוֹרֶה עֲלֵיהֶם הַצַּד הָאַחֵר נִקְרָאִים נְבֵלָה.</p>\n<p>הָקִיצוּ וְרַנְּנוּ שּכְנֵי עָפָר. שּכְנֵי - דַּיָּרִים יְשֵׁנִים, וְלֹא מֵתִים. וּמִי הֵם? יְשֵׁנֵי חֶבְרוֹן, שֶׁהֵם לֹא מֵתִים, אֶלָּא יְשֵׁנִים. וְלָכֵן כָּתוּב בָּהֶם גְּוִיעָה, כְּמִי שֶׁגּוֹוֵעַ וְיֵשׁ בּוֹ קִיּוּם לְהִתְנַעֵר. אַף כָּךְ אוֹתָם אַרְבַּע זוּגוֹת שֶׁל חֶבְרוֹן יְשֵׁנִים הֵם וְלֹא מֵתִים, וְכֻלָּם עוֹמְדִים בְּקִיּוּמָם בְּאוֹתָם הַגּוּפוֹת שֶׁלָּהֶם, וְיוֹדְעִים סְתָרִים גְּנוּזִים יוֹתֵר מִשְּׁאָר בְּנֵי אָדָם. גְּנוּזִים הָיוּ שָׁם תּוֹךְ פֶּתַח הַגַּן עֵדֶן אוֹתָם הַגּוּפִים שֶׁלָּהֶם, וְאֵלֶּה הֵם שׁוֹכְנֵי עָפָר. וְלָכֵן כָּל אוֹתָם שֶׁיָּצְאָה נִשְׁמָתָם בָּאָרֶץ הַקְּדוֹשָׁה, אֵינָהּ יוֹצֵאת עַל יְדֵי אוֹתוֹ הַמַּשְׁחִית, וְלֹא שׁוֹלֵט שָׁם, אֶלָּא עַל יְדֵי מַלְאַךְ הָרַחֲמִים, שֶׁהָאָרֶץ הַקְּדוֹשָׁה עוֹמֶדֶת בְּגוֹרָלוֹ. קדִּישָׁא קיְּימָא בְ עדְבֵיהּ</p>"],[9522011732,"<p>יֵשׁ מָקוֹם בַּיִּשּׁוּב שֶׁלֹּא שׁוֹלֵט בּוֹ אוֹתוֹ מַשְׁחִית וְלֹא נִתֶּנֶת לוֹ רְשׁוּת לְהִכָּנֵס לְשָׁם, וְכָל אוֹתָם שֶׁדָּרִים שָׁם לֹא מֵתִים, עַד שֶׁיּוֹצְאִים מִחוּץ לָעִיר. וְאֵין לְךְ אָדָם מִכָּל הַדַּיָּרִים שָׁם שֶׁלֹּא מֵתִים, וְכֻלָּם מֵתִים כְּמוֹ שְׁאָר בְּנֵי אָדָם, אֲבָל לֹא בָּעִיר. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא יְכוֹלִים תָּמִיד לָשֶׁבֶת בָּעִיר, אֶלָּא אֵלֶּה יוֹצְאִים וְאֵלֶּה נִכְנָסִים, וְלָכֵן כֻּלָּם מֵתִים.</p>\n<p>מָה הַטַּעַם אֵין שׁוֹלֵט שָׁם אוֹתוֹ מַלְאַךְ הַמַּשְׁחִית? אִם תֹּאמַר שֶׁלֹּא עוֹמֶדֶת בִּרְשׁוּתוֹ, הֲרֵי אֶרֶץ הַקֹּדֶשׁ שֶׁלֹּא עוֹמֶדֶת בְּרָשׁוּת אַחֶרֶת וּמֵתִים, בְּאוֹתוֹ מָקוֹם לָמָּה לֹא מֵתִים? אִם תֹּאמַר מִשּׁוּם קְדֻשָּׁה - אֵין מָקוֹם בַּקְּדֻשָּׁה בְּכָל הַיִּשּׁוּב כְּמוֹ אֶרֶץ יִשְׂרָאֵל. וְאִם תֹּאמַר מִשּׁוּם אוֹתוֹ אִישׁ שֶׁבָּנָה אוֹתוֹ - כַּמָּה בְּנֵי אָדָם הָיוּ שֶׁזְּכוּתָם יְתֵרָה מִשֶּׁלּוֹ. אָמַר רַבִּי יִצְחָק, אֲנִי לֹא שָׁמַעְתִּי וְלֹא אֹמַר.</p>\n<p>בָּאוּ וְשָׁאֲלוּ אֶת רַבִּי שִׁמְעוֹן. אָמַר לָהֶם, וַדַּאי שֶׁאוֹתוֹ מָקוֹם לֹא שׁוֹלֵט בּוֹ מַלְאַךְ הַמָּוֶת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה שֶׁבְּאוֹתוֹ מָקוֹם יָמוּת אָדָם לְעוֹלָמִים. וְאִם תֹּאמַר שֶׁקֹּדֶם לָכֵן בְּאוֹתוֹ מָקוֹם טֶרֶם שֶׁנִּבְנָה מֵתוּ בּוֹ בְּנֵי אָדָם - לֹא כָּךְ! אֶלָּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם הִתְתַּקֵּן אוֹתוֹ מָקוֹם לְקִיּוּם, וְסוֹד הַסּוֹדוֹת כָּאן לְאוֹתָם הַמִּתְבּוֹנְנִים בְּסוֹד הַחָכְמָה.</p>\n<p>כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא אוֹתוֹ בְּסוֹד הָאוֹתִיּוֹת, וְהִתְגַּלְגְּלוּ הָאוֹתִיּוֹת, וּבָרָא אֶת הָעוֹלָם בַּחֲקִיקוֹת הַשֵּׁם הַקָּדוֹשׁ. הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת וְסוֹבְבוּ אֶת הָעוֹלָם בַּחֲקִיקוֹת. וּכְשֶׁהִתְגַּלָּה וְהִתְפַּשֵּׁט הָעוֹלָם וְנִבְרָא, הָיוּ הָאוֹתִיּוֹת סוֹבְבוֹת כְּדֵי לִבְרֹא. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּסְתַּיֵּם בְּיוֹ\"ד. נִשְׁאֲרָה הָאוֹת ט' (יתגלגלו האותיות, וסבבו את העולם בחקיקת השם הקדוש. וכאשר התגלגלו האותיות והיו מסובבות לברא, אמר הקדוש ברוך הוא', די יסתים ביו\"ד. נשארה אות ט' לבדה) בְּאוֹתוֹ מָקוֹם תְּלוּיָה בָּאֲוִיר. כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּסְתַּיֵּם בָּאוֹת יוֹ\"ד, נִשְׁאֲרָה אוֹת טֵי\"ת בִּלְבַדָּהּ תְּלוּיָה בָּאֲוִיר עַל גַּבֵּי אוֹתוֹ מָקוֹם. טֵי\"ת הִיא אוֹת שֶׁל אוֹר הַחַיִּים. וְלָכֵן מִי שֶׁרוֹאֶה טֵי\"ת בַּחֲלוֹמוֹ, סִימָן טוֹב הוּא לוֹ וְחַיִּים נִתְקְנוּ לוֹ. וְלָכֵן, מִשּׁוּם שֶׁהָיְתָה ט' תְּלוּיָה עַל אוֹתוֹ מָקוֹם, לֹא שׁוֹלֵט בּוֹ הַמָּוֶת.</p>\n<p>כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲמִיד עוֹלָם, זָרַק צְרוֹר אֶחָד לְתוֹךְ הַמַּיִם חָקוּק בְּסוֹד שֶׁל ע\"ב (של כ\"ב) אוֹתִיּוֹת, וּמִשָּׁם הִתְחִיל לָלֶכֶת אוֹתוֹ צְרוֹר, וְלֹא מָצָא מָקוֹם לַעֲמֹד בּוֹ פְּרָט הָאָרֶץ הַקְּדוֹשָׁה (בבית המקדש), וְהַמַּיִם הָיוּ הוֹלְכִים אַחֲרָיו, עַד שֶׁהִגִּיעַ אוֹתוֹ צְרוֹר תַּחַת הַמִּזְבֵּחַ, וְשָׁם נִשְׁקַע, וְהִתְקַיֵּם כָּל הָעוֹלָם.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ שֶׁבְּאוֹתוֹ מָקוֹם שׁוֹרִים חַיִּים, לָמָּה לֹא נִבְנָה שָׁם בֵּית הַמִּקְדָּשׁ לָתֵת חַיִּים לְיוֹשְׁבֶיהָ? אֶלָּא כָּאן בַּמָּקוֹם הַזֶּה הִתְקַיֵּם מִשּׁוּם אוֹת אַחַת שֶׁשּׁוֹרָה עָלָיו. בְּבֵית הַמִּקְדָּשׁ כָּל הָאוֹתִיּוֹת כֻּלָּן שׁוֹרוֹת בּוֹ, וּבָהֶם נִבְרָא הוּא לְבַדּוֹ כְּמוֹ שֶׁכָּל הָעוֹלָם.</p>\n<p>וְעוֹד, שֶׁהָאָרֶץ הַקְּדוֹשָׁה (ביתהמקדש) נוֹתֶנֶת חַיִּים וְכַפָּרָה לְיוֹשְׁבֶיהָ בְּאוֹתוֹ הָעוֹלָם, וּמָקוֹם זֶה לֹא כָּךְ - נוֹתֵן חַיִּים לְאוֹתוֹ מָקוֹם בָּעוֹלָם הַזֶּה, וְלֹא בָּעוֹלָם הַבָּא. וּבֵית הַמִּקְדָּשׁ בְּהֵפֶךְ מִשָּׁם, מִשּׁוּם שֶׁיֵּשׁ חֵלֶק לְיִשְׂרָאֵל בְּאוֹתוֹ עוֹלָם, וְלֹא בָּעוֹלָם הַבָּא. וְלָכֵן עוֹמֵד בֵּית הַמִּקְדָּשׁ לְכַפֵּר חֲטָאִים וּלְזַכּוֹת אֶת יִשְׂרָאֵל לָעוֹלָם הַבָּא.</p>\n<p>בֹּא וּרְאֵה, טֵי\"ת אוֹר שֶׁל חַיִּים בְּכָל מָקוֹם, וְלָכֵן פָּתַח בָּהּ הַכָּתוּב כִּי טוֹב, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. מֵהָאוֹת הַזּוֹ (ממקום זה) בּוֹרֵחַ מַלְאָךְ הַמַּשְׁחִית. אַל תֹּאמַר בּוֹרֵחַ, אֶלָּא שֶׁלֹּא נִתֶּנֶת לוֹ רְשׁוּת לְהִכָּנֵס לְשָׁם.</p>\n<p>הָאוֹת הַזּוֹ מְשֻׁנָּה מֵהָאוֹת ק'. ק' לֹא מִתְיַשֶּׁבֶת (מאות ח'. ח' לא מתישבת) כְּלָל בְּמָקוֹם בָּעוֹלָם, וְסִימָנְךְ - (תהלים קמ) אִישׁ לָשׁוֹן בַּל יִכּוֹן בָּאָרֶץ. הָאוֹת טֵי\"ת מִתְיַשֶּׁבֶת בְּכָל מָקוֹם, וּמִתְתַּקֶּנֶת לָשֶׁבֶת כָּרָאוּי, וְלָכֵן בְּכָל מָקוֹם שֶׁשָּׁם אוֹת ט', אֵין יִשּׁוּב לָאוֹת ק' שָׁם לְהִתְיַשֵּׁב בּוֹ. וְלָכֵן בַּמָּקוֹם הַזֶּה לֹא שׁוֹלֵט כְּלָל הַצַּד הָאַחֵר, וְנוֹתֵן חַיִּים שֶׁל הָעוֹלָם הַזֶּה לַיּוֹשְׁבִים תַּחַת הָאוֹת הַזּוֹ, וְלֹא יֵצֵא הַחוּצָה. וּכְשֶׁיּוֹצֵא הַחוּצָה, יֵשׁ רְשׁוּת לַצַּד הָאַחֵר לִשְׁלֹט בּוֹ. כְּמוֹ שֶׁאוֹת זוֹ שׁוֹלֶטֶת בְּמָקוֹם זֶה, כָּךְ גַּם שׁוֹלֶטֶת אוֹת אַחֶרֶת בִּמְקוֹם הַגֵּיהִנֹּם. וּמִיהִי? הָאוֹת ק'.</p>"],[9522011733,"<p>וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, כָּאן הֵן שְׁתֵּי אוֹתִיּוֹת: ח', ט'. וְלָכֵן לֹא הָיוּ כְתוּבוֹת בְּתוֹךְ אַבְנֵי שּהַם וְאַבְנֵי מִלּוּאִים, וּמִשִּׁבְטֵי יִשְׂרָאֵל נִמְנְעוּ שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ, כְּדֵי שֵׁלֹּא רָשׁוּם בְּתוֹכָם חֵ\"ט.</p>\n<p>בִּמְקֹוֹם בֵּית הַמִּקְדָּשׁ תְּלוּיִים כָּל אוֹתִיּוֹת הָאַלְפָא בֵּיתָא בְּסוֹדוֹת חֲקוּקִים שֶׁל שֵׁמוֹת קְדוֹשִׁים, קְשׁוּרִים, רְקוּמִים עָלָיו, וְכָל הָעוֹלָם שֶׁלְּמַעְלָה וּמַטָּה, הַכֹּל בְּסוֹד שֶׁל אוֹתִיּוֹת מְתֻחָמוֹת (חקוקות) וּגְלוּפוֹת, וְסוֹדוֹת הַקְּדֻשָּׁה (השם הקדוש) הָעֶלְיוֹנָה נֶחְקָק עֲלֵיהֶם.</p>\n<p>בַּמִּשְׁכָּן נֶחְקְקוּ וְהִצְטַיְּרוּ הָאוֹתִיּוֹת כָּרָאוּי, שֶׁהֲרֵי בְּצַלְאֵל הָיָה יוֹדֵעַ אֶת הַחָכְמָה לְצָרֵף אוֹתִיּוֹת שֶׁבָּהֶן נִבְרְאוּ שָׁמַיִם וָאָרֶץ, וְעַל חָכְמָתוֹ (זו) נִבְנָה הַמִּשְׁכָּן עַל יָדוֹ וְנִבְחַר מִכָּל עַם יִשְׂרָאֵל.</p>\n<p>וּכְמוֹ שֶׁהוּא נִבְחָר לְמַעְלָה, כָּךְ רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּבָּחֵר לְמַטָּה. לְמַעִִלָה כָּתוּב (שמות לא) רְאֵה קָרָאתִי בְשֵׁם בְּצַלְאֵל. לְמַטָּה - (שם לה) רְאוּ קָרָא ה' בְּשֵׁם בְּצַלְאֵל. וּשְׁמוֹ בְּסוֹד עֶלְיוֹן נִקְרָא כָּךְ בְּצַלְאֵל - בְּצֵל אֵל. וּמִיהוּ? זֶה צַדִּיק, שֶׁהוּא יוֹשֵׁב בְּצֵל אֵל, אוֹתוֹ שֶׁנִּקְרָא אֵל עֶלְיוֹן, וְהוּא יוֹשֵׁב כְּמוֹ שֶׁאוֹתוֹ אֵל. אוֹתוֹ אֵל נוֹטֵל שִׁשָּׁה צְדָדִים, אוֹתוֹ צַדִּיק נוֹטֵל אוֹתָם. אַף כָּךְ אוֹתוֹ אֵל מֵאִיר לְמַעְלָה, וְהַצַּדִּיק הַזֶּה מֵאִיר לְמַטָּה. אוֹתוֹ הָאֵל כְּלָל שֶׁל כָּל שֵׁשֶׁת הַצְּדָדִים. וְאוֹתוֹ צַדִּיק הוּא כְּלָל שֶׁל כָּל שֵׁשֶׁת הַצְּדָדִים.</p>\n<p>בֶּן אוּרִי - בֶּן הָאוֹר הָרִאשׁוֹן שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית. בֶּן חוּר - הַבֵּן שֶׁל חֵרוּת הַכֹּל. דָּבָר אַחֵר בֶּן חוּר - בֵּן חִוֵּר מִכָּל הַגְּוָנִים. וְזֶה הִתְמַנָּה לְמַטֵּה יְהוּדָה, הַכֹּל כָּרָאוּי.</p>"],[9522011734,"<p>כָּל הַגְּוָנִים טוֹבִים לַחֲלוֹם פְּרָט לִתְכֵלֶת, כְּמוֹ שֶׁנֶּאֱמַר, מִשּׁוּם שֶׁהוּא כִּסֵּא לָדוּן אֶת דִּינֵי הַנְּשָׁמוֹת. וַהֲרֵי דַּרְגָּה זוֹ (אחת) הִיא לְבָנָה. אֶלָּא בְּשָׁעָה שֶׁעוֹמֶדֶת בְּדִינֵי נְפָשׁוֹת, אָז הִיא גָּוֶן תְּכֵלֶת, וַהֲרֵי בֵּאַרְנוּהָ.</p>\n<p>בְּשָׁעָה שֶׁרוֹאֶה אָדָם אֶת הַגָּוֶן הַזֶּה, נִזְכַּר הָאָדָם לַעֲשׂוֹת מִצְווֹת רִבּוֹנוֹ. כְּמוֹ שֶׁנְּחַשׁ הַנְּחֹשֶׁת, בְּשָׁעָה שֶׁהָיוּ רוֹאִים אוֹתוֹ, הָיוּ פוֹחֲדִים מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹמְרִים אֶת עַצְמָם מִכָּל הַחֲטָאִים, וּבְשָׁעָה שֶׁאוֹתוֹ הַפַּחַד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹלֶה עֲלֵיהֶם, מִיָּד נִרְפָּאִים. מִי גָרַם לָהֶם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא? אוֹתוֹ נָחָשׁ, אוֹתָהּ רְצוּעָה שֶׁמִּסְתַּכְּלִים בָּהּ. אַף כָּךְ הַתְּכֵלֶת - (במדבר טו) וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְות ה'. מֵאוֹתוֹ הַפַּחַד שֶׁלּוֹ. וְעַל זֶה תְּכֵלֶת בַּמִּשְׁכָּן.</p>\n<p>אָמַר רַבִּי יִצְחָק, זֶה שֶׁאָמַר מוֹרֵנוּ שֶׁתְּכֵלֶת הִיא כִּסֵּא דִין, וּכְשֶׁהִיא עוֹמֶדֶת בַּגָּוֶן הַזֶּה, אֲזַי הִיא כִּסֵּא לָדוּן דִּינֵי נְפָשׁוֹת. מָתַי הִיא בְּרַחֲמִים? אָמַר לוֹ, בְּשָׁעָה שֶׁהַכְּרוּבִים מַחֲזִירִים פְּנֵיהֶם זֶה עִם זֶה וּמִסְתַכְּלִים פָּנִים בְּפָנִים. כֵּיוָן שֶׁאוֹתָם כְּרוּבִים מִסְתַּכְּלִים פָּנִים בְּפָנִים, אָז כָּל הַגְּוָנִים מִתְתַּקְּנִים, וּמִתְהַפֵּךְ גָּוֶן תְּכֵלֶת לְגָוֶן אַחֵר. מִתְהַפֵּךְ גָּוֶן יָרֹק לְגָוֶן זָהָב (לבן).</p>\n<p>וְלָכֵן בְּהִפּוּךְ הַגְּוָנִים מִתְהַפֵּךְ מִדִּין לְרַחֲמִים, וְכֵן מֵרַחֲמִים לְדִין, וְהַכֹּל בְּהִפּוּךְ הַגְּוָנִים. כְּמוֹ שֶׁמְּסַדְּרִים יִשְׂרָאֵל תִּקּוּנֵיהֶם לַקָּדוֹשׁ-בָּרוּךְ-הוּא, כָּךְ הַכֹּל עוֹמֵד וְכָךְ מִסְתַּדֵּר. וְלָכֵן כָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר, בְּאוֹתָם גְּוָנִים שֶׁכְּלוּלִים זֶה בָּזֶה, הַיֹּפִי שֶׁל כֻּלָּם.</p>"],[9522011735,"<p>וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (דברים ח) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ וְגוֹ'. כַּמָּה צַדִּיקִים הֵם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם וְקֵרְבָם אֵלָיו מִכָּל הָעַמִּים, וּבִשְׁבִיל יִשְׂרָאֵל נָתַן מָזוֹן וְשּׁבַע לְכָל הָעוֹלָם, וְאִלְמָלֵא יִשְׂרָאֵל - לֹא נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא מָזוֹן לָעוֹלָם, וְעַכְשָׁו שֶׁיִּשְׂרָאֵל בַּגָּלוּת, עַל אַחַת כַּמָּה וְכַמָּה שֶׁנּוֹטְלִים מָזוֹן עַל אֶחָד פִּי שְׁנַיִם.</p>\n<p>בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ הַקְּדוֹשָׁה, הָיָה יוֹרֵד לָהֶם מָזוֹן מִמָּקוֹם עֶלְיוֹן, וְהֵם נוֹתְנִים חֵלֶק תַּמְצִית לָעַמִּים עוֹבְדֵי כּוֹכָבִים, וְכָל הָעַמִּים לֹא נִזּוֹנוּ אֶלָּא מֵהַתַּמְצִית, וְעַכְשָׁו שֶׁיִּשְׂרָאֵל הֵם בַּגָּלוּת, הִתְהַפֵּךְ לְגָוֶן אַחֵר.</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁהִתְקִין סְעוּדָה לִבְנֵי בֵיתוֹ. כָּל זְמַן שֶׁהֵם עוֹשִׂים אֶת רְצוֹנוֹ, אוֹכְלִים סְעוּדָה עִם הַמֶּלֶךְ, וְנוֹתְנִים לַכְּלָבִים חֵלֶק הָעֲצָמוֹת לִגְרֹר. בְּשָׁעָה שֶׁבְּנֵי בֵיתוֹ לֹא עוֹשִׂים אֶת רְצוֹן הַמֶּלֶךְ, הַמֶּלֶךְ נוֹתֵן אֶת כָּל הַסְּעוּדָה לַכְּלָבִים, וּמַעֲלֶה לָהֶם אֶת הָעֲצָמוֹת.</p>\n<p>כְּמוֹ זֶה, כָּל זְמַן שֶׁיִּשְׂרָאֵל עוֹשִׂים רְצוֹן רִבּוֹנָם, הֵם אוֹכְלִים עַל הַשֻּׁלְחָן הַזֶּה שֶׁל הַמֶּלֶךְ, וְכָל הַסְּעוּדוֹת מְתֻקָּנוֹת לָהֶם. וְהֵם, מֵאוֹתָהּ שִׂמְחָה שֶׁלָּהֶם, נוֹתְנִים עֲצָמוֹת שֶׁהֵן תַּמְצִית לְעוֹבְדֵי כּוֹכָבִים. וְכָל זְמַן שֶׁיִּשְׂרָאֵל לֹא עוֹשִׂים רְצוֹן רִבּוֹנָם, הֵם הוֹלְכִים לַגָּלוּת, וְהַסְּעוּדָה הוֹלֶכֶת לַכְּלָבִים, וְעוֹלָה לָהֶם הַתַּמְצִית. כָּכָה יֹאכְלוּ בְנֵי יִשְׂרָאֵל אֶת לַחְמָם טָמֵא בַּגּוֹיִם, שֶׁהֲרֵי תַּמְצִית הַגֹּעַל שֶׁלָּהֶם הֵם אוֹכְלִים. אוֹי לְבֶן הַמֶּלֶךְ שֶׁיּוֹשֵׁב וּמְצַפֶּה לְשֻׁלְחַן הָעֶבֶד, וּמַה שֶּׁנִּשְׁאָר מִתּוֹךְ הַשֻּׁלְחָן הוּא אוֹכֵל.</p>\n<p>דָּוִד הַמֶּלֶךְ אָמַר, (תהלים כג) תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צֹרְרָי דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי כּוֹסִי רְוָיָה. תַּעֲרֹךְ לְפָנַי שֻׁלְחָן - זוֹ סְעוּדַת הַמֶּלֶךְ. נֶגֶד צֹרְרָי - אוֹתָם הַכְּלָבִים שֶׁיּוֹשְׁבִים לִפְנֵי הַשֻּׁלְחָן וּמְצַפִּים לַחֲלֻקַּת עֲצָמוֹת, וְהוּא יוֹשֵׁב עִם הָמֶּלֶךְ בָּעֹנֶג שֶׁל הַסְּעוּדָה בַּשֻּׁלְחָן.</p>\n<p>דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי - זֶה רֹאשׁ הַסְּעוּדָה. שֶׁכָּל שֶׁמֶן וְשַׁמְנוּנִית וְתִקּוּן הַסְּעוּדָה נִתָּנִים בָּרִאשׁוֹנָה לַאֲהוּב הַמֶּלֶךְ. מַה שֶּׁנִּשְׁאָר נִתָּן אַחַר כָּךְ לַכְּלָבִים וּלְאוֹתָם עוֹבְדֵי הַשֻּׁלְחָן. כּוֹסִי רְוָיָה - מְלֵאָה הַכּוֹס לִפְנֵי אֲהוּב הַמֶּלֶךְ תָּמִיד שֶׁלֹּא יִצְטָרֵךְ לְבַקֵּשׁ, וְעַל סוֹד זֶה הָיוּ יִשְׂרָאֵל תָּמִיד עִם שְׁאָר הָעַמִּים.</p>\n<p>רַבִּי חִיָּיא הָיָה הוֹלֵךְ לְרַבִּי שִׁמְעוֹן לִטְבֶרְיָה, וְהָיוּ עִמּוֹ רַבִּי יַעֲקֹב בַּר אִידִי וְרַבִּי יֵיסָא הַקָּטָן. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי יֵיסָא לְרַבִּי חִיָּיא, תָּמוּהַּ מַה שֶּׁכָּתוּב (מלכים א ב) וְלִבְנֵי בַרְזִלַּי הַגִּלְעָדִי תַּעֲשֶׂה חֶסֶד וְהָיוּ בְּאֹכְלֵי שֻׁלְחָנֶךְ וְגוֹ'. אִם כָּךְ, כָּל טוֹב וֶאֱמֶת לֶאֱכֹל עַל שֻׁלְחָנוֹ וְלֹא יוֹתֵר, מִשֶּׁאָמַר כָּאן וְהָיוּ בְּאֹכְלֵי שֻׁלְחָנֶךְ. וְעוֹד, לֹא כְּבוֹד הַמֶּלֶךְ הוּא שֶׁיֹּאכַל אִישׁ אַחֵר עַל שֻׁלְחַן הַמֶּלֶךְ, וְלֹא צָרִיךְ זֶה אֶלָּא הַמֶּלֶךְ לְבַדּוֹ, וְכָל הַגְּדוֹלִים שֶׁלּוֹ סְבִיבוֹ לְמַטָּה מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי חִיָּיא, לֹא שָׁמַעְתִּי בָזֶה דָבָר, וְלֹא אֹמַר. אָמַר לוֹ לְרַבִּי יַעֲקֹב בַּר אִידִי, וְאַתָּה שָׁמַעְתָּ בְּזֶה הַדָּבָר? אָמַר לוֹ, אַתֶּם שֶׁיּוֹנְקִים בְּכָל יוֹם מִדְּבַשׁ שֶׁמֶן הָעֶלְיוֹן לֹא שְׁמַעְתֶּם, כָּל שֶׁכֵּן אֲנִי. שָׁאַל אֶת רַבִּי יֵיסָא, וְאַתָּה שָׁמַעְתָּ בָּזֶה דָבָר? אָמַר לוֹ, אַף עַל גַּב שֶׁאֲנִי תִינוֹק וּמִלִּפְנֵי מִסְפַּר יָמִים בָּאתִי אֲלֵיכֶם וְלֹא זָכִיתִי מִקֹּדֶם לָזֶה - אֲנִי כֵּן שָׁמַעְתִּי.</p>\n<p>פָּתַח וְאָמַר, (תהלים קלו) נוֹתֵן לֶחֶם לְכָל בָּשָׂר כִּי לְעוֹלָם חַסְדּוֹ. מָה רָאָה דָוִד שֶׁבְּסִיּוּם הַהַלֵּל הַגָּדוֹל סִיֵּם כָּךְ בַּפָּסוּק הַזֶּה? אֶלָּא שְׁלֹשָׁה שַׁלִּיטִים הֵם לְמַעְלָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע בָּהֶם, וְהֵם סוֹד נִכְבָּד שֶׁלּוֹ, וְאֵלֶּה הֵם: מֹחַ וְלֵב וְכָבֵד. וְהֵם בַּהֵפֶךְ שֶׁל הָעוֹלָם הַזֶּה. לְמַעְלָה הַמֹּחַ נוֹטֵל בָּרֹאשׁ, וְאַחַר כָּךְ נוֹתֵן לַלֵּב, וְהַלֵּב נוֹטֵל וְנוֹתֵן לַכָּבֵד, וְאַחַר כָּךְ הַכָּבֵד נוֹתֵן חֵלֶק לְכָל אוֹתָם מְקוֹרוֹת שֶׁלְּמַטָּה, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. לְמַטָּה הַכָּבֵד נוֹטֵל בָּרֹאשׁ, וְאַחַר מְקָרֵב הַכֹּל לַלֵּב, וְהַלֵּב נוֹטֵל אֶת הַיָּפֶה שֶׁל הַמַּאֲכָל. כֵּיוָן שֶׁנּוֹטֵל וּמִתְחַזֵּק מֵאוֹתוֹ כֹחַ וְרָצוֹן שֶׁנּוֹטֵל, נוֹתֵן וּמְעוֹרֵר אֶל הַמֹּחַ. וְאַחַר כָּךְ חוֹזֵר לַכָּבֵד וּמְחַלֵּק מָזוֹן לְכָל מְקוֹרוֹת הַגּוּף. (ביום שהאדם מתעורר בתענית, מתעורר למעלה כאותה דגמא ממש, וביום של שבע לא כך).</p>\n<p>בְּיוֹם שֶׁל תַּעֲנִית, אָדָם מַקְרִיב מַאֲכָל וּמִשְׁתֶּה לַכָּבֵד הָעֶלְיוֹן, וּמַה הוּא מַקְרִיב? חֶלְבּוֹ וְדָמוֹ וּרְצוֹנוֹ. אוֹתוֹ כָבֵד נוֹטֵל הַכֹּל בְּרָצוֹן. כֵּיוָן שֶׁהַכֹּל הוּא אֵלָיו, נוֹטֵל וּמַקְרִיב הַכֹּל לִפְנֵי הַלֵּב, שֶׁהוּא גָּדוֹל וְשׁוֹלֵט עָלָיו. כֵּיוָן שֶׁהַלֵּב נוֹטֵל וּמִתְחַזֵּק הָרָצוֹן, מַקְרִיב הַכֹּל לַמֹּחַ, שֶׁהוּא שַׁלִּיט עֶלְיוֹן עַל כָּל הַגּוּף. אַחַר כָּךְ חוֹזֵר הַכָּבֵד וּמְחַלֵּק חֲלָקִים לְכָל אוֹתָם מְקוֹרוֹת וְאֵיבָרִים שֶׁלְּמַטָּה. בִּזְמַן אַחֵר, כַּאֲשֶׁר (כל) הַמֹּחַ נוֹטֵל הַכֹּל בַּתְּחִלָּה, וְאַחַר כָּךְ נוֹתֵן לַלֵּב, וְהַלֵּב נוֹתֵן לַכָּבֵד, וְהַכָּבֵד נוֹתֵן לְכָל הַמְּקוֹרוֹת וְהָאֵיבָרִים שֶׁלְּמַטָּה, וְאַחַר כָּךְ כְּשֶׁרוֹצֶה לְחַלֵּק מָזוֹן לָעוֹלָם הַזֶּה, בָּרִאשׁוֹנָה נוֹתֵן לַלֵּב, שֶׁהוּא הַמֶּלֶךְ שֶׁבָּאָרֶץ, וְשֻׁלְחַן הַמֶּלֶךְ מִתְעוֹרֵר בָּרִאשׁוֹנָה מִכָּל שְׁאָר בְּנֵי הָעוֹלָם.</p>\n<p>אַשְׁרָיו מִי שֶׁהָיָה בַּחֶשְׁבּוֹן שֶׁל שֻׁלְחַן הַמֶּלֶךְ, שֶׁהֲרֵי יָדוּעַ הוּא לְהֵיטִיב לוֹ בְּאוֹתוֹ טוֹב שֶׁלְּמַעְלָה.</p>\n<p>(ומשום כך) וְזֶהוּ טוֹב וֶאֱמֶת שֶׁעָשָׂה דָוִד לִבְנֵי בַרְזִלַּי, שֶׁכָּתוּב וְהָיוּ בְּאֹכְלֵי שֻׁלְחָנֶךְ. וְאִם תֹּאמַר שֶׁבְּשֻׁלְחַן הַמֶּלֶךְ אוֹכֵל אָדָם אַחֵר פְּרָט לוֹ - לֹא! אֶלָּא הַמֶּלֶךְ אוֹכֵל בָּרִאשׁוֹנָה, וְאַחַר כָּךְ כָּל הָעָם. וְאוֹתָם שֶׁאוֹכְלִים עִם הַמֶּלֶךְ בְּשָׁעָה שֶׁהוּא אוֹכֵל - אוֹתָם שֶׁחֲבִיבִים עָלָיו מִכֻּלָּם, וְהֵם נִמְנִים מִשֻּׁלְחַן הַמֶּלֶךְ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (שמואל ב ט) עַל שֻׁלְחַן הַמֶּלֶךְ תָּמִיד הוּא אֹכֵל - מִשּׁוּם שֶׁכָּל מְזוֹנוֹ לֹא עוֹשֶׂה חֶשְׁבּוֹן אַחֵר, אֶלָּא עַל שֻׁלְחַן הַמֶּלֶךְ, שֶׁמִּשָּׁם הָיָה בָּא מְזוֹנוֹ וּמַאֲכָלוֹ. וְזֶהוּ עַל שֻׁלְחַן הַמֶּלֶךְ תָּמִיד הוּא אֹכֵל. בָּא רַבִּי חִיָּיא וּנְשָׁקוֹ עַל רֹאשׁוֹ. אָמַר לוֹ, תִּינוֹק אַתָּה, וְחָכְמָה עֶלְיוֹנָה שׁוֹרָה בְלִבְּךְ. בֵּינְתַיִם רָאוּ אֶת רַבִּי חִזְקִיָּה שֶׁהָיָה בָּא. אָמַר לוֹ רַבִּי חִיָּיא, וַדַּאי בַּחֲבֵרוּת זוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא יִתְחַבֵּר עָלֵינוּ, שֶׁהֲרֵי דְּבָרִים חִדּוּשֵׁי תוֹרָה יִתְחַדְּשׁוּ כָאן.</p>\n<p>יָשְׁבוּ לֶאֱכֹל. אָמְרוּ, כָּל אֶחָד וְאֶחָד יֹאמַר דִּבְרֵי תוֹרָה בַּסְּעוּדָה הַזּוֹ. אָמַר רַבִּי יֵיסָא, סְעוּדַת עֲרַאי הִיא, וְלָכֵן נִקְרֵאת סְעוּדָה. וְלֹא עוֹד, אֶלָּא שֶׁזּוֹ נִקְרֵאת סְעוּדָה שֶׁנֶּהֱנֶה מִמֶּנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה כָּתוּב, זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה', שֶׁהֲרֵי דִּבְרֵי תוֹרָה יַקִּיפוּ אֶת הַמָּקוֹם הַזֶּה.</p>"],[9522011736,"<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (דברים ח) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ וְגוֹ'. וְכִי עַד שֶׁלֹּא אוֹכֵל אָדָם לְשָׂבְעָה וְתִתְמַלֵּא כְרֵסוֹ לֹא יְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא?! (אם כך) בַּמֶּה נְבָאֵר וְאָכַלְתָּ וְשָׂבָעְתָּ, וְאַחַר כָּךְ וּבֵרַכְתָּ? אֶלָּא אֲפִלּוּ לֹא יֹאכַל אָדָם אֶלָּא כַּזַּיִת, וּרְצוֹנוֹ עָלָיו, וְיָשִׂים אֶת אוֹתוֹ הַמַּאֲכָל עִקַּר מַאֲכָלוֹ - נִקְרָא שָׂבְעָה, שֶׁכָּתוּב (תהלים קמה) פּוֹתֵחַ אֶת יָדֶךְ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. לֹא כָתוּב לְכָל חַי אֲכִילָה, אֶלָּא רָצוֹן. אוֹתוֹ רָצוֹן שֶׁשָּׂם עַל אוֹתוֹ מַאֲכָל נִקְרָא שָׂבְעָה, וַאֲפִלּוּ שֶׁאֵין לִפְנֵי הָאָדָם אֶלָּא אוֹתוֹ מְעַט בְּכַזַּיִת וְלֹא יוֹתֵר, הֲרֵי רְצוֹן הַשּׂבַע שָׂם עָלָיו. וּמִשּׁוּם כָּךְ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. כָּתוּב רָצוֹן, וְלֹא אֲכִילָה. וְעַל זֶה וּבֵרַכְתָּ וַדַּאי, וּמִתְחַיֵּב הָאָדָם לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לָתֵת שִׂמְחָה לְמַעְלָה.</p>\n<p>פָּתַח רַבִּי חִזְקִיָּה בַּפָּסוּק הַזֶּה אַחֲרָיו וְאָמַר, וְאָכַלְתָּ וְשָׂבָעְתָּ. מִכָּאן שֶׁלְּשִׁכּוֹר מֻתָּר לְבָרֵךְ בִּרְכַּת הַמָּזוֹן, מַה שֶּׁאֵין כֵּן בִּתְפִלָּה. שֶׁתְּפִלָּה לֹא כָּךְ, שֶׁהֲרֵי תְּפִלָּה מְעֻלָּה הִיא בְּלִי אֲכִילָה, מָה הַטַּעַם? מִשּׁוּם שֶׁתְּפִלָּה עוֹלָה לְמַעְלָה לְמַעְלָה, מָקוֹם שֶׁאֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה. וְעַל זֶה שָׁנִינוּ, הָעוֹלָם הַבָּא אֵין בּוֹ אֲכִילָה וּשְׁתִיָּה וְכוּ'.</p>\n<p>אֲבָל שְׁאָר הַדְּרָגוֹת שֶׁלְּמַטָּה יֵשׁ. בְּבִרְכַּת הַמָּזוֹן נִמְצָא גָוֶן אַחֵר וּמְעֻלֶּה, אוֹתָהּ בְּרָכָה שֶׁנִּמְצֵאת בַּשּׂבַע. מִשּׁוּם שֶׁבִּרְכַּת הַמָּזוֹן הִיא בְּמָקוֹם שֶׁיֵּשׁ בּוֹ אֲכִילָה וּשְׁתִיָּה, וּמִמֶּנּוּ יוֹצֵאת מָזוֹן וְשּבַע לְמַטָּה, וְעַל זֶה צָרִיךְ לְהַרְאוֹת לְפָנָיו שּׁבַע וְשִׂמְחָה. (ומשום כך זהו מקום שיש בו אכילה ושתיה, וממנו יוצא מזון למטה, וצריך להראות לפניו שבע ושמחה) בְּמָקוֹם שֶׁל תְּפִלָּה לֹא כָּךְ, שֶׁהֲרֵי עוֹלָה יוֹתֵר לְמַעְלָה לְמַעְלָה, וְעַל זֶה שִׁכּוֹר לֹא יִתְפַּלֵּל תְּפִלָּה.</p>\n<p>בְּבִרְכַּת הַמָּזוֹן, שִׁכּוֹר מֻתָּר לוֹ לְבָרֵךְ בִּרְכַּת הַמָּזוֹן. מַשְׁמָע מֵהַפָּסוּק הַזֶּה, שֶׁכָּתוּב וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ. וְאָכַלְתָּ - זוֹ אֲכִילָה. וְשָׂבָעְתָּ - זוֹ שְׁתִיָּה, שֶׁהֲרֵי שּׁבַע בְּיַיִן מִתְרַוֶּה. יַיִן שּׁבַע וַדַּאי, וְזֶהוּ שִׁכּוֹר, שֶׁכָּתוּב וּבֵרַכְתָּ אֶת דַּוְקָא, שֶׁמַּשְׁמָע שֶׁבִּרְכַּת הַמָּזוֹן צָרִיךְ שִׂמְחָה וְשּׁבַע. עַל הָאָרֶץ הַטּוֹבָה. מַה זֶּה טוֹבָה? שּׁבַע, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה מד) וַנִּשְׂבַּע לֶחֶם וַנִּהְיֶה טוֹבִים. מִשּׁוּם כָּךְ צָרִיךְ שִׂמְחָה וְשּבַע.</p>"],[9522011737,"<p>פָּתַח רַבִּי יֵיסָא וְאָמַר, וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ'. הַשֻּׁלְחָן הַזֶּה הוּא עוֹמֵד לְתוֹךְ הַמִּשְׁכָּן, וְהַבְּרָכָה שֶׁלְּמַעְלָה שׁוֹרָה עָלָיו, וּמִמֶּנּוּ יוֹצֵא מָזוֹן לְכָל הָעוֹלָם. וְשֻׁלְחָן זֶה לֹא צָרִיךְ לִהְיוֹת בְּרֵיקָנוּת אֲפִלּוּ רֶגַע אֶחָד, אֶלָּא שֶׁיִּהְיֶה עָלָיו מָזוֹן, שֶׁהֲרֵי הַבְּרָכָה לֹא נִמְצֵאת בְּמָקוֹם רֵיק. וְלָכֵן צָרִיךְ לִהְיוֹת עָלָיו תָּמִיד לֶחֶם, שֶׁתִּהְיֶה תָּמִיד בְּרָכָה עֶלְיוֹנָה נִמְצֵאת בּוֹ, וּמִתּוֹךְ אוֹתוֹ שֻׁלְחָן יוֹצְאוֹת בְּרָכוֹת וּמְזוֹנוֹת לְכָל שְׁאָר שֻׁלְחֲנוֹת הָעוֹלָם, שֶׁמִּתְבָּרְכִים בִּגְלָלוֹ.</p>\n<p>הַשְּׁלְחָן שֶׁל כָּל אָדָם צָרִיךְ לִהְיוֹת כָּךְֹ לְפָנָיו בְּשָׁעָה שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי שֶׁתִּשְׁרֶה עָלָיו בְּרָכָה מִלְמַעְלָה, וְלֹא יֵרָאֶה בְרֵיקָנוּת, שֶׁהֲרֵי הַבְּרָכוֹת שֶׁלְּמַעְלָה לֹא שׁוֹרוֹת בְּמָקוֹם רֵיק, שֶׁכָּתוּב (מלכים ב ד) הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת, וַהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים.</p>\n<p>שֻׁלְחָן שֶׁלֹּא נֶאֶמְרוּ עָלָיו דִּבְרֵי תוֹרָה (ולא ברך על אותו מזון לקדוש ברוך הוא), עָלָיו כָּתוּב (ישעיה כח) כִּי כָּל שֻׁלְחָנוֹת מָלְאוּ קִיא צֹאָה בְּלִי מָקוֹם. וְאָסוּר לְבָרֵךְ עַל אוֹתוֹ שֻׁלְחָן. מָה הַטַּעַם? מִשּׁוּם שֶׁיֵּשׁ שֻׁלְחָן וְיֵשׁ שֻׁלְחָן. שֻׁלְחָן שֶׁהוּא מְסֻדָּר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וְעוֹמֵד תָּמִיד לְסַדֵּר בּוֹ דִּבְרֵי תוֹרָה וּלְהַכְלִיל בּוֹ אוֹתִיּוֹת שֶׁל דִּבְרֵי תוֹרָה, (זהו ברכת המזון. שיש פסוקים ודברי תורה ואותן אותיות של דברי תורה נכללים בו באותו שלחן) וְהוּא לוֹקֵט אוֹתָם אֵלָיו וְכוֹלֵל אֶת כֻּלָּם לְתוֹכוֹ, וּבָהֶם מִשְׁתַּלֵּם וְשָׂמֵחַ וְיֵשׁ לוֹ שִׂמְחָה. וְעַל שֻׁלְחָן זֶה כָּתוּב (יחזקאל מא) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה'. לִפְנֵי ה', וְלֹא מִלִּפְנֵי ה'.</p>\n<p>יֵשׁ שֻׁלְחָן אַחֵר שֶׁאֵין בּוֹ חֵלֶק שֶׁל תּוֹרָה, וְאֵין לוֹ חֵלֶק בִּקְדֻשַּׁת הַתּוֹרָה. וְאוֹתוֹ שֻׁלְחָן נִקְרָא קִיא צוֹאָה, וְזֶהוּ בְּלִי מָקוֹם, שֶׁאֵין לוֹ חֵלֶק בְּצַד הַקְּדֻשָּׁה כְּלוּם. מִשּׁוּם כָּךְ, שֻׁלְחָן שֶׁלֹּא נֶאֱמַר עָלָיו דִּבְרֵי תוֹרָה הוּא שֻׁלְחָן שֶׁל קִיא צֹאָה, הוּא שֻׁלְחָן שֶׁל אֱלִיל אַחֵר. אֵין בְּאוֹתוֹ שֻׁלְחָן חֵלֶק בְּסוֹד הָאֱלוֹהַּ הָעֶלְיוֹן.</p>\n<p>שֻׁלְחָן שֶׁדִּבְרֵי תוֹרָה נֶאֱמָרִים עָלָיו, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אוֹתוֹ שֻׁלְחָן וְשָׂם אוֹתוֹ לְחֶלְקוֹ. וְלֹא עוֹד, אֶלָּא סוּרְיָ\"א, הַמְמֻנֶּה הַגָּדוֹל, נוֹטֵל כָּל הַדְּבָרִים הַלָּלוּ, וְשָׂם דְּיוֹקַן אוֹתוֹ הַשֻּׁלְחָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכָל אוֹתָם דִּבְרֵי הַתּוֹרָה שֶׁנֶּאֶמְרוּ עָלָיו עוֹלִים עַל אוֹתוֹ שֻׁלְחָן, וּמִתְעַטֵּר (ומזדמן) לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. מַשְׁמָע שֶׁכָּתוּב זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה', שֶׁמִּתְעַטֵּר (שמזדמן) לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֻׁלְחָנוֹ שֶׁל אָדָם עוֹמֵד לְטַהֵר אֶת הָאָדָם מִכָּל חֲטָאָיו. אַשְׁרֵי הוּא מִי שֶׁאֵלֶּה הַשְּׁנַיִם עוֹמְדִים עַל שֻׁלְחָנוֹ - דִּבְרֵי תוֹרָה, וְחֵלֶק לָעֲנִיִּים. מֵאוֹתוֹ שֻׁלְחָן.</p>\n<p>כְּשֶׁמַּעָלִים אוֹתוֹ שֻׁלְחָן מִלִּפְנֵי אוֹתוֹ אָדָם, שְׁנֵי מַלְאָכִים קְדוֹשִׁים מִזְדַּמְּנִים לְשָׁם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. אֶחָד אוֹמֵר: זֶהוּ שֻׁלְחָן שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁפְּלוֹנִי מְסַדֵּר לְפָנָיו, מְסֻדָּר יִהְיֶה תָּמִיד הַשֻּׁלְחָן הַזֶּה בִּבְרָכוֹת עֶלְיוֹנוֹת, וְשֶׁמֶן וּמִשְׁחָה עֶלְיוֹנָה הַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁרֶה עָלָיו. וְאֶחָד אוֹמֵר: זֶהוּ הַשֻּׁלְחָן שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁפְּלוֹנִי מְסַדֵּר לְפָנָיו, זֶה שֻׁלְחָן שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים יְבָרְכוּ אוֹתוֹ, מְסֻדָּר יִהְיֶה שֻׁלְחָן זֶה לִפְנֵי עַתִּיק הַיָּמִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>רַבִּי אַבָּא, כְּשֶׁהָיוּ מַעֲלִים אֶת הַשֻּׁלְחָן מִלְּפָנָיו, הָיָה מְכַסֶּה אוֹתוֹ וְהָיָה אוֹמֵר: סַלְּקוּ שֻׁלְחָן זֶה בִּצְנִיעוּת, שֶׁלֹּא יִהְיֶה בְּבוּשָׁה לִפְנֵי שְׁלוּחֵי הַמֶּלֶךְ. הַשֻּׁלְחָן שֶׁאָדָם זוֹכֶה לוֹ לָעוֹלָם הַבָּא, וְזוֹכֶה לוֹ לַמָּזוֹן שֶׁל הָעוֹלָם הַזֶּה, וּמְזַכֶּה אוֹתוֹ לְהִוָּדַע לְטוֹב לִפְנֵי עַתִּיק הַיָּמִים, וּמְזַכֶּה אוֹתוֹ לְהִתּוֹסֵף כֹּחַ וְגֹדֶל בְּמָקוֹם שֶׁצָּרִיךְ. אַשְׁרָיו חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>רַבִּי יַעֲקֹב אָמַר, כָּתוּב (שמואל א י) וַיְהִי כָּל יוֹדְעוֹ מֵאִתְּמוֹל שִׁלְשֹׁם וְגוֹ', הֲגַם שָׁאוּל בַּנְּבִיאִים. וְכִי שָׁאוּל בְּחִיר ה' מִקֹּדֶם לָכֵן הָיָה, שֶׁכָּתוּב הַרְאִיתֶם אֲשֶׁר בָּחַר בּוֹ ה'. לֹא כָתוּב אֲשֶׁר בּוֹחֵר בּוֹ, אֶלָּא אֲשֶׁר בָּחַר בּוֹ, מִקֹּדֶם לָכֵן. וּבְשָׁעָה שֶׁבָּא וְנִכְנָס בֵּין הַנְּבִיאִים וְהִתְנַבֵּא בֵינֵיהֶם, לָמָּה תָּמְהוּ?</p>\n<p>אֶלָּא כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בּוֹ, לֹא הִתְרַצָּה בּוֹ אֶלָּא לְמַלְכוּת, אֲבָל לֹא לִנְבוּאָה. שֶׁהֲרֵי שְׁנֵי אֵלֶּה לֹא נִמְסְרוּ כְאֶחָד בְּאָדָם בָּעוֹלָם, פְּרָט לְמֹשֶׁה הַנֶּאֱמָן הָעֶלְיוֹן שֶׁזָּכָה לִנְבוּאָה וּמַלְכוּת כְּאֶחָד, וְלֹא נִתַּן לְשׁוּם אָדָם אַחֵר שְׁנֵיהֶם כְּאֶחָד.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי שְׁמוּאֵל שֶׁזָּכָה לִשְׁנֵיהֶם, לִנְבוּאָה וּמַלְכוּת - לֹא כָּךְ! לִנְבוּאָה זָכָה, שֶׁכָּתוּב (שם ג) וַיֵּדַע כָּל יִשְׂרָאֵל מִדָּן וְעַד בְּאֵר שָׁבַע כִּי נֶאֱמָן שְׁמוּאֵל לְנָבִיא. לְנָבִיא וְלֹא לְמֶלֶךְ. נָבִיא וְדַיָּן הָיָה. שֶׁאִם מֶלֶךְ הָיָה, לֹא שָׁאֲלוּ יִשְׂרָאֵל מֶלֶךְ. אֲבָל הוּא לֹא הָיָה אֶלָּא נָבִיא נֶאֱמָן, וְהָיָה דָּן אֶת דִּינֵי יִשְׂרָאֵל, שֶׁכָּתוּב (שם ז) וְשָׁפַט אֶת יִשְׂרָאֵל. וְלָכֵן כְּשֶׁהָיָה שָׁאוּל בִּנְבוּאָה, תָּמְהוּ עָלָיו.</p>\n<p>וְאִם תֹּאמַר, לָמָּה שָׁרְתָה עָלָיו נְבוּאָה, הוֹאִיל וְזָכָה לְמַלְכוּת? - אֶלָּא שְׁנֵיהֶם לֹא זָכָה בָהֶם כְּאֶחָד, (ומשום (שהנבוּאָה) שהמלכות נתן לו הקדוש ברוך הוא והודה לו עליו בטרם היה מלך) וּמִשּׁוּם שֶׁמַּלְכוּת הִתְיַשְּׁבָה עַל הִתְעוֹרְרוּת שֶׁל רוּחַ הַקֹּדֶשׁ, הָיָה בְּהִתְעוֹרְרוּת הַנְּבוּאָה קֹדֶם לָכֵן. אֲבָל כְּשֶׁעָלָה לַמַּלְכוּת, לֹא הָיְתָה בּוֹ נְבוּאָה, אֶלָּא הִתְעוֹרְרוּת שֶׁל רוּחַ הַשֵּׂכֶל לָדוּן אֱמֶת הִתְעוֹרְרָה עָלָיו, שֶׁכָּךְ רָאוּי לְמֶלֶךְ. וּבְעוֹד שֶׁהָיָה בְּתוֹךְ אוֹתָם נְבִיאִים שָׁרְתָה עָלָיו נְבוּאָה, וּלְאַחַר שֶׁנִּפְרַד מֵהֶם לֹא הָיְתָה בּוֹ נְבוּאָה.</p>\n<p>וַאֲנִי, מִי נָתַן לִי הִתְעוֹרְרוּת שֶׁל רוּחַ הַקֹּדֶשׁ לִהְיוֹת בְּתוֹךְ נְבִיאִים נֶאֱמָנִים, תַּלְמִידֵי רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים חֲרֵדִים מִפָּנָיו, כָּל שֶׁכֵּן אֲנִי לִהְיוֹת בֵּינֵיכֶם.</p>\n<p>פָּתַח וְאָמַר, וְעָשִׂיתָ שֻׁלְחָן וְגוֹ'. שֻׁלְחָן זֶה הוּא לְמַטָּה לָשִׂים עָלָיו לֶחֶם הָאֲפִיָּה, מִי עָדִיף זֶה מִזֶּה, לֶחֶם אוֹ שֻׁלְחָן? אִם תֹּאמַר שֶׁהַכֹּל הוּא אֶחָד - הֲרֵי (אם תאמר לחם עדיף, שהרי) שֻׁלְחָן מְסֻדָּר לְאוֹתוֹ לֶחֶם. וְעוֹד, שֻׁלְחָן לְמַטָּה וְלֶחֶם עָלָיו - לֹא כָּךְ! אֶלָּא הַשֻּׁלְחָן הוּא הָעִקָּר בַּסִּדּוּר שֶׁלּוֹ לְקַבֵּל בְּרָכוֹת שֶׁלְּמַעְלָה וּמָזוֹן לָעוֹלָם, וּמֵהַסּוֹד שֶׁל הַשֻּׁלְחָן הַזֶּה יוֹצֵא מָזוֹן לָעוֹלָם כְּמוֹ שֶׁנִּתָּן בּוֹ מִלְמַעְלָה.</p>\n<p>וְאוֹתוֹ לֶחֶם הוּא פְּרִי וּמָזוֹן שֶׁיּוֹצֵא מֵהַשֻּׁלְחָן הַזֶּה, לְהַרְאוֹת שֶׁהֲרֵי מֵהַשֻּׁלְחָן הַזֶּה יוֹצְאִים פֵּרוֹת וּמְזוֹנוֹת לָעוֹלָם. אִם לֹא נִמְצָא כֶרֶם - הָעֲנָבִים, שֶׁהֵם הַפְּרִי הַיּוֹצֵא מִמֶּנּוּ, לֹא יִהְיוּ נִמְצָאִים. אִם הָאִילָן לֹא יִהְיֶה, לֹא יִמָּצֵא פְּרִי בָעוֹלָם, לָכֵן הַשֻּׁלְחָן הוּא הָעִקָּר. הַמָּזוֹן שֶׁיּוֹצֵא מִמֶּנּוּ הוּא אוֹתוֹ לֶחֶם הַפָּנִים.</p>\n<p>וְהַכֹּהֲנִים הָיוּ לוֹקְטִים פְּרִי הַשֻּׁלְחָן מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת (משבת לשבת), לְהַרְאוֹת שֶׁהֲרֵי מָזוֹן עֶלְיוֹן יוֹצֵא מִתּוֹךְ אוֹתוֹ שֻׁלְחָן. מִשּׁוּם אוֹתוֹ לֶחֶם שֶׁהָיוּ לוֹקְטִים הַכֹּהֲנִים, הִתְבָּרֵךְ כָּל מָזוֹן וּמָזוֹן שֶׁאוֹכְלִים וְשׁוֹתִים שֶׁלֹּא יְקַטְרֵג בָּהֶם יֵצֶר הָרָע, שֶׁהֲרֵי יֵצֶר הָרָע לֹא נִמְצָא אֶלָּא מִתּוֹךְ מַאֲכָל וּמִשְׁתֶּה. זֶהוּ שֶׁכָּתוּב (משליל) פֶּן אֶשְׂבַּע וְכִחַשְׁתִּי וְגוֹ'. שֶׁמִּתּוֹךְ מַאֲכָל וּמִשְׁתֶּה, יֵצֶר הָרָע מִתְגַּדֵּל בִּמְעִי הָאָדָם.</p>\n<p>לֶחֶם זֶה, מָזוֹן שֶׁיּוֹצֵא מִתּוֹךְ הַשֻּׁלְחָן, מְבָרֵךְ אֶת מְזוֹן הַכֹּהֲנִים שֶׁלֹּא יִמָּצֵא בָהֶם מְקַטְרֵג לְקַטְרֵג לָהֶם, וְלַעֲבֹד בְּלֵב שָׁלֵם לַקָּדוֹשׁ- בָּרוּךְ-הוּא. וְזֶה צָרִיךְ לַכֹּהֲנִים יוֹתֵר מִכָּל הָעוֹלָם, וְלָכֵן שֻׁלְחָן הוּא עִקָּר, וְהַפְּרִי וְהַמָּזוֹן שֶׁיּוֹצֵא מִמֶּנּוּ הוּא אוֹתוֹ לֶחֶם.</p>\n<p>הַשֻּׁלְחָן הַזֶּה צָרִיךְ הַסִּדּוּר שֶׁלּוֹ לְהִתְתַּקֵּן בְּצַד הַצָּפוֹן, שֶׁכָּתוּב וְהַשֻּׁלְחָן תִּתֵּן עַל צֶלַע צָפוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּשָּׁם רֵאשִׁית הַשִּׂמְחָה. הַשְּׂמֹאל נוֹטֵל תָּמִיד מֵהַיָּמִין בָּרִאשׁוֹנָה, וְאַחַר כָּךְ הוּא מִתְעוֹרֵר לַנְּקֵבָה. אַחַר כָּךְ הַיָּמִין מְקָרֵב אוֹתוֹ אֵלָיו וְנִדְבָּק בּוֹ.</p>\n<p>הַמַּיִם הֵם מִיָּמִין, וְהֵם שִׂמְחָה. מִיָּד נוֹתֵן לַשְּׂמֹאל, וְנִדְבָּקִים בּוֹ אוֹתָם מַיִם וּמְשַׂמְּחִים אוֹתוֹ. וְאַחַר כָּךְ הוּא נִכְלָל בַּיָּמִין, וּמְעוֹרֵר אֶת הַנְּקֵבָה בְּאוֹתָהּ שִׂמְחָה, וְסִימָנְךְ - מִי שֶׁנּוֹטֵל מַיִם בְּיַד יְמִינוֹ בִּכְלִי, רִאשׁוֹן לְרוֹקֵן מַיִם הוּא בִּשְׂמֹאל, וְלֹא מִשְּׂמֹאל לְיָמִין, שֶׁהֲרֵי מַיִם מִיָּמִין לוֹקֵחַ אוֹתָם הַשְּׂמֹאל.</p>\n<p>וְלָכֵן מַיִם לֹא נִמְצָאִים אֶלָּא מִצַּד הַשְּׂמֹאל. כֵּיוָן שֶׁנִּלְקְחוּ הַמַּיִם אֵלָיו, הֲרֵי הִתְעוֹרְרוּ לַנְּקֵבָה בְּאוֹתָם מַיִם, וְלָכֵן גְּבוּרוֹת גְּשָׁמִים שָׁנִינוּ. וְלָכֵן וְהַשֻּׁלְחָן תִּתֵּן עַל צֶלַע צָפוֹן, שֶׁמֵּאוֹתוֹ הַצַּד הַפֵּרוֹת נִמְצָאִים בּוֹ יוֹתֵר מֵהַצַּד הָאַחֵר, בְּהִתְעוֹרְרוּת הַשִּׂמְחָה שֶׁלּוֹ בָּרִאשׁוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, וְאַחַר כָּךְ - וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>שֻׁלְחָנוֹ שֶׁל אָדָם צָרִיךְ לְהִמָּצֵא בִּנְקִיּוּת הַגּוּף, שֶׁלֹּא יִקְרַב לֶאֱכֹל אֶת מְזוֹנוֹ אֶלָּא בְּנִקְיוֹן עַצְמוֹ. וְלָכֵן צָרִיךְ הָאָדָם לְפַנּוֹת עַצְמוֹ בַּתְּחִלָּה טֶרֶם שֶׁיֹּאכַל מָזוֹן שֶׁל שֻׁלְחָן טָהוֹר, כִּי אוֹתוֹ מָזוֹן שֶׁהֵכִין לוֹ, בּוֹ רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי שֶׁלֹּא יִקְרַב עַל אוֹתוֹ שֻׁלְחָן קִיא צוֹאָה, שֶׁהוּא מִסּוֹד הַצַּד הָאַחֵר, וְהַצַּד הָאַחֵר לֹא יְקַבֵּל כְּלוּם מֵאוֹתוֹ מָזוֹן שֶׁל הַשֻּׁלְחָן הַזֶּה.</p>\n<p>אַחַר שֶׁאָכַל אָדָם וְהִתְעַנֵּג, צָרִיךְ לָתֵת חֵלֶק שֶׁל תַּמְצִית לְאוֹתוֹ הַצַּד, וּמַהוּ? מַיִם אַחֲרוֹנִים. אוֹתָהּ זֻהֲמַת הַיָּדַיִם. שֶׁצָּרִיךְ לָתֵת לְאוֹתוֹ צַד חֵלֶק שֶׁצָּרִיךְ לוֹ. וְלָכֵן וַדַּאי שֶׁהֵם חוֹבָה, חוֹבָה הֵם, וּבְמָקוֹם שֶׁל חוֹבָה שׁוֹרִים, וְהוּא חִיּוּב עַל אָדָם לָתֵת לוֹ חֵלֶק זֶה. וְלָכֵן לֹא צָרִיךְ לְבָרֵךְ כְּלָל, שֶׁהֲרֵי אֵין הַבְּרָכָה בְּאוֹתוֹ הַצַּד.</p>\n<p>וְלָכֵן צָרִיךְ אָדָם שֶׁלֹּא יִתֵּן מָזוֹן שֶׁעַל גַּבֵּי שֻׁלְחָנוֹ לְאוֹתוֹ קִיא צוֹאָה, וְכָל שֶׁכֵּן בְּמֵעָיו, וְכָל שֶׁכֵּן שֶׁהוּא טָהוֹר (טוב) לָאָדָם וּבְרִיאוּת וְתִקּוּן הַגּוּף שֶׁלּוֹ. וְלָכֵן הַשֻּׁלְחָן הוּא לֶאֱכֹל בּוֹ בְּטָהֳרָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>שֻׁלְחָן זֶה שֶׁעוֹמֵד בְּבֵית הַמִּקְדָּשׁ, כְּדֵי לְהִמָּצֵא בּוֹ מָזוֹן וּלְהוֹצִיא מִמֶּנּוּ מָזוֹן, וְלָכֵן אֲפִלּוּ רֶגַע אֶחָד לֹא צָרִיךְ לַעֲמֹד בְּרֵיקָנוּת. שֻׁלְחָן אַחֵר הוּא שֻׁלְחַן הָרֵיקָנוּת, וְלֹא צָרִיךְ לָתֵת לוֹ מָקוֹם בְּמָקוֹם קָדוֹשׁ. וְלָכֵן שֻׁלְחַן הַמִּקְדָּשׁ אֲפִלּוּ רֶגַע אֶחָד לֹא יֵשֵׁב בְּלִי מָזוֹן, וְיִצְטָרֵךְ שֶׁלֹּא יִמָּצֵא בְּמָקוֹם גָּרוּעַ, שֶׁהֲרֵי הַבְּרָכָה שֶׁלְּמַעְלָה לֹא נִמְצֵאת בְּמָקוֹם גָּרוּעַ. זֶה שֻׁלְחָן שֶׁלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֻׁלְחָן שֶׁאָדָם מְבָרֵךְ עָלָיו אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף כָּךְ לֹא צָרִיךְ לִהְיוֹת בְּרֵיקָנוּת, שֶׁהֲרֵי אֵין הַבְּרָכָה בְּמָקוֹם רֵיק.</p>\n<p>הַלְּחָמִים שֶׁעַל גַּבֵּי הַשֻּׁלְחָן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם שְׁנֵים עָשָׂר. וַהֲרֵי בֵּאַרְנוּ סוֹד הַלְּחָמִים, שֶׁהֵם סוֹד הַפָּנִים, וְלָכֵן נִקְרָא לֶחֶם הַפָּנִים, שֶׁהֲרֵי מָזוֹן וְסִפּוּק שֶׁל הָעוֹלָם בָּאִים מֵאוֹתָם הַפָּנִים הָעֶלְיוֹנִים. וְלָכֵן לֶחֶם זֶה הוּא פְּנִימִי שֶׁל הַכֹּל, הוּא בְּסוֹד עֶלְיוֹן כָּרָאוּי.</p>\n<p>לֶחֶם הַפָּנִים - מַאֲכָל שֶׁל אוֹתָם פָּנִים, מָזוֹן וְסִפּוּק שֶׁיּוֹצֵא לָעוֹלָם, מֵהֶם בָּא, וְשׁוֹרֶה עַל אוֹתוֹ שֻׁלְחָן. וּמִשּׁוּם שֶׁשֻּׁלְחָן זֶה מְקַבֵּל מָזוֹן וְסִפּוּק מֵאוֹתָם פָּנִים שֶׁל מַעְלָה, וְהִיא מוֹצִיאָה מְזוֹנוֹת וְסִפּוּקִים מֵאוֹתָם פָּנִים פְּנִימִיִּים, וְהַמָּזוֹן שֶׁמּוֹצִיאָה הוּא אוֹתוֹ לֶחֶם, כְּפִי שֶׁאָמַרְנוּ, חֹם הָיָה מִתְקָרֵב, וְחֹם הָיָה מוּסָר מִשָּׁם, וַהֲרֵי פֵּרְשׁוּהוּ, שֶׁכָּתוּב בְּיוֹם הִלָּקְחוֹ, וּמִשּׁוּם שֻׁלְחָן זֶה יֵשׁ לָאָדָם לִשְׁמֹר סוֹדוֹת שֻׁלְחָנוֹ בְּכָל אוֹתָם גְּוָנִים שֶׁאָמַרְנוּ.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (קהלת ט) בְּכָל עֵת יִהְיוּ בְגָדֶיךְ לְבָנִים וְשֶׁמֶן עַל רֹאשְׁךְ אַל יֶחְסָר. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר. אֲבָל בֹּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָאָדָם בְּסוֹד הַחָכְמָה, וְעָשָׂה אוֹתוֹ בְּאֻמָּנוּת רַבָּה, וְנָפַח בְּאַפָּיו נִשְׁמַת חַיִּים כְּדֵי לָדַעַת וּלְהִתְבּוֹנֵן בְּסוֹדוֹת הַחָכְמָה וְלָדַעַת בִּכְבוֹד רִבּוֹנוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. וְלִכְבוֹדִי בְּרָאתִיו דַּוְקָא, וְסוֹד זֶה וְלִכְבוֹדִי בְּרָאתִיו לָמַדְנוּ, שֶׁהֲרֵי הַכָּבוֹד שֶׁלְּמַטָּה סוֹד הַכִּסֵּא הַקָּדוֹשׁ לֹא הִתְתַּקֵּן לְמַעְלָה, אֶלָּא מִתּוֹךְ תִּקּוּן בְּנֵי הָעוֹלָם.</p>\n<p>כְּשֶׁאוֹתָם בְּנֵי אָדָם צַדִּיקִים וַחֲסִידִים וְיוֹדְעִים לְתַקֵּן תִּקּוּנָם, זֶהוּ שֶׁכָּתוּב וְלִכְבוֹדִי בְּרָאתִיו. מִשּׁוּם שֶׁכְּבוֹדִי הַזֶּה לְתַקֵּן אוֹתוֹ בְּעַמּוּדִים חֲזָקִים וּלְקַשְּׁטוֹ בְּתִקּוּן וְקִשּׁוּט שֶׁלְּמַטָּה, בִּשְׁבִיל שֶׁכְּבוֹדִי הַזֶּה יִתְעַלֶּה (בכבוד) בִּזְכוּת הַצַּדִּיקִים שֶׁבָּאָרֶץ.</p>\n<p>בִּשְׁבִיל כָּךְ בְּרָאתִיו, כְּמוֹ הַכָּבוֹד הָעֶלְיוֹן שֶׁבּוֹ הַתִּקּוּנִים הַלָּלוּ. בְּרִיאָה לְצַד שְׂמֹאל, יְצִירָה בְּיָמִין, כְּמוֹ שֶׁנֶּאֱמַר יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ. עֲשִׂיָּה בָּאֶמְצַע, כְמוֹ שֶׁנֶּאֱמַר אֲנִי ה' עֹשֶׂה כָל, וְכָתוּב עוֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע, וְכָתוּב עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, וְעַל זֶה בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו, כְּתִקּוּן עֶלְיוֹן. וְלָכֵן, הוֹאִיל וְאָדָם הוּא בָּאָרֶץ וְיֵשׁ לוֹ לְתַקֵּן אוֹתוֹ כָבוֹד, עָשִׂיתִי בוֹ תִּקּוּנִים שֶׁל כָּבוֹד עֶלְיוֹן, שֶׁיֵּשׁ בּוֹ אַף בְּרִיאָה, וְלָכֵן בְּרָאתִיו.</p>\n<p>בְּאוֹתוֹ כָבוֹד עֶלְיוֹן יֵשׁ בּוֹ יְצִירָה, וְלָכֵן יְצַרְתִּיו. תִּקּוּן זֶה נָתַתִּי בּוֹ בָּאָדָם לִהְיוֹת הוּא בָּאָרֶץ, כְּמוֹ שֶׁאוֹתוֹ כָבוֹד עֶלְיוֹן. בְּאוֹתוֹ כָבוֹד עֶלְיוֹן יֵשׁ בּוֹ עֲשִׂיָּה, וְלָכֵן אַף כָּךְ בָּאָדָם כָּתוּב עֲשִׂיתִיו, שֶׁהוּא יִהְיֶה כְּמוֹ אוֹתוֹ כָבוֹד עֶלְיוֹן שֶׁמְּתַקֵּן וּמְבָרֵךְ אֶת הַכָּבוֹד הַתַּחְתּוֹן.</p>\n<p>מִנַּיִן לָנוּ שֶׁבְּאוֹתוֹ כָבוֹד עֶלְיוֹן יֵשׁ שְׁלֹשֶׁת אֵלֶּה? שֶׁכָּתוּב בּוֹ (ישעיהמה) יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ עֹשֶׂה שָׁלוֹם. יוֹצֵר אוֹר - הֲרֵי יְצִירָה. וּבוֹרֵא חֹשֶׁךְ - הֲרֵי בְּרִיאָה. עֹשֶׂה שָׁלוֹם - הֲרֵי עֲשִׂיָּה. וְזֶהוּ כָּבוֹד עֶלְיוֹן, שֶׁהֲרֵי מְתַקֵּן וּמְבָרֵךְ וּמְסַפֵּק בְּכָל צְרָכָיו אֶת הַכָּבוֹד הַתַּחְתּוֹן.</p>\n<p>כְּמוֹ כֵן בָּרָא אָדָם בָּאָרֶץ שֶׁהוּא כְּמוֹ אוֹתוֹ כָבוֹד עֶלְיוֹן, לְתַקֵּן אֶת הַכָּבוֹד הַזֶּה וּלְהִכָּלֵל מִכָּל הַצְּדָדִים. בַּכָּבוֹד הָעֶלְיוֹן יֵשׁ אֶת שְׁלֹשֶׁת אֵלֶּה - בָּאָדָם לְמַטָּה יֵשׁ אֶת שְׁלֹשֶׁת אֵלֶּה. וּלְהִתְכַּלֵּל אוֹתוֹ כָבוֹד תַּחְתּוֹן מִמַּעְלָה וּמִמַּטָּה, לִהְיוֹת שָׁלֵם בְּכָל הַצְּדָדִים. אַשְׁרֵי הָאִישׁ שֶׁזּוֹכֶה בְמַעֲשָׂיו לִהְיוֹת כְּמוֹ זֶה. וְלָכֵן כָּתוּב, בְּכָל עֵת יִהְיוּ בְגָדֶיךְ לְבָנִים וְשֶׁמֶן עַל רֹאשְׁךְ אַל יֶחְסָר.</p>\n<p>מַה לַּכָּבוֹד הָעֶלְיוֹן לֹא נִמְנָע אוֹתוֹ שֶׁמֶן מִשְׁחַת קֹדֶשׁ מִסּוֹד הָעוֹלָם הַבָּא - אַף כָּךְ לָאָדָם, שֶׁמַּעֲשָׂיו מִתְלַבְּנִים תָּמִיד, אוֹתוֹ שֶׁמֶן מִשְׁחַת קֹדֶשׁ לֹא יִמָּנַע מִמֶּנּוּ תָּמִיד.</p>\n<p>בַּמֶּה זוֹכֶה אָדָם לְהִתְעַדֵּן בְּאוֹתוֹ עִדּוּן עֶלְיוֹן? בְּשֻׁלְחָנוֹ. כְּמוֹ שֶׁהוּא מְעַדֵּן עַל שֻׁלְחָנוֹ נַפְשׁוֹת הָעֲנִיִּים, שֶׁכָּתוּב (ישעיה נח) וְנֶפֶשׁ נַעֲנָה תַּשְׂבִּיעַ, מַה כָּתוּב אַחֲרָיו? אָז תִּתְעַנַּג עַל ה' וְגוֹ', שֶׁאַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַרְוֶה אוֹתוֹ בְּכָל אוֹתָם עִדּוּנִים שֶׁל שֶׁמֶן מִשְׁחַת קֹדֶשׁ הָעֶלְיוֹן שֶׁנִּשְׁפָּע וְנִמְשָׁךְ תָּמִיד לְאוֹתוֹ כָבוֹד עֶלְיוֹן. כָּתוּב וְנֶפֶשׁ נַעֲנָה תַּשְׂבִּיעַ. מַה כָּתוּב אַחֲרָיו? אָז תִּתְעַנַּג עַל ה'.</p>"],[9522011738,"<p>רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהָיָה סוֹחֵר אֶחָד מְחַמֵּר אַחֲרֵיהֶם. אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, יֵשׁ לָנוּ לְהִתְעַסֵּק וּלְהִשְׁתַּדֵּל בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ לְפָנֵינוּ, (שהרי השכינה הולכת לפנינו, שכתוב (תהלים פה) צדק לפניו יהלך) וְלָכֵן זְמַן הוּא לַעֲשׂוֹת לוֹ (לה) תִּקּוּן עִמָּנוּ בְּדֶרֶךְ זוֹ.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (תהלים קיט) עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תּוֹרָתֶךְ. פָּסוּק זֶה נִתְבָּאֵר וּפֵרְשׁוּהוּ הַחֲבֵרִים. אֲבָל עֵת לַעֲשׂוֹת לַה' - בְּכָל זְמַן שֶׁהַתּוֹרָה מִתְקַיֶּמֶת בָּעוֹלָם וּבְנֵי אָדָם מִשְׁתַּדְּלִים בָּהּ, כִּבְיָכוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ בְּמַעֲשֵׂי יָדָיו וְשָׂמֵחַ בְּכָל הָעוֹלָמוֹת, וְשָׁמַיִם וָאָרֶץ עוֹמְדִים בְּקִיּוּמָם. וְלֹא עוֹד, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּץ אֶת כָּל הַפָּמַלְיָה שֶׁלּוֹ וְאוֹמֵר לָהֶם: רְאוּ אֶת הָעָם הַקָּדוֹשׁ שֶׁיֵּשׁ לִי בָּאָרֶץ, שֶׁתּוֹרָתִי מִתְעַטֶּרֶת בִּשְׁבִילָם! רְאוּ מַעֲשֵׂי יָדַי שֶׁאַתֶּם אֲמַרְתֶּם (תהלים ח) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ. וְהֵם, כְּשֶׁהֵם רוֹאִים אֶת שִׂמְחַת רִבּוֹנָם בְּעַמּוֹ, מִיָּד פּוֹתְחִים וְאוֹמְרִים, (שמואל ב ז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ.</p>\n<p>וּבְשָׁעָה שֶׁיִּשְׂרָאֵל מִתְבַּטְּלִים מֵהַתּוֹרָה, כִּבְיָכוֹ\"ל תָּשַׁשׁ כֹּחוֹ, שֶׁכָּתוּב צוּר יְלָדְךְ תֶּשִׁי. וְאָז כָּתוּב, וְכָל צְבָא הַשָּׁמַיִם עֹמְדִים עָלָיו. וְעַל זֶה עֵת לַעֲשׂוֹת לַה'. אוֹתָם (בני העולם) הַצַּדִּיקִים שֶׁנִּשְׁאֲרוּ, יֵשׁ לָהֶם לְשַׁנֵּס מָתְנַיִם וְלַעֲשׂוֹת מַעֲשִׂים כְּשֵׁרִים, כְּדֵי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְחַזֵּק בָּהֶם בַּצַּדִּיקִים וּבַמַּחֲנוֹת וּבַהֲמוֹנִים שֶׁלּוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵפֵרוּ תּוֹרָתֶךְ, וְלֹא מִשְׁתַּדְּלִים בָּהּ בְּנֵי הָעוֹלָם כָּרָאוּי.</p>\n<p>אוֹתוֹ סוֹחֵר שֶׁהָיָה מְחַמֵּר אַחֲרֵיהֶם, אָמַר לָהֶם, בְּבַקָּשָׁה מִכֶּם, שְׁאֵלָה אַחַת בִּרְצוֹנִי לָדַעַת. אָמַר רַבִּי יוֹסֵי, וַדַּאי שֶׁהַדֶּרֶךְ מְתֻקֶּנֶת לְפָנֵינוּ, שְׁאַל אֶת שְׁאֵלָתְךְ! אָמַר, הַפָּסוּק הַזֶּה אִם כָּתוּבּ יֵשׁ לַעֲשׂוֹת אוֹ נַעֲשֶׂה - הָיִיתִי אוֹמֵר כָּךְ. מַה זֶּה עֵת? וְעוֹד, לַעֲשׂוֹת לַה', לִפְנֵי ה' הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לַעֲשׂוֹת לַה'? אָמַר רַבִּי יוֹסֵי, בְּכַמָּה גְוָנִים הַדֶּרֶךְ מְתֻקֶּנֶת לְפָנֵינוּ; אֶחָד - שֶׁהָיִינוּ שְׁנַיִם וְעַכְשָׁו הֲרֵי אָנוּ שְׁלֹשָׁה, וְהַשְּׁכִינָה כְּלוּלָה עִמָּנוּ. וְאֶחָד - שֶׁחָשַׁבְתִּי שֶׁלֹּא הָיִיתָ אֶלָּא כְּמוֹ עֵץ יָבֵשׁ, וְאַתָּה רַעֲנָן כְּמוֹ זַיִת. וְאֶחָד - שֶׁיָּפֶה שָׁאַלְתָּ, וְהוֹאִיל וְהִתְחַלְתָּ אֶת הַדָּבָר - אֱמוֹר.</p>\n<p>פָּתַח וְאָמַר, עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תּוֹרָתֶךְ. עֵת לַעֲשׂוֹת לַה', יֵשׁ עֵת וְיֵשׁ עֵת. (קהלת ג) עֵת לֶאֱהֹב וְעֵת לִשְׂנֹא. עֵת הִיא לְמַעְלָה, שֶׁאוֹתָהּ עֵת הִיא סוֹד הָאֱמוּנָה. וְזוֹ נִקְרֵאת עֵת רָצוֹן, וְזֶהוּ שֶׁהִתְחַיֵּב אָדָם לֶאֱהֹב לַה' תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר (דברים ו) וְאָהַבְתָּ אֶת ה' אֱלֹהֶיךְ, וְלָכֵן עֵת לֶאֱהֹב, זֶהוּ עֵת שֶׁמְּחֻיָּב הָאָדָם לֶאֱהֹב.</p>\n<p>וְיֵשׁ עֵת אַחֶרֶת שֶׁהִיא סוֹד שֶׁל אֱלֹהִים אֲחֵרִים, וּמְחֻיָּב הָאָדָם לִשְׂנֹא אוֹתָהּ וְלֹא יִמְשֹׁךְ לִבּוֹ אַחֲרֶיהָ, וְעַל זֶה עֵת לִשְׂנֹא, וְלָכֵן כָּתוּב (ויקרא טז) דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ.</p>\n<p>(וכאן) בִּזְמַן שֶׁיִּשְׂרָאֵל מִשְׁתַּדְּלִים בַּתּוֹרָה וּבְמִצְווֹת הַתּוֹרָה, אוֹתָהּ עֵת סוֹד הָאֱמוּנָה הַקְּדוֹשָׁה מִתְתַּקֶּנֶת בְּתִקּוּנֶיהָ וּמִתְקַשֶּׁטֶת בִּשְׁלֵמוּת כָּרָאוּי. וּבִזְמַן שֶׁיִּשְׂרָאֵל מִתְבַּטְּלִים מֵהַתּוֹרָה, כִּבְיָכוֹל אוֹתָהּ עֵת אֵינָהּ בְּתִקּוּנֶיהָ, וְלֹא נִמְצֵאת בִּשְׁלֵמוּת וְלֹא בְאוֹר, וְאָז עֵת לַעֲשׂוֹת לַה'.</p>\n<p>מַה זֶּה לַעֲשׂוֹת? כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת. מַה זֶּה לַעֲשׂוֹת? שֶׁנִּשְׁאֲרוּ גוּפוֹת הַשֵּׁדִים כְּשֶׁהִתְקַדֵּשׁ הַיּוֹם וְלֹא נַעֲשׂוּ, וְנִשְׁאֲרוּ לַעֲשׂוֹת רוּחוֹת לְלֹא גוּפִים. אַף כָּאן עֵת לַעֲשׂוֹת - נִשְׁאָר בְּלִי תִקּוּן וּבְלִי שְׁלֵמוּת. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵפֵרוּ תּוֹרָתֶךְ, מִשּׁוּם שֶׁהִתְבַּטְּלוּ יִשְׂרָאֵל לְמַטָּה מִדִּבְרֵי הַתּוֹרָה, מִשּׁוּם שֶׁאוֹתָהּ עֵת כָּךְ עוֹמֶדֶת, אוֹ עוֹלָה אוֹ יוֹרֶדֶת, בִּגְלַל יִשְׂרָאֵל.</p>\n<p>בָּאוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא וּנְשָׁקוּהוּ בְרֹאשׁוֹ. אָמַר רַבִּי יוֹסֵי, וַדַּאי אֵינְךְ כְּדַאי לְחַמֵּר אַחֲרֵינוּ. אַשְׁרֵי הַדֶּרֶךְ הַזּוֹ שֶׁזָּכִינוּ לִשְׁמֹעַ אֶת זֶה. אַשְׁרֵי הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בְּתוֹכוֹ, שֶׁאֲפִלּוּ בֵּין הֶהָרִים נִמְצֵאת שָׁם הַחָכְמָה. יָרְדוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא, וְהָלְכוּ שְׁלָשְׁתָּם בַּדֶּרֶךְ.</p>"],[9522011739,"<p>פָּתַח אוֹתוֹ הַסּוֹחֵר וְאָמַר, (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ ה' עֵת רָצוֹן אֱלֹהִים בְּרָב חַסְדֶּךְ עֲנֵנִי בֶּאֱמֶת יִשְׁעֶךְ. שָׁנִינוּ, אֵימָתַי נִקְרֵאת עֵת רָצוֹן? בְּשָׁעָה שֶׁהַצִּבּוּר מִתְפַּלְלִים. יָפֶה הוּא, וְכָךְ הוּא וַדַּאי. שֶׁהֲרֵי אָז הַצִּבּוּר מְסַדְּרִים וּמְתַקְּנִים אֶת תִּקּוּנָהּ שֶׁל הָעֵת הַ את, וְאָז הוּא עֵת רָצוֹן וְצָרִיךְ לְבַקֵּשׁ בַּקָּשָׁה, שֶׁכָּתוּב אֱלֹהִים בְּרָב חַסְדֶּךְ עֲנֵנִי בֶּאֱמֶת יִשְׁעֶךְ, שֶׁהֲרֵי אָז יֵשׁ לְבַקֵּשׁ אֶת הַבַּקָּשָׁה.</p>\n<p>וַאֲנִי תְפִלָּתִי לְךְ ה', הֲרֵי כָּאן סוֹד הַיִּחוּד. וַאֲנִי - זֶה דָּוִד הַמֶּלֶךְ, הַמָּקוֹם שֶׁנִּקְרָא גְּאֻלָּה. תְפִלָּתִי - זוֹ תְּפִלָּה. וְכָאן הוּא סְמִיכָה לַגְּאֻלָּה, שֶׁהוּא אֶחָד. כְּשֶׁהוּא סוֹמֵךְ גְּאֻלָּה לַתְּפִלָּה, אֲזַי הוּא עֵת רָצוֹן. עֵת רָצוֹן - אַף כָּךְ, כְּלָל הוּא כְּאֶחָד, עֵת אֶחָד, רָצוֹן אֶחָד, נִכְלְלוּ זֶה בָזֶה וְנִהְיוּ אֶחָד. וְדָוִד הַמֶּלֶךְ רָצָה לְיַחֵד בַּפָּסוּק הַזֶּה יִחוּד אֶחָד.</p>\n<p>וְאִם תֹּאמַר, לָמָּה הִתְמַנָּה הַפָּסוּק הַזֶּה בִּתְפִלַּת מִנְחָה שֶׁל שַׁבָּת? נָאֶה הוּא לִהְיוֹת בְּשַׁבָּת בְּאוֹתָהּ תְּפִלַּת מִנְחָה וְלֹא בִּתְפִלַּת חֹל, שֶׁוַּדַּאי אֵין תְּפִלַּת מִנְחָה שֶׁל שַׁבָּת כְּמוֹ חֹל. מִשּׁוּם שֶׁהֲרֵי בַּחֹל, בִּשְׁעַת הַמִּנְחָה, תָּלוּי הַדִּין בָּעוֹלָם וְאֵינוֹ עֵת רָצוֹן, אֲבָל בְּשַׁבָּת כְּשֶׁכָּל הָרֹגֶז הוּסַר וְהַכֹּל נִכְלָל כְּאֶחָד, וְאַף עַל גַּב שֶׁמִּתְעוֹרֵר דִּין, זוֹ הִתְבַּשְּׂמוּת, וְלָכֵן צָרִיךְ פָּסוּק שֶׁל יִחוּד לְיַחֵד אֶת כָּל הַדְּרָגוֹת. שֶׁכְּשֶׁיֵּשׁ יִחוּד, הַדִּין מִתְחַבֵּר וְנִכְלָל בָּרַחֲמִים וְהַכֹּל מִתְבַּסֵּם, וְאָז כָּתוּב עֵת רָצוֹן. עֵת רָצוֹן כּוֹלֵל הַכֹּל כְּאֶחָד. וְהַדִּין מִתְבַּסֵּם בְּאוֹתוֹ זְמַן, וְיֵשׁ שִׂמְחָה בַּכֹּל.</p>\n<p>מֹשֶׁה הִסְתַּלֵּק מִן הָעוֹלָם בְּאוֹתָהּ שְׁעַת תְּפִלַּת מִנְחָה שֶׁל שַׁבָּת, בְּשָׁעָה שֶׁנִּמְצֵאת עֵת רָצוֹן. וּבְאוֹתָהּ שָׁעָה רָצוֹן הָיָה לְמַעְלָה, וְצַעַר לְמַטָּה, וְעַל זֶה נִנְעֲללוּ הַשְּׁעָרִים בְּשַׁבָּת מִשְּׁעַת הַמִּנְחָה וָמַעְלָה. אֵילוּ שְׁעָרִים נִנְעֲלוּ? שַׁעֲרֵי בֵּית הַמִּדְרָשׁ, כְּדֵי לְהַזְכִּיר אֶת מֹשֶׁה הָרוֹעֶה הַנֶּאֱמָן שֶׁהַתּוֹרָה הִתְבַּטְּלָה בִּגְלָלוֹ.</p>\n<p>בְּאוֹתוֹ זְמַן בֵּית מִדְרָשׁוֹ שֶׁל מֹשֶׁה בָּטַל, כָּל שֶׁכֵּן הָאֲחֵרִים. מִי רוֹאֶה אֶת שַׁעֲרֵי בֵּית מִדְרָשׁוֹ שֶׁל מֹשֶׁה שֶׁנִּנְעֲלוּ, וְשֶׁלֹּא יִנָּעֲלוּ כָּל הָאֲחֵרִים?! כְּשֶׁהַתּוֹרָה שֶׁל מֹשֶׁה עֲצוּבָה עָלָיו בְּאוֹתוֹ זְמַן, מִי לֹא עָצוּב?! מִשּׁוּם כָּךְ כָּל שַׁעֲרֵי בֵּית הַמִּדְרָשׁ נִנְעֲלוּ, וְהִצְטָרְכוּ כֻלָּם לְצַדֵּק אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדֶרֶךְ שֶׁבַח, וְהַיְנוּ (תהלים לו) צִדְקָתְךְ כְּהַרְרֵי אֵל.</p>\n<p>שְׁלשָה הֵם שֶׁהִסְתַּלְּקוּ מִן הָעוֹלָם בַּזְּמַן הַזֶּה, וְכֻלָּם כְּלוּלִים בְּמֹשֶׁה. אֶחָד - מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן הָעֶלְיוֹן, וְאֶחָד - יוֹסֵף הַצַּדִּיק, וְאֶחָד - דָּוִד הַמֶּלֶךְ. מִשּׁוּם כָּךְ יֵשׁ כָּאן שְׁלֹשָׁה צִדּוּקֵי דִין. אֶחָד הוּא שֶׁל יוֹסֵף הַצַּדִּיק קוֹדֵם לְכָל אֵלֶּה, וְזֶהוּ צִדְקָתְךְ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה וְגוֹ'. זֶה יוֹסֵף, שֶׁהוּא לְבַדּוֹ כְּהַרְרֵי אֵל, כְּמוֹ כָּל הֶהָרִים הָעֶלְיוֹנִים. וְאֶחָד מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן, וְזֶהוּ שֶׁכָּתוּב (שם עא) וְצִדְקָתְךְ אֱלֹהִים עַד מָרוֹם אֲשֶׁר עָשִׂיתָ גְדלוֹת, מִשּׁוּם שֶׁהוּא נוֹטֵל לְכָל הַצְּדָדִים, יָמִין וּשְׂמֹאל. וְאֶחָד הוּא דָּוִד הַמֶּלֶךְ, וְזֶהוּ שֶׁכָּתוּב (שם קיט) צִדְקָתְךְ צֶדֶק לְעוֹלָם וְתוֹרָתְךְ אֱמֶת. לְעוֹלָם - זֶה דָּוִד הַמֶּלֶךְ.</p>\n<p>אָז מִתְכַּנֵּס הַכֹּל בַּזְּמַן הַזֶּה, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. וְעַל זֶה בַּזְּמַן הַזֶּה נִנְעֲלוּ שַׁעֲרֵי תוֹרָה, וְנִנְעֲלוּ שַׁעֲרֵי כָּל הָעוֹלָם בַּזְּמַן הַזֶּה. בְּשָׁעָה שֶׁמֵּת יוֹסֵף הַצַּדִּיק, יָבְשׁוּ הַמְּקוֹרוֹת וְהַמַּעְיָנוֹת, וְכָל הַשְּׁבָטִים נָפְלוּ בַגָּלוּת. פָּתְחוּ הָעֶלְיוֹנִים וְאָמְרוּ, צִדְקָתְךְ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה וְגוֹ'. בְּשָׁעָה שֶׁמֵּת מֹשֶׁה, נֶחֱשַׁךְ הַשֶּׁמֶשׁ בַּצָּהֳרַיִם, וְנִנְעֲלָה תּוֹרָה שֶׁבִּכְתָב, הָאוֹר שֶׁל הָאַסְפַּקְלַרְיָה הַמְּאִירָה. בְּשָׁעָה שֶׁמֵּת דָּוִד הַמֶּלֶךְ, כָּנְסָה הַלְּבָנָה אֶת אוֹרָהּ, וְתוֹרָה שֶׁבְּעַל פֶּה כָּנְסָה אֶת אוֹרָהּ. וּמֵאוֹתוֹ זְמַן נִגְנְזוּ אוֹרוֹת הַתּוֹרָה, וְהִתְרַבְּתָה הַמַּחֲלֹקֶת עַל הַמִּשְׁנָה, וְהַחֲכָמִים בְּמַחֲלֹקֶת, וְכָל חִזְקֵי הַלֵּב בְּעִרְבּוּבְיָה. וְעַל זֶה אֵין שִׂמְחַת הַתּוֹרָה בְּאוֹתוֹ זְמַן בְּכָל דּוֹרוֹת הָעוֹלָם.</p>\n<p>וּמָהֵן חֻמְרוֹת הַתַּעֲנִיּוֹת שֶׁגָּזְרוּ רַבָּנָן? כְּשֶׁמֵּת פְּלוֹנִי גָּזְרוּ תַעֲנִית, כְּשֶׁהָיָה כָּךְ גָּזְרוּ כָּךְ. (זה שהיה) וּכְשֶׁהָיָה כִּנּוּס יָתֵר שֶׁל שִׂמְחַת הַתּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, בְּאוֹתוֹ זְמַן עַל אַחַת כַּמָּה וְכַמָּה שֶׁצָּרִיךְ לִנְעֹל שַׁעֲרֵי הַתּוֹרָה בְּאוֹתוֹ זְמַן. וְלָכֵן אוֹמְרִים אֶת אֵלּוּ צִדּוּקֵי הַדִּין, כְּמוֹ שֶׁנִּתְבָּאֵר. שָׂמְחוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא וּנְשָׁקוּהוּ בְרֹאשׁוֹ כְּמִקֹּדֶם, וְאָמְרוּ, אַשְׁרֵי חֶלְקֵנוּ בַּדֶּרֶךְ הַזּוֹ!</p>"],[9522011740,"<p>עוֹד פָּתַח וְאָמַר, (קהלת כ) הַחָכְמָה תָּעֹז לֶחָכָם מֵעֲשָׂרָה שַׁלִּיטִים אֲשֶׁר הָיוּ בָּעִיר. הַחָכְמָה תָּעֹז לֶחָכָם - זֶה מֹשֶׁה. כְּשֶׁעָלָה לְהַר סִינַי לְקַבֵּל תּוֹרָה, הִזְדַּעְזְעוּ כָּל אוֹתָם רְקִיעִים וְכָל אוֹתָם מַחֲנוֹת עֶלְיוֹנִים, וְאָמְרוּ לְפָנָיו: רִבּוֹן הָעוֹלָם, וּמַה כָּל טוּב וְכָל שִׂמְחָה שֶׁלָּנוּ אֵינָהּ אֶלָּא בַּתּוֹרָה, וְאַתָּה רוֹצֶה לְהוֹרִידָהּ לָאָרֶץ?! הִתְקַבְּצוּ עַל מֹשֶׁה לְשָׂרְפוֹ בָאֵשׁ. הִתְחַזֵּק מֹשֶׁה וְכוּ', כְּמוֹ שֶׁבֵּאֲרוּהָ הַחֲבֵרִים, שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה וְכוּ'.</p>\n<p>אֲבָל, הַחָכְמָה תָּעֹז לֶחָכָם - כָּל מִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה וּמִשְׁתַּדֵּל בָּהּ לִשְׁמָהּ, מִתְחַזֵּק בַּתּוֹרָה בְּשָׁעָה שֶׁצָּרִיךְ לוֹ תֹּקֶף וְחֹזֶק לְהָגֵן עָלָיו בְּשָׁעָה שֶׁצָּרִיךְ. וְאוֹתוֹ תֹקֶף וְחֹזֶק מֵאֵיזֶה מָקוֹם מִתְחַזֵּק? חָזַר וְאָמַר, מֵעֲשָׂרָה שַׁלִּיטִים. מֵאוֹתָן עֶשֶׂר אֲמִירוֹת שֶׁכְּתוּבוֹת בַּתּוֹרָה, שֶׁהֵם שַׁלִּיטִים עֶלְיוֹנִים, שֶׁאָדָם מִתְחַזֵּק בָּהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. כָּל סוֹדוֹת הָעוֹלָם וְכָל הַמִּצְווֹת וְכָל הַחָכְמָה שֶׁלְּמַעְלָה וּמַטָּה תְּלוּיִים בָּהֶם, וּבָהֶם הַכֹּל נִכְלָל, וְהַכֹּל הוּא בַּתּוֹרָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לִהְיוֹת מִתְחַזֵּק בְּחֹזֶק לָעוֹלָם הַבָּא.</p>\n<p>עָשָׂרָה שַׁלִּיטִים - עֲשָׂרָה מִינֵי חָכְמָה הֵם בַּתּוֹרָה, בַּעֲשָׂרָה שֵׁמוֹת חֲקוּקִים, וְנִכְלְלוּ בְשֵׁם אֶחָד שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת, סוֹדוֹת הָעוֹלָם הַבָּא, בְּאוֹתָם זְהָרִים, שֶׁאֵין הָעַיִן שׁוֹלֶטֶת לִרְאוֹת, וַאֲפִלּוּ בְּשֵׂכֶל לָדַעַת, וּלְהִסְתַּכֵּל בְּאוֹתוֹ עִדּוּן וּתְשׁוּקָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִישׁ לַצַּדִּיקִים לָעוֹלָם הַבָּא, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"],[9522011741,"<p>שֻׁלְחָנוֹ שֶׁל אָדָם מְזַכֶּה אוֹתוֹ לֶאֱכֹל עַל שֻׁלְחָן אַחֵר בָּעִדּוּן שֶׁל אוֹתוֹ הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב ט) כִּי עַל שֻׁלְחַן הַמֶּלֶךְ תָּמִיד הוּא אֹכֵל. וְדָוִד הַמֶּלֶךְ הָיָה אוֹמֵר, תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צֹרְרָי, וְזוֹהִי עֲרִיכַת הַשֻּׁלְחָן בְּאוֹתוֹ עוֹלָם, שֶׁהֲרֵי אָז הוּא עִדּוּן וּתְשׁוּקָה שֶׁהַנְּשָׁמָה נֶהֱנֵית בָּהֶם בָּעוֹלָם הַבָּא.</p>\n<p>וְכִי שֻׁלְחָן יֵשׁ לַנְּשָׁמוֹת בְּאוֹתוֹ עוֹלָם? כֵּן. שֶׁהֲרֵי מָזוֹן וְסִפּוּק וְעִדּוּן אוֹכְלִים בְּאוֹתוֹ עוֹלָם כְּמוֹ שֶׁאוֹכְלִים מַלְאָכִים עֶלְיוֹנִים. וְכִי מַלְאָכִים עֶלְיוֹנִים אוֹכְלִים? כֵּן. כְּמוֹתָם אָכְלוּ יִשְׂרָאֵל בַּמִּדְבָּר. וְאוֹתוֹ מָזוֹן סוֹד הוּא לַטַּל שֶׁשּׁוֹפֵעַ וְנִמְשָׁךְ מִמַּעְלָה מִסּוֹד הָעוֹלָם הַבָּא, וְהוּא מָזוֹן שֶׁל אוֹר שֶׁמֶן מִשְׁחַת קֹדֶשׁ, וְנִשְׁמוֹת הַצַּדִּיקִים נִזּוֹנוֹת מִשָּׁם בְּגַן עֵדֶן וְנֶהֱנוֹת שָׁם, שֶׁהֲרֵי שָׁם נִשְׁמוֹת הַצַּדִּיקִים מִתְלַבְּשׁוֹת בְּגַן עֵדֶן שֶׁל מַטָּה כְּמוֹ שֶׁהָעוֹלָם הַזֶּה.</p>\n<p>וּבְשַׁבָּתוֹת וּבִזְמַנִּים מִתְפַּשְּׁטִים וְעוֹלִים לִרְאוֹת בִּכְבוֹד רִבּוֹנָם וּלְהִתְעַדֵּן בְּעִדּוּן עֶלְיוֹן כָּרָאוּי, שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבוֹא כָל בָּשָׂר לְהִשְׁתַּחֲות לְפָנַי אָמַר ה'. וְכִי כָל בָּשָׂר יָבוֹא? לֹא כָּךְ הָיָה לוֹ לִכְתֹּב, אֶלָּא כָּל רוּחַ אוֹ כָּל נְשָׁמָה. מַהוּ כָל בָּשָׂר? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָאָדָם בָּעוֹלָם הַבָּא כְּמוֹ יְקַר הַכָּבוֹד הָעֶלְיוֹן לְמַעְלָה. אוֹתוֹ כָבוֹד עֶלְיוֹן הוּא רוּחַ לְרוּחַ וּנְשָׁמָה לִנְשָׁמָה, עַד שֶׁמַּגִּיעַ לְמָקוֹם אֶחָד לְמַטָּה שֶׁנִּקְרָא גוּף, וּבָזֶה נִכְנֶסֶת רוּחַ אַחַת שֶׁל מְקוֹר הַחַיִּים שֶׁנִּקְרֵאת כֹּל, בָּזֶה הוּא כָּל הַטּוּב וְכָל הַמָּזוֹן וְכָל סִפּוּק אוֹתוֹ הַגּוּף. וְסוֹד זֶה - (קהלתה) וְיִתְרוֹן אֶרֶץ בַּכֹּל הוּא. (מהו בכל היא, ') הַכֹּל הַזֶּה הוּא רוּחַ לְאוֹתוֹ גוּף.</p>\n<p>כְּמוֹ זֶה אָדָם בָּעוֹלָם הַזֶּה הוּא גוּף, וְרוּחַ שֶׁשּׁוֹלֶטֶת בּוֹ, כְּמוֹ אוֹתָהּ רוּחַ עֶלְיוֹנָה (ששולטת על הגוף שגקרא כל) שֶׁנִּקְרֵאת כֹּל, שֶׁשּׁוֹלֶטֶת עַל הַגּוּף לְמַעְלָה, וְזֶהוּ שֶׁנִּקְרָא כָל בָּשָׂר, וְעַל זֶה כָּתוּב יָבוֹא כָל בָּשָׂר לְהִשְׁתַּחֲות לְפָנַי אָמַר ה'. עַל אוֹתוֹ עִדּוּן כָּתוּב, (ישעיהסד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>שָׂמְחוּ הַחֲבֵרִים בַּדֶּרֶךְ. כְּשֶׁהִגִּיעוּ לְתוֹךְ הַר אֶחָד, אָמַר רַבִּי חִיָּיא לְאוֹתוֹ סוֹחֵר, מַה שִּׁמְךְ? אָמַר לוֹ, חָנָן. אָמַר לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא יְחָנֶּנְךְ וְיִשְׁמַע לְקוֹלְךְ בְּשָׁעָה שֶׁתִּצְטָרֵךְ לוֹ. אָמַר רַבִּי יוֹסֵי, וַדַּאי הֲרֵי נָטָה הַשֶּׁמֶשׁ, וְכֵן אַחַר הָהָר הַזֶּה יֵשׁ כְּפָר אֶחָד עַל שִׁמְךְ, שֶׁנִּקְרָא כְּפַר חָנָן, נָלוּן שָׁם בִּשְׁבִיל כְּבוֹד שִׁמְךְ. כְּשֶׁהִגִּיעוּ לְשָׁם נִכְנְסוּ לְבֵית מְאָרְחֵיהֶם, וְסִדְּרוּ לִפְנֵיהֶם שֻׁלְחָן בְּכַמָּה מִינִים לֶאֱכֹל. אָמַר רַבִּי חִיָּיא, וַדַּאי שֻׁלְחָן זֶה כְּמוֹ הָעוֹלָם הַבָּא, וְיֵשׁ לָנוּ לְהַעֲלוֹת שֻׁלְחָן זֶה וּלְעַטְּרוֹ בְּדִבְרֵי תוֹרָה.</p>"],[9522011742,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (דברים ח) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ עַל הָאָרֶץ הַ בָה אֲשֶׁר נָתַן לָךְ. אִם בְּאֶרֶץ יִשְׂרָאֵל מְבָרְכִים, בְּחוּץ לָאָרֶץ מִנַּיִן לָנוּ, שֶׁהֲרֵי בְּגָוֶן זֶה לֹא צָרִיךְ? אֶלָּא, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, חִלֵּק אֶת הָאָרֶץ. הַיִּשּׁוּב הוּא לְצַד אֶחָד, וְהֶחָרָבָה הִיא לְצַד אַחֵר. חִלֵּק אֶת הַיִּשּׁוּב וְהִקִּיף אֶת הָעוֹלָם סְבִיב נְקֻדָּה אַחַת, וּמִי הִיא? הָאָרֶץ הַקְּדוֹשָׁה. הָאָרֶץ הַקְּדוֹשָׁה הִיא מֶרְכַּז הָעוֹלָם, וּבְאֶמְצַע הָאָרֶץ הַקְּדוֹשָׁה הִיא יְרוּשָׁלַיִם. אֶמְצַע יְרוּשָׁלַיִם הוּא בֵּית קֹדֶשׁ הַקְּדָשִׁים. וְכָל הַטּוּב וְכָל הַמָּזוֹן שֶׁל כָּל הַיִּשּׁוּב יוֹרֵד לְשָׁם מִלְמַעְלָה, וְאֵין לְךְ מָקוֹם בְּכָל הַיִּשּׁוּב שֶׁלֹּא נִזּוֹן מִשָּׁם.</p>\n<p>חִלֵּק אֶת הֶחָרָבָה, וְלֹא נִמְצָא מָקוֹם חָרֵב קָשֶׁה בְּכָל הָעוֹלָם פְּרָט לְאוֹתוֹ מִדְבָּר, שֶׁשָּׁבְרוּ יִשְׂרָאֵל כֹּחוֹ וְתָקְפּוֹ אַרְבָּעִים שָׁנָה, כְּמוֹ שֶׁנֶּאֱמַר (דברים ח) הַמּוֹלִיכֲךְ בַּמִּדְבָּר הַגָּדל וְהַנּוֹרָא. בְּאוֹתוֹ מִדְבָּר שׁוֹלֵט הַצַּד הָאַחֵר, וּבְעַל כָּרְחוֹ הָלְכוּ עָלָיו יִשְׂרָאֵל וְשָׁבְרוּ כֹחוֹ אַרְבָּעִים שָׁנִים. וְאִם יִשְׂרָאֵל נִמְצְאוּ צַדִּיקִים בְּאוֹתָם אַרְבָּעִים שָׁנִים, הָיָה מָעֳבָר אוֹתוֹ הַצַּד הָאַחֵר מִן הָעוֹלָם. וּמִשֶּׁהִרְגִּיזוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל אוֹתָן פְּעָמִים, הִתְחַזֵק אוֹתוֹ הַצַּד הָאַחֵר, וְנָפְלוּ כֻלָּם תַּחַת רְשׁוּתוֹ.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי מֹשֶׁה שֶׁעָלָה עַל כָּל בְּנֵי הָעוֹלָם אֵיךְ מֵת שָׁם? - לֹא כָּךְ, שֶׁהֲרֵי מֹשֶׁה הַנֶּאֱמָן לֹא הָיָה בִּרְשׁוּתוֹ אֶלָּא בְּהַר הָעֲבָרִים. מַה זֶּה הָעֲבָרִים? מַחֲלֹקֶת. שֶׁנֶּחְלְקוּ עָלָיו שַׁלִּיטִים עֶלְיוֹנִים שֶׁלְּמַעְלָה, וְלֹא נִמְסַר בִּידֵי מְמֻנֶּה וְשַׁלִּיט אַחֵר, וְנִשְׁאַר כָּךְ, עַד שֶׁבָּא מֹשֶׁה הָעֶבֶד הַנֶּאֱמָן וְשָׁלַט עָלָיו, וְנִקְבַּר שָׁם, וְלֹא הִתְעַסֵּק בִּקְבוּרָתוֹ - רַק הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, שֶׁכָּתוּב (שם לד) וַיִּקְבֹּר אֹתוֹ בַגַּי.</p>\n<p>וַיִּקְבֹּר אֹתוֹ, מִי? אוֹתוֹ שֶׁכָּתוּב בּוֹ בְּדֶרֶךְ נִסְתָּר (שמות כד) וְאֶל מֹשֶׁה אָמַר, וְלֹא כָתוּב מִי הוּא. וַיִּקְרָא אֶל מֹשֶׁה, וְלֹא כָתוּב מִי הוּא. אַף כָּאן וַיִּקְבֹּר אֹתוֹ, וְלֹא כָתוּב מִי הוּא, אֶלָּא וַדַּאי מָקוֹם זֶה יָדוּעַ הוּא לַחֲבֵרִים. וְלָכֵן בְּאוֹתוֹ הַר לֹא שָׁלַט עָלָיו - רַק מֹשֶׁה לְבַדּוֹ, וְהוּא נִקְבַּר שָׁם. וּבִשְׁבִיל לְהוֹדִיעַ לְכָל הַדּוֹרוֹת הָאֲחֵרִים שֶׁל הָעוֹלָם שֶׁאוֹתָם מֵתֵי מִדְבָּר יָקוּמוּ, אוֹתוֹ הָרוֹעֶה שֶׁלָּהֶם הֻשְׁרָה בְתוֹכָם, לִהְיוֹת כֻּלָּם בְּהִתְעוֹרְרוּת הָעֲמִידָה לָעוֹלָם הַבָּא.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ שֶׁאוֹתוֹ מִדְבָּר הוּא תֹּקֶף וְכֹחַ הַצַּד הָאַחֵר, אֵיךְ צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אוֹתוֹ שָׂעִיר לְשָׁלְחוֹ לְהַר אַחֵר שֶׁנִּקְרָא עֲזָאזֵל? הָיָה לָהֶם לְשָׁלְחוֹ לְאוֹתוֹ הַר שֶׁהָלְכוּ בוֹ יִשְׂרָאֵל בַּמִּדְבָּר. אֶלָּא, כֵּיוָן שֶׁהֲרֵי הָלְכוּ בוֹ יִשְׂרָאֵל אַרְבָּעִים שָׁנִים, הֲרֵי נִשְׁבַּר תָּקְפּוֹ. וְתָקְפּוֹ הִתְחַזֵּק בְּמָקוֹם שֶׁלֹּא עָבַר בּוֹ אִישׁ שָׁם לְעוֹלָמִים, וּבְאוֹתוֹ הַר הֲרֵי הָיָה דִּיּוּרָם שֶׁל יִשְׂרָאֵל שָׁם אַרְבָּעִים שָׁנִים.</p>\n<p>אֲבָל בַּשָּׂעִיר הַזֶּה, אוֹתוֹ מָקוֹם הוּא סֶלַע חָזָק עֶלְיוֹן, וְתַחַת עֹמֶק אוֹתוֹ סֶלַע, שֶׁאִישׁ לֹא (אינו יכול להכנס לשם) נִכְנָס שָׁם, הוּא שׁוֹלֵט יוֹתֵר לֶאֱכֹל טַרְפּוֹ, כְּדֵי שֶׁיַּעֲבֹר מֵעַל יִשְׂרָאֵל וְלֹא יִמָּצֵא לָהֶם מְקַטְרֵג עֲלֵיהֶם בַּיִּשּׁוּב.</p>\n<p>שִׁלְטוֹנוֹ שֶׁל סוֹד הָאֱמוּנָה תּוֹךְ מֶרְכַּז הַנְּקֻדָּה שֶׁל כָּל (העולם) הָאָרֶץ הַקְּדוֹשָׁה בְּבֵית קֹדֶשׁ הַקְּדָשִׁים. וְאַף עַל גַּב שֶׁעַכְשָׁו אֵינוֹ בְקִיּוּם, בִּזְכוּתוֹ נִזּוֹן כָּל הָעוֹלָם, וּמָזוֹן וְסִפּוּק יוֹצְאִים מִשָּׁם לַכֹּל בְּכָל מָקוֹם שֶׁל צַד הַיִּשּׁוּב. וְלָכֵן, אַף עַל גַּב שֶׁיִּשְׂרָאֵל עַכְשָׁו מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, עִם כָּל זֶה, מִכֹּחַ וּזְכוּת הָאָרֶץ נִמְצָא מָזוֹן וְסִפּוּק לְכָל הָעוֹלָם. וְעַל זֶה כָּתוּב (דברים ח) וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ עַל הָאָרֶץ הַטֹּבָה אֲשֶׁר נָתַן לָךְ. עַל הָאָרֶץ הַטֹּבָה וַדַּאי, שֶׁהֲרֵי בִּשְׁבִילָהּ נִמְצָא מָזוֹן וְסִפּוּק לָעוֹלָם.</p>\n<p>מִי שֶׁמִּתְעַדֵּן עַל שֻׁלְחָנוֹ וּמִתְעַנֵּג בְּאוֹתָם מַאֲכָלִים, יֵשׁ לוֹ לְהַזְכִּיר וְלִדְאֹג עַל קְדֻשַּׁת הָאָרֶץ הַקְּדוֹשָׁה וְעַל הֵיכַל הַמֶּלֶךְ שֶׁחָרַב. וּבִשְׁבִיל אוֹתוֹ עֶצֶב שֶׁהוּא מִתְעַצֵּב עַל שֻׁלְחָנוֹ בְּאוֹתָהּ שִׂמְחָה וּמִשְׁתֶּה שֶׁל שָׁם, הַקָּדוֹשׁ בָּרוּךְ הוּא חוֹשֵׁב עָלָיו כְּאִלּוּ בָּנָה אֶת בֵּיתוֹ וּבָנָה אֶת כָּל חָרְבוֹת בֵּית הַמִּקְדָּשׁ. אַשְׁרֵי חֶלְקוֹ!</p>"],[9522011743,"<p>כּוֹס שֶׁל בְּרָכָה אֵינוֹ אֶלָּא בִּשְׁלֹשָׁה, מִשּׁוּם שֶׁהֲרֵי מִסּוֹד שֶׁל שְׁלֹשֶׁת הָאָבוֹת מִתְבָּרֵךְ, וְעַל זֶה לֹא צָרִיךְ כּוֹס אֶלָּא בִּשְׁלֹשָׁה. כּוֹס שֶׁל בְּרָכָה צָרִיךְ לָתֵת אוֹתָהּ בְּיָמִין וּבִשְׂמֹאל וּלְקַבְּלָהּ בֵּין שְׁנֵיהֶם, מִשּׁוּם שֶׁנִּתֶּנֶת בֵּין יָמִין וּשְׂמֹאל. אַחַר כָּךְ יַשְׁאִיר אוֹתָהּ בְּיָמִין, שֶׁהֲרֵי מִשָּׁם מִתְבָּרֵךְ.</p>\n<p>עָשָׂרָה דְבָרִים נֶאֶמְרוּ בְּכוֹס שֶׁל בְּרָכָה, וְכֻלָּם הֵם כָּרָאוּי, מִשּׁוּם שֶׁתִּקּוּנֵי כּוֹס שֶׁל בְּרָכָה הֵם עֲשָׂרָה, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. כּוֹס שֶׁל בְּרָכָה צָרִיךְ לְהַשְׁגִּיחַ בּוֹ בָּעַיִן, מִשּׁוּם שֶׁכָּתוּב (שם יא) עֵינֵי ה' אֱלֹהֶיךְ בָּהּ, וְלֹא צָרִיךְ לְהִשָּׁכַח מֵהָעַיִן, אֶלָּא לְהַשְׁגִּיחַ בּוֹ.</p>\n<p>כּוֹס שֶׁל בְּרָכָה מִתְבָּרֵךְ בְּאוֹתָהּ בְּרָכָה שֶׁמְּבָרֵךְ הָאָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם (כך) שֶׁהוּא סוֹד הָאֱמוּנָה, וְצָרִיךְ לְשָׁמְרוֹ בִּשְׁמִירָה עֶלְיוֹנָה, כְּמִי שֶׁהוּא חֲשִׁיבוּת הַמֶּלֶךְ, שֶׁהֲרֵי בִּשְׁבִילוֹ נִתְבָּרֵךְ שֻׁלְחָנוֹ בִּשְׁעַת בִּרְכַּת הַמָּזוֹן שֶׁאוֹתוֹ אָדָם מְבָרֵךְ.</p>\n<p>צָרִיךָ שֶׁשֻּׁלְחָנוֹ לֹא יִהְיֶה רֵיקָם, שֶׁהֲרֵי אֵין בְּרָכָה מְצוּיָה עַל שֻׁלְחָן רֵיק, כְמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (מלכים ב ד) הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת וְגוֹ'. וְלָכֵן שֻׁלְחָן לֹא צָרִיךְ לְהֵרָאוֹת רֵיקָם, שֶׁהֲרֵי הַבְּרָכוֹת הָעֶלְיוֹנוֹת לֹא שׁוֹרוֹת אֶלָּא בְּמָקוֹם שָׁלֵם. וְסוֹד זֶה - וּבְלֵב כָּל חֲכַם לֵב נָתַתִּי חָכְמָה, וְכָתוּב (דניאל ב) נוֹתֵן חָכְמָה לַחֲכָמִים. וְעַל סוֹד זֶה שֻׁלְחָן שֶׁל לֶחֶם הַפָּנִים, שֶׁכָּתוּב (שמות כח) וְנָתַתָּ עַל הַשֻּׁלְחָן לֶחֶם פָּנִים לְפָנַי תָּמִיד.</p>"],[9522011744,"<p>תַּנָּאִים וְאָמוֹרָאִים, הִתְכַּנְּסוּ כֻלְּכֶם, שֶׁהֲרֵי הִגִּיעָה הַשָּׁעָה לְתַקֵּן בָּהּ כְּלֵי הַמֶּלֶךְ, (להזהיר ולהתתקן) לְהָאִיר לְהִתְתַּקֵּן לְפָנָיו, שֶׁהֵן: מִשְׁכָּן, מְנוֹרָה, שֻׁלְחָן, מִזְבֵּחַ, כִּיּוֹר וְכַנּוֹ, אָרוֹן וְכַפֹּרֶת וּכְרוּבִים. וְהַכֹּל בְּשֶׁקֶל. וּמִשּׁוּם כָּךְ צִוָּה אֶת יִשְׂרָאֵל, זֶה יִתְּנוּ.</p>\n<p>עָמַד תַּנָּא אֶחָד וְאָמַר, רוֹעֶה הַנֶּאֱמָן, וַדַּאי כָּךְ הוּא, וְאוֹתְךְ צִוָּה לַעֲשׂוֹת אֶת כֻּלָּם, זֶהוּ שֶׁכָּתוּב וְעָשִׂיתָ מְנוֹרָת. וְעָשִׂיתָ שֻׁלְחָן. וְכָךְ בְּהַכֹּל, וּרְאֵה וַעֲשֵׂה, וּמֵהַכֹּל לֹא הִתְקַשָּׁה לְךְ לַעֲשׂוֹת אֶלָּא שְׁלֹשָׁה דְבָרִים רְשׁוּמִים בְּאוֹתִיּוֹת שִׁמְךְ: מְ\"נוֹרָה, שְׁ\"קָלִים, הַ\"חֹדֶשׁ. לָמָּה הִתְקַשּׁוּ לְךְ?</p>\n<p>אָמַר לוֹ, זָקֵן זָקֵן, אַתֶּם מוֹצִיאִים קֻשְׁיָה זוֹ שֶׁהִתְקַשְּׁתָה לִי מִן מִקְשָׁה תֵּיעָשֶׂה הַמְּנוֹרָה. וַדַּאי שֶׁהַכְּלִי שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא שְׁכִינָה, שֶׁהִיא כְּלִי לְשַׁמֵּשׁ אֶת בַּעְלָהּ, הִיא הַמְּנוֹרָה שֶׁלּוֹ שֶׁנֶּאֱמַר בָּהּ (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ, שֶׁהֵם: הַגְּדֻלָּה, וְהַגְּבוּרָה, וְהַתִּפְאֶרֶת, וְהַנֵּצַח, וְהַהוֹד, יְסוֹד וּמַלְכוּת. בְּשֶׁבַע כְּלוּלָה.</p>\n<p>מִשֶּׁבַע הַדְּרָגוֹת הַלָּלוּ - שְׁלֹשֶׁת קְנֵי הַמְּנוֹרָה מִצִּדָּהּ הָאֶחָד, גּוּף וּשְׁתֵּי זְרוֹעוֹת הַמֶּלֶךְ, הוּא נֵר מִצְוָה לְהָאִיר בָּהֶם. וּשְׁלֹשֶׁת קְנֵי הַמְּנוֹרָה מִצִּדָּהּ הַשֵּׁנִי, הֵם שְׁתֵּי שׁוֹקַיִם וּבְרִית, וְהוּא נֵר מַעֲרָבִי לְהָאִיר בָּהֶם. מְנוֹרַת הַמֶּלֶךְ נִקְרֵאת, וְהִיא נֵר לְהָאִיר בּוֹ נֵר מִצְוָה, שֶׁנֶּאֱמַר בּוֹ מִצְוַת ה' בָּרָה מְאִירַת עֵינָיִם.</p>\n<p>וּמִי רֹאשׁ הַמְּנוֹרָה? בִּינָה, ה' הָעֶלְיוֹנָה, שֶׁיֵּשׁ לָהּ שְׁלֹשָׁה קָנִים, בִּדְיוֹקָן זֶה ה', שָׁלֹשׁ וָוִי\"ם, שֶׁהֵם שְׁלֹשֶׁת הָאָבוֹת. ה' הַשְּׁנִיָּה, שְׁלֹשָׁה קָנִים, בִּדְיוֹקָן זֶה ה', (שלש ווים) שֶׁהֵם נֵצַח הוֹד יְסוֹד. ו' הַמְּנוֹרָה שֶׁל הָאֶמְצַע בֶּן יָ\"הּ. עַל שְׁמוֹ נִקְרֵאת בִּינָה. הוּא כּוֹלֵל ו' קָנִים לְמַטָּה בְּחֶשְׁבּוֹן ו', בְּשֵׁשֶׁת הַקָּנִים שֶׁלּוֹ.</p>\n<p>י' אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ (משלי יב). כֶּתֶר שֶׁל סֵפֶר תּוֹרָה כְּצוּרַת ז' מִצַּד שֶׁל הָעוֹלָם הַבָּא אֵינָהּ כְּלִי אֵלָיו, וְלֹא מְשַׁמֶּשֶׁת לוֹ אֶלָּא עֲטָרָה עַל רֹאשׁוֹ. אֲבָל בָּעוֹלָם הַזֶּה הוּא כְּמוֹ זֶה הוה\"י, הוּא כְּלִי תַּחְתָּיו. הַשִּׁמּוּשׁ שֶׁלּוֹ בְּכָל סְפִירָה שֶׁלּוֹ, בְּכָל אֵיבָר שֶׁלּוֹ, בְּכָל מִדָּה שֶׁלּוֹ.</p>\n<p>וּמִשּׁוּם זֶה י' זוֹ לִפְעָמִים הִיא תַּחְתָּיו, לִפְעָמִים עַל רֹאשׁוֹ, לִפְעָמִים בָּאֶמְצַע. עַל רֹאשׁוֹ יְהֹוָ\"ה, (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְזֶה (ויקרא כד) לְהַעֲלֹת נֵר תָּמִיד, שֶׁהוּא י' עַל הו\"ה מִצַּד הַמְּנוֹרָה. בָּאֶמְצַע מַחֲצִית הַשֶּׁקֶל, זֶהוּ שֶׁכָּתוּב (שמות ל) זֶה יִתְּנוּ, כְּמוֹ זֶה הוי\"ה. בַּסּוֹף, בַּמִּשְׁכָּן, כְּמוֹ זֶה הוה\"י, חָמֵשׁ אַמּוֹת אֹרֶךְ מִצַּד הַה' הָעֶלְיוֹנָה, וְחָמֵשׁ אַמּוֹת רֹחַב מִצַּד הַה' הַתַּחְתּוֹנָה, וְאַמָּה ו'. וַחֲצִי הָאַמָּה י'. וְהַכֹּל נִרְמָז בָּאוֹת ו'.</p>\n<p>וְזְהִוּ סוֹד (ישעיה מד) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אֱלֹהִים, שֶׁנִּרְמָז בַּשֵּׁם הַזֶּה יוֹ\"ד הֵ\"י וָי\"ו הֵ\"י, וְכָל שֵׁם שֶׁשּׁוֹלֵט ה' עַל י' הוּא נְקֵבָה מִצַּד הַשְּׂמֹאל. וְאַף עַל גַּב שֶׁמִּצִּדָּהּ שֶׁל הָאוֹת י' הִיא בָּרֹאשׁ, אַחַר שֶׁבִּשְׁנֵי הֵהִי\"ן הִיא בַּסּוֹף, כְּמוֹ זֶה הֵ\"י הֵ\"י נִדּוֹן לָרֹב, וְהִיא נְקֵבָה. אֶלָּא י' עַל ה' (ו') הוּא כֶּתֶר, תַּחַת ה' - שִׁמּוּשׁ. כָּל שֶׁכֵּן תַּחַת ו'.</p>\n<p>וּמִשּׁוּם שֶׁלֹּא עָשִׂינוּ קִצּוּץ וּפֵרוּד בַּיִּחוּד הָעֶלְיוֹן, שֶׁהַכֹּל יִחוּד אֶחָד, הִתְקַשָּׁה לִי לַעֲשׂוֹת. (או כתר, או אמצעי, או שמוש) וְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיּוֹדֵעַ כָּל הַמַּחֲשָׁבוֹת, אָמַר, אַחַר שֶׁזֶּה הִתְכַּוֵּן לְטוֹב, שֶׁלֹּא לַעֲשׂוֹת קִבּוּץ וּפֵרוּד, (שמות כה) תֵּ\"יעָשֶׂה הַמְּנ\"וֹרָה, תֵּעָשֶׂה מֵעַצְמָהּ כְּמוֹ הַשְּׁכִינָה, תֵּעָשֶׂה מֵעַצְמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלִי פֵרוּד. שְׁאָר הַכֵּלִים שֶׁבָּהֶם הִיא שְׁכִינָה שִׁמּוּשׁ, (שם לז) וַיַּעַשׂ בְּצַלְאֵל.</p>\n<p>וּבְכָל מָקוֹם שֶׁשְּׁכִינָה תַּחְתּוֹנָה, הִיא עֲטָרָה שֶׁל הָעַמּוּד הָאֶמְצָעִי, כְּשֶׁנִּטֶּלֶת מִבִּינָה, שֶׁהִיא הָעוֹלָם הַבָּא, וַדַּאי אֵין הַכָּרָה לָאָדָם בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְלֹא בְּכָל מִדּוֹתָיו, עַד שֶׁיִּכָּנֵס לַשַּׁעַר הַזֶּה, שֶׁנֶּאֱמַר עָלָיו (תהלים קיח) זֶה הַשַּׁעַר לַה'.</p>\n<p>בְּאוֹת ל', שֶׁהִיא יי (ייי) הִיא כְּלוּלָה מִכָּל סְפִירָה וּמִכָּל הָאוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת, מְפֹרָשִׁים וְנִסְתָּרִים. הִיא נְקֻדָּה בְּכָל אוֹת וָאוֹת, שִׁמּוּשׁ תַּחַת בַּעְלָהּ. וְהִיא עֲטָרָה עַל רֹאשׁוֹ, מֵהַצַּד שֶׁלָּהּ שֶׁל הַטְּעָמִים, כְּמוֹ סֶגּוֹל נְקוּדָה תַּחַת בִּרְכֵּי הַמֶּלֶךְ, (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי. וְהִיא בָּאֶמְצַע עִמּוֹ, מַחֲצִית הַשֶּׁקֶל, בְּשׁוּרֻק. וְהִיא עֲטָרָה עַל רֹאשׁוֹ מִצַּד הַסֶּגוֹלְתָּא.</p>\n<p>זַרְקָא מַקַּף שׁוֹפָר הוֹלֵךְ סֶגוֹלְתָּא. בְּאוֹתוֹ זְמַן הִיא כֶּתֶר עַל רֹאשׁ הַמֶּלֶךְ, כֶּתֶר יִתְּנוּ לְךְ ה' אֱלֹהֵינוּ. הִיא יְדוּעָה בְּאוֹתוֹ שֶׁנֶּאֱמַר בּוֹ, בַּמֻּפְלָא מִמְּךְ אַל תִּדְר!שׁ וּבַמְכֻסֶּה מִמְּךְ אַל תַּחְקֹר. שֶׁבָּהּ הוּא נוֹדָע שֶׁהוּא רִאשׁוֹן לְמַעְלָה בְּכֶתֶר, שֶׁהַיְנוּ סֶגוֹלְתָּא, וְהוּא אַחֲרוֹן, בְּסֶגּוֹל. וּמִבַּלְעָדָיו אֵין אֱלֹהִים, בְּשׁוּרֻק. וְהַכֹּל בָּהּ נוֹדָע (למטה).</p>\n<p>מִי שֶׁנִּדְבָּק בָּהּ לְמַטָּה, הִיא מַעֲלָה אוֹתוֹ לְמַעְלָה. וּמִי שֶׁרוֹצֶה לַעֲלוֹת עָלֶיהָ לְהַשִּׂיג לְמַעְלָה מִמֶּנָּה, הִיא מַשְׁפִּילָה אוֹתוֹ לְמַטָּה מִמֶּנָּה וְאֵין לוֹ חֵלֶק בָּהּ. וּמִשּׁוּם שֶׁיַּעֲקֹב נוֹדָע בָּהּ, לִמֵּד אוֹתָהּ לְבָנָיו, וְצִוָּה שֶׁלֹּא יְבַקְשׁוּ לַעֲלוֹת לְדַרְגָּה לְמַעְלָה מִמֶּנָּה, שֶׁהִיא הַכֹּל - מַעְלָה וּמַטָּה וְאֶמְצַע. זֶהוּ שֶׁכָּתוּב (בראשית מט) וְזאת אֲשֶׁר דִּבֶּר לָהֶם אֲבִיהֶם.</p>\n<p>נָבִיא שֶׁהָיָה מַכִּיר אוֹתָהּ, צָוַח וְאָמַר לְבַעֲלֵי תוֹרָה חֲכָמִים בַּתּוֹרָה וַעֲשִׁירִים בָּהּ וּשְׂמֵחִים בְּחֶלְקָם. צָוַח אֲלֵיהֶם וְאָמַר, (ירמיה ט) כֹּה אָמַר ה' אַל יִתְהַלֵּל וְגוֹ', כִּי אִם בְּזאת יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל וְיָדעַ אוֹתִי. דָּוִד שֶׁהָיָה מַכִּיר אוֹתָהּ אָמַר, (תהלים כו) אִם תַּחֲנֶה עָלַי מַחֲנֶה וְגוֹ', בְּזֹאת אֲנִי בוֹטֵחַ. וְיִרְמְיָה רָאָה אֶת אֹרֶךְ הַגָּלוּת, וְסָמָאֵ\"ל (בא) וְהַנָּחָשׁ, וְכָל הַמְמֻנִּים שֶׁל שִׁבְעִים הָאֻמּוֹת בְּרִבּוֹא רְבָבוֹת שֶׁיּוֹרְדִים עַל יִשְׂרָאֵל, וְרָאָה אֶת הַפָּסוּק הַזֶּה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, (ויקרא כו) וְאַף גַּם זאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'. אָמַר הַנָּבִיא, (איכה ג) זֹאת אָשִׁיב אֶל לִבִּי עַל כֵּן אוֹחִיל. וַאֲשֶׁר לֹא שָׁת לִבּוֹ גַּם לָזֹאת, עָלָיו נֶאֱמַר (תהלים צב) וּכְסִיל לֹא יָבִין אֶת זאת. (דברים לג) וְזאת לִיהוּדָה וַיּאמַר שְׁמַע ה' קוֹל יְהוּדָה. מִשּׁוּם שֶׁשָּׁמַר מַה שֶּׁצִּוָּהוּ אָבִיו, זָכָה לַמַּלְכוּת. וְדָוִד בִּשְׁבִילָהּ עָלָה לַמַּלְכוּת, שֶׁטָּרַח עָלֶיהָ כָּל יָמָיו.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, עָלֶיהָ נֶאֱמַר (שם ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה וְגוֹ'. בָּהּ הִזְהַרְתָּ אֶת יִשְׂרָאֵל בִּשְׁעַת מִיתָתְךְ, בָּהּ בֵּרַכְתָּ אֶת יִשְׂרָאֵל בְּכָל שֵׁבֶט וְשֵׁבֶט. זֶהוּ שֶׁכָּתוּב (שם לג) וְזֹאת הַבְּרָכָה אֲשֶׁר בֵּרַךְ מֹשֶׁה וְגוֹ'. וּמִשּׁוּם כָּךְ פֵּרְשׁוּהָ הַחֲבֵרִים בַּעֲלֵי הַמִּשְׁנָה, שֶׁכָּתוּב (במדבר יט) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל, וְאָמְרוּ עָלֶיהָ, מַה זֶּה כִּי יָמוּת? אֶלָּא אֵין הַתּוֹרָה מִתְקַיֶּמֶת אֶלָּא בְּמִי שֶׁמֵּמִית עַצְמוֹ עָלֶיהָ, וְאֵין מִיתָה אֶלָּא עֹנִי, שֶׁעָנִי חָשׁוּב כַּמֵּת.</p>\n<p>שֶׁהוּא קָרְבַּן עוֹלֶה וְיוֹרֵד. מִצַּד שֶׁל עָשִׁיר עוֹלֶה וַדַּאי, שֶׁמִּתְעַלֶּה עָלָיו. שֶׁכָּל הָעֲשִׁירִים, כָּל טוֹב שֶׁהֵם עוֹשִׂים, כֻּלָּם (רבם) לְזַכּוֹתָם לָעוֹלָם הַבָּא, וְשָׁם הִיא כֶּתֶר עַל רֹאשָׁם. הַבֵּינוֹנִי שֶׁעוֹבֵד כְּדֵי לִזְכּוֹת בִּשְׁנֵי עוֹלָמוֹת, הוּא מַחֲצִית הַשֶּׁקֶל עִמּוֹ בָּעוֹלָם הַבָּא, כְּמוֹ הַמַּצָּב שֶׁנֶּחֱלֶקֶת, חֶצְיָהּ תַּחַת הַמַּפָּה לָאֲפִיקוֹמָן אַחַר הַסְּעוּדָה, וְחֶצְיָהּ לַמִּצְוָה קֹדֶם סְעוּדָה. וּמִצַּד זֶה נֶאֱמַר בְּאֶסְתֵּר, (אסתר ה) מַה שְּׁאֵלָתֵךְ וְיִנָּתֶן לָךְ וּמַה בַּקָּשָׁתֵךְ עַד חֲצִי הַמַּלְכוּת וְתֵעָשׂ.</p>\n<p>אֲבָל מִי שֶׁהוּא עָנִי, שֶׁמֵּמִית אֶת עַצְמוֹ בִּשְׁבִילָהּ, כְּמוֹ שֶׁאַתָּה הָרוֹעֶה הַנֶּאֱמָן, הִיא קָרְבַּן עוֹלֶה וְיוֹרֵד תַּחְתֶּיךְ, וְלָמָּה? כִּי מִי שֶׁמַּשְׁפִּיל אֶת עַצְמוֹ בִּשְׁבִיל שְׁכִינָתוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד עָלָיו. וְזֶהוּ שֶׁאָמַר דָּוִד, (תהלים קלח) כִּי רָם ה' וְשָׁפָל יִרְאֶה. וְהַנָּבִיא אָמַר, (ישעיהנג) כִּי כֹה אָמַר רָם וְנִשָּׂא שֹׁכֵן עַד וְקָדוֹשׁ שְׁמוֹ וְגוֹ', וְאֶת דַּכָּא וּשְׁפַל רוּחַ. שֶׁאַף עַל גַּב שֶׁאֲנִי מָרוֹם וְקָדוֹשׁ אֶשְׁכּוֹן, בִּשְׁבִיל אוֹתוֹ שֶׁנַּעֲשֶׂה דַּכָּא וּשְׁפַל רוּחַ בַּעֲבוּר שְׁכִינָתִי לְהַעֲלוֹתָהּ מִשִּׁפְלוּתָהּ עֲטָרָה לְרֹאשׁוֹ, אֲנִי אֵרֵד לָדוּר עִמּוֹ. וְאַחַר שֶׁבַּעַל הַשְּׁכִינָה יוֹרֵד עַל הָאָדָם, הִיא יוֹרֶדֶת מֵעַל רֹאשׁוֹ, וְנוֹתֶנֶת הַמָּקוֹם שֶׁל הָרֹאשׁ לְבַעְלָהּ וְיוֹרֶדֶת לְרַגְלֵי הַמֶּלֶךְ. וְסוֹד הַדָּבָר - (ישעיה סו)</p>\n<p>הַשָּׁמַיִם כִּסְאִי וְהָאָרֶץ הֲדם רַגְלָי. שֶׁמִּיּוֹם שֶׁיּוֹרֵשׁ אָדָם נְשָׁמָה שֶׁכְּלוּלָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, מֵאוֹתָהּ שָׁעָה נִקְרָא בֵּן. אָמַר תַּנָּא אֶחָד, וְכִי מֵאוֹתוֹ יוֹם שֶׁיּוֹרֵשׁ אָדָם נְשָׁמָה כְּלוּלָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ יִקָּרֵא בֵּן? מִנַּיִן לָנוּ? מֵהַפָּסוּק הַזֶּה שֶׁאָמַר דָּוד בְּסֵפֶר תְּהִלִּים, (תהלים ב) אֲסַפְּרָה אֶל חֹק ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ.</p>\n<p>אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה הַנֶּאֱמָן, מַה זֶּה הַיּוֹם יְלִדְתִּיךְ? אֶלָּא בִּשְׁבִילְךְ אָמַר דָּוִד בְּרוּחַ הַקֹּדֶשׁ אֲנִי הַיּוֹם יְלִדְתִּיךְ. הֵן עוֹד הַיּוֹם גָּדוֹל, בְּאוֹתוֹ שֶׁנֶּאֱמַר בּוֹ (דברים לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. אַתָּה קִיַּמְתָּ בַּשְּׁכִינָה וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ - שֶׁהַיְנוּ הַגּוּף, וּבְכָל נַפְשְׁךְ - שֶׁהַיְנוּ הַנְּשָׁמָה, שֶׁחֲמִשָּׁה שֵׁמוֹת יֵשׁ לָהּ: נְשָׁמָה, רוּחַ, נֶפֶשׁ, חַיָּה, יְחִידָה. וּבְכָל מְאֹדֶךְ - בְּכָל מָמוֹנְךְ. הַקָּדוֹשׁ בָּרוּךָ הוּא וּשְׁכִינָתוֹ לֹא יָזוּז מִמְּךְ בְּכָל אֵלּוּ.</p>\n<p>אַתָּה חָשַׁבְתָּ שֶׁאֲפִלּוּ הָיוּ כָּל הָעוֹלָמוֹת תַּחַת רְשׁוּתְךְ, הָיִיתָ נוֹתֵן לְהָקִים שְׁכִינָה עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהַמְלִיכוֹ עִם שְׁכִינָתוֹ עַל כָּל הַמְמֻנִּים שֶׁל אֻמּוֹת הָעוֹלָם, וְאַחַר כָּךְ לְהַעֲלוֹתוֹ וּשְׁכִינָתוֹ - בִּדְיוֹקַנְךְ כְּלוּלָה מִכָּל הַמִּדּוֹת הַטּוֹבוֹת, בְּכָל הָעוֹלָמוֹת, וּבַמַּחֲנוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְעַל כָּל יִשְׂרָאֵל.</p>\n<p>מַחֲשָׁבָה טוֹבָה הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרְפָהּ לְמַעֲשֶׂה. מֵאַחַר שֶׁאַתָּה בְנוֹ - עַל כָּל מַה שֶּׁחָשַׁבְתָּ לְרִבּוֹנְךְ, יְקֻיַּם עַל יָדְךְ וְלֹא תָזוּז מִמֶּנּוּ לְעוֹלָמִים, אֶלָּא תִּהְיֶה בִּדְיוֹקְנוֹ בַּכֹּל, וְאַתָּה בַּגָּלוּת גָּנוּז מִבְּנֵי אָדָם, וְאַתָּה מֵהָעוֹלָם הַזֶּה שְׁלִיחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לוֹמַר דְּבָרִים אֵלּוּ לְפָנֶיךְ, וַאֲנִי מְצֻוֶּה מִמֶּנּוּ שֶׁלֹּא לָזוּז מִמְּךְ בְּכָל עֵת וְשָׁעָה שֶׁאַתָּה רוֹצֶה, אֲנִי וְכָל הַתַּנָּאִים וְהָאָמוֹרָאִים שֶׁל הַיְשִׁיבוֹת. קוּם הַשְׁלֵם מִצְווֹת רִבּוֹנְךְ.</p>"],[9522011745,"<p>פָּתַח וְאָמַר, וְעָשׂוּ אֲרוֹן עֲצֵי שִׁטִּים. סֵפֶר תּוֹרָה, עַמּוּד הָאֶמְצָעִי. אֲרוֹנוֹ הַשְּׁכִינָה. מִבַּיִת וּמִחוּץ תְּצַפֶּנּוּ, אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁכִינָתוֹ, מִבַּחוּץ וּמִבִּפְנִים (שלו), וְהַכֹּל אֶחָד. מַה שֶּׁאֵין כֵּן בָּאָרוֹן שֶׁל הָעוֹלָם הַזֶּה, שֶׁתּוֹרָה מִבִּפְנִים מִין אֶחָד, וְהָאָרוֹן מִין אַחֵר. זֶה בִּכְתִיבַת דְּיוֹ, וְזֶה עֵץ מְצֻפֶּה זָהָב. שֶׁוַּדַּאי הַתּוֹרָה חֲבִיבָה מֵהַכֹּל. זֶהוּ שֶׁכָּתוּב, (איוב כח) לֹא יַעַרְכֶנָּה זָהָב וּזְכוּכִית.</p>\n<p>וּמִצַד אַחֵר אֲפִלּוּ בָּעוֹלָם הַזֶּה מַרְאֶה שֶׁהַכֹּל אֶחָד, דְּיוֹ וְעֵץ. (שהדיו) מִתַּפּוּחִים שֶׁהֵם נַעֲשׂוּ בָּעֵץ. (וכל דברי הדיו מעץ הם) וְעוֹד, דְּיוֹ שָׁחֹר מִבַּחוּץ וְלָבָן מִבִּפְנִים. כָּךְ הֵם (חכמים בעלי תורה) בַּעֲלֵי תוֹרָה וַחֲכָמִים - שְׁחֹרִים בָּעוֹלָם הַזֶּה, שֶׁהוּא מִבַּחוּץ, וְיָפִים בְּאוֹתוֹ הָעוֹלָם הַבָּא, שֶׁהוּא מִבִּפְנִים. וְלָכֵן דְּיוֹ, לָשׁוֹן שֶׁל דַּיּוֹ לָעֶבֶד לִהְיוֹת כְּרַבּוֹ. דַּיּוֹ: יוֹ\"ד יָד\"וֹ, חָכְמָה וּתְבוּנָה וָדַעַת, שֶׁכָּתַב אָדָם בְּיָדוֹ בִּדְיוֹ.</p>"],[9522011746,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, בְּאוֹתָם הַסּוֹדוֹת הָעֶלְיוֹנִים שֶׁל הַמִּשְׁכָּן כָּתוּב, וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם וְגוֹ', וְכָתוּב וַהֲקֵמֹתָ אֶת הַמִּשְׁכָּן כְּמִשְׁפָּטוֹ וְגוֹ'. לָמַדְנוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה כָּל הַתִּקּוּנִים וְכָל הַדְּיוֹקְנָאוֹת שֶׁל הַמִּשְׁכָּן, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, שֶׁהֶרְאָה לוֹ אֶת מטטרו\"ן שֶׁמְּשַׁמֵּשׁ כֹּהֵן גָּדוֹל לִפְנִים. וְאִם תֹּאמַר, הֲרֵי לֹא הוּקַם הַמִּשְׁכָּן לְמַעְלָה עַד הַיּוֹם שֶׁהוּקַם הַמִּשְׁכָּן לְמַטָּה, וְלֹא שִׁמֵּשׁ אוֹתוֹ נַעַר שֶׁלְּמַעְלָה עַד הַיּוֹם שֶׁשִּׁמְּשׁוּ לְמַטָּה בַּמִּשְׁכָּן הָאַחֵר הַזֶּה.</p>\n<p>אֶלָּא וַדַּאי כָּךְ זֶה, שֶׁהֲרֵי הַמִּשְׁכָּן לֹא הוּקַם לְמַעְלָה עַד שֶׁהוּקַם הַמִּשְׁכָּן לְמַטָּה, אֲבָל מֹשֶׁה רָאָה אֶת כָּל מַרְאֵה הַמִּשְׁכָּן, וְלֹא הָיָה מִסְתַּדֵּר בְּקִיּוּמוֹ, עַד שֶׁהוּקַם הַמִּשְׁכָּן לְמַטָּה, וְרָאָה אֶת מטטרו\"ן מְשַׁמֵּשׁ אַחַר כָּךְ. לֹא שֶׁהוּא הָיָה מְשַׁמֵּשׁ, אֶלָּא שֶׁהָיָה מְשַׁמֵּשׁ אַחַר כָּךְ, וְלֹא בְּאוֹתוֹ זְמַן. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, רְאֵה אֶת הַמִּשְׁכָּן וּרְאֵה אֶת הַנַּעַר, הַכֹּל מִתְעַכֵּב עַד שֶׁיּוּקַם כָּאן לְמַטָּה.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, מטטרו\"ן שֶׁהוּא הַמְשַׁמֵּשׁ? אֶלָּא וַדַּאי שֶׁהַמִּשְׁכָּן הוּא שֶׁלּוֹ, וּמִיכָאֵל הַכֹּהֵן הַגָּדוֹל הוּא שֶׁמְּשַׁמֵּשׁ בְּתוֹךְ אוֹתוֹ מִשְׁכָּן שֶׁל מטטרו\"ן, כְּמוֹ שֶׁמְּשַׁמֵּשׁ הַכֹּהֵן הַגָּדוֹל הָעֶלְיוֹן לְמַעְלָה בְּתוֹךְ מִשְׁכָּן אַחֵר הַנִּסְתָּר שֶׁלֹּא הִתְגַּלָּה בְּסוֹד הָעוֹלָם הַבָּא. שְׁנֵי מִשְׁכָּנוֹת הֵם., אֶחָד הוּא נִסְתָּר לְמַעְלָה, וְאֶחָד הַמִּשְׁכָּן הַזֶּה שֶׁל מטטרו\"ן. שְׁנֵי כֹהֲנִים הֵם., אֶחָד אוֹר רִאשׁוֹן, וְאֶחָד מִיכָאֵל הַכֹּהֵן הַגָּדוֹל לְמַטָּה.</p>"],[9522011747,"<p>מִכָּאן סוֹדוֹת נִסְתָּרִים שֶׁל בֵּית הַמִּשְׁכָּן מִפִּי הַמְּנוֹרָה. הַמִּשְׁכָּן הָעֶלְיוֹן נִבְנָה עַל שְׁתֵּים עֶשְׂרֵה מַרְגָּלִיּוֹת, אֵיבָרִים עֶלְיוֹנִים, יָמִין וּשְׂמֹאל, שְׂמֹאל וְיָמִין.</p>\n<p>שְׁלשָה שֵׁמוֹת הֵם כְּלוּלִים כְּאֶחָד, וְזֶה נִכְנָס בָּזֶה, וְזֶה נִכְנָס בָּזֶה. אֵ\"ל הָרִאשׁוֹן וּמִסְתַּדֵּר בְּיָמִין. א הִיא רִאשׁוֹנָה, שֶׁהִיא יָמִין, וּמִתְגַּשֵּׁם וּמִצְטַיֵּר בְּסוֹד הַיָּמִין, וּכְשֶׁנִּכְנָס וּמְשַׁמֵּשׁ בִּפְנִים, נֶאֱחָז עִם ל, וְנִקְרָא בְסוֹדוֹ אֵ\"ל, שֶׁהֲרֵי ל' מִסּוֹד שֶׁלְּמַעְלָה בְּתוֹךְ קֹדֶשׁ הַקְּדָשִׁים יָצָא.</p>\n<p>לֹא שֶׁשָּׁם הִתְגַּשֵּׁם, אֶלָּא וַדַּאי כְּשֶׁיָּצָא הִתְגַּשֵּׁם, כִּשְׁאָר הָאוֹתִיּוֹת שֶׁכְּשֶׁיָּצְאוּ מִסּוֹד הָעוֹלָם הַבָּא הִתְגַּשְּׁמוּ וְהִצְטַיְּרוּ. אַף כָּךְ הַל' הַזּוֹ, אַף עַל גַּב שֶׁהִיא סוֹד שֶׁלְּמַעְלָה, לֹא הִתְגַּשְּׁמָה עַד שֶׁיָּצְאָה הַחוּצָה, וְאָז אֵ\"ל. וְזֶהוּ סוֹד הַיָּמִין.</p>\n<p>הַשְּׂמֹאל כּוֹלֵל בְּתוֹכוֹ אֶת הַיָּמִין וְנוֹטֵל אֶת הַשֵּׁם הַזֶּה אֵלָיו וְנִכְלָל עִמּוֹ, וּכְשֶׁנִּכְלָל עִמּוֹ הוּא נִקְרָא אֱלֹהִים. וְאִם תֹּאמַר, הֲרֵי הִקְדִּים הַשְּׂמֹאל בְּסוֹד הָעוֹלָם הַבָּא.</p>\n<p>וַדַּאי זֶה כָּךְ. אֶלָּא כְּשֶׁיָּצְאוּ הַדְּרָגוֹת בְּסוֹד הָאוֹתִיּוֹת מִתּוֹךְ הָעוֹלָם הַבָּא, רָצָה הַשֵּׁם הַזֶּה לְהֵרָאוֹת וּלְהִבָּנוֹת, לְהַרְאוֹת עַל אוֹתוֹ מָקוֹם שֶׁיָּצְאוּ מִשָּׁם, וְנִבְנָה שֵׁם זֶה כְּמוֹ זֶה. אֵ\"ל בַּתְּחִלָּה בְּצַד הַיָּמִין, נִכְלָל בְּתוֹךְ הַשְּׂמֹאל, וְנוֹטֵל אוֹתוֹ הַשְּׂמֹאל, וְנִקְרָא אֱלֹהִים, וְזֶהוּ סוֹד הַיָּמִין (אמר לו בשם וכו') בַּשֵּׁם שֶׁל אֱלֹהִים, וְעַל סוֹד זֶה, בְּכָל מָקוֹם שֶׁהוּא דִּין, שָׁם הוּא רַחֲמִים, שֶׁהֲרֵי הוּא כּוֹלֵל דִּין, וְזֶה נִבְנֶה וְנִרְאֶה.</p>\n<p>אוֹתוֹ שֶׁיָּצָא מִשָּׁם, אֶמְצָעִי, נוֹטֵל אֶת שְׁנֵיהֶם, וּמִשְׁתַּלֵּם, וְנִקְרָא אֱלֹהֵינוּ. הֲרֵי כָּאן הַשְּׁלֵמוּת שֶׁנִּרְאֵית מִסּוֹד הָעוֹלָם הָעֶלְיוֹן, וְהַכֹּל נִכְלָל זֶה בָּזֶה. כֵּיוָן שֶׁהָאֶמְצַע הַזֶּה הִשְׁתַּלֵּם, שׁוֹרֶה עָלָיו הַשֵּׁם הַקָּדוֹשׁ, הַמַּפְתֵּחַ שֶׁל הַכֹּל שֶׁנִּקְרָא יְהֹוָ\"ה, וְאָז נוֹטֵל אֶת כָּל הַצְּדָדִים, מַעְלָה וּמַטָּה, יָמִין וּשְׂמֹאל, וּלְכָל הַצְּדָדִים הָאֲחֵרִים. וְלָכֵן כְּשֶׁנִּשְׁתַּלֵּם מִסּוֹד שְׁנֵי הַצְּדָדִים, מִיָּמִין וּשְׂמֹאל, נִקְרָא אֱלֹהֵינוּ. הֲרֵי כָּאן יָמִין וּשְׂמֹאל וְאֶמְצַע בִּכְלַל הַשֵּׁם הַזֶּה. וְזֶה נִרְאֶה וְנִבְנֶה. הַסּוֹד שֶׁהָאוֹתִיּוֹת יָצְאוּ מִשָּׁם, כָּךְ נִבְנֶה וְנִרְאֶה כָּל אֶחָד וְאֶחָד.</p>\n<p>הֲרֵי נִכְלָל יָמִין בַּשְּׂמֹאל, וְנוֹטֵל הַשְּׂמֹאל אֶת שֵׁם הַיָּמִין. אֵיפֹה כָּלוּל הַיָּמִין בְּתוֹךְ הַשְּׂמֹאל, שֶׁהַיָּמִין יִטֹּל אֶת סוֹד הַשְּׂמֹאל? אֶלָּא כְּשֶׁנִּכְלָל יָמִין בִּשְׂמֹאל וְנוֹטֵל הַשְּׂמֹאל אֶת שֵׁם סוֹד הַיָּמִין, הַיָּמִין כּוֹלֵל בְּתוֹכוֹ אֶת הַשְּׂמֹאל, הַשֵּׁם אֵ\"ל. וְהוּא הי\"ם.</p>\n<p>לָמָּה כָּךְ? אֶלָּא בְּשָׁעָה שֶׁנִּבְנֶה אוֹתוֹ מָקוֹם שֶׁיָּצְאוּ מִשָּׁם, נוֹטֵל הַשְּׂמֹאל שְׁתֵּי אוֹתִיּוֹת. הַיָּמִין נוֹטֵל אַחַת מִסּוֹד הָעוֹלָם הַבָּא. הַשְּׂמֹאל שְׁתַּיִם, וְהוּא הי\"ם. אָז הַיָּמִין כּוֹלֵל בְּתוֹכוֹ אֶת הַשְּׂמֹאל, וְנוֹטֵל הָאוֹת הָאַחֲרוֹנָה ם, וְנוֹטֵל י' שֶׁהָיְתָה בִּשְׂמֹאל. ם הִיא בִּשְׁלֵמוּת מֵ\"ם, וְכָךְ נִבְנֶה מַיִ\"ם בְּאוֹתוֹ י' שֶׁנּוֹטֵל יוֹתֵר. וְאָז הַיָּמִין כּוֹלֵל אֶת הַשְּׂמֹאל בְּתוֹכוֹ.</p>"],[9522011748,"<p>אַחַר כָּךְ נִבְנוֹת הָאוֹתִיּוֹת. א' שֶׁהָיָה בַּהַתְחָלָה בְּצַד הַיָּמִין, הוֹלִידָה וְהוֹצִיאָה אֶת הָאוֹת ש', כְּלוּלָה בִּשְׁלֹשָׁה צְדָדִים, וּמִשְׁתַּתֶּפֶת עִם הָאוֹת א', וְנַעֲשׂוֹת אֵשׁ. עוֹד זָזוֹת הָאוֹתִיּוֹת הַלָּלוּ תּוֹךְ הַכָּאַת שְׁנֵי הַצְּדָדִים הַלָּלוּ וּמִתְקָרְבִים כְּאֶחָד בְּמַחֲלֹקֶת, וּמִתּוֹךְ מַחֲלֹקֶת זוֹ שֶׁל מַיִם בְּאֵשׁ וְאֵשׁ בְּמַיִם, מוֹלִידִים אוֹתִיּוֹת, וּמוֹצִיאִים אוֹת ר' וְאוֹת ו' וְאוֹת ח' וְנַעֲשִׂים רוּחַ. וְנִכְנָס בֵּין שְׁנֵי צְדָדִים, וְאָז מִתְיַשְּׁבוֹת הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת בִּמְקוֹמָן, כָּל אַחַת וְאַחַת בִּשְׁלֵמוּת.</p>\n<p>עוֹד זָזוֹת הָאוֹתִיּוֹת וּמִתְגַּלְגְּלוֹת כְּאֶחָד, א' מוֹצִיאָה מ', שֶׁהִיא מִצִּדּוֹ בְּיָמִין, שֶׁהֲרֵי בְּיָמִין מִתְיַשֶּׁבֶת. מ' מוֹצִיאָה ש', מִשּׁוּם שֶׁהֲרֵי מ' הִיא כְּלוּלָה, בָּרִאשׁוֹנָה הָיְתָה מִשְּׂמֹאל, וְנִכְלֶלֶת אַחַר כָּךְ בְּיָמִין וּמִשְׁתַּלֶּמֶת בִּשְׁנֵי צְדָדִים. כֵּיוָן שֶׁהִשְׁתַּלְּמָה, זָזוּ וְהוֹלִידוּ כְאֶחָד, וְנִכְלְלוּ בִשְׁנֵי צְדָדִים.</p>\n<p>הִתְחַזְּקוּ הָאוֹתִיּוֹת אמ\"ש שְׁלֹשׁ אֵלֶּה, וְהִתְעַבְּרוּ וְהוֹלִידוּ שָׁלֹשׁ אֲחֵרוֹת תּוֹךְ הַגִּלְגּוּל. מ' הִתְתַּקְּנָה וְהִתְעַבְּרָה וְהוֹלִידָה ר'. א' הִתְעַבְּרָה וְהוֹלִידָה ו'. ש' הִתְעַבְּרָה וְהוֹלִידָה ח', וְהַכֹּל נִתְקַן.</p>\n<p>עוֹד הִתְעַבְּרוּ הָאוֹתִיּוֹת הַלָּלוּ סוֹד אמ\"ש, וְהִתְגַּלְגְּלוּ כְּמִקֹּדֶם. א' הִתְעַבְּרָה וְהוֹלִידָה וְהוֹצִיאָה אֶת הָאוֹת ב' בְּצַד מַעֲרָב, וְאָז הִיא מִתְיַשֶּׁבֶת בְּצַד הַדָּרוֹם. מ' הִתְעַבְּרָה וְהוֹלִידָה וְהוֹצִיאָה אֶת הָאוֹת ד' בְּצַד הַצָּפוֹן, וְאָז הִיא מִתְעַלָּה בֵּין צָפוֹן וְדָרוֹם וּתְלוּיָה בָּאֲוִיר. ש' הִתְעַבְּרָה וְהוֹלִידָה וְהוֹצִיאָה אוֹת ג', וּמִתְיַשֶּׁבֶת בְּצַד הַמִּזְרָח, וּמִתְעַלָּה בֵּין מַעֲרָב וּמִזְרָח וּתְלוּיָה בָּאֲוִיר. נִמְצְאוּ שְׁתֵּי אוֹתִיּוֹת מ\"ש תְּלוּיוֹת בָּאֲוִיר.</p>\n<p>א' שֶׁנִּשְׁאֲרָה הִתְעַלְּתָה בִּמְקוֹמָהּ, וְעָלְתָה לְמַעְלָה, וְהִתְעַטֵּר בָּהּ יָ\"הּ. בְּאֵלֶּה הִתְחַזְּקָה וְהִתְעַבְּרָה וְהוֹלִידָה ה\"ו וְעָמְדָה בִּמְקוֹמָהּ. אָז מִתְעַטֶּרֶת וּמְאִירָה וּפוֹשֶׁטֶת אוֹר, וּמוֹלִידָה אוֹר, וְהוֹצִיאָה אֶת הָאוֹת ט', הַמַּכָּה שֶׁהִכָּה וְהֵאִיר סוֹד הָעוֹלָם הָעֶלְיוֹן בְּאוֹר.</p>\n<p>אָז מִתְעַלָּה א' וְנוֹטֶלֶת מִתּוֹךְ הָאוֹר אֶת מ\"ש, וְהִתְחַבְּרוּ עִמָּהּ, וְנִהְיוֹת אמ\"ש כְּמִקֹּדֶם, וּמִתְיַשֶּׁבֶת א' בְּצַד דָּרוֹם, ש' בְּצַד מִזְרָח, מ' בְּצַד צָפוֹן. עוֹלָה ג' שֶׁהָיְתָה בְּצַד מִזְרָח, וּמִתְעַבֶּרֶת וּמוֹלִידָה צ\"ת. בָּאָה ב' שֶׁהָיְתָה בְּצַד מַעֲרָב, וְעוֹלָה וּמִתְחַבֶּרֶת בֵּין צ\"ת. עוֹלוֹת א' ו', זוֹ מִצַּד מַעֲרָב (דרום) וְזוֹ מִצַּד מִזְרָח, וּמִתְחַבְּרוֹת שְׁתֵּיהֶן עִם ב' בֵּין צ\"ת, וּמֵאִיר הַשֵּׁם צְבָאוֹת.</p>\n<p>כְּשֶׁמֵּאִיר הַשֵּׁם הַזֶּה בְּתוֹךְ הַמִּשְׁכָּן, מִתְעַבְּרוֹת הָאוֹתִיּוֹת וּמוֹלִידוֹת ז' ב' (ג') נ. עוֹלוֹת אמ\"ש כְּמִקֹּדֶם, וּמִתְעַבְּרוֹת וּמוֹלִידוֹת ס' ע' פ'.</p>\n<p>נִשְׁאֲרָה ק' יְחִידָה, וְעוֹלָה וְיוֹרֶדֶת, וְעוֹמֶדֶת בְּתוֹךְ נֶקֶב תְּהוֹם רַבָּה. רוֹאֶה אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמִּתְעַרְבֶּבֶת בְּלִי גוּף וְלֹא צִיּוּר וְלֹא נִכְנֶסֶת לַמִּשְׁכָּן, עָשָׂה אוֹתָהּ חֻפָּה וְכִסּוּי לַמִּשְׁכָּן. וּמַהִי? יְרִיעוֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן, כְּמוֹ שֶׁנֶּאֱמַר וְעָשִׂיתָ יְרִיעֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן, לְאֹהֶל וְלֹא אֹהֶל. קוֹ\"ף וְלֹא אָדָם.</p>\n<p>עוֹד הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת כְּמִקֹּדֶם בְּתוֹךְ מַעֲשֵׂה הַמִּשְׁכָּן, אמ\"ש. ש' הִתְגַּלְגְּלָה וְהִתְיַשְּׁבָה בְּצַד מִזְרָח, וְנִשְׁאֲרָה ג' תְּלוּיָה בָּאֲוִיר. מ' הִתְגַּלְגְּלָה וְהִתְיַשְּׁבָה בְּצַד צָפוֹן, וְיָצְאָה ד' וְהִתְחַבְּרָה בְּתוֹךְ ש' בְּאוֹתוֹ צַד. א' הִתְגַּלְגְּלָה וְהִתְיַשְּׁבָה וְעָלְתָה לְי', וְעָלְתָה וְהֶחֱזִיקָה עִמּוֹ וְנָטְלָה אוֹתוֹ, וְהִתְחַבְּרָה בְתוֹכוֹ בְּחִבּוּר אֶחָד שַׁדַּ\"י. כְּשֶׁהַשֵּׁם הַזֶּה נִתְתַּקֵּן בְּתוֹךְ הַמִּשְׁכָּן, אָז קִיּוּם וַעֲמִידָה הוּא מִתּוֹךְ הַמִּשְׁכָּן שֶׁלְּמַטָּה.</p>\n<p>עוֹד הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת כְּמִקֹּדֶם לְהִתְיַשֵּׁב בַּמִּשְׁכָּן, וְעָלוּ הָאוֹתִיּוֹת - א' בָּרֹאשׁ, ת' אַחַר כָּךְ, א\"ת. ב' בָּרֹאשׁ, ש' אַחַר כָּךְ. הִתְחַלְּפוּ הָאוֹתִיּוֹת אב\"ג ית\"ץ, הִתְגַּלְגְּלוּ בַּחֲקִיקוֹת קֹדֶשׁ א' ק'. א' הוֹצִיאָה ק' לִשְׁמֹר אֶת הַמִּשְׁכָּן. ק' הוֹצִיאָה ר'. ר' הוֹצִיעָה ע' קר\"ע.</p>\n<p>הַסּוֹד הַזֶּה - וְאֵת עֹרֹת גְּדָיֵי הָעִזִּים הִלְבִּישָׁה עַל יָדָיו וְעַל חֶלְקַת צַוָּארָיו. כְּמוֹ זֶה, וְעָשִׂיתָ יְרִיעֹת עִזִּים לְאֹהֶל עַל הַמִּשְׁכָּן. שֶׁהֲרֵי הַחֵלֶק הַזֶּה הִצְטָרֵךְ לְהֵרָאוֹת בַּחוּץ לִשְׁמֹר אֶת אוֹתוֹ פְּנִים. וְעַל סוֹד זֶה הִלְבִּישָׁה אֶת יַעֲקֹב בַּחוּץ. שט\"ן קר\"ע, אוֹתָן אוֹתִיּוֹת רְשׁוּמוֹת בַּחוּץ בִּשְׁבִיל שְׁמִירַת הַמִּשְׁכָּן, שֶׁהוּא סוֹד הַבְּרִית הַקְּדוֹשָׁה, וְנִפְרְעָה הָעָרְלָה אַחַר כָּךְ עַל יְדֵי הַכִּסּוּי הַזֶּה.</p>\n<p>עוֹד הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת וְהוֹצִיאוּ א\"ת ב\"ש, שקוצי\"ת בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְגוֹ'. בְּגִלְגּוּל זֶה וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ, בְּאוֹתִיּוֹת קר\"ע שט\"ן. וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם - ג' הוֹצִיאָה ר', ד' ק'. עַד כָּאן הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת וְהִכּוּ זוֹ בָּזוֹ לְתִקּוּן בְּתוֹךְ הַמִּשְׁכָּן.</p>\n<p>אוֹתָן אמ\"ש הוֹצִיאוּ תוֹלָדוֹת, (ת') ה' צ' ו' ף' אוֹתִיּוֹת הַתְּלוּיוֹת בְּתוֹךְ הָאֲוִיר, וְהִכּוּ בְאוֹתָן אֲחֵרוֹת וְהוֹצִיאוּ אֶת צִיּוּר הַמִּשְׁכָּן ז' ע'. עַד כָּאן עוֹמֵד וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם, כֻּלָּם בְּצִדּוֹ, ח' בָּאָה ס' וְהִתְחַבְּרָה עִמּוֹ, אָז יְהִי אוֹר וַיְהִי אוֹר.</p>\n<p>הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת כְּמִקֹּדֶם אב\"ג ית\"ץ, הִתְעַבְּרוּ וְהוֹלִידוּ וְהוֹצִיאוּ צִיּוּר תּוֹךְ סוֹדוֹת הַמִּשְׁכָּן (בכללות) הִתְגַּלְגְּלוּ אֶחָד בְּסוֹד א' ל' ב' ם', שֶׁהֲרֵי הָאוֹת א' הִתְעַבְּרָה וְהוֹלִידָה בְּסוֹד שֶׁל כֹּחַ וְתֹקֶף אֶת הָאוֹת ל'. הִתְגַּבֵּר בְּתָקְפּוֹ וְהִתְעַלָּה בִכְבוֹדוֹ, וְהוֹלִיד אֶת הָאוֹת ב'. אָז הִתְעַבְּרוּ וְהוֹלִידוּ הָאוֹתִיּוֹת וְהִתְחַבְּרוּ אֲחֵרוֹת אֵלּוּ, א' הִתְחַבְּרָה בַּחֲקִיקָתָהּ בָּאוֹת ב'. אָז ט\"ר בְּחִבּוּר ט\"ת, לִהְיוֹת הָאוֹתִיּוֹת עוֹלוֹת לִמְקוֹמָן, תּוֹךְ צֵרוּף שֶׁל סוֹד הַמִּשְׁכָּן. אֶת הַכִּיּוֹר וְאֶת כַּנּוֹ.</p>\n<p>יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, שֶׁהֲרֵי הַמַּיִם עָלוּ וְיָרְדוּ בַּסּוֹד שֶׁל הָאוֹתִיּוֹת א\"ל. א' הוֹצִיאָה ו'. ו' הוֹצִיאָה ק'. הָאוֹת ל' עוֹלָה, וְנֶחְקְקוּ הָאוֹתִיּוֹת בַּחֲקִיקוֹתֵיהֶן בְּחִבּוּר אֶחָד. קוֹל ה' עַל הַמָּיִם אֵ\"ל וְכוּ'. אֵלּוּ אוֹתִיּוֹת אֵ\"ל, שֶׁהֲרֵי אֵלֶּה הִתְעַבְּרוּ וְהוֹלִידוּ וְהוֹצִיאוּ אוֹתִיּוֹת תּוֹךְ צִיּוּרֵי הַמִּשְׁכָּן.</p>\n<p>אמ\"ש הִתְעַבְּרוּ וְהוֹלִידוּ וְנֶחְקְקוּ בַּחֲקִיקוֹת שֶׁל סוֹדוֹת הָאוֹתִיּוֹת לְהוֹצִיא אֶת צִיּוּרֵי הַמִּשְׁכָּן. א' הוֹצִיאָה ג', ש' הוֹצִיאָה ן', לְחַבֵּר תּוֹךְ הָאוֹת ג' בְּסוֹד גַּן. תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב וְגוֹ'. הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת כְּמִקֹּדֶם אמ\"ש, בְּסוֹד ב\"ם בְּאֵלֶּה נִכְנְסוּ הַמַּיִם לְמָקוֹם אֶחָד, שֶׁכָּתוּב יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד.</p>"]]});
